window.TET_DATA_SPECIAL_EDUCATION = [{"id": 1, "sec": "Special Education", "passage": "", "q_en": "This is not a character of Development", "q_te": "క్రింది వానిలో వికాస లక్షణం కానిది", "opts": [{"en": "Development is Qualitative", "te": "వికాసం గుణాత్మకమైనది", "raw": "Development is Qualitative / వికాసం గుణాత్మకమైనది"}, {"en": "Lifelong Continuous Process", "te": "జీవితాంతం కొనసాగే నిరంతర ప్రక్రియ", "raw": "Lifelong Continuous Process / జీవితాంతం కొనసాగే నిరంతర ప్రక్రియ"}, {"en": "Possible to measure", "te": "ఖచ్చితంగా కొలవడానికి సాధ్యం (కొలవదగినది)", "raw": "Possible to measure / ఖచ్చితంగా కొలవడానికి సాధ్యం (కొలవదగినది)"}, {"en": "Broad and Comprehensive concept", "te": "విస్తృతమైన మరియు సమగ్రమైన భావన", "raw": "Broad and Comprehensive concept / విస్తృతమైన మరియు సమగ్రమైన భావన"}], "ans": 3, "exp_en": "Growth is quantitative and can be directly measured (e.g., height, weight). In contrast, Development is qualitative, complex, and continuous, reflecting changes in functional capacity and behavior. It cannot be directly measured using physical units; it can only be assessed through observation.", "exp_te": "పెరుగుదల పరిమాణాత్మకమైనది కాబట్టి దానిని నేరుగా కొలవవచ్చు (ఎత్తు, బరువు). కానీ వికాసం గుణాత్మకమైనది, సంక్లిష్టమైనది మరియు సమగ్రమైనది. దీనిని భౌతిక ప్రమాణాలతో నేరుగా ఖచ్చితంగా కొలవడం సాధ్యం కాదు; కేవలం ప్రవర్తనా మార్పుల ద్వారా అంచనా మాత్రమే వేయగలం."}, {"id": 2, "sec": "Special Education", "passage": "", "q_en": "Self Centeredness (Egocentrism) is seen more at this stage", "q_te": "ఆత్మ కేంద్రీకృత భావన (అహంకేంద్రితత్వం / స్వార్థ బుద్ధి) ఎక్కువగా కనిపించే దశ", "opts": [{"en": "Pre Operational Stage", "te": "పూర్వ ప్రచాలక దశ", "raw": "Pre Operational Stage / పూర్వ ప్రచాలక దశ"}, {"en": "Sensory - Motor Stage", "te": "ఇంద్రియ ప్రచాలక దశ", "raw": "Sensory - Motor Stage / ఇంద్రియ ప్రచాలక దశ"}, {"en": "Concrete Operational Stage", "te": "మూర్త ప్రచాలక దశ", "raw": "Concrete Operational Stage / మూర్త ప్రచాలక దశ"}, {"en": "Formal Operational Stage", "te": "అమూర్త ప్రచాలక దశ", "raw": "Formal Operational Stage / అమూర్త ప్రచాలక దశ"}], "ans": 1, "exp_en": "According to Jean Piaget's Theory of Cognitive Development, Egocentrism (self-centeredness)—the inability of a child to understand another person's perspective—is a hallmark characteristic of the Pre-Operational Stage (2 to 7 years).", "exp_te": "జీన్ పియాజే సంజ్ఞానాత్మక వికాస సిద్ధాంతం ప్రకారం, ఎదుటివారి దృక్కోణాన్ని అర్థం చేసుకోలేక ప్రతిదాన్నీ తమ స్వంత కోణం నుంచే ఆలోచించే అహంకేంద్రితత్వం (Egocentrism / Self-centeredness) పూర్వ ప్రచాలక దశ (2-7 సం.) లో ప్రస్ఫుటంగా కనిపిస్తుంది."}, {"id": 3, "sec": "Special Education", "passage": "", "q_en": "Secondary Sexual Characters appear clearly at this stage", "q_te": "ద్వితీయ లైంగిక లక్షణాలు స్పష్టంగా కనిపించే దశ", "opts": [{"en": "Infancy", "te": "శైశవ దశ", "raw": "Infancy / శైశవ దశ"}, {"en": "Early Childhood", "te": "పూర్వ బాల్యదశ", "raw": "Early Childhood / పూర్వ బాల్యదశ"}, {"en": "Later Childhood", "te": "ఉత్తర బాల్యదశ", "raw": "Later Childhood / ఉత్తర బాల్యదశ"}, {"en": "Adolescence", "te": "కౌమార దశ", "raw": "Adolescence / కౌమార దశ"}], "ans": 4, "exp_en": "Adolescence (around 12-18 years) is triggered by puberty hormones resulting in the emergence of secondary sexual characteristics (deepening of voice, facial hair, breast development, pubic hair).", "exp_te": "కౌమార దశ (Adolescence) లో లైంగిక హార్మోన్ల స్రావం వల్ల శారీరక మార్పులు జరిగి, ద్వితీయ లైంగిక లక్షణాలు (స్వరంలో మార్పు, గడ్డం/మీసాలు రావడం మొదలైనవి) స్పష్టంగా వ్యక్తమవుతాయి."}, {"id": 4, "sec": "Special Education", "passage": "", "q_en": "Under Pre-Primary educational Programme, these are to be given importance", "q_te": "పూర్వ ప్రాథమిక విద్యా కార్యక్రమంలో వీటికి ప్రాధాన్యత ఇవ్వాలి", "opts": [{"en": "Discussions", "te": "చర్చలు", "raw": "Discussions / చర్చలు"}, {"en": "Stories", "te": "కథలు", "raw": "Stories / కథలు"}, {"en": "Drawing", "te": "చిత్రలేఖనం", "raw": "Drawing / చిత్రలేఖనం"}, {"en": "Questioning", "te": "ప్రశ్నించడం", "raw": "Questioning / ప్రశ్నించడం"}], "ans": 2, "exp_en": "At the pre-primary stage (3-6 years), children learn best through play, imagination, and narrative storytelling (Stories), which significantly foster language acquisition, listening skills, and vocabulary.", "exp_te": "పూర్వ ప్రాథమిక దశలో కథల (Stories) ద్వారా బోధించడం వల్ల పిల్లల్లో కల్పనా శక్తి, వినే నైపుణ్యం, భాషా పరిజ్ఞానం మరియు పద సంపద అత్యంత సహజంగా అలవడతాయి."}, {"id": 5, "sec": "Special Education", "passage": "", "q_en": "Education in Modern era is to be", "q_te": "ఆధునిక కాలంలో విద్య ఇలా ఉండాలి", "opts": [{"en": "Child Centred", "te": "శిశు కేంద్రీకృతం (విద్యార్థి కేంద్రీకృతం)", "raw": "Child Centred / శిశు కేంద్రీకృతం (విద్యార్థి కేంద్రీకృతం)"}, {"en": "Teacher Centred", "te": "ఉపాధ్యాయ కేంద్రీకృతం", "raw": "Teacher Centred / ఉపాధ్యాయ కేంద్రీకృతం"}, {"en": "Parents Centred", "te": "తల్లిదండ్రుల కేంద్రీకృతం", "raw": "Parents Centred / తల్లిదండ్రుల కేంద్రీకృతం"}, {"en": "Society Centred", "te": "సమాజ కేంద్రీకృతం", "raw": "Society Centred / సమాజ కేంద్రీకృతం"}], "ans": 1, "exp_en": "Modern educational philosophy and curriculum frameworks (NCF 2005, NEP 2020) mandate Child-Centred Education, focusing on the child's needs, interests, pace of learning, and active participation.", "exp_te": "ఆధునిక విద్యా విధానం (NCF 2005, NEP 2020) ప్రకారం విద్య అనేది విద్యార్థి యొక్క అవసరాలు, ఆసక్తులు, సామర్థ్యాలు మరియు క్రియాశీలక అభ్యసనానికి ప్రాధాన్యతనిచ్చే 'శిశు కేంద్రీకృతం' (Child-Centred) గా ఉండాలి."}, {"id": 6, "sec": "Special Education", "passage": "", "q_en": "Neonates express their feelings first through", "q_te": "నవజాత శిశువులు తమ భావాలను మొదటగా దీని ద్వారా వ్యక్తం చేస్తారు", "opts": [{"en": "Laughing", "te": "నవ్వడం", "raw": "Laughing / నవ్వడం"}, {"en": "Jumping", "te": "దూకడం", "raw": "Jumping / దూకడం"}, {"en": "Talking", "te": "మాట్లాడటం", "raw": "Talking / మాట్లాడటం"}, {"en": "Crying", "te": "ఏడవడం", "raw": "Crying / ఏడవడం"}], "ans": 4, "exp_en": "Crying is the first and primary form of communication for neonates (newborn infants) to signal physical discomfort, hunger, fatigue, or the need for care.", "exp_te": "నవజాత శిశువులకు ఏడుపు (Crying) అనేది మొట్టమొదటి సహజ సంభాషణా సాధనం. ఆకలి, నొప్పి, నిద్ర వంటి శారీరక అసౌకర్యాలను ఏడుపు ద్వారానే వ్యక్తపరుస్తారు."}, {"id": 7, "sec": "Special Education", "passage": "", "q_en": "Having proper, complete orientation on the topics related to Nature is called", "q_te": "ప్రకృతికి సంబంధించిన అంశాలపై పూర్తి అవగాహన, సౌందర్య స్పృహ కలిగి ఉండడాన్ని ఏమంటారు", "opts": [{"en": "Musical Intelligence", "te": "సంగీత ప్రజ్ఞ", "raw": "Musical Intelligence / సంగీత ప్రజ్ఞ"}, {"en": "Spatial Intelligence", "te": "దృశ్య-ప్రాదేశిక ప్రజ్ఞ", "raw": "Spatial Intelligence / దృశ్య-ప్రాదేశిక ప్రజ్ఞ"}, {"en": "Aesthetic Intelligence", "te": "సౌందర్యాత్మక / ప్రకృతి ప్రజ్ఞ (Aesthetic Intelligence)", "raw": "Aesthetic Intelligence / సౌందర్యాత్మక / ప్రకృతి ప్రజ్ఞ (Aesthetic Intelligence)"}, {"en": "Logical Intelligence", "te": "తార్కిక-గణిత ప్రజ్ఞ", "raw": "Logical Intelligence / తార్కిక-గణిత ప్రజ్ఞ"}], "ans": 3, "exp_en": "Aesthetic / Naturalistic intelligence refers to appreciation, sensitivity, and deep understanding of natural patterns, ecological systems, and beauty in nature.", "exp_te": "ప్రకృతిలోని అందాలు, పర్యావరణ వ్యవస్థలు, సహజసిద్ధమైన జీవ వైవిధ్యాన్ని గుర్తించి ఆస్వాదించగలిగే అవగాహనను సౌందర్యాత్మక / ప్రకృతి ప్రజ్ఞ అంటారు."}, {"id": 8, "sec": "Special Education", "passage": "", "q_en": "A Book written by Rousseau", "q_te": "జీన్ జాక్వెస్ రూసో రాసిన ప్రసిద్ధ గ్రంథం", "opts": [{"en": "Emile", "te": "ఎమిలీ (Emile)", "raw": "Emile / ఎమిలీ (Emile)"}, {"en": "Jamili", "te": "జామిలీ", "raw": "Jamili / జామిలీ"}, {"en": "Geethanjali", "te": "గీతాంజలి", "raw": "Geethanjali / గీతాంజలి"}, {"en": "Kamili", "te": "కామిలీ", "raw": "Kamili / కామిలీ"}], "ans": 1, "exp_en": "'Emile, or On Education' (1762) is the renowned treatise written by the philosopher Jean-Jacques Rousseau advocating naturalism and child-centred education.", "exp_te": "ప్రకృతివాద విద్యావేత్త అయిన జీన్ జాక్వెస్ రూసో 1762లో 'ఎమిలీ' (Emile) అనే గ్రంథాన్ని రచించారు. ఇందులో ప్రకృతి ఒడిలో విద్యార్థి స్వేచ్ఛాయుత సహజ వికాసాన్ని ప్రతిపాదించారు."}, {"id": 9, "sec": "Special Education", "passage": "", "q_en": "Cognitive development theory was proposed by", "q_te": "సంజ్ఞానాత్మక వికాస సిద్ధాంతాన్ని ప్రతిపాదించినది", "opts": [{"en": "Francis Galton", "te": "ఫ్రాన్సిస్ గాల్టన్", "raw": "Francis Galton / ఫ్రాన్సిస్ గాల్టన్"}, {"en": "Spearman", "te": "స్పియర్‌మ్యాన్", "raw": "Spearman / స్పియర్‌మ్యాన్"}, {"en": "E.L. Thorndike", "te": "ఇ.ఎల్. థార్న్‌డైక్", "raw": "E.L. Thorndike / ఇ.ఎల్. థార్న్‌డైక్"}, {"en": "Jean Piaget", "te": "జీన్ పియాజే", "raw": "Jean Piaget / జీన్ పియాజే"}], "ans": 4, "exp_en": "Swiss psychologist Jean Piaget developed the 4-stage Theory of Cognitive Development (Sensorimotor, Pre-operational, Concrete operational, Formal operational).", "exp_te": "స్విస్ మనోవిజ్ఞానవేత్త అయిన జీన్ పియాజే పిల్లల మానసిక/మేధో వికాసాన్ని వివరిస్తూ నాలుగు దశల సంజ్ఞానాత్మక వికాస సిద్ధాంతాన్ని ప్రతిపాదించారు."}, {"id": 10, "sec": "Special Education", "passage": "", "q_en": "Two Factor Theory of Intelligence was proposed by", "q_te": "ప్రజ్ఞా ద్వికారక సిద్ధాంతాన్ని ప్రతిపాదించినది", "opts": [{"en": "J.P. Guilford", "te": "జె.పి. గిల్‌ఫోర్డ్", "raw": "J.P. Guilford / జె.పి. గిల్‌ఫోర్డ్"}, {"en": "Louis Thurstone", "te": "లూయిస్ థర్స్టన్", "raw": "Louis Thurstone / లూయిస్ థర్స్టన్"}, {"en": "Spearman", "te": "చార్లెస్ స్పియర్‌మ్యాన్", "raw": "Spearman / చార్లెస్ స్పియర్‌మ్యాన్"}, {"en": "Skinner", "te": "బి.ఎఫ్. స్కిన్నర్", "raw": "Skinner / బి.ఎఫ్. స్కిన్నర్"}], "ans": 3, "exp_en": "Charles Spearman proposed the Two-Factor Theory of Intelligence in 1904, identifying General factor ('g') and Specific factors ('s').", "exp_te": "చార్లెస్ స్పియర్‌మ్యాన్ 1904లో ప్రజ్ఞా ద్వికారక సిద్ధాంతాన్ని ప్రతిపాదించారు. ప్రజ్ఞలో సాధారణ కారకం ('g' factor) మరియు నిర్దిష్ట కారకాలు ('s' factors) ఉంటాయని ఆయన పేర్కొన్నారు."}, {"id": 11, "sec": "Special Education", "passage": "", "q_en": "Multiple Intelligence means", "q_te": "బహుళ ప్రజ్ఞ అనగా", "opts": [{"en": "Proficiency towards one sector", "te": "కేవలం ఒకే రంగంలో నైపుణ్యం ఉండటం", "raw": "Proficiency towards one sector / కేవలం ఒకే రంగంలో నైపుణ్యం ఉండటం"}, {"en": "No proficiency in any sector", "te": "ఏ రంగంలోనూ నైపుణ్యం లేకపోవడం", "raw": "No proficiency in any sector / ఏ రంగంలోనూ నైపుణ్యం లేకపోవడం"}, {"en": "Proficiency towards two or more sectors", "te": "రెండు లేదా అంతకంటే ఎక్కువ రంగాలలో నైపుణ్యాలు కలిగి ఉండటం", "raw": "Proficiency towards two or more sectors / రెండు లేదా అంతకంటే ఎక్కువ రంగాలలో నైపుణ్యాలు కలిగి ఉండటం"}, {"en": "Proficiency towards one language only", "te": "ఒకే భాషలో మాత్రమే నైపుణ్యం కలిగి ఉండటం", "raw": "Proficiency towards one language only / ఒకే భాషలో మాత్రమే నైపుణ్యం కలిగి ఉండటం"}], "ans": 3, "exp_en": "Howard Gardner's Theory of Multiple Intelligences suggests people possess different kinds of minds and can display exceptional capabilities across multiple distinct domains (linguistic, musical, spatial, bodily, etc.).", "exp_te": "హోవార్డ్ గార్డనర్ ప్రతిపాదించిన బహుళ ప్రజ్ఞా సిద్ధాంతం ప్రకారం వ్యక్తులు కేవలం ఒకే రకమైన ప్రజ్ఞను కాకుండా విభిన్న రంగాలలో (భాష, గణితం, సంగీతం, శారీరక మొదలైన బహుళ నైపుణ్యాలలో) ప్రావీణ్యం కలిగి ఉంటారు."}, {"id": 12, "sec": "Special Education", "passage": "", "q_en": "Self description means", "q_te": "స్వీయ వర్ణన (Self description) అనగా", "opts": [{"en": "Describe about Teacher", "te": "ఉపాధ్యాయుని గురించి వివరించడం", "raw": "Describe about Teacher / ఉపాధ్యాయుని గురించి వివరించడం"}, {"en": "Describe about Country", "te": "దేశం గురించి వివరించడం", "raw": "Describe about Country / దేశం గురించి వివరించడం"}, {"en": "Describe about him/her self", "te": "వ్యక్తి తనను తాను వివరించుకోవడం (స్వయం గురించి)", "raw": "Describe about him/her self / వ్యక్తి తనను తాను వివరించుకోవడం (స్వయం గురించి)"}, {"en": "Describe about friend", "te": "స్నేహితుని గురించి వివరించడం", "raw": "Describe about friend / స్నేహితుని గురించి వివరించడం"}], "ans": 3, "exp_en": "Self-description is an introspective psychological assessment technique where an individual portrays their own traits, feelings, strengths, and weaknesses.", "exp_te": "స్వీయ వర్ణన అనగా ఒక వ్యక్తి తన స్వంత ఆలోచనలు, భావోద్వేగాలు, బలహీనతలు మరియు వ్యక్తిత్వాన్ని తనకు తానే వర్ణించుకోవడం."}, {"id": 13, "sec": "Special Education", "passage": "", "q_en": "Major Causes of Individual Differences among Students", "q_te": "విద్యార్థులలో వైయుక్తిక భేదాలకు ప్రధాన కారణాలు", "opts": [{"en": "Heredity, Environment", "te": "వంశపారంపర్యం (అనువంశికత), పరిసరం", "raw": "Heredity, Environment / వంశపారంపర్యం (అనువంశికత), పరిసరం"}, {"en": "Research, Experiments", "te": "పరిశోధనలు, ప్రయోగాలు", "raw": "Research, Experiments / పరిశోధనలు, ప్రయోగాలు"}, {"en": "Food", "te": "ఆహారం", "raw": "Food / ఆహారం"}, {"en": "Sleep, Strength", "te": "నిద్ర, శారీరక బలం", "raw": "Sleep, Strength / నిద్ర, శారీరక బలం"}], "ans": 1, "exp_en": "Individual differences in intelligence, personality, and physical capabilities arise from the dynamic interaction between genetic inheritance (Heredity) and life experiences (Environment).", "exp_te": "వ్యక్తుల మధ్య కనిపించే భేదాలకు జన్యుపరమైన అనువంశికత (Heredity) మరియు వారు పెరిగే భౌతిక, సాంఘిక పరిసరం (Environment) ల పరస్పర చర్యనూ ప్రాథమిక కారణంగా చెప్పవచ్చు."}, {"id": 14, "sec": "Special Education", "passage": "", "q_en": "Level, Range, Area, and Speed are the attributes of Intelligence described in this theory", "q_te": "స్థాయి (Level), శ్రేణి/వ్యాప్తి (Range), విస్తీర్ణం (Area) వంటి లక్షణాలు కనిపించే ప్రజ్ఞా సిద్ధాంతం", "opts": [{"en": "Two Factor Theory", "te": "ద్వికారక సిద్ధాంతం", "raw": "Two Factor Theory / ద్వికారక సిద్ధాంతం"}, {"en": "Uni Factor Theory", "te": "ఏకకారక సిద్ధాంతం", "raw": "Uni Factor Theory / ఏకకారక సిద్ధాంతం"}, {"en": "Group Factor Theory", "te": "సమూహ కారక సిద్ధాంతం", "raw": "Group Factor Theory / సమూహ కారక సిద్ధాంతం"}, {"en": "Multi Factor Theory", "te": "బహుకారక సిద్ధాంతం (థార్న్‌డైక్)", "raw": "Multi Factor Theory / బహుకారక సిద్ధాంతం (థార్న్‌డైక్)"}], "ans": 4, "exp_en": "E.L. Thorndike's Multi-Factor Theory of Intelligence characterizes intelligence through four primary dimensions: Level (difficulty), Range (breadth of tasks), Area (total tasks at a level), and Speed.", "exp_te": "ఇ.ఎల్. థార్న్‌డైక్ ప్రతిపాదించిన ప్రజ్ఞా బహుకారక సిద్ధాంతం (Multi-Factor Theory) లో ప్రజ్ఞకు స్థాయి (Level), వ్యాప్తి (Range), వైశాల్యం (Area), మరియు వేగం (Speed) అనే నాలుగు గుణాంశాలు ఉంటాయని వివరించారు."}, {"id": 15, "sec": "Special Education", "passage": "", "q_en": "Intelligence Tests primarily measure this factor according to Two Factor theory", "q_te": "ద్వికారక సిద్ధాంతం ప్రకారం ప్రజ్ఞా పరీక్షలు ప్రధానంగా కొలిచే కారకం", "opts": [{"en": "'G' Factor", "te": "'G' కారకం (సాధారణ ప్రజ్ఞా కారకం)", "raw": "'G' Factor / 'G' కారకం (సాధారణ ప్రజ్ఞా కారకం)"}, {"en": "'S' Factor", "te": "'S' కారకం (నిర్దిష్ట కారకం)", "raw": "'S' Factor / 'S' కారకం (నిర్దిష్ట కారకం)"}, {"en": "'D' Factor", "te": "'D' కారకం", "raw": "'D' Factor / 'D' కారకం"}, {"en": "'P' Factor", "te": "'P' కారకం", "raw": "'P' Factor / 'P' కారకం"}], "ans": 1, "exp_en": "Spearman posited that standardized intelligence tests primarily measure the General Factor ('g'), which underlies all intellectual performance and represents mental energy.", "exp_te": "స్పియర్‌మ్యాన్ సిద్ధాంతం ప్రకారం ప్రామాణిక ప్రజ్ఞా పరీక్షలు అన్ని రకాల మానసిక సామర్థ్యాలకు మూలమైన 'సాధారణ ప్రజ్ఞా కారకం' ('G' Factor - General Mental Ability) ను కొలుస్తాయి."}, {"id": 16, "sec": "Special Education", "passage": "", "q_en": "In the CAVD Intelligence Test of Thorndike, 'A' stands for", "q_te": "థార్న్‌డైక్ యొక్క CAVD ప్రజ్ఞా పరీక్షలో 'A' దేనిని సూచిస్తుంది", "opts": [{"en": "Auto", "te": "ఆటో", "raw": "Auto / ఆటో"}, {"en": "Aquarium", "te": "అక్వేరియం", "raw": "Aquarium / అక్వేరియం"}, {"en": "Arithmetic", "te": "అరిథ్‌మెటిక్ రీజనింగ్ (అంకగణితం)", "raw": "Arithmetic / అరిథ్‌మెటిక్ రీజనింగ్ (అంకగణితం)"}, {"en": "Area", "te": "ఏరియా", "raw": "Area / ఏరియా"}], "ans": 3, "exp_en": "Thorndike's CAVD test measures four cognitive abilities: C = Sentence Completion, A = Arithmetic Reasoning, V = Vocabulary, D = Following Directions.", "exp_te": "థార్న్‌డైక్ CAVD పరీక్ష నాలుగు సామర్థ్యాల సంక్షిప్త రూపం: C = Completion (వాక్య పూరణ), A = Arithmetical reasoning (అంకగణిత తార్కికత), V = Vocabulary (పదజాలం), D = Directions (ఆదేశాల అమలు)."}, {"id": 17, "sec": "Special Education", "passage": "", "q_en": "Flying Aptitude Test is conducted for persons in this profession", "q_te": "ఫ్లయింగ్ ఆప్టిట్యూడ్ టెస్ట్ (Flying Aptitude Test) ను ఈ వృత్తి వారికి నిర్వహిస్తారు", "opts": [{"en": "Teacher Profession", "te": "ఉపాధ్యాయ వృత్తి", "raw": "Teacher Profession / ఉపాధ్యాయ వృత్తి"}, {"en": "Doctor Profession", "te": "వైద్య వృత్తి", "raw": "Doctor Profession / వైద్య వృత్తి"}, {"en": "Air Force Profession", "te": "వైమానిక దళం (ఎయిర్ ఫోర్స్ / పైలట్లు)", "raw": "Air Force Profession / వైమానిక దళం (ఎయిర్ ఫోర్స్ / పైలట్లు)"}, {"en": "Postal Service", "te": "తపాలా సేవలు", "raw": "Postal Service / తపాలా సేవలు"}], "ans": 3, "exp_en": "Pilot Aptitude and Flying Aptitude Tests assess spatial orientation, sensory-motor coordination, and reaction time required for Air Force pilots.", "exp_te": "వైమానిక దళంలో పైలట్లుగా పనిచేసే అభ్యర్థులకు అవసరమైన ప్రాదేశిక దిశాజ్ఞానం, వేగవంతమైన ప్రతిస్పందన సమన్వయాన్ని పరీక్షించడానికి ఎయిర్ ఫోర్స్ విభాగంలో ఈ పరీక్ష నిర్వహిస్తారు."}, {"id": 18, "sec": "Special Education", "passage": "", "q_en": "Albinism means", "q_te": "ఆల్బినిజం (Albinism) అనగా", "opts": [{"en": "Loss of pigment (Melanin)", "te": "శరీరంలో వర్ణద్రవ్యం (మెలనిన్) లోపించడం", "raw": "Loss of pigment (Melanin) / శరీరంలో వర్ణద్రవ్యం (మెలనిన్) లోపించడం"}, {"en": "Eye Test", "te": "కంటి పరీక్ష", "raw": "Eye Test / కంటి పరీక్ష"}, {"en": "Squint Eye", "te": "మెల్లకన్ను", "raw": "Squint Eye / మెల్లకన్ను"}, {"en": "Glaucoma", "te": "గ్లాకోమా", "raw": "Glaucoma / గ్లాకోమా"}], "ans": 1, "exp_en": "Albinism is a congenital genetic disorder characterized by the complete or partial absence of melanin pigment in the skin, hair, and eyes, often accompanied by visual impairments.", "exp_te": "ఆల్బినిజం అనేది ఒక జన్యుపరమైన రుగ్మత. దీనిలో శరీరంలో మెలనిన్ (Melanin) అనే వర్ణద్రవ్యం ఉత్పత్తి లోపించడం వలన చర్మం, జుట్టు మరియు కనుగుడ్డు రంగు పాలిపోయి దృష్టి లోపాలు కలుగుతాయి."}, {"id": 19, "sec": "Special Education", "passage": "", "q_en": "'Snellen Chart / Test' is conducted to examine this organ", "q_te": "'స్నెల్లెన్ చార్ట్ / పరీక్ష' ను ఈ శరీర అవయవానికి నిర్వహిస్తారు", "opts": [{"en": "Nose", "te": "ముక్కు", "raw": "Nose / ముక్కు"}, {"en": "Ear", "te": "చెవి", "raw": "Ear / చెవి"}, {"en": "Eye", "te": "కన్ను (దృష్టి సామర్థ్యం)", "raw": "Eye / కన్ను (దృష్టి సామర్థ్యం)"}, {"en": "Skin", "te": "చర్మం", "raw": "Skin / చర్మం"}], "ans": 3, "exp_en": "The Snellen chart, created by Dutch ophthalmologist Herman Snellen, measures visual acuity of the eyes at a distance of 20 feet (6 meters).", "exp_te": "స్నెల్లెన్ చార్ట్ అనేది కంటి దృష్టి సామర్థ్యాన్ని (Visual Acuity) 20 అడుగుల (6 మీటర్ల) దూరం నుండి ప్రామాణికంగా కొలవడానికి ఉపయోగించే కంటి పరీక్ష."}, {"id": 20, "sec": "Special Education", "passage": "", "q_en": "According to Guilford, the process of producing something novel and innovative is called", "q_te": "గిల్‌ఫోర్డ్ ప్రకారం, నూతన భావనలతో సరికొత్త అంశాలను సృష్టించే ప్రక్రియను ఏమంటారు", "opts": [{"en": "Thinking", "te": "సాధారణ ఆలోచన", "raw": "Thinking / సాధారణ ఆలోచన"}, {"en": "Creativity", "te": "సృజనాత్మకత (Creativity)", "raw": "Creativity / సృజనాత్మకత (Creativity)"}, {"en": "Attitude", "te": "వైఖరి", "raw": "Attitude / వైఖరి"}, {"en": "Interest", "te": "ఆసక్తి", "raw": "Interest / ఆసక్తి"}], "ans": 2, "exp_en": "J.P. Guilford defined Creativity through divergent thinking, which involves fluency, flexibility, originality, and the ability to produce novel solutions.", "exp_te": "జె.పి. గిల్‌ఫోర్డ్ ప్రకారం నూతనమైన, మౌలికమైన, వైవిధ్యభరితమైన పరిష్కారాలు లేదా ఉత్పత్తులను రూపొందించే మానసిక ప్రక్రియను 'సృజనాత్మకత' (Creativity / భిన్న ఆలోచన) అంటారు."}, {"id": 21, "sec": "Special Education", "passage": "", "q_en": "An infant identifying 'Mother' among family members refers to this learning", "q_te": "శిశువు కుటుంబ సభ్యులలో తన 'తల్లి'ని వేరుగా గుర్తించగలగడం ఏ అభ్యసనానికి చెందుతుంది", "opts": [{"en": "Verbal Learning", "te": "శాబ్దిక అభ్యసనం", "raw": "Verbal Learning / శాబ్దిక అభ్యసనం"}, {"en": "Environmental Learning", "te": "పరిసరాల అభ్యసనం", "raw": "Environmental Learning / పరిసరాల అభ్యసనం"}, {"en": "Discrimination Learning", "te": "విచక్షణాయుత అభ్యసనం (Discrimination Learning)", "raw": "Discrimination Learning / విచక్షణాయుత అభ్యసనం (Discrimination Learning)"}, {"en": "Artificial Learning", "te": "కృత్రిమ అభ్యసనం", "raw": "Artificial Learning / కృత్రిమ అభ్యసనం"}], "ans": 3, "exp_en": "Discrimination learning occurs when an organism learns to respond differently to different stimuli (recognizing the specific mother's face and voice distinct from other faces).", "exp_te": "శిశువు కుటుంబంలోని ఇతరులతో పోల్చి తన తల్లిని ప్రత్యేకంగా పోల్చుకోగలగడం అనేది ప్రేరణల మధ్య తేడాలను గుర్తించే 'విచక్షణాయుత అభ్యసనం' (Discrimination Learning) అవుతుంది."}, {"id": 22, "sec": "Special Education", "passage": "", "q_en": "Name of the Chimpanzee used in Insightful Learning experiments by Wolfgang Kohler", "q_te": "వోల్ఫ్‌గ్యాంగ్ కోహ్లర్ అంతర్దృష్టి అభ్యసన ప్రయోగాలలో ఉపయోగించిన చింపాంజీ పేరు", "opts": [{"en": "Masthana", "te": "మస్తానా", "raw": "Masthana / మస్తానా"}, {"en": "Sumathi", "te": "సుమతి", "raw": "Sumathi / సుమతి"}, {"en": "Maneesha", "te": "మనీషా", "raw": "Maneesha / మనీషా"}, {"en": "Sultan / Sultana", "te": "సుల్తాన్ (Sultan / Sultana)", "raw": "Sultan / Sultana / సుల్తాన్ (Sultan / Sultana)"}], "ans": 4, "exp_en": "Gestalt psychologist Wolfgang Kohler famously tested Insightful Learning using a chimpanzee named Sultan, who successfully joined sticks and stacked boxes to reach bananas.", "exp_te": "గెస్టాల్ట్ మనోవిజ్ఞానవేత్త అయిన వోల్ఫ్‌గ్యాంగ్ కోహ్లర్ తన అంతర్దృష్టి అభ్యసన (Insightful Learning) ప్రయోగాలలో 'సుల్తాన్' (Sultan) అనే తెలివైన చింపాంజీని ఉపయోగించారు."}, {"id": 23, "sec": "Special Education", "passage": "", "q_en": "The theory explaining that learning transfer is possible due to identical elements between tasks is", "q_te": "రెండు అంశాల మధ్య సారూప్యత మరియు ఉమ్మడి అంశాలు ఉన్నప్పుడు అభ్యసన బదలాయింపు సాధ్యమవుతుందని తెలిపే సిద్ధాంతం", "opts": [{"en": "Theory of Identical Elements (Similar Components)", "te": "సారూప్య / సమరూప మూలకాల సిద్ధాంతం (థార్న్‌డైక్)", "raw": "Theory of Identical Elements (Similar Components) / సారూప్య / సమరూప మూలకాల సిద్ధాంతం (థార్న్‌డైక్)"}, {"en": "Theory of Generalisation", "te": "సాధారణీకరణ సిద్ధాంతం (జడ్)", "raw": "Theory of Generalisation / సాధారణీకరణ సిద్ధాంతం (జడ్)"}, {"en": "Gestaltean Transposition Theory", "te": "గెస్టాల్ట్ బదలాయింపు సిద్ధాంతం", "raw": "Gestaltean Transposition Theory / గెస్టాల్ట్ బదలాయింపు సిద్ధాంతం"}, {"en": "Theory of Ideals", "te": "ఆదర్శాల సిద్ధాంతం (బాగ్లే)", "raw": "Theory of Ideals / ఆదర్శాల సిద్ధాంతం (బాగ్లే)"}], "ans": 1, "exp_en": "E.L. Thorndike formulated the Theory of Identical Elements, stating that transfer of learning occurs only when there are common elements and identical components between the original and new situations.", "exp_te": "థార్న్‌డైక్ ప్రతిపాదించిన 'సమరూప మూలకాల సిద్ధాంతం' (Theory of Identical Elements) ప్రకారం పూర్వ అభ్యసనానికి, నూతన అభ్యసనానికి మధ్య ఉమ్మడి లేదా సారూప్య అంశాలు ఉన్నప్పుడే బదలాయింపు జరుగుతుంది."}, {"id": 24, "sec": "Special Education", "passage": "", "q_en": "Knowledge of Sanskrit language helping in learning associated Indian languages is an example of", "q_te": "సంస్కృత భాషా పరిజ్ఞానం ఇతర భారతీయ భాషలను సులభంగా నేర్చుకోవడానికి తోడ్పడటం ఏ అభ్యసన బదలాయింపు", "opts": [{"en": "Positive Transfer", "te": "అనుకూల బదలాయింపు (Positive Transfer)", "raw": "Positive Transfer / అనుకూల బదలాయింపు (Positive Transfer)"}, {"en": "Zero Transfer", "te": "శూన్య బదలాయింపు", "raw": "Zero Transfer / శూన్య బదలాయింపు"}, {"en": "Negative Transfer", "te": "ప్రతికూల బదలాయింపు", "raw": "Negative Transfer / ప్రతికూల బదలాయింపు"}, {"en": "Training Transfer", "te": "శిక్షణా బదలాయింపు", "raw": "Training Transfer / శిక్షణా బదలాయింపు"}], "ans": 1, "exp_en": "Positive transfer of learning occurs when prior learning facilitates, enhances, or aids in the acquisition of a new skill or knowledge.", "exp_te": "ఒక రంగంలో నేర్చుకున్న జ్ఞానం మరొక నూతన అభ్యసనానికి తోడ్పడితే దానిని 'అనుకూల బదలాయింపు' (Positive Transfer of Learning) అంటారు."}, {"id": 25, "sec": "Special Education", "passage": "", "q_en": "Solitary Play starts at this developmental stage", "q_te": "ఏకాంత క్రీడ (Solitary Play) ప్రారంభమయ్యే దశ", "opts": [{"en": "Early stage / Infancy", "te": "ప్రారంభ దశ (శైశవ దశ / Early Stage)", "raw": "Early stage / Infancy / ప్రారంభ దశ (శైశవ దశ / Early Stage)"}, {"en": "Late Childhood", "te": "ఉత్తర బాల్యదశ", "raw": "Late Childhood / ఉత్తర బాల్యదశ"}, {"en": "Old age", "te": "వృద్ధాప్యం", "raw": "Old age / వృద్ధాప్యం"}, {"en": "Adolescence stage", "te": "కౌమార దశ", "raw": "Adolescence stage / కౌమార దశ"}], "ans": 1, "exp_en": "Mildred Parten's stages of play state that Solitary Play (playing alone independently without interacting with others) typically begins in infancy and toddlerhood (under 2 years).", "exp_te": "మిల్డ్రెడ్ పార్టెన్ క్రీడా వర్గీకరణ ప్రకారం, ఇతరులతో సంబంధం లేకుండా తనంతట తాను ఒంటరిగా ఆడుకునే 'ఏకాంత క్రీడ' శైశవ/ప్రారంభ దశ (Infancy / Early stage) లో మొదలవుతుంది."}, {"id": 26, "sec": "Special Education", "passage": "", "q_en": "The performance test where pictures/cards are arranged in chronological order to form a story is", "q_te": "కార్డులు లేదా బొమ్మలను సరైన క్రమంలో అమర్చి కథను రూపొందించే ప్రజ్ఞా పరీక్ష", "opts": [{"en": "Picture Completion Test", "te": "చిత్ర పూరణ పరీక్ష", "raw": "Picture Completion Test / చిత్ర పూరణ పరీక్ష"}, {"en": "Block Design Test", "te": "బ్లాక్ డిజైన్ పరీక్ష", "raw": "Block Design Test / బ్లాక్ డిజైన్ పరీక్ష"}, {"en": "Picture Arrangement Test", "te": "చిత్ర అమరిక పరీక్ష (Picture Arrangement Test)", "raw": "Picture Arrangement Test / చిత్ర అమరిక పరీక్ష (Picture Arrangement Test)"}, {"en": "Object Assembly", "te": "వస్తు అనుసంధాన పరీక్ష", "raw": "Object Assembly / వస్తు అనుసంధాన పరీక్ష"}], "ans": 3, "exp_en": "The Picture Arrangement Test (part of the Wechsler Adult Intelligence Scale - WAIS) requires the test-taker to arrange a series of pictures sequentially to tell a logical story.", "exp_te": "వెకస్లర్ ప్రజ్ఞా పరీక్షలలో భాగమైన 'చిత్ర అమరిక పరీక్ష' (Picture Arrangement Test) లో చిత్రాలను కాలక్రమానుసారం అమర్చి ఒక అర్థవంతమైన కథను రూపొందించాల్సి ఉంటుంది."}, {"id": 27, "sec": "Special Education", "passage": "", "q_en": "Identify the test that is NOT a Group Intelligence Test from the following", "q_te": "క్రింది వానిలో సమూహ ప్రజ్ఞా పరీక్ష కానిది (వ్యక్తిగత పరీక్ష అయినది) ఏది", "opts": [{"en": "Binet - Simon Tests", "te": "బినే - సైమన్ పరీక్ష (వ్యక్తిగత పరీక్ష)", "raw": "Binet - Simon Tests / బినే - సైమన్ పరీక్ష (వ్యక్తిగత పరీక్ష)"}, {"en": "Army Alpha Test", "te": "ఆర్మీ ఆల్ఫా పరీక్ష", "raw": "Army Alpha Test / ఆర్మీ ఆల్ఫా పరీక్ష"}, {"en": "Army Beta Test", "te": "ఆర్మీ బీటా పరీక్ష", "raw": "Army Beta Test / ఆర్మీ బీటా పరీక్ష"}, {"en": "Raven's Standard Progressive Matrices Test", "te": "రావెన్స్ ప్రోగ్రెసివ్ మ్యాట్రిసెస్ పరీక్ష", "raw": "Raven's Standard Progressive Matrices Test / రావెన్స్ ప్రోగ్రెసివ్ మ్యాట్రిసెస్ పరీక్ష"}], "ans": 1, "exp_en": "The Binet-Simon Intelligence Scale (1905) is an Individual intelligence test administered to one child at a time, whereas Army Alpha, Army Beta, and Raven's SPM can be administered in groups.", "exp_te": "బినే-సైమన్ పరీక్ష అనేది ఒకేసారి ఒక్కరికే నిర్వహించే 'వ్యక్తిగత ప్రజ్ఞా పరీక్ష'. మిగిలిన ఆర్మీ ఆల్ఫా, ఆర్మీ బీటా, రావెన్స్ వంటివి సమూహ పరీక్షలు."}, {"id": 28, "sec": "Special Education", "passage": "", "q_en": "A psychological state that energizes, directs, and sustains goal-oriented action is called", "q_te": "నిర్దిష్ట లక్ష్యాల దిశగా చర్యలను ఉత్తేజపరిచే అంతర్గత లేదా బాహ్య ప్రేరక శక్తి", "opts": [{"en": "Motivation", "te": "ప్రేరణ (Motivation)", "raw": "Motivation / ప్రేరణ (Motivation)"}, {"en": "Aptitude", "te": "సహజ సామర్థ్యం", "raw": "Aptitude / సహజ సామర్థ్యం"}, {"en": "Attitude", "te": "వైఖరి", "raw": "Attitude / వైఖరి"}, {"en": "Memory", "te": "స్మృతి", "raw": "Memory / స్మృతి"}], "ans": 1, "exp_en": "Motivation is the internal psychological condition or external incentive that initiates, guides, and maintains target-directed behavior.", "exp_te": "ఒక వ్యక్తి నిర్దిష్టమైన లక్ష్యాలను సాధించడానికి కార్యోన్ముఖుడిని చేసే మానసిక ఉత్ప్రేరకాన్ని 'ప్రేరణ' (Motivation) అంటారు."}, {"id": 29, "sec": "Special Education", "passage": "", "q_en": "Involuntary muscle tightness, stiffness, and resistance to movement in Cerebral Palsy is called", "q_te": "సెరిబ్రల్ పాల్సీలో కండరాల బిగుతుదనం మరియు కదలికలకు తీవ్ర ప్రతిఘటన కనిపించే రుగ్మత", "opts": [{"en": "Athetosis", "te": "ఎథెటోసిస్", "raw": "Athetosis / ఎథెటోసిస్"}, {"en": "Spasticity", "te": "స్పాస్టిసిటీ (Spasticity / బిగుసుకుపోవుట)", "raw": "Spasticity / స్పాస్టిసిటీ (Spasticity / బిగుసుకుపోవుట)"}, {"en": "Rigidity", "te": "రిజిడిటీ", "raw": "Rigidity / రిజిడిటీ"}, {"en": "Ataxia", "te": "అటాక్సియా", "raw": "Ataxia / అటాక్సియా"}], "ans": 2, "exp_en": "Spastic Cerebral Palsy is the most common form, marked by hypertonia (excessive muscle stiffness and tension) leading to jerky, awkward, and rigid movements.", "exp_te": "సెరిబ్రల్ పాల్సీ (మస్తిష్క పక్షవాతం) లో స్పాస్టిసిటీ (Spasticity) ఉన్న పిల్లలలో కండరాలు నిరంతరం బిగుసుకుపోయి, కాళ్ళు చేతులు వంగక తీవ్ర ఇబ్బంది కలుగుతుంది."}, {"id": 30, "sec": "Special Education", "passage": "", "q_en": "Cataract is a condition observed in this disability", "q_te": "కంటిలో శుక్లాలు (Cataract) ఏర్పడటం ఈ వైకల్యానికి సంబంధించినది", "opts": [{"en": "Hearing Impairment", "te": "శ్రవణ లోపం", "raw": "Hearing Impairment / శ్రవణ లోపం"}, {"en": "Locomotor Disability", "te": "చలన వైకల్యం", "raw": "Locomotor Disability / చలన వైకల్యం"}, {"en": "Visual Impairment", "te": "దృష్టి లోపం (Visual Impairment)", "raw": "Visual Impairment / దృష్టి లోపం (Visual Impairment)"}, {"en": "Intellectual Disability", "te": "మేధోపరమైన వైకల్యం", "raw": "Intellectual Disability / మేధోపరమైన వైకల్యం"}], "ans": 3, "exp_en": "Cataract is the clouding or opacification of the natural lens of the eye, which blocks light and causes partial or complete visual impairment.", "exp_te": "కంటిలోని సహజ లెన్స్ మసకబారడం (శుక్లాలు ఏర్పడటం) వలన కాంతి ప్రసరణ తగ్గి దృష్టి లోపం (Visual Impairment) సంభవిస్తుంది."}, {"id": 31, "sec": "Special Education", "passage": "", "q_en": "The learning difficulties Dysgraphia and Agraphia come under", "q_te": "డిస్‌గ్రాఫియా (Dysgraphia) మరియు ఆగ్రాఫియా (Agraphia) అనే అభ్యసన వైకల్యాలు దేనికి సంబంధించినవి", "opts": [{"en": "Oral language disabilities", "te": "మౌఖిక భాషా వైకల్యాలు", "raw": "Oral language disabilities / మౌఖిక భాషా వైకల్యాలు"}, {"en": "Reading disabilities", "te": "పఠన వైకల్యాలు (రీడింగ్)", "raw": "Reading disabilities / పఠన వైకల్యాలు (రీడింగ్)"}, {"en": "Writing disabilities", "te": "లేఖన వైకల్యాలు (రాత సంబంధిత / Writing Disabilities)", "raw": "Writing disabilities / లేఖన వైకల్యాలు (రాత సంబంధిత / Writing Disabilities)"}, {"en": "Arithmetic disabilities", "te": "గణిత వైకల్యాలు", "raw": "Arithmetic disabilities / గణిత వైకల్యాలు"}], "ans": 3, "exp_en": "Dysgraphia (impairment in handwriting, spelling, and fine-motor writing ability) and Agraphia (total loss of writing ability due to brain damage) are writing disabilities.", "exp_te": "డిస్‌గ్రాఫియా మరియు ఆగ్రాఫియా అనేవి రాత సంబంధిత (Writing Disabilities) లోపాలు. వీటిలో చేతిరాత స్పష్టత లేకపోవడం, అక్షరాలను సరిగ్గా రాయలేకపోవడం జరుగుతుంది."}, {"id": 32, "sec": "Special Education", "passage": "", "q_en": "Myopia (Nearsightedness) means", "q_te": "హ్రస్వదృష్టి (మయోపియా / Myopia) అనగా", "opts": [{"en": "Cannot see objects completely", "te": "వస్తువులను అస్సలు చూడలేకపోవడం", "raw": "Cannot see objects completely / వస్తువులను అస్సలు చూడలేకపోవడం"}, {"en": "Can see objects blurry", "te": "అన్ని వస్తువులూ మసకగా కనిపించడం", "raw": "Can see objects blurry / అన్ని వస్తువులూ మసకగా కనిపించడం"}, {"en": "Can see close objects clearly but distant objects blurry", "te": "దగ్గరి వస్తువులను స్పష్టంగా చూడగలగడం, దూరపు వస్తువులు మసకగా కనిపించడం", "raw": "Can see close objects clearly but distant objects blurry / దగ్గరి వస్తువులను స్పష్టంగా చూడగలగడం, దూరపు వస్తువులు మసకగా కనిపించడం"}, {"en": "Can see distant objects clearly", "te": "దూరపు వస్తువులను మాత్రమే చూడగలగడం", "raw": "Can see distant objects clearly / దూరపు వస్తువులను మాత్రమే చూడగలగడం"}], "ans": 3, "exp_en": "Myopia (short-sightedness) is a refractive defect where light rays focus in front of the retina, allowing clear vision of close objects while distant objects appear blurred.", "exp_te": "హ్రస్వదృష్టి (Myopia) లో కాంతి కిరణాలు రెటీనాకు ముందు కేంద్రీకృతమవడం వలన దగ్గరగా ఉన్న వస్తువులు స్పష్టంగా కనిపిస్తాయి, కానీ దూరపు వస్తువులు అస్పష్టంగా కనిపిస్తాయి."}, {"id": 33, "sec": "Special Education", "passage": "", "q_en": "Difficulty in movement due to continuous muscle stiffness in children with Cerebral palsy is", "q_te": "సెరిబ్రల్ పాల్సీ ఉన్న పిల్లలలో కండరాల విపరీతమైన మొండి బిగుతు వల్ల కదలికలు కష్టతరమవడం", "opts": [{"en": "Rigidity", "te": "రిజిడిటీ (Rigidity / తీవ్ర బిరుసుతనం)", "raw": "Rigidity / రిజిడిటీ (Rigidity / తీవ్ర బిరుసుతనం)"}, {"en": "Dyspraxia", "te": "డిస్‌ప్రాక్సియా", "raw": "Dyspraxia / డిస్‌ప్రాక్సియా"}, {"en": "Ataxia", "te": "అటాక్సియా", "raw": "Ataxia / అటాక్సియా"}, {"en": "Athetosis", "te": "ఎథెటోసిస్", "raw": "Athetosis / ఎథెటోసిస్"}], "ans": 1, "exp_en": "Rigidity in Cerebral Palsy involves severe hypertonia with continuous, lead-pipe or cogwheel resistance to passive movement throughout the entire joint range.", "exp_te": "సెరిబ్రల్ పాల్సీలో 'రిజిడిటీ' అనేది అవయవాలను ఏ దిశలో కదిలించినా స్థిరమైన, తీవ్రమైన కండర ప్రతిఘటన (Lead-pipe resistance) ఉండే పరిస్థితి."}, {"id": 34, "sec": "Special Education", "passage": "", "q_en": "'Cribogram' is an instrument used to", "q_te": "'క్రిబోగ్రామ్' (Cribogram) అనే పరికరాన్ని దేనిని గుర్తించడానికి ఉపయోగిస్తారు", "opts": [{"en": "Identify Visual impairments in Infants", "te": "శిశువులలో దృష్టి లోపాలను గుర్తించడం", "raw": "Identify Visual impairments in Infants / శిశువులలో దృష్టి లోపాలను గుర్తించడం"}, {"en": "Identify Hearing impairments in Infants", "te": "శిశువులలో శ్రవణ (వినికిడి) లోపాలను గుర్తించడం", "raw": "Identify Hearing impairments in Infants / శిశువులలో శ్రవణ (వినికిడి) లోపాలను గుర్తించడం"}, {"en": "Identify Speech impairments in Infants", "te": "శిశువులలో వాక్ లోపాలను గుర్తించడం", "raw": "Identify Speech impairments in Infants / శిశువులలో వాక్ లోపాలను గుర్తించడం"}, {"en": "Identify Locomotor impairments in Infants", "te": "శిశువులలో చలన లోపాలను గుర్తించడం", "raw": "Identify Locomotor impairments in Infants / శిశువులలో చలన లోపాలను గుర్తించడం"}], "ans": 2, "exp_en": "A Crib-o-gram is an automated neonatal hearing screening device placed in an infant's crib that detects physical movement or startle response to auditory stimuli.", "exp_te": "క్రిబోగ్రామ్ (Cribogram) అనేది పసిపిల్లల ఉయ్యాలలో ఉంచి శబ్దాలకు వారి శరీర కదలికలను కొలవడం ద్వారా వినికిడి లోపాలను (Hearing impairments) గుర్తించే పరికరం."}, {"id": 35, "sec": "Special Education", "passage": "", "q_en": "Difficulty in paying attention to any activity even for a short period is a symptom of", "q_te": "ఒక పనిపై కొద్ది సమయం కూడా ఏకాగ్రతను నిలపలేకపోవడం దీని యొక్క ప్రధాన లక్షణం", "opts": [{"en": "Multiple disability", "te": "బహుళ వైకల్యం", "raw": "Multiple disability / బహుళ వైకల్యం"}, {"en": "Hearing impairment", "te": "వినికిడి లోపం", "raw": "Hearing impairment / వినికిడి లోపం"}, {"en": "Visual impairment", "te": "దృష్టి లోపం", "raw": "Visual impairment / దృష్టి లోపం"}, {"en": "Attention Deficit Hyperactivity Disorder (ADHD)", "te": "అటెన్షన్ డెఫిసిట్ హైపర్యాక్టివిటీ డిజార్డర్ (ADHD)", "raw": "Attention Deficit Hyperactivity Disorder (ADHD) / అటెన్షన్ డెఫిసిట్ హైపర్యాక్టివిటీ డిజార్డర్ (ADHD)"}], "ans": 4, "exp_en": "ADHD (Attention Deficit Hyperactivity Disorder) is a neurodevelopmental disorder characterized by persistent inattention, short attention span, impulsivity, and hyperactivity.", "exp_te": "ఏకాగ్రత నిలపలేకపోవడం, అతి చురుకుదనం, తొందరపాటు ప్రవర్తన ఉండే న్యూరో డెవలప్‌మెంటల్ రుగ్మతను ADHD (Attention Deficit Hyperactivity Disorder) అంటారు."}, {"id": 36, "sec": "Special Education", "passage": "", "q_en": "Common characteristic behavior of 'Temper tantrums' is", "q_te": "'టెంపర్ టాన్‌ట్రమ్స్' (Temper Tantrums / తీవ్ర ఆగ్రహావేశం) యొక్క సాధారణ లక్షణం", "opts": [{"en": "Fears", "te": "భయపడటం", "raw": "Fears / భయపడటం"}, {"en": "Nodding Head", "te": "తల ఊపడం", "raw": "Nodding Head / తల ఊపడం"}, {"en": "Rolls on the floor", "te": "నేల మీద పడి దొర్లడం (Rolls on the floor)", "raw": "Rolls on the floor / నేల మీద పడి దొర్లడం (Rolls on the floor)"}, {"en": "Stealing", "te": "దొంగతనం చేయడం", "raw": "Stealing / దొంగతనం చేయడం"}], "ans": 3, "exp_en": "Temper tantrums in young children or children with behavioral disorders feature intense emotional outbursts, crying, screaming, and rolling or flailing on the floor.", "exp_te": "పిల్లలు తీవ్రమైన కోపంతో ఏడుస్తూ, కాళ్ళు చేతులు కొట్టుకుంటూ 'నేల మీద పడి దొర్లడం' (Rolls on the floor) టెంపర్ టాన్‌ట్రమ్స్ యొక్క విలక్షణ లక్షణం."}, {"id": 37, "sec": "Special Education", "passage": "", "q_en": "This is NOT a correct principle of Reinforcement", "q_te": "క్రింది వానిలో పునర్బలన సూత్రం కానిది ఏది", "opts": [{"en": "Immediate reinforcing for the desired behaviour", "te": "ఆశించిన ప్రవర్తన వ్యక్తమైన వెంటనే పునర్బలనం ఇవ్వడం", "raw": "Immediate reinforcing for the desired behaviour / ఆశించిన ప్రవర్తన వ్యక్తమైన వెంటనే పునర్బలనం ఇవ్వడం"}, {"en": "Reinforcement is not based on student's aim or behaviour", "te": "పునర్బలనం అనేది విద్యార్థి ప్రవర్తన లేదా లక్ష్యంతో సంబంధం లేకుండా ఇవ్వడం", "raw": "Reinforcement is not based on student's aim or behaviour / పునర్బలనం అనేది విద్యార్థి ప్రవర్తన లేదా లక్ష్యంతో సంబంధం లేకుండా ఇవ్వడం"}, {"en": "Reinforcing regularly when attains desired behaviour at primary stage", "te": "ప్రారంభ దశలో ప్రతిసారీ క్రమంతప్పకుండా పునర్బలనం ఇవ్వడం", "raw": "Reinforcing regularly when attains desired behaviour at primary stage / ప్రారంభ దశలో ప్రతిసారీ క్రమంతప్పకుండా పునర్బలనం ఇవ్వడం"}, {"en": "Teacher needs to reinforce appropriately after learning", "te": "ప్రత్యేక నైపుణ్యాన్ని సాధించిన తర్వాత క్రమంగా పునర్బలనాన్ని సర్దుబాటు చేయడం", "raw": "Teacher needs to reinforce appropriately after learning / ప్రత్యేక నైపుణ్యాన్ని సాధించిన తర్వాత క్రమంగా పునర్బలనాన్ని సర్దుబాటు చేయడం"}], "ans": 2, "exp_en": "Reinforcement MUST always be contingent upon the specific target behavior. Providing reinforcement without regard to the child's demonstrated behavior violates the fundamental rule of conditioning.", "exp_te": "పునర్బలనం ఎల్లప్పుడూ ఆశించిన ప్రవర్తనపై ఆధారపడి మాత్రమే ఇవ్వాలి. విద్యార్థి ప్రవర్తనతో సంబంధం లేకుండా ఇస్తే అది అభ్యసనానికి ఏమాత్రం తోడ్పడదు."}, {"id": 38, "sec": "Special Education", "passage": "", "q_en": "Applying learned behaviour from one training condition to different situations is called", "q_te": "ఒక నిర్దిష్ట పరిస్థితిలో నేర్చుకున్న ప్రవర్తనను ఇతర విభిన్న పరిస్థితులకు అన్వయించడాన్ని ఏమంటారు", "opts": [{"en": "Summary", "te": "సంగ్రహం", "raw": "Summary / సంగ్రహం"}, {"en": "Discrimination", "te": "విచక్షణ", "raw": "Discrimination / విచక్షణ"}, {"en": "Generalisation", "te": "సాధారణీకరణం (Generalisation)", "raw": "Generalisation / సాధారణీకరణం (Generalisation)"}, {"en": "Environmental changes", "te": "పరిసరాల మార్పు", "raw": "Environmental changes / పరిసరాల మార్పు"}], "ans": 3, "exp_en": "Stimulus Generalization in special education refers to transferring and performing a trained skill in unfamiliar settings, with different people, or across varied stimuli.", "exp_te": "ఒక నిర్దిష్ట పరిస్థితిలో నేర్చుకున్న నైపుణ్యాన్ని సమాజంలోని విభిన్న నూతన సందర్భాలలో అమలు చేయగలగడాన్ని 'సాధారణీకరణం' (Generalisation) అంటారు."}, {"id": 39, "sec": "Special Education", "passage": "", "q_en": "Damage to Wernicke's area and Broca's area of the Brain causes this disability", "q_te": "మెదడులోని వెర్నిక్స్ ప్రాంతం మరియు బ్రోకాస్ ప్రాంతం దెబ్బతినడం వల్ల కలిగే వైకల్యం", "opts": [{"en": "Dyslexia", "te": "డిస్లెక్సియా", "raw": "Dyslexia / డిస్లెక్సియా"}, {"en": "Dysgraphia", "te": "డిస్‌గ్రాఫియా", "raw": "Dysgraphia / డిస్‌గ్రాఫియా"}, {"en": "Aphasia", "te": "ఎఫాసియా (Aphasia / భాషా గ్రహణ-ఉచ్ఛారణ లోపం)", "raw": "Aphasia / ఎఫాసియా (Aphasia / భాషా గ్రహణ-ఉచ్ఛారణ లోపం)"}, {"en": "Dyscalculia", "te": "డిస్‌కాలిక్యులియా", "raw": "Dyscalculia / డిస్‌కాలిక్యులియా"}], "ans": 3, "exp_en": "Broca's area (speech production) and Wernicke's area (language comprehension) damage leads to Aphasia (dysphasia), the impairment of language expression and comprehension.", "exp_te": "మెదడులోని భాషా ఉచ్ఛారణకు తోడ్పడే బ్రోకాస్ మరియు భాషా గ్రహణకు తోడ్పడే వెర్నిక్స్ ప్రాంతాలు దెబ్బతినడం వల్ల 'ఎఫాసియా' (Aphasia - భాషా గ్రహణ లోపం) కలుగుతుంది."}, {"id": 40, "sec": "Special Education", "passage": "", "q_en": "'Padhe Bharat Badhe Bharat' is a nationwide sub-programme of", "q_te": "'పఢే భారత్ బఢే భారత్' అనేది దేని యొక్క ఉప-కార్యక్రమం", "opts": [{"en": "Rashtriya Madhyamika Shiksha Abhiyan (RMSA)", "te": "రాష్ట్రీయ మాధ్యమిక శిక్షా అభియాన్ (RMSA)", "raw": "Rashtriya Madhyamika Shiksha Abhiyan (RMSA) / రాష్ట్రీయ మాధ్యమిక శిక్షా అభియాన్ (RMSA)"}, {"en": "Sarva Shiksha Abhiyan (SSA)", "te": "సర్వ శిక్షా అభియాన్ (SSA)", "raw": "Sarva Shiksha Abhiyan (SSA) / సర్వ శిక్షా అభియాన్ (SSA)"}, {"en": "NCERT", "te": "NCERT", "raw": "NCERT"}, {"en": "CIET", "te": "CIET", "raw": "CIET"}], "ans": 2, "exp_en": "'Padhe Bharat Badhe Bharat' was launched in 2014 as a nationwide sub-programme of Sarva Shiksha Abhiyan (SSA) to ensure early grade reading, writing, and mathematics skills.", "exp_te": "'పఢే భారత్ బఢే భారత్' అనేది ప్రాథమిక తరగతుల్లో పిల్లల పఠనం, లేఖనం, ప్రాథమిక గణిత నైపుణ్యాలను పెంపొందించడానికి సర్వ శిక్షా అభియాన్ (SSA) క్రింద ప్రారంభించిన దేశవ్యాప్త ఉప-కార్యక్రమం."}, {"id": 41, "sec": "Special Education", "passage": "", "q_en": "Inclusive Education for Disabled at Secondary Stage (IEDSS) scheme was implemented from this year", "q_te": "మాధ్యమిక దశలో వికలాంగుల సమ్మిళిత విద్యా పథకం (IEDSS) ఈ సంవత్సరం నుండి అమలులోకి వచ్చింది", "opts": [{"en": "2024-25", "te": "2024-25", "raw": "2024-25"}, {"en": "2020-21", "te": "2020-21", "raw": "2020-21"}, {"en": "2025-26", "te": "2025-26", "raw": "2025-26"}, {"en": "2009-10", "te": "2009-10", "raw": "2009-10"}], "ans": 4, "exp_en": "The Centrally Sponsored Scheme of Inclusive Education for Disabled at Secondary Stage (IEDSS) was launched in 2009-10, replacing the earlier IEDC scheme for classes IX-XII.", "exp_te": "9 నుండి 12వ తరగతి వరకు చదివే వికలాంగ విద్యార్థుల కోసం ఉద్దేశించిన IEDSS (Inclusive Education for Disabled at Secondary Stage) పథకం 2009-10 విద్యా సంవత్సరంలో ప్రారంభమైంది."}, {"id": 42, "sec": "Special Education", "passage": "", "q_en": "The objective of this Commission was to evaluate education's role in the comprehensive development of the country", "q_te": "దేశ సమగ్ర అభివృద్ధిలో విద్య యొక్క పాత్రను పునఃసమీక్షించి సూచనలు చేసిన కమిషన్", "opts": [{"en": "Kothari Commission (1964-66)", "te": "కొఠారి కమిషన్ (1964-66)", "raw": "Kothari Commission (1964-66) / కొఠారి కమిషన్ (1964-66)"}, {"en": "National Education Policy 1986", "te": "జాతీయ విద్యా విధానం 1986", "raw": "National Education Policy 1986 / జాతీయ విద్యా విధానం 1986"}, {"en": "Mudaliar Commission", "te": "ముదలియార్ కమిషన్", "raw": "Mudaliar Commission / ముదలియార్ కమిషన్"}, {"en": "Narasimhan Committee", "te": "నరసింహం కమిటీ", "raw": "Narasimhan Committee / నరసింహం కమిటీ"}], "ans": 1, "exp_en": "The Kothari Commission (1964-66), titled 'Education and National Development', emphasized education as the instrument of economic growth, social change, and national integration.", "exp_te": "డా. డి.ఎస్. కొఠారి అధ్యక్షతన ఏర్పడిన కొఠారి కమిషన్ (1964-66) 'విద్య - జాతీయ వికాసం' అనే నినాదంతో దేశ సమగ్ర ప్రగతిలో విద్య పాత్రను స్పష్టం చేసింది."}, {"id": 43, "sec": "Special Education", "passage": "", "q_en": "A customized instructional plan prepared for a Child with Special Needs (CwSN) by a Special Educator is called", "q_te": "ప్రత్యేక అవసరాలు గల పిల్లల (CwSN) కోసం ప్రత్యేక ఉపాధ్యాయుడు రూపొందించే వ్యక్తిగత విద్యా ప్రణాళిక", "opts": [{"en": "General Plan", "te": "సాధారణ ప్రణాళిక", "raw": "General Plan / సాధారణ ప్రణాళిక"}, {"en": "Individualized Educational Plan (IEP)", "te": "వ్యక్తిగత విద్యా ప్రణాళిక (IEP - Individualized Educational Plan)", "raw": "Individualized Educational Plan (IEP) / వ్యక్తిగత విద్యా ప్రణాళిక (IEP - Individualized Educational Plan)"}, {"en": "Lesson Plan", "te": "పాఠ్య ప్రణాళిక", "raw": "Lesson Plan / పాఠ్య ప్రణాళిక"}, {"en": "Annual Plan", "te": "వార్షిక ప్రణాళిక", "raw": "Annual Plan / వార్షిక ప్రణాళిక"}], "ans": 2, "exp_en": "An Individualized Education Program (IEP) is a tailored legal and instructional document designed specifically to meet the unique learning needs and goals of a child with disabilities.", "exp_te": "ప్రత్యేక అవసరాలు గల ప్రతి విద్యార్థి యొక్క నిర్దిష్ట సామర్థ్యాలు, అవసరాలకు అనుగుణంగా ప్రత్యేకంగా తయారుచేసే ప్రణాళికను వ్యక్తిగత విద్యా ప్రణాళిక (IEP) అంటారు."}, {"id": 44, "sec": "Special Education", "passage": "", "q_en": "Expand IEP", "q_te": "IEP యొక్క పూర్తి రూపం", "opts": [{"en": "Institutional Education Programme", "te": "ఇన్‌స్టిట్యూషనల్ ఎడ్యుకేషన్ ప్రోగ్రామ్", "raw": "Institutional Education Programme / ఇన్‌స్టిట్యూషనల్ ఎడ్యుకేషన్ ప్రోగ్రామ్"}, {"en": "Indian Education Programme", "te": "ఇండియన్ ఎడ్యుకేషన్ ప్రోగ్రామ్", "raw": "Indian Education Programme / ఇండియన్ ఎడ్యుకేషన్ ప్రోగ్రామ్"}, {"en": "Institutional Empowerment Programme", "te": "ఇన్‌స్టిట్యూషనల్ ఎంపవర్‌మెంట్ ప్రోగ్రామ్", "raw": "Institutional Empowerment Programme / ఇన్‌స్టిట్యూషనల్ ఎంపవర్‌మెంట్ ప్రోగ్రామ్"}, {"en": "Individualized Educational Plan / Programme", "te": "ఇండివిడ్యువలైజ్డ్ ఎడ్యుకేషనల్ ప్లాన్ / ప్రోగ్రామ్ (IEP)", "raw": "Individualized Educational Plan / Programme / ఇండివిడ్యువలైజ్డ్ ఎడ్యుకేషనల్ ప్లాన్ / ప్రోగ్రామ్ (IEP)"}], "ans": 4, "exp_en": "IEP stands for Individualized Educational Plan (or Individualized Education Program), a structured roadmap defining special education services, accommodations, and goals.", "exp_te": "IEP అనగా Individualized Educational Plan (వ్యక్తిగత విద్యా ప్రణాళిక). ప్రత్యేక విద్యలో విద్యార్థి అవసరాలకు అనుగుణంగా దీనిని రూపొందిస్తారు."}, {"id": 45, "sec": "Special Education", "passage": "", "q_en": "These are the main baseline components of an IEP", "q_te": "ఒక IEP (వ్యక్తిగత విద్యా ప్రణాళిక) లోని ప్రధాన మౌలిక అంశాలు", "opts": [{"en": "Individual Needs and their Strengths", "te": "విద్యార్థి వ్యక్తిగత అవసరాలు మరియు వారి సామర్థ్యాలు / బలహీనతలు (Needs & Strengths)", "raw": "Individual Needs and their Strengths / విద్యార్థి వ్యక్తిగత అవసరాలు మరియు వారి సామర్థ్యాలు / బలహీనతలు (Needs & Strengths)"}, {"en": "Child relationship with Teacher", "te": "ఉపాధ్యాయునితో విద్యార్థి సంబంధం", "raw": "Child relationship with Teacher / ఉపాధ్యాయునితో విద్యార్థి సంబంధం"}, {"en": "Peer information", "te": "సహచరుల సమాచారం", "raw": "Peer information / సహచరుల సమాచారం"}, {"en": "Marks obtained in exams", "te": "పరీక్షల్లో వచ్చిన మార్కులు", "raw": "Marks obtained in exams / పరీక్షల్లో వచ్చిన మార్కులు"}], "ans": 1, "exp_en": "A standard IEP must begin with the Present Level of Performance (PLOP), identifying the child's unique developmental needs, learning barriers, and individual strengths.", "exp_te": "IEP లో విద్యార్థి యొక్క ప్రస్తుత అభ్యసన స్థాయి, వారి వ్యక్తిగత అవసరాలు (Needs), మరియు వారికున్న నైపుణ్యాలు/సామర్థ్యాలు (Strengths) అత్యంత కీలకమైన భాగాలు."}, {"id": 46, "sec": "Special Education", "passage": "", "q_en": "Evaluation of children with special needs should be", "q_te": "ప్రత్యేక అవసరాలు గల పిల్లల మూల్యాంకనం ఇలా ఉండాలి", "opts": [{"en": "Not related with student's observation", "te": "విద్యార్థి పరిశీలనతో సంబంధం లేకుండా ఉండాలి", "raw": "Not related with student's observation / విద్యార్థి పరిశీలనతో సంబంధం లేకుండా ఉండాలి"}, {"en": "No need of Medical certificates", "te": "వైద్య ధ్రువీకరణ పత్రాలు అవసరం లేదు", "raw": "No need of Medical certificates / వైద్య ధ్రువీకరణ పత్రాలు అవసరం లేదు"}, {"en": "Do not consider cumulative records", "te": "సంచిత రికార్డులను పరిగణించకూడదు", "raw": "Do not consider cumulative records / సంచిత రికార్డులను పరిగణించకూడదు"}, {"en": "To be done comprehensively in all aspects and areas", "te": "అన్ని రంగాలు మరియు అంశాలలో సమగ్రంగా జరగాలి (Comprehensive)", "raw": "To be done comprehensively in all aspects and areas / అన్ని రంగాలు మరియు అంశాలలో సమగ్రంగా జరగాలి (Comprehensive)"}], "ans": 4, "exp_en": "Assessment of CwSN must be multidimensional, covering cognitive, physical, socio-emotional, functional, and adaptive domains in a holistic manner.", "exp_te": "ప్రత్యేక అవసరాలు గల పిల్లల మూల్యాంకనం కేవలం రాత పరీక్షలకే పరిమితం కాకుండా, వారి శారీరక, మానసిక, సాంఘిక మరియు అనుకూల ప్రవర్తనలకు సంబంధించిన అన్ని అంశాలలో సమగ్రంగా జరగాలి."}, {"id": 47, "sec": "Special Education", "passage": "", "q_en": "The primary goal of Universal Design for Learning (UDL) is", "q_te": "యూనివర్సల్ డిజైన్ ఫర్ లెర్నింగ్ (UDL) యొక్క ముఖ్య ఉద్దేశం", "opts": [{"en": "Segregating CwSN into separate schools", "te": "ప్రత్యేక అవసరాలు గల పిల్లలను ప్రత్యేక తరగతులకు పరిమితం చేయడం", "raw": "Segregating CwSN into separate schools / ప్రత్యేక అవసరాలు గల పిల్లలను ప్రత్యేక తరగతులకు పరిమితం చేయడం"}, {"en": "Obtaining top marks in standard tests", "te": "ప్రామాణిక పరీక్షల్లో ఎక్కువ మార్కులు సాధించడం", "raw": "Obtaining top marks in standard tests / ప్రామాణిక పరీక్షల్లో ఎక్కువ మార్కులు సాధించడం"}, {"en": "Not providing friendly environment", "te": "స్నేహపూర్వక వాతావరణం కల్పించకపోవడం", "raw": "Not providing friendly environment / స్నేహపూర్వక వాతావరణం కల్పించకపోవడం"}, {"en": "Minimise learning barriers and enhance access for all students", "te": "అభ్యసన అవరోధాలను తగ్గించి విద్యార్థులందరికీ సమాన అవకాశాలు కల్పించడం", "raw": "Minimise learning barriers and enhance access for all students / అభ్యసన అవరోధాలను తగ్గించి విద్యార్థులందరికీ సమాన అవకాశాలు కల్పించడం"}], "ans": 4, "exp_en": "Universal Design for Learning (UDL) provides flexible goals, methods, materials, and assessments that reduce barriers and maximize learning opportunities for all diverse learners.", "exp_te": "UDL ముఖ్య లక్ష్యం తరగతి గదిలోని భిన్న అభ్యసనా సామర్థ్యాలు గల విద్యార్థులందరికీ అభ్యసనంలో ఎదురయ్యే అడ్డంకులను తొలగించి, సమాన అవకాశాలు మరియు సౌలభ్యాన్ని కల్పించడం."}, {"id": 48, "sec": "Special Education", "passage": "", "q_en": "A major pedagogical advantage of Educational Evaluation is", "q_te": "విద్యా మూల్యాంకనం వల్ల కలిగే ప్రధాన ప్రయోజనం", "opts": [{"en": "Helps in taking informed educational decisions", "te": "సరైన విద్యాపరమైన మరియు బోధనా నిర్ణయాలు తీసుకోవడానికి సహాయపడుతుంది", "raw": "Helps in taking informed educational decisions / సరైన విద్యాపరమైన మరియు బోధనా నిర్ణయాలు తీసుకోవడానికి సహాయపడుతుంది"}, {"en": "No change among students", "te": "విద్యార్థులలో ఎటువంటి మార్పు ఉండదు", "raw": "No change among students / విద్యార్థులలో ఎటువంటి మార్పు ఉండదు"}, {"en": "No accountability in academic programmes", "te": "విద్యా కార్యక్రమాలలో జవాబుదారీతనం లోపిస్తుంది", "raw": "No accountability in academic programmes / విద్యా కార్యక్రమాలలో జవాబుదారీతనం లోపిస్తుంది"}, {"en": "Useful only at the beginning level", "te": "కేవలం ప్రారంభ స్థాయిలో మాత్రమే ఉపయోగపడుతుంది", "raw": "Useful only at the beginning level / కేవలం ప్రారంభ స్థాయిలో మాత్రమే ఉపయోగపడుతుంది"}], "ans": 1, "exp_en": "Evaluation provides systematic feedback on student progress, curriculum efficacy, and instructional methods, guiding teachers to make sound diagnostic and remediation decisions.", "exp_te": "మూల్యాంకనం ద్వారా విద్యార్థుల పురోగతిని, బోధనా పద్ధతుల ప్రభావశీలతను తెలుసుకొని, అవసరమైన సవరణాత్మక బోధనా నిర్ణయాలు తీసుకోవడానికి ఉపాధ్యాయులకు తోడ్పడుతుంది."}, {"id": 49, "sec": "Special Education", "passage": "", "q_en": "An effective visual activity to sustain Attention in children with Intellectual Disability is", "q_te": "మేధో వైకల్యం గల పిల్లలలో ఏకాగ్రతను నిలపడానికి అనువైన కృత్యం", "opts": [{"en": "Copy writing", "te": "కాపీ రైటింగ్ రాయించడం", "raw": "Copy writing / కాపీ రైటింగ్ రాయించడం"}, {"en": "Colour matching", "te": "రంగులను జతపరచడం (Colour Matching)", "raw": "Colour matching / రంగులను జతపరచడం (Colour Matching)"}, {"en": "Reading long lesson", "te": "పెద్ద పాఠాలు చదివించడం", "raw": "Reading long lesson / పెద్ద పాఠాలు చదివించడం"}, {"en": "Writing slip test", "te": "స్లిప్ టెస్ట్ రాయించడం", "raw": "Writing slip test / స్లిప్ టెస్ట్ రాయించడం"}], "ans": 2, "exp_en": "Children with intellectual disabilities benefit most from hands-on, concrete sensory tasks like Color Matching, which provide visual structure and enhance sustained focus.", "exp_te": "మేధో వైకల్యం ఉన్న పిల్లలకు అమూర్త అంశాల కంటే రంగులను జతపరచడం (Colour matching) వంటి మూర్తమైన, రంగురంగుల దృశ్య కృత్యాలు ఏకాగ్రతను నిలపడానికి దోహదపడతాయి."}, {"id": 50, "sec": "Special Education", "passage": "", "q_en": "The most suitable experiential method to teach about 'Post Office' to children with special needs is", "q_te": "ప్రత్యేక అవసరాలు గల పిల్లలకు 'పోస్టాఫీసు' గురించి బోధించడానికి అత్యంత అనువైన పద్ధతి", "opts": [{"en": "Project Method / Field Visit", "te": "ప్రాజెక్ట్ పద్ధతి / ప్రత్యక్ష క్షేత్ర పర్యటన (Project Method)", "raw": "Project Method / Field Visit / ప్రాజెక్ట్ పద్ధతి / ప్రత్యక్ష క్షేత్ర పర్యటన (Project Method)"}, {"en": "Imagination Method", "te": "కల్పనా పద్ధతి", "raw": "Imagination Method / కల్పనా పద్ధతి"}, {"en": "Lecture Method", "te": "ఉపన్యాస పద్ధతి", "raw": "Lecture Method / ఉపన్యాస పద్ధతి"}, {"en": "Problem Method", "te": "సమస్యా పరిష్కార పద్ధతి", "raw": "Problem Method / సమస్యా పరిష్కార పద్ధతి"}], "ans": 1, "exp_en": "The Project Method / Field visit provides direct, real-life practical exposure (buying stamps, posting letters), making abstract concepts tangible and memorable for CwSN.", "exp_te": "పోస్టాఫీసుకు నేరుగా తీసుకెళ్లడం లేదా ప్రాజెక్ట్ విధానం (Project Method) ద్వారా ఉత్తరాలు పోస్ట్ చేయడం, స్టాంపులు కొనడం వంటి ప్రత్యక్ష అనుభవాలు కల్పించినప్పుడు పిల్లలు సమగ్రంగా నేర్చుకుంటారు."}, {"id": 51, "sec": "Special Education", "passage": "", "q_en": "The Department of Empowerment of Persons with Disabilities (DEPwD) works under which Ministry?", "q_te": "దివ్యాంగుల సాధికారత విభాగం (DEPwD) ఏ కేంద్ర మంత్రిత్వ శాఖ పరిధిలో పనిచేస్తుంది?", "opts": [{"en": "Ministry of Finance", "te": "ఆర్థిక మంత్రిత్వ శాఖ", "raw": "Ministry of Finance / ఆర్థిక మంత్రిత్వ శాఖ"}, {"en": "Ministry of Social Justice & Empowerment", "te": "సామాజిక న్యాయం మరియు సాధికారత మంత్రిత్వ శాఖ (Ministry of Social Justice & Empowerment)", "raw": "Ministry of Social Justice & Empowerment / సామాజిక న్యాయం మరియు సాధికారత మంత్రిత్వ శాఖ (Ministry of Social Justice & Empowerment)"}, {"en": "Ministry of Labour", "te": "కార్మిక మంత్రిత్వ శాఖ", "raw": "Ministry of Labour / కార్మిక మంత్రిత్వ శాఖ"}, {"en": "Ministry of Law", "te": "న్యాయ మంత్రిత్వ శాఖ", "raw": "Ministry of Law / న్యాయ మంత్రిత్వ శాఖ"}], "ans": 2, "exp_en": "DEPwD (Divyangjan) is a dedicated department operating under the Ministry of Social Justice and Empowerment, Government of India.", "exp_te": "దివ్యాంగుల సంక్షేమం మరియు హక్కుల పరిరక్షణకై భారత ప్రభుత్వంలోని 'సామాజిక న్యాయం మరియు సాధికారత మంత్రిత్వ శాఖ' పరిధిలో DEPwD పనిచేస్తుంది."}, {"id": 52, "sec": "Special Education", "passage": "", "q_en": "The allowance/scholarship that is NOT provided by the Government to Children with Special Needs is", "q_te": "ప్రభుత్వం ప్రత్యేక అవసరాలు గల పిల్లలకు మంజూరు చేయని అలవెన్స్ ఏది", "opts": [{"en": "Academic Scholarships", "te": "విద్యా ఉపకార వేతనాలు (Academic Scholarships)", "raw": "Academic Scholarships / విద్యా ఉపకార వేతనాలు (Academic Scholarships)"}, {"en": "Reader Allowance", "te": "రీడర్ అలవెన్స్ (చదివి వినిపించే భత్యం)", "raw": "Reader Allowance / రీడర్ అలవెన్స్ (చదివి వినిపించే భత్యం)"}, {"en": "Transport Allowance", "te": "రవాణా భత్యం (ట్రాన్స్‌పోర్ట్ అలవెన్స్)", "raw": "Transport Allowance / రవాణా భత్యం (ట్రాన్స్‌పోర్ట్ అలవెన్స్)"}, {"en": "Family Allowance", "te": "ఫ్యామిలీ అలవెన్స్ (కుటుంబ భత్యం)", "raw": "Family Allowance / ఫ్యామిలీ అలవెన్స్ (కుటుంబ భత్యం)"}], "ans": 4, "exp_en": "Under government inclusive education schemes (Samagra Shiksha), individual CwSN receive Reader allowance, Transport allowance, Escort allowance, and Scholarships, but NO 'Family Allowance' exists.", "exp_te": "దివ్యాంగ విద్యార్థులకు ప్రభుత్వం రవాణా, రీడర్, ఎస్కార్ట్ భత్యాలు మరియు స్కాలర్‌షిప్‌లు అందిస్తుంది కానీ 'కుటుంబ భత్యం' (Family Allowance) అనే పథకం లేదు."}, {"id": 53, "sec": "Special Education", "passage": "", "q_en": "The National Institute for Locomotor Disability 'SVNIRTAR' is located in the region of", "q_te": "చలన వైకల్యానికి సంబంధించిన జాతీయ సంస్థ 'SVNIRTAR' ఉన్న ప్రాంతం", "opts": [{"en": "New Delhi", "te": "న్యూఢిల్లీ", "raw": "New Delhi / న్యూఢిల్లీ"}, {"en": "Mumbai", "te": "ముంబై", "raw": "Mumbai / ముంబై"}, {"en": "Kolkata / Cuttack region", "te": "కోల్‌కతా / కటక్ ప్రాంతం (ఒలాట్‌పూర్, ఒడిశా)", "raw": "Kolkata / Cuttack region / కోల్‌కతా / కటక్ ప్రాంతం (ఒలాట్‌పూర్, ఒడిశా)"}, {"en": "Hyderabad", "te": "హైదరాబాద్", "raw": "Hyderabad / హైదరాబాద్"}], "ans": 3, "exp_en": "Swami Vivekanand National Institute of Rehabilitation Training and Research (SVNIRTAR) is located at Olatpur near Cuttack (Eastern region, affiliated/grouped with Kolkata centers in exam options).", "exp_te": "చలన వైకల్యాల పునరావాస మరియు శిక్షణ పరిశోధనా సంస్థ అయిన SVNIRTAR ఒడిశాలోని కటక్ సమీపంలోని ఒలాట్‌పూర్‌లో ఉంది (తూర్పు మండల ప్రధాన కేంద్రం కోల్‌కతా పరిధి)."}, {"id": 54, "sec": "Special Education", "passage": "", "q_en": "'Madrasas' as Special schools for", "q_te": "'మదరసాలు' అనునవి వీరి కోసం ప్రత్యేక పాఠశాలలు", "opts": [{"en": "Christians", "te": "క్రైస్తవులు", "raw": "Christians / క్రైస్తవులు"}, {"en": "Muslims", "te": "ముస్లింలు", "raw": "Muslims / ముస్లింలు"}, {"en": "Buddhists", "te": "బౌద్ధులు", "raw": "Buddhists / బౌద్ధులు"}, {"en": "Jains", "te": "జైనులు", "raw": "Jains / జైనులు"}], "ans": 3, "exp_en": "As per the official SCERT answer key, Option (3) is marked. Historically and educationally, Madrasas (మదరసాలు) are Islamic educational institutions established for Muslim education (Option 2), whereas Buddhist educational centers were known as Viharas or Monasteries. In the official key table, 3 is indicated.", "exp_te": "SCERT అధికారిక 'కీ' ప్రకారం ఐచ్ఛికం (3) గా ఇవ్వబడింది. అయితే చారిత్రకంగా మరియు విద్యాపరంగా 'మదరసాలు' ముస్లింల కోసం ఏర్పడిన సాంప్రదాయ ఇస్లామిక్ విద్యాసంస్థలు (ఐచ్ఛికం 2). బౌద్ధుల విద్యా కేంద్రాలను విహారాలు/సంఘారామాలు అంటారు."}, {"id": 55, "sec": "Special Education", "passage": "", "q_en": "The marks of students in a class are: 35, 60, 78, 99, 46, 55, 69. The Range of this data is", "q_te": "ఒక తరగతిలోని విద్యార్థుల మార్కులు: 35, 60, 78, 99, 46, 55, 69. ఈ దత్తాంశం యొక్క వ్యాప్తి (Range)", "opts": [{"en": "99", "te": "99", "raw": "99"}, {"en": "60", "te": "60", "raw": "60"}, {"en": "64", "te": "64", "raw": "64"}, {"en": "35", "te": "35", "raw": "35"}], "ans": 3, "exp_en": "Range = Maximum Value - Minimum Value = 99 - 35 = 64.", "exp_te": "వ్యాప్తి (Range) = గరిష్ట విలువ - కనిష్ట విలువ = 99 - 35 = 64."}, {"id": 56, "sec": "Special Education", "passage": "", "q_en": "The lower boundary (True Lower Limit) of the class interval 50 - 59 is", "q_te": "50 - 59 తరగతి అంతరం యొక్క దిగువ సరిహద్దు (Lower Boundary)", "opts": [{"en": "50", "te": "50", "raw": "50"}, {"en": "49.5", "te": "49.5", "raw": "49.5"}, {"en": "59", "te": "59", "raw": "59"}, {"en": "59.5", "te": "59.5", "raw": "59.5"}], "ans": 2, "exp_en": "For discrete class intervals (50-59, 60-69), the lower boundary is: Lower Limit - 0.5 = 50 - 0.5 = 49.5.", "exp_te": "విచ్ఛిన్న తరగతి అంతరాలలో దిగువ సరిహద్దు = దిగువ అవధి - 0.5 = 50 - 0.5 = 49.5."}, {"id": 57, "sec": "Special Education", "passage": "", "q_en": "Which of the following is NOT a measure of central tendency?", "q_te": "క్రింది వానిలో కేంద్రీయ ప్రవృత్తి కొలత కానిది ఏది", "opts": [{"en": "Arithmetic Mean", "te": "అంకగణిత సగటు (Mean)", "raw": "Arithmetic Mean / అంకగణిత సగటు (Mean)"}, {"en": "Median", "te": "మధ్యగతం (Median)", "raw": "Median / మధ్యగతం (Median)"}, {"en": "Sets", "te": "సమితులు (Sets)", "raw": "Sets / సమితులు (Sets)"}, {"en": "Mode", "te": "బాహుళకం (Mode)", "raw": "Mode / బాహుళకం (Mode)"}], "ans": 3, "exp_en": "Measures of Central Tendency include Mean, Median, and Mode. 'Sets' is a branch of discrete mathematics, not a statistical average.", "exp_te": "కేంద్రీయ ప్రవృత్తి కొలతలు సగటు (Mean), మధ్యగతం (Median), బాహుళకం (Mode). 'సమితులు' (Sets) అనేది గణిత భావన కానీ కేంద్రీయ ప్రవృత్తి కొలత కాదు."}, {"id": 58, "sec": "Special Education", "passage": "", "q_en": "If the IQ levels of 10 students in a class are 107, 95, 98, 100, 105, 93, 102, 100, 96, and 104, then their average IQ is", "q_te": "ఒక తరగతిలోని 10 మంది విద్యార్థుల ప్రజ్ఞా లబ్ధి వరుసగా 107, 95, 98, 100, 105, 93, 102, 100, 96, 104 అయితే వారి సగటు IQ", "opts": [{"en": "100", "te": "100", "raw": "100"}, {"en": "105", "te": "105", "raw": "105"}, {"en": "102", "te": "102", "raw": "102"}, {"en": "98", "te": "98", "raw": "98"}], "ans": 1, "exp_en": "Average = Sum / Number of items = (107 + 95 + 98 + 100 + 105 + 93 + 102 + 100 + 96 + 104) / 10 = 1000 / 10 = 100.", "exp_te": "సగటు = రాశుల మొత్తం / రాశుల సంఖ్య = 1000 / 10 = 100."}, {"id": 59, "sec": "Special Education", "passage": "", "q_en": "The formula for calculating the Median of grouped data is", "q_te": "వర్గీకృత దత్తాంశపు మధ్యగతాన్ని (Median) కనుగొనే సూత్రం", "opts": [{"en": "Δ1 = f - f1", "te": "Δ1 = f - f1", "raw": "Δ1 = f - f1"}, {"en": "L + [(N/2 - F) / f] × C", "te": "L + [(N/2 - F) / f] × C", "raw": "L + [(N/2 - F) / f] × C"}, {"en": "X̄ = ΣX / N", "te": "X̄ = ΣX / N", "raw": "X̄ = ΣX / N"}, {"en": "X̄ = Σfx / Σf", "te": "X̄ = Σfx / Σf", "raw": "X̄ = Σfx / Σf"}], "ans": 2, "exp_en": "Median of grouped data is calculated as: Median = L + [((N/2) - F) / f] × C, where L is lower limit of median class, N is total frequency, F is cumulative frequency preceding median class, f is frequency of median class, and C is class width.", "exp_te": "వర్గీకృత దత్తాంశంలో మధ్యగతం సూత్రం: L + [(N/2 - F) / f] × C (ఇక్కడ L = మధ్యగత తరగతి దిగువ హద్దు, N = మొత్తం పౌనఃపున్యం, F = సంచిత పౌనఃపున్యం, f = మధ్యగత తరగతి పౌనఃపున్యం, C = తరగతి పొడవు)."}, {"id": 60, "sec": "Special Education", "passage": "", "q_en": "The statistical symbol universally used to represent 'Mode' is", "q_te": "సాంఖ్యక శాస్త్రంలో 'బాహుళకం' (Mode) ను సూచించడానికి ఉపయోగించే ప్రామాణిక గుర్తు", "opts": [{"en": "Q", "te": "Q", "raw": "Q"}, {"en": "M", "te": "M", "raw": "M"}, {"en": "F", "te": "F", "raw": "F"}, {"en": "Z", "te": "Z", "raw": "Z"}], "ans": 4, "exp_en": "In educational statistics: Mean is denoted by M or X̄, Median by Mdn, and Mode is universally represented by the symbol 'Z'.", "exp_te": "గణాంక శాస్త్రంలో అంకగణిత సగటును M లేదా X̄ తోను, మధ్యగతాన్ని Mdn తోను, బాహుళకాన్ని 'Z' అక్షరంతోనూ సూచిస్తారు."}, {"id": 61, "sec": "Special Education", "passage": "", "q_en": "'Basic Education Policy' (Nai Talim / Wardha Scheme) was recommended by", "q_te": "'బేసిక్ విద్యా విధానాన్ని' (వార్ధా విద్యా పథకం / నయీ తాలీమ్) ప్రతిపాదించినది", "opts": [{"en": "Mahatma Gandhi", "te": "మహాత్మా గాంధీ", "raw": "Mahatma Gandhi / మహాత్మా గాంధీ"}, {"en": "Ishwar Chandra Vidyasagar", "te": "ఈశ్వర చంద్ర విద్యాసాగర్", "raw": "Ishwar Chandra Vidyasagar / ఈశ్వర చంద్ర విద్యాసాగర్"}, {"en": "Dr. Radhakrishnan", "te": "డా. సర్వేపల్లి రాధాకృష్ణన్", "raw": "Dr. Radhakrishnan / డా. సర్వేపల్లి రాధాకృష్ణన్"}, {"en": "William Bentinck", "te": "విలియం బెంటింక్", "raw": "William Bentinck / విలియం బెంటింక్"}], "ans": 1, "exp_en": "Mahatma Gandhi formulated the Wardha Scheme of Basic Education (Nai Talim) in 1937, centering education around productive manual craft and mother tongue.", "exp_te": "1937లో మహాత్మా గాంధీ 'బేసిక్ విద్యా విధానాన్ని' (వార్ధా పథకం) ప్రతిపాదించారు. చేతిపనుల ద్వారా మరియు మాతృభాషలో అభ్యసనానికి ఇది ప్రాధాన్యతనిచ్చింది."}, {"id": 62, "sec": "Special Education", "passage": "", "q_en": "The root meaning of the Sanskrit word 'Vid' from which 'Vidya' is derived is", "q_te": "'విద్య' అనే పదం ఉద్భవించిన సంస్కృత మూలధాతువు 'విద్' (Vid) యొక్క అర్థం", "opts": [{"en": "To Explain", "te": "వివరించడం", "raw": "To Explain / వివరించడం"}, {"en": "Campaigning", "te": "ప్రచారం చేయడం", "raw": "Campaigning / ప్రచారం చేయడం"}, {"en": "To Know / Knowledge", "te": "తెలుసుకొనుట (జ్ఞానాన్ని సంపాదించుట / To know)", "raw": "To Know / Knowledge / తెలుసుకొనుట (జ్ఞానాన్ని సంపాదించుట / To know)"}, {"en": "To Rectify", "te": "సరిదిద్దుట", "raw": "To Rectify / సరిదిద్దుట"}], "ans": 3, "exp_en": "The word 'Vidya' is derived from the Sanskrit root 'Vid', which means 'to know', 'to learn', or 'to acquire true knowledge'.", "exp_te": "'విద్య' అనే పదం 'విద్' అనే సంస్కృత ధాతువు నుండి వచ్చింది. 'విద్' అనగా 'తెలుసుకొనుట' లేదా 'జ్ఞానం సంపాదించుట' అని అర్థం."}, {"id": 63, "sec": "Special Education", "passage": "", "q_en": "The 'National Curriculum Framework' (NCF) is formulated and developed by", "q_te": "'జాతీయ పాఠ్యప్రణాళిక చట్రం' (National Curriculum Framework - NCF) ను రూపొందించే సంస్థ", "opts": [{"en": "CABE", "te": "CABE", "raw": "CABE"}, {"en": "NCTE", "te": "NCTE", "raw": "NCTE"}, {"en": "NCERT", "te": "NCERT", "raw": "NCERT"}, {"en": "SCERT", "te": "SCERT", "raw": "SCERT"}], "ans": 3, "exp_en": "NCERT (National Council of Educational Research and Training) is mandated by the Government of India to formulate the National Curriculum Framework (e.g., NCF 2005, NCF 2023).", "exp_te": "భారతదేశంలో పాఠశాల విద్య కోసం జాతీయ పాఠ్యప్రణాళిక చట్రాన్ని (NCF) రూపొందించే అత్యున్నత సంస్థ 'NCERT' (National Council of Educational Research and Training)."}, {"id": 64, "sec": "Special Education", "passage": "", "q_en": "The 10+2+3 Education Pattern was recommended by", "q_te": "10+2+3 విద్యా విధానాన్ని ప్రతిపాదించిన కమిషన్", "opts": [{"en": "Eshwarbhai Patel Committee", "te": "ఈశ్వర్ భాయ్ పటేల్ కమిటీ", "raw": "Eshwarbhai Patel Committee / ఈశ్వర్ భాయ్ పటేల్ కమిటీ"}, {"en": "Kothari Commission", "te": "కొఠారి కమిషన్ (1964-66)", "raw": "Kothari Commission / కొఠారి కమిషన్ (1964-66)"}, {"en": "Secondary Education Commission", "te": "మాధ్యమిక విద్యా కమిషన్ (ముదలియార్)", "raw": "Secondary Education Commission / మాధ్యమిక విద్యా కమిషన్ (ముదలియార్)"}, {"en": "University Education Commission", "te": "విశ్వవిద్యాలయ విద్యా కమిషన్ (రాధాకృష్ణన్)", "raw": "University Education Commission / విశ్వవిద్యాలయ విద్యా కమిషన్ (రాధాకృష్ణన్)"}], "ans": 2, "exp_en": "The Kothari Commission (1964-66) proposed the standardized national educational structure of 10 years of general schooling, 2 years of higher secondary, and 3 years of degree (10+2+3).", "exp_te": "కొఠారి కమిషన్ (1964-66) దేశవ్యాప్తంగా 10 సంవత్సరాల ఉన్నత పాఠశాల, 2 సంవత్సరాల ఇంటర్మీడియట్, 3 సంవత్సరాల డిగ్రీ (10+2+3) విధానాన్ని ప్రతిపాదించింది."}, {"id": 65, "sec": "Special Education", "passage": "", "q_en": "A fundamental guiding principle of NCF 2005 is", "q_te": "జాతీయ పాఠ్యప్రణాళిక చట్రం (NCF 2005) యొక్క ప్రాథమిక మార్గదర్శక సూత్రం", "opts": [{"en": "Making examinations more complex", "te": "పరీక్షలను అత్యంత సంక్లిష్టంగా మార్చడం", "raw": "Making examinations more complex / పరీక్షలను అత్యంత సంక్లిష్టంగా మార్చడం"}, {"en": "Connecting knowledge to life outside the school", "te": "జ్ఞానాన్ని పాఠశాల వెలుపలి నిజ జీవితంతో అనుసంధానించడం", "raw": "Connecting knowledge to life outside the school / జ్ఞానాన్ని పాఠశాల వెలుపలి నిజ జీవితంతో అనుసంధానించడం"}, {"en": "Giving strict punishment to students", "te": "విద్యార్థులను కఠినంగా శిక్షించడం", "raw": "Giving strict punishment to students / విద్యార్థులను కఠినంగా శిక్షించడం"}, {"en": "Encouraging rote learning", "te": "కంఠస్థ పద్ధతులను (బట్టీ పట్టడం) ప్రోత్సహించడం", "raw": "Encouraging rote learning / కంఠస్థ పద్ధతులను (బట్టీ పట్టడం) ప్రోత్సహించడం"}], "ans": 2, "exp_en": "NCF 2005 lays down 5 guiding principles, top among which is 'Connecting knowledge to life outside the school' and moving away from rote memorization.", "exp_te": "NCF 2005 ప్రధాన మార్గదర్శక సూత్రాలలో ముఖ్యమైనది పాఠశాలలో నేర్చుకున్న జ్ఞానాన్ని తరగతి గదికే పరిమితం చేయకుండా బాహ్య సమాజంలోని నిజ జీవిత అనుభవాలతో అనుసంధానించడం."}, {"id": 66, "sec": "Special Education", "passage": "", "q_en": "The project launched to provide integrated educational facilities for children with disabilities was", "q_te": "వికలాంగ పిల్లలకు సమ్మిళిత/సమీకృత విద్యా సౌకర్యాలు కల్పించడానికి ప్రారంభించిన ప్రాజెక్ట్", "opts": [{"en": "Project Girl Education for All (PGEA)", "te": "PGEA ప్రాజెక్ట్", "raw": "Project Girl Education for All (PGEA) / PGEA ప్రాజెక్ట్"}, {"en": "Project Indian Education for Disabled at Adult stage (PIEDA)", "te": "PIEDA ప్రాజెక్ట్", "raw": "Project Indian Education for Disabled at Adult stage (PIEDA) / PIEDA ప్రాజెక్ట్"}, {"en": "Project Individual Education for All (PIEA)", "te": "PIEA ప్రాజెక్ట్", "raw": "Project Individual Education for All (PIEA) / PIEA ప్రాజెక్ట్"}, {"en": "Project Integrated Education for the Disabled (PIED)", "te": "ప్రాజెక్ట్ ఇంటిగ్రేటెడ్ ఎడ్యుకేషన్ ఫర్ ది డిసేబుల్డ్ (PIED)", "raw": "Project Integrated Education for the Disabled (PIED) / ప్రాజెక్ట్ ఇంటిగ్రేటెడ్ ఎడ్యుకేషన్ ఫర్ ది డిసేబుల్డ్ (PIED)"}], "ans": 4, "exp_en": "Project Integrated Education for the Disabled (PIED) was launched in 1987 in collaboration with UNICEF to integrate children with disabilities into regular schools.", "exp_te": "1987లో యునిసెఫ్ (UNICEF) మరియు భారత ప్రభుత్వం సంయుక్తంగా ప్రారంభించిన ప్రాజెక్ట్ 'Project Integrated Education for the Disabled' (PIED)."}, {"id": 67, "sec": "Special Education", "passage": "", "q_en": "The percentage of reservation for Persons with Benchmark Disabilities in Government Higher Educational Institutions as per RPwD Act 2016 is", "q_te": "RPwD చట్టం 2016 ప్రకారం ప్రభుత్వ ఉన్నత విద్యా సంస్థలలో కనీస వైకల్యం గల దివ్యాంగులకు కేటాయించిన రిజర్వేషన్ శాతం", "opts": [{"en": "1%", "te": "1%", "raw": "1%"}, {"en": "3%", "te": "3%", "raw": "3%"}, {"en": "4%", "te": "4%", "raw": "4%"}, {"en": "5%", "te": "5% (ఐదు శాతం)", "raw": "5% / 5% (ఐదు శాతం)"}], "ans": 4, "exp_en": "Section 32 of the Rights of Persons with Disabilities (RPwD) Act, 2016 mandates not less than 5% reservation in all government institutions of higher education, with an upper age relaxation of 5 years.", "exp_te": "దివ్యాంగుల హక్కుల చట్టం (RPwD Act) 2016 లోని సెక్షన్ 32 ప్రకారం ప్రభుత్వ మరియు ప్రభుత్వ సహాయం పొందే ఉన్నత విద్యా సంస్థల సీట్లలో దివ్యాంగులకు 5% రిజర్వేషన్ కేటాయించాలి (ఉద్యోగాలలో 4%)."}, {"id": 68, "sec": "Special Education", "passage": "", "q_en": "Under Right to Education (RTE) Act 2009, 'Right to Free and Compulsory Education' is specified in", "q_te": "ఉచిత నిర్బంధ విద్యా హక్కు చట్టం 2009 ప్రకారం 'ఉచిత నిర్బంధ విద్య పొందే హక్కు' ఏ అధ్యాయంలో పేర్కొనబడింది", "opts": [{"en": "Chapter-I", "te": "అధ్యాయం - I", "raw": "Chapter-I / అధ్యాయం - I"}, {"en": "Chapter-II", "te": "అధ్యాయం - II (Chapter-II)", "raw": "Chapter-II / అధ్యాయం - II (Chapter-II)"}, {"en": "Chapter-IV", "te": "అధ్యాయం - IV", "raw": "Chapter-IV / అధ్యాయం - IV"}, {"en": "Chapter-VII", "te": "అధ్యాయం - VII", "raw": "Chapter-VII / అధ్యాయం - VII"}], "ans": 2, "exp_en": "Chapter-II (Sections 3, 4, 5) of the Right of Children to Free and Compulsory Education Act, 2009 contains the fundamental provisions for the 'Right of Children to Free and Compulsory Education'.", "exp_te": "విద్యా హక్కు చట్టం 2009 లోని అధ్యాయం-II (సెక్షన్లు 3, 4, 5) పిల్లల ఉచిత మరియు నిర్బంధ ప్రాథమిక విద్యా హక్కును వివరిస్తుంది."}, {"id": 69, "sec": "Special Education", "passage": "", "q_en": "Provisions for legal guardianship for persons with Autism, Cerebral Palsy, Mental Retardation, and Multiple Disabilities are laid down in", "q_te": "ఆటిజం, సెరిబ్రల్ పాల్సీ, మానసిక వైకల్యం మరియు బహుళ వైకల్యాలు గల వ్యక్తుల సంరక్షకుల (లీగల్ గార్డియన్) నియామకం గురించి తెలిపే చట్టం", "opts": [{"en": "National Curriculum Framework", "te": "జాతీయ పాఠ్యప్రణాళిక చట్రం", "raw": "National Curriculum Framework / జాతీయ పాఠ్యప్రణాళిక చట్రం"}, {"en": "National Policy on Education", "te": "జాతీయ విద్యా విధానం", "raw": "National Policy on Education / జాతీయ విద్యా విధానం"}, {"en": "National Trust Act, 1999", "te": "నేషనల్ ట్రస్ట్ చట్టం, 1999 (National Trust Act, 1999)", "raw": "National Trust Act, 1999 / నేషనల్ ట్రస్ట్ చట్టం, 1999 (National Trust Act, 1999)"}, {"en": "NCTE Act", "te": "NCTE చట్టం", "raw": "NCTE Act / NCTE చట్టం"}], "ans": 3, "exp_en": "The National Trust Act, 1999 (specifically Section 14) establishes Local Level Committees (LLCs) empowered to appoint legal guardians for adults with Autism, Cerebral Palsy, Intellectual Disability, and Multiple Disabilities.", "exp_te": "నేషనల్ ట్రస్ట్ చట్టం, 1999 ముఖ్యంగా ఆటిజం, సెరిబ్రల్ పాల్సీ, మానసిక మాంద్యం మరియు బహుళ వైకల్యం గల వ్యక్తులకు చట్టబద్ధమైన సంరక్షకులను (Legal Guardians) నియమించే అధికార యంత్రాంగాన్ని కల్పిస్తుంది."}, {"id": 70, "sec": "Special Education", "passage": "", "q_en": "A prominent nationwide sub-programme launched under 'Sarva Shiksha Abhiyan' to foster reading is", "q_te": "సర్వ శిక్షా అభియాన్ కింద పఠన సంస్కృతిని పెంపొందించడానికి ప్రారంభించిన దేశవ్యాప్త ఉప-కార్యక్రమం", "opts": [{"en": "Beti Padhao Beti Bachao", "te": "బేటీ బచావో బేటీ పఢావో", "raw": "Beti Padhao Beti Bachao / బేటీ బచావో బేటీ పఢావో"}, {"en": "Swachh Bharat Swachh Vidyalaya", "te": "స్వచ్ఛ భారత్", "raw": "Swachh Bharat Swachh Vidyalaya / స్వచ్ఛ భారత్"}, {"en": "Padhe Bharat Badhe Bharat", "te": "పఢే భారత్ బఢే భారత్ (Padhe Bharat Badhe Bharat)", "raw": "Padhe Bharat Badhe Bharat / పఢే భారత్ బఢే భారత్ (Padhe Bharat Badhe Bharat)"}, {"en": "Jai Jawan Jai Kisan", "te": "జై జవాన్ జై కిసాన్", "raw": "Jai Jawan Jai Kisan / జై జవాన్ జై కిసాన్"}], "ans": 3, "exp_en": "'Padhe Bharat Badhe Bharat' focuses directly on enhancing early language comprehension, reading fluency, and writing skills among young school learners under SSA.", "exp_te": "'పఢే భారత్ బఢే భారత్' అనేది సర్వ శిక్షా అభియాన్ (SSA) ఆధ్వర్యంలో పాఠశాలల్లో విద్యార్థులకు పఠన, లేఖన నైపుణ్యాలను అభివృద్ధి చేసేందుకు ఉద్దేశించిన కార్యక్రమం."}, {"id": 71, "sec": "Special Education", "passage": "", "q_en": "IEDC Scheme was formulated specifically for", "q_te": "IEDC పథకం ఎవరి కోసం ఉద్దేశించబడింది", "opts": [{"en": "Children with disabilities", "te": "దివ్యాంగ పిల్లలు (Children with disabilities)", "raw": "Children with disabilities / దివ్యాంగ పిల్లలు (Children with disabilities)"}, {"en": "Normal children", "te": "సాధారణ పిల్లలు", "raw": "Normal children / సాధారణ పిల్లలు"}, {"en": "Out of school children", "te": "బడి బయట ఉన్న పిల్లలు", "raw": "Out of school children / బడి బయట ఉన్న పిల్లలు"}, {"en": "HIV victims", "te": "హెచ్.ఐ.వి బాధితులు", "raw": "HIV victims / హెచ్.ఐ.వి బాధితులు"}], "ans": 1, "exp_en": "The Integrated Education for Disabled Children (IEDC) scheme was launched in 1974 by the Ministry of Social Justice and Empowerment (later transferred to Department of Education) to integrate children with mild to moderate disabilities into regular schools.", "exp_te": "IEDC (Integrated Education for Disabled Children) పథకం 1974లో ప్రారంభించబడింది. దివ్యాంగ పిల్లలను సాధారణ పాఠశాలల్లో విద్యావంతులను చేయడం దీని ముఖ్య ఉద్దేశం."}, {"id": 72, "sec": "Special Education", "passage": "", "q_en": "Which of the following is NOT an objective of IEDSS (Inclusive Education for Disabled at Secondary Stage)?", "q_te": "క్రింది వానిలో IEDSS పథకం యొక్క లక్ష్యం కానిది ఏది", "opts": [{"en": "Identify children with disability at secondary stage", "te": "మాధ్యమిక దశలో దివ్యాంగ పిల్లలను గుర్తించడం", "raw": "Identify children with disability at secondary stage / మాధ్యమిక దశలో దివ్యాంగ పిల్లలను గుర్తించడం"}, {"en": "Providing appropriate assistive devices to all disabled students", "te": "దివ్యాంగ విద్యార్థులందరికీ తగిన సహాయక ఉపకరణాలను అందించడం", "raw": "Providing appropriate assistive devices to all disabled students / దివ్యాంగ విద్యార్థులందరికీ తగిన సహాయక ఉపకరణాలను అందించడం"}, {"en": "Distribute learning aids to all students with disability", "te": "దివ్యాంగ విద్యార్థులందరికీ అభ్యసన సామాగ్రిని పంపిణీ చేయడం", "raw": "Distribute learning aids to all students with disability / దివ్యాంగ విద్యార్థులందరికీ అభ్యసన సామాగ్రిని పంపిణీ చేయడం"}, {"en": "Not to provide services related to students with disabilities", "te": "దివ్యాంగ విద్యార్థులకు సేవలు అందించకుండా ఉండటం", "raw": "Not to provide services related to students with disabilities / దివ్యాంగ విద్యార్థులకు సేవలు అందించకుండా ఉండటం"}], "ans": 4, "exp_en": "The core purpose of IEDSS is to enable all students with disabilities completing eight years of elementary schooling to continue their education at the secondary stage (Classes IX-XII) in an inclusive environment with full educational services and aids.", "exp_te": "IEDSS పథకం ప్రధాన లక్ష్యం దివ్యాంగ విద్యార్థులకు అవసరమైన అన్ని సేవలు, ఉపకరణాలు అందించి వారి మాధ్యమిక విద్యను ప్రోత్సహించడం. సేవలు అందించకపోవడం అనేది పథకానికి విరుద్ధం."}, {"id": 73, "sec": "Special Education", "passage": "", "q_en": "The United Nations Convention on the Rights of Persons with Disabilities (UNCRPD) 2006 was adopted at", "q_te": "దివ్యాంగుల హక్కులపై ఐక్యరాజ్యసమితి సమావేశం (UNCRPD) 2006 ఎక్కడ జరిగింది", "opts": [{"en": "New York", "te": "న్యూయార్క్ (ఐక్యరాజ్యసమితి ప్రధాన కార్యాలయం)", "raw": "New York / న్యూయార్క్ (ఐక్యరాజ్యసమితి ప్రధాన కార్యాలయం)"}, {"en": "Spain", "te": "స్పెయిన్", "raw": "Spain / స్పెయిన్"}, {"en": "France", "te": "ఫ్రాన్స్", "raw": "France / ఫ్రాన్స్"}, {"en": "Portugal", "te": "పోర్చుగల్", "raw": "Portugal / పోర్చుగల్"}], "ans": 1, "exp_en": "The UNCRPD was adopted on 13 December 2006 at the United Nations Headquarters in New York, establishing a landmark international human rights treaty protecting the dignity of persons with disabilities.", "exp_te": "దివ్యాంగుల హక్కుల పరిరక్షణ కొరకు UNCRPD ఒప్పందం 2006 డిసెంబర్ 13న న్యూయార్క్‌లోని ఐక్యరాజ్యసమితి ప్రధాన కార్యాలయంలో ఆమోదించబడింది."}, {"id": 74, "sec": "Special Education", "passage": "", "q_en": "UNESCAP has adopted a regional 10-year Plan of Action for disability rights titled", "q_te": "UNESCAP ఆసియా-పసిఫిక్ ప్రాంతంలో దివ్యాంగుల హక్కుల కోసం ఆమోదించిన కార్యాచరణ ప్రణాళిక", "opts": [{"en": "TCAB", "te": "TCAB", "raw": "TCAB"}, {"en": "UNCRPD", "te": "UNCRPD", "raw": "UNCRPD"}, {"en": "INCHEON Strategy", "te": "ఇంచియాన్ వ్యూహం (INCHEON Strategy)", "raw": "INCHEON Strategy / ఇంచియాన్ వ్యూహం (INCHEON Strategy)"}, {"en": "ICT Strategy", "te": "ICT", "raw": "ICT Strategy / ICT"}], "ans": 3, "exp_en": "The Incheon Strategy to 'Make the Right Real' for Persons with Disabilities in Asia and the Pacific (2013-2022) was adopted by UNESCAP member states in Incheon, South Korea.", "exp_te": "ఆసియా-పసిఫిక్ ప్రాంతంలో దివ్యాంగుల హక్కులను వాస్తవ రూపంలోకి తీసుకురావడానికి UNESCAP రూపొందించిన 10 సంవత్సరాల రోడ్‌మ్యాప్‌ను 'ఇంచియాన్ వ్యూహం' (Incheon Strategy) అంటారు."}, {"id": 75, "sec": "Special Education", "passage": "", "q_en": "Which of the following does NOT come under the Millennium Development Goals (MDGs)?", "q_te": "క్రింది వానిలో సహస్రాబ్ది అభివృద్ధి లక్ష్యాలలో (MDG) లేనిది ఏది", "opts": [{"en": "Attain Universalization of Elementary Education", "te": "సార్వత్రిక ప్రాథమిక విద్యను సాధించడం", "raw": "Attain Universalization of Elementary Education / సార్వత్రిక ప్రాథమిక విద్యను సాధించడం"}, {"en": "Promote gender equality and empower women", "te": "లింగ సమానత్వాన్ని మరియు మహిళా సాధికారతను ప్రోత్సహించడం", "raw": "Promote gender equality and empower women / లింగ సమానత్వాన్ని మరియు మహిళా సాధికారతను ప్రోత్సహించడం"}, {"en": "Avoid global partnerships and participation", "te": "ప్రపంచ దేశాల భాగస్వామ్యాన్ని మరియు సహకారాన్ని నివారించడం", "raw": "Avoid global partnerships and participation / ప్రపంచ దేశాల భాగస్వామ్యాన్ని మరియు సహకారాన్ని నివారించడం"}, {"en": "Eradicate extreme poverty and hunger", "te": "తీవ్రమైన పేదరికాన్ని మరియు ఆకలిని నిర్మూలించడం", "raw": "Eradicate extreme poverty and hunger / తీవ్రమైన పేదరికాన్ని మరియు ఆకలిని నిర్మూలించడం"}], "ans": 3, "exp_en": "The Millennium Development Goals (MDGs) comprise 8 goals. Goal 8 specifically mandates 'Develop a global partnership for development'. Avoiding global participation is completely contrary to the MDGs.", "exp_te": "MDG లలో 8వ లక్ష్యం 'అభివృద్ధి కోసం అంతర్జాతీయ భాగస్వామ్యాన్ని పెంపొందించడం'. ప్రపంచ భాగస్వామ్యాన్ని నివారించడం అనేది తప్పు ప్రకటన."}, {"id": 76, "sec": "Special Education", "passage": "", "q_en": "The word 'Technology' is derived from which language?", "q_te": "'టెక్నాలజీ' (Technology) అనే ఆంగ్ల పదం ఏ భాష నుండి ఉద్భవించింది", "opts": [{"en": "Greek language", "te": "గ్రీకు భాష (Greek - Techne)", "raw": "Greek language / గ్రీకు భాష (Greek - Techne)"}, {"en": "Latin language", "te": "లాటిన్ భాష", "raw": "Latin language / లాటిన్ భాష"}, {"en": "Roman language", "te": "రోమన్ భాష", "raw": "Roman language / రోమన్ భాష"}, {"en": "Arabic language", "te": "అరబిక్ భాష", "raw": "Arabic language / అరబిక్ భాష"}], "ans": 1, "exp_en": "'Technology' comes from the Greek word 'Techne' (meaning art, skill, craft) and 'Logos' (meaning study, science, or systematic knowledge).", "exp_te": "'టెక్నాలజీ' అనే పదం గ్రీకు భాషకు చెందిన 'టెక్నే' (Techne - కళ, నైపుణ్యం) మరియు 'లోగోస్' (Logos - శాస్త్రం) అనే పదాల నుండి ఉద్భవించింది."}, {"id": 77, "sec": "Special Education", "passage": "", "q_en": "Which of the following is NOT an objective of Educational Technology?", "q_te": "క్రింది వానిలో విద్యా సాంకేతిక శాస్త్రం (Educational Technology) యొక్క లక్ష్యం కానిది ఏది", "opts": [{"en": "Helps in learning specific individual skills", "te": "నిర్దిష్ట నైపుణ్యాలను అభ్యసించడంలో సహాయపడటం", "raw": "Helps in learning specific individual skills / నిర్దిష్ట నైపుణ్యాలను అభ్యసించడంలో సహాయపడటం"}, {"en": "Confining education to reach only a small number of learners", "te": "విద్యను అతి తక్కువ మంది అభ్యాసకులకు మాత్రమే పరిమితం చేయడం", "raw": "Confining education to reach only a small number of learners / విద్యను అతి తక్కువ మంది అభ్యాసకులకు మాత్రమే పరిమితం చేయడం"}, {"en": "Providing advanced learning materials to all", "te": "అందరికీ అధునాతన అభ్యసన సామాగ్రిని అందించడం", "raw": "Providing advanced learning materials to all / అందరికీ అధునాతన అభ్యసన సామాగ్రిని అందించడం"}, {"en": "Identifying social needs and educational objectives", "te": "సామాజిక అవసరాలను మరియు విద్యా లక్ష్యాలను గుర్తించడం", "raw": "Identifying social needs and educational objectives / సామాజిక అవసరాలను మరియు విద్యా లక్ష్యాలను గుర్తించడం"}], "ans": 2, "exp_en": "Educational Technology aims to democratize education and mass-disseminate quality instructional resources to large, diverse populations, not to restrict learning to small groups.", "exp_te": "విద్యా సాంకేతికత ముఖ్య ఉద్దేశం నాణ్యమైన విద్యను అందరికీ సులభంగా చేరువ చేయడం. విద్యను కొద్దిమందికే పరిమితం చేయడం అనేది దీని లక్ష్యం కాదు."}, {"id": 78, "sec": "Special Education", "passage": "", "q_en": "Among teaching media, along with Audio aids and Visual aids, the third traditional category is", "q_te": "బోధనా మాధ్యమాలలో శ్రవణ (ఆడియో), దృశ్య (విజువల్) సాధనాలతో పాటు మూడవ ప్రధాన వర్గం", "opts": [{"en": "Radio / Tape recorder", "te": "రేడియో, టేప్ రికార్డర్", "raw": "Radio / Tape recorder / రేడియో, టేప్ రికార్డర్"}, {"en": "Television", "te": "టెలివిజన్", "raw": "Television / టెలివిజన్"}, {"en": "Cinema", "te": "సినిమా", "raw": "Cinema / సినిమా"}, {"en": "Print Media", "te": "ముద్రణ మాధ్యమం (Print Media - పుస్తకాలు, పత్రికలు)", "raw": "Print Media / ముద్రణ మాధ్యమం (Print Media - పుస్తకాలు, పత్రికలు)"}], "ans": 4, "exp_en": "The three classical pillars of educational instructional materials are Print media (textbooks, charts, modules), Audio media, and Visual/Audio-Visual media.", "exp_te": "సాంప్రదాయ బోధనా సాధనాలలో శ్రవణ సాధనాలు, దృశ్య సాధనాలతో పాటు ముద్రణ మాధ్యమం (Print Media - పాఠ్యపుస్తకాలు, వర్క్‌బుక్స్) మూడవ కీలకమైన విభాగం."}, {"id": 79, "sec": "Special Education", "passage": "", "q_en": "An example of Tacit Knowledge acquisition in education is", "q_te": "అంతర్గత / వ్యక్తీకరించలేని జ్ఞానాన్ని (Tacit Knowledge) అలవర్చుకోవడానికి సరైన ఉదాహరణ", "opts": [{"en": "Leadership skills", "te": "నాయకత్వ నైపుణ్యాలు (Leadership)", "raw": "Leadership skills / నాయకత్వ నైపుణ్యాలు (Leadership)"}, {"en": "Manual guidelines", "te": "మాన్యువల్ సూచికలు", "raw": "Manual guidelines / మాన్యువల్ సూచికలు"}, {"en": "Written reports", "te": "రాతపూర్వక నివేదికలు", "raw": "Written reports / రాతపూర్వక నివేదికలు"}, {"en": "Running on a track", "te": "పరుగు పందెం", "raw": "Running on a track / పరుగు పందెం"}], "ans": 1, "exp_en": "Tacit knowledge is intuitive, deeply personal, and experiential knowledge (such as leadership, judgment, intuition, and empathy) that cannot be easily written down or codified in a manual.", "exp_te": "పుస్తకాల ద్వారా కాకుండా ప్రత్యక్ష అనుభవం, వ్యక్తిత్వ వికాసం ద్వారా మాత్రమే పెంపొందే అంతర్గత జ్ఞానానికి 'నాయకత్వ లక్షణాలు' (Leadership Skills) అత్యుత్తమ ఉదాహరణ."}, {"id": 80, "sec": "Special Education", "passage": "", "q_en": "The maximum and most lasting learning occurs when we make optimum use of our", "q_te": "అభ్యసనంలో వీటిని సమగ్రంగా మరియు గరిష్టంగా ఉపయోగించినప్పుడు అత్యుత్తమ ఫలితాలు వస్తాయి", "opts": [{"en": "Eyes only", "te": "కేవలం కళ్ళు మాత్రమే", "raw": "Eyes only / కేవలం కళ్ళు మాత్రమే"}, {"en": "Legs", "te": "కాళ్ళు", "raw": "Legs / కాళ్ళు"}, {"en": "Sense organs (Multi-sensory)", "te": "జ్ఞానేంద్రియాలు (Sense Organs / బహుళ ఇంద్రియాలు)", "raw": "Sense organs (Multi-sensory) / జ్ఞానేంద్రియాలు (Sense Organs / బహుళ ఇంద్రియాలు)"}, {"en": "Hands only", "te": "చేతులు మాత్రమే", "raw": "Hands only / చేతులు మాత్రమే"}], "ans": 3, "exp_en": "Maria Montessori emphasized that the senses are the gateways to knowledge. Engaging multiple sense organs (visual, auditory, tactile, kinesthetic) yields deep and enduring learning.", "exp_te": "జ్ఞానేంద్రియాలు జ్ఞానానికి ద్వారాలు. బహుళ జ్ఞానేంద్రియాలను (Multi-sensory) ఉపయోగించి నేర్చుకున్నప్పుడు అభ్యసనం దృఢంగా మరియు చిరస్థాయిగా ఉంటుంది."}, {"id": 81, "sec": "Special Education", "passage": "", "q_en": "The most fundamental and essential life skill among WHO core life skills is", "q_te": "WHO నిర్దేశించిన జీవన నైపుణ్యాలలో అత్యంత కీలకమైన ప్రాథమిక నైపుణ్యం", "opts": [{"en": "Social skills", "te": "సాంఘిక నైపుణ్యాలు", "raw": "Social skills / సాంఘిక నైపుణ్యాలు"}, {"en": "Hearing skills", "te": "వినికిడి నైపుణ్యం", "raw": "Hearing skills / వినికిడి నైపుణ్యం"}, {"en": "Drawing skills", "te": "చిత్రలేఖనం", "raw": "Drawing skills / చిత్రలేఖనం"}, {"en": "Communication skills", "te": "సంభాషణా / భావవ్యక్తీకరణ నైపుణ్యాలు (Communication Skills)", "raw": "Communication skills / సంభాషణా / భావవ్యక్తీకరణ నైపుణ్యాలు (Communication Skills)"}], "ans": 4, "exp_en": "Effective Communication Skills underpin all interpersonal relations, self-advocacy, emotional expression, and social interaction, making it the core life skill.", "exp_te": "భావవ్యక్తీకరణ మరియు సమర్థవంతమైన సంభాషణా నైపుణ్యం (Communication Skills) అనేది సమాజంలో విజయవంతంగా జీవించడానికి అత్యంత కీలకమైన ప్రాథమిక జీవన నైపుణ్యం."}, {"id": 82, "sec": "Special Education", "passage": "", "q_en": "The type of operating system used in real-time airline reservation systems is", "q_te": "విమానయాన రిజర్వేషన్ సేవల్లో పెద్ద సంఖ్యలో ప్రజలు ఏకకాలంలో ఉపయోగించే ఆపరేటింగ్ సిస్టమ్", "opts": [{"en": "Single-user operating system", "te": "సింగిల్ యూజర్ ఆపరేటింగ్ సిస్టమ్", "raw": "Single-user operating system / సింగిల్ యూజర్ ఆపరేటింగ్ సిస్టమ్"}, {"en": "MS-DOS", "te": "ఎంఎస్-డాస్ (MS-DOS)", "raw": "MS-DOS / ఎంఎస్-డాస్ (MS-DOS)"}, {"en": "Multi-user operating system", "te": "మల్టీ యూజర్ ఆపరేటింగ్ సిస్టమ్ (Multi-user Operating System)", "raw": "Multi-user operating system / మల్టీ యూజర్ ఆపరేటింగ్ సిస్టమ్ (Multi-user Operating System)"}, {"en": "Android operating system", "te": "ఆండ్రాయిడ్ ఆపరేటింగ్ సిస్టమ్", "raw": "Android operating system / ఆండ్రాయిడ్ ఆపరేటింగ్ సిస్టమ్"}], "ans": 3, "exp_en": "Airline booking and ticketing platforms require a Multi-user, multi-access network Operating System allowing thousands of simultaneous transactions across the globe.", "exp_te": "విమాన లేదా రైల్వే టికెట్ రిజర్వేషన్ల వంటి బహుళ వ్యక్తుల వ్యవస్థలలో ఒకేసారి వేలాదిమంది యాక్సెస్ చేయడానికి 'మల్టీ యూజర్ ఆపరేటింగ్ సిస్టమ్' అవసరం."}, {"id": 83, "sec": "Special Education", "passage": "", "q_en": "Which of the following is a computer hardware input device?", "q_te": "క్రింది వానిలో కంప్యూటర్ హార్డ్‌వేర్ ఇన్‌పుట్ పరికరం ఏది", "opts": [{"en": "Mouse", "te": "మౌస్ (Mouse)", "raw": "Mouse / మౌస్ (Mouse)"}, {"en": "Monitor", "te": "మానిటర్", "raw": "Monitor / మానిటర్"}, {"en": "Printers", "te": "ప్రింటర్లు", "raw": "Printers / ప్రింటర్లు"}, {"en": "Speaker", "te": "స్పీకర్", "raw": "Speaker / స్పీకర్"}], "ans": 1, "exp_en": "A Mouse is a handheld pointing input device. In contrast, Monitor, Printer, and Speakers are output hardware devices.", "exp_te": "మౌస్ అనేది సమాచారాన్ని కంప్యూటర్‌కు అందించే ఇన్‌పుట్ పరికరం (Input Device). మానిటర్, ప్రింటర్, స్పీకర్లు అవుట్‌పుట్ పరికరాలు."}, {"id": 84, "sec": "Special Education", "passage": "", "q_en": "Computers used in hospital Intensive Care Units (ICU) to measure continuous analog vitals and compute digital outputs are", "q_te": "హాస్పిటల్ ఐసీయూ (ICU) విభాగాలలో రోగుల శారీరక సంకేతాలను కొలవడానికి ఉపయోగించే కంప్యూటర్లు", "opts": [{"en": "General computers", "te": "సాధారణ కంప్యూటర్లు", "raw": "General computers / సాధారణ కంప్యూటర్లు"}, {"en": "Hybrid computers", "te": "హైబ్రిడ్ కంప్యూటర్లు (Hybrid Computers)", "raw": "Hybrid computers / హైబ్రిడ్ కంప్యూటర్లు (Hybrid Computers)"}, {"en": "Digital computers", "te": "డిజిటల్ కంప్యూటర్లు", "raw": "Digital computers / డిజిటల్ కంప్యూటర్లు"}, {"en": "Analog computers", "te": "అనలాగ్ కంప్యూటర్లు", "raw": "Analog computers / అనలాగ్ కంప్యూటర్లు"}], "ans": 2, "exp_en": "Hybrid computers combine the continuous measurement speed of analog computers (measuring heart rate, temperature, blood pressure) with the precision and storage of digital computers.", "exp_te": "ఐసీయూ విభాగాలలో రోగుల గుండె కొట్టుకోవడం, రక్తపోటు వంటి అనలాగ్ సంకేతాలను స్వీకరించి డిజిటల్ రూపంలో ఫలితాలను చూపించే కంప్యూటర్లను 'హైబ్రిడ్ కంప్యూటర్లు' అంటారు."}, {"id": 85, "sec": "Special Education", "passage": "", "q_en": "In the evolutionary development of educational systems, the present prevailing technological stage is", "q_te": "విద్యా వ్యవస్థలో వచ్చిన సాంకేతిక మార్పుల క్రమంలో ప్రస్తుత యుగాన్ని సూచించే దశ", "opts": [{"en": "Information and Communication Technology (ICT) stage", "te": "సమాచార మరియు ప్రసార సాంకేతిక దశ (ICT Stage)", "raw": "Information and Communication Technology (ICT) stage / సమాచార మరియు ప్రసార సాంకేతిక దశ (ICT Stage)"}, {"en": "Audio-visual stage", "te": "దృశ్య-శ్రవణ దశ", "raw": "Audio-visual stage / దృశ్య-శ్రవణ దశ"}, {"en": "Psycho-sociological stage", "te": "మనో-సామాజిక దశ", "raw": "Psycho-sociological stage / మనో-సామాజిక దశ"}, {"en": "Cybernetic stage", "te": "సైబర్‌నెటిక్స్ దశ", "raw": "Cybernetic stage / సైబర్‌నెటిక్స్ దశ"}], "ans": 1, "exp_en": "The modern classroom has evolved from the print and AV phases into the Information and Communication Technology (ICT) stage, powered by digital learning platforms, smart boards, and internet connectivity.", "exp_te": "నేటి ఆధునిక విద్యా విధానం డిజిటల్ పరికరాలు, ఇంటర్నెట్, స్మార్ట్ క్లాస్‌రూమ్‌లతో కూడిన 'సమాచార మరియు సమాచార సాంకేతిక దశ' (ICT Stage) లో ఉంది."}, {"id": 86, "sec": "Special Education", "passage": "", "q_en": "The conceptual pedagogical framework of Project-Based Learning centers around", "q_te": "ప్రాజెక్ట్ ఆధారిత అభ్యసనం (Project Based Learning) యొక్క ప్రాథమిక నమూనా దేని చుట్టూ కేంద్రీకృతమై ఉంటుంది", "opts": [{"en": "Learning and chatting", "te": "అభ్యసనం మరియు ముచ్చట్లు", "raw": "Learning and chatting / అభ్యసనం మరియు ముచ్చట్లు"}, {"en": "Teaching and Learning (Experiential Learning)", "te": "బోధన - అభ్యసన ప్రక్రియ (Teaching & Learning / అన్వేషణాత్మక అభ్యసనం)", "raw": "Teaching and Learning (Experiential Learning) / బోధన - అభ్యసన ప్రక్రియ (Teaching & Learning / అన్వేషణాత్మక అభ్యసనం)"}, {"en": "Reading and Writing", "te": "చదవడం - రాయడం", "raw": "Reading and Writing / చదవడం - రాయడం"}, {"en": "Listening and Speaking", "te": "వినడం - మాట్లాడటం", "raw": "Listening and Speaking / వినడం - మాట్లాడటం"}], "ans": 2, "exp_en": "Project-Based Learning is an experiential teaching-learning framework where students gain knowledge and skills by working for an extended period to investigate and respond to an authentic, engaging problem.", "exp_te": "ప్రాజెక్ట్ ఆధారిత అభ్యసనంలో ఉపాధ్యాయుని మార్గదర్శకత్వం మరియు విద్యార్థుల క్రియాశీల అభ్యసన (Teaching - Learning) ప్రక్రియల సమన్వయం ద్వారా జ్ఞాన నిర్మాణం జరుగుతుంది."}, {"id": 87, "sec": "Special Education", "passage": "", "q_en": "Leaving the classroom to gather direct, real-world experiences in the environment is called", "q_te": "తరగతి గది దాటి వెళ్లి సమాజం మరియు ప్రకృతి నుండి ప్రత్యక్ష అనుభవాలు పొందే ప్రక్రియ", "opts": [{"en": "PBL", "te": "PBL", "raw": "PBL"}, {"en": "Group Discussion", "te": "సామూహిక చర్చ", "raw": "Group Discussion / సామూహిక చర్చ"}, {"en": "Blogs", "te": "బ్లాగులు", "raw": "Blogs / బ్లాగులు"}, {"en": "Field Visits (Educational Excursions)", "te": "క్షేత్ర పర్యటనలు (Field Visits / క్షేత్ర స్థాయి అధ్యయనం)", "raw": "Field Visits (Educational Excursions) / క్షేత్ర పర్యటనలు (Field Visits / క్షేత్ర స్థాయి అధ్యయనం)"}], "ans": 4, "exp_en": "Field visits (educational tours, outdoor excursions) enable students to step outside the classroom and acquire direct sensory experiences from reality.", "exp_te": "విద్యార్థులు తరగతి గది నుండి నేరుగా ఆయా ప్రదేశాలకు వెళ్లి ప్రత్యక్ష అనుభవాలను పొందడాన్ని 'క్షేత్ర పర్యటనలు' (Field Visits) అంటారు."}, {"id": 88, "sec": "Special Education", "passage": "", "q_en": "'An Airplane flight simulation program' used in pilot training is an example of a", "q_te": "'విమాన ప్రయాణ సిమ్యులేషన్ ప్రోగ్రామ్' (Flight Simulation) అనేది ఏ రకమైన సాంకేతిక సాధనం", "opts": [{"en": "Constructive tool", "te": "నిర్మాణాత్మక సాధనం", "raw": "Constructive tool / నిర్మాణాత్మక సాధనం"}, {"en": "Co-Constructive tool", "te": "సహ-నిర్మాణాత్మక సాధనం", "raw": "Co-Constructive tool / సహ-నిర్మాణాత్మక సాధనం"}, {"en": "Information tool", "te": "సమాచార సాధనం", "raw": "Information tool / సమాచార సాధనం"}, {"en": "Contextual / Situational Simulation tool", "te": "సందర్భోచిత / వాస్తవిక అనుకరణ సాధనం (Contextual / Simulation Tool)", "raw": "Contextual / Situational Simulation tool / సందర్భోచిత / వాస్తవిక అనుకరణ సాధనం (Contextual / Simulation Tool)"}], "ans": 4, "exp_en": "Simulation software represents contextual tools that place the learner in a realistic, situational environment to practice high-stakes skills safely.", "exp_te": "ఫ్లైట్ సిమ్యులేటర్ అనేది వాస్తవ విమాన పరిస్థితులను కృత్రిమంగా సృష్టించి సురక్షితంగా శిక్షణనిచ్చే 'సందర్భోచిత అనుకరణ సాధనం' (Contextual / Simulation Tool)."}, {"id": 89, "sec": "Special Education", "passage": "", "q_en": "e-Learning is primarily facilitated through", "q_te": "ఈ-లెర్నింగ్ (e-Learning) అనేది ప్రధానంగా దీని సహకారంతో సులభతరం అవుతుంది", "opts": [{"en": "Electronic devices and digital assistance", "te": "ఎలక్ట్రానిక్ పరికరాలు మరియు డిజిటల్ మాధ్యమాల తోడ్పాటు", "raw": "Electronic devices and digital assistance / ఎలక్ట్రానిక్ పరికరాలు మరియు డిజిటల్ మాధ్యమాల తోడ్పాటు"}, {"en": "Traditional blackboards only", "te": "కేవలం సంప్రదాయ నల్లబల్లలు", "raw": "Traditional blackboards only / కేవలం సంప్రదాయ నల్లబల్లలు"}, {"en": "Teachers handbook", "te": "ఉపాధ్యాయుల చేతిపుస్తకం", "raw": "Teachers handbook / ఉపాధ్యాయుల చేతిపుస్తకం"}, {"en": "Chalk and talk", "te": "సాధారణ ఉపన్యాసం", "raw": "Chalk and talk / సాధారణ ఉపన్యాసం"}], "ans": 1, "exp_en": "e-Learning refers to learning delivered via electronic devices (computers, tablets, smartphones) utilizing digital content, educational apps, and the internet.", "exp_te": "ఈ-లెర్నింగ్ అనేది కంప్యూటర్లు, మొబైల్స్, ఇంటర్నెట్ వంటి ఎలక్ట్రానిక్ పరికరాలు మరియు డిజిటల్ సాంకేతికత ద్వారా జరిగే అభ్యసనం."}, {"id": 90, "sec": "Special Education", "passage": "", "q_en": "The mobile screening app developed by NCERT to identify children with suspected disabilities in general schools is", "q_te": "సాధారణ పాఠశాలల్లో ప్రత్యేక అవసరాలు గల పిల్లలను ప్రాథమికంగా గుర్తించడానికి NCERT రూపొందించిన స్క్రీనింగ్ యాప్", "opts": [{"en": "DIKSHA", "te": "దీక్ష (DIKSHA)", "raw": "DIKSHA / దీక్ష (DIKSHA)"}, {"en": "DISHA", "te": "దిశ (DISHA)", "raw": "DISHA / దిశ (DISHA)"}, {"en": "KARMAYOGI", "te": "కర్మయోగి", "raw": "KARMAYOGI / కర్మయోగి"}, {"en": "PRASHAST", "te": "ప్రశస్త్ (PRASHAST App - NCERT)", "raw": "PRASHAST / ప్రశస్త్ (PRASHAST App - NCERT)"}], "ans": 4, "exp_en": "PRASHAST (Pre-Assessment Holistic Screening Tool) is a digital app launched by the Department of School Education and Literacy and NCERT for screening 21 disabilities recognized under RPwD Act 2016.", "exp_te": "PRASHAST (Pre-Assessment Holistic Screening Tool) అనేది పాఠశాలల్లో 21 రకాల దివ్యాంగత్వాలను ప్రాథమికంగా గుర్తించేందుకు NCERT అభివృద్ధి చేసిన మొబైల్ స్క్రీనింగ్ యాప్."}, {"id": 91, "sec": "Special Education", "passage": "", "q_en": "Repetitive behaviours are observable in", "q_te": "పునరావృత ప్రవర్తనలు (Repetitive behaviours) వీరిలో ఎక్కువగా గమనించవచ్చు", "opts": [{"en": "Parkinson's disease", "te": "పార్కిన్సన్స్ వ్యాధి", "raw": "Parkinson's disease / పార్కిన్సన్స్ వ్యాధి"}, {"en": "Acid attack victims", "te": "యాసిడ్ దాడి బాధితులు", "raw": "Acid attack victims / యాసిడ్ దాడి బాధితులు"}, {"en": "Dwarfism", "te": "మరుగుజ్జుతనం (డ్వార్ఫిజం)", "raw": "Dwarfism / మరుగుజ్జుతనం (డ్వార్ఫిజం)"}, {"en": "Autism", "te": "ఆటిజం (స్వలీనత)", "raw": "Autism / ఆటిజం (స్వలీనత)"}], "ans": 4, "exp_en": "Repetitive, stereotypical, and ritualistic motor mannerisms (such as hand flapping, rocking, spinning, echolalia, or insistence on sameness) are classic behavioral hallmarks of Autism Spectrum Disorder (ASD).", "exp_te": "చేతులు ఆడించడం (hand flapping), అటూ ఇటూ ఊగడం, ఒకే పనిని పదేపదే చేయడం వంటి పునరావృత మరియు మూస ప్రవర్తనలు (Stereotyped / Repetitive behaviors) ఆటిజం స్పెక్ట్రమ్ డిజార్డర్ (స్వలీనత) కలిగిన పిల్లల్లో ప్రధాన లక్షణాలు."}, {"id": 92, "sec": "Special Education", "passage": "", "q_en": "'Lack of socialization, Lack of communication, Lack of flexibility'. These three are together called", "q_te": "'సాంఘికీకరణ లోపం, భావప్రసార లోపం, అనుకూలత/వశ్యత లోపం (సద్దుబాటు కాకపోవడం)' - ఈ మూడింటిని కలిపి ఏమంటారు?", "opts": [{"en": "Autistic Triad (Wing's Triad)", "te": "ఆటిస్టిక్ ట్రయాడ్ (Autistic Triad)", "raw": "Autistic Triad (Wing's Triad) / ఆటిస్టిక్ ట్రయాడ్ (Autistic Triad)"}, {"en": "Heartistic Triad", "te": "హార్టిస్టిక్ ట్రయాడ్", "raw": "Heartistic Triad / హార్టిస్టిక్ ట్రయాడ్"}, {"en": "Dwarfistic Triad", "te": "డ్వార్ఫిస్టిక్ ట్రయాడ్", "raw": "Dwarfistic Triad / డ్వార్ఫిస్టిక్ ట్రయాడ్"}, {"en": "Intellestic Triad", "te": "ఇంటెల్లెస్టిక్ ట్రయాడ్", "raw": "Intellestic Triad / ఇంటెల్లెస్టిక్ ట్రయాడ్"}], "ans": 1, "exp_en": "Dr. Lorna Wing and Judith Gould formulated the classic 'Autistic Triad' (Triad of Impairments) representing the three core diagnostic impairments in autism: impairments in social interaction, impairments in communication, and lack of flexibility/imagination.", "exp_te": "డాక్టర్ లోర్నా వింగ్ ప్రతిపాదించిన 'ఆటిస్టిక్ ట్రయాడ్' (Autistic Triad / Triad of Impairments) లో మూడు ముఖ్య లోపాలు ఉంటాయి: 1) సాంఘిక పరస్పర చర్యలలో లోపం, 2) భావప్రసార (కమ్యూనికేషన్) లోపం, 3) ప్రవర్తన మరియు ఆలోచనలలో అనుకూలత/వశ్యత లేకపోవడం (Lack of flexibility)."}, {"id": 93, "sec": "Special Education", "passage": "", "q_en": "These individuals can be differentiated by their behaviours even though their physical appearance is normal", "q_te": "శారీరక రూపం సాధారణంగా ఉన్నప్పటికీ, వారి ప్రవర్తనల ద్వారా గుర్తించగలిగే వారు", "opts": [{"en": "Dwarfism", "te": "మరుగుజ్జుతనం", "raw": "Dwarfism / మరుగుజ్జుతనం"}, {"en": "Autism", "te": "ఆటిజం (స్వలీనత)", "raw": "Autism / ఆటిజం (స్వలీనత)"}, {"en": "Cerebral palsy", "te": "మస్తిష్క పక్షవాతం (సెరిబ్రల్ పాల్సీ)", "raw": "Cerebral palsy / మస్తిష్క పక్షవాతం (సెరిబ్రల్ పాల్సీ)"}, {"en": "Acid attack victims", "te": "యాసిడ్ దాడి బాధితులు", "raw": "Acid attack victims / యాసిడ్ దాడి బాధితులు"}], "ans": 2, "exp_en": "Children with Autism Spectrum Disorder typically possess completely normal physical features and general appearance; their condition is diagnosed primarily through distinct behavioral, social interaction, and communication differences.", "exp_te": "ఆటిజం (స్వలీనత) గల పిల్లలు శారీరకంగా సాధారణ పిల్లల లాగే కనిపిస్తారు. ఎలాంటి శారీరక వైకల్య చిహ్నాలు కనిపించవు, కానీ వారి అసాధారణ ప్రవర్తనలు, కంటి చూపును కలపకపోవడం, సాంఘిక పరస్పర చర్యల లోపం ద్వారా మాత్రమే వారిని గుర్తించవచ్చు."}, {"id": 94, "sec": "Special Education", "passage": "", "q_en": "Repeated speech (parrot-like repetition of words or phrases) in children with autism is called", "q_te": "ఆటిజం పిల్లలు ఇతరులు మాట్లాడిన మాటలను పదే పదే చిలుకపలుకుల్లా పునరావృతం చేయడాన్ని ఏమంటారు?", "opts": [{"en": "Ukararia", "te": "ఉకరారియా", "raw": "Ukararia / ఉకరారియా"}, {"en": "Echolalia", "te": "ఎకోలేలియా (Echolalia)", "raw": "Echolalia / ఎకోలేలియా (Echolalia)"}, {"en": "Carrot", "te": "క్యారెట్", "raw": "Carrot / క్యారెట్"}, {"en": "More speech", "te": "మోర్ స్పీచ్", "raw": "More speech / మోర్ స్పీచ్"}], "ans": 2, "exp_en": "Echolalia is the automatic, parrot-like repetition of vocalizations, words, or phrases made by another person, commonly seen in children with autism (can be immediate or delayed echolalia).", "exp_te": "ఎకోలేలియా (Echolalia) అనగా ఇతరులు పలికిన శబ్దాలు, పదాలు లేదా వాక్యాలను యథాతథంగా పదేపదే ప్రతిధ్వనించడం లేదా పునరావృతం చేయడం. ఇది ఆటిజం గల పిల్లల్లో కనిపించే ఒక విలక్షణమైన భాషా లక్షణం."}, {"id": 95, "sec": "Special Education", "passage": "", "q_en": "Marked absence or severe difficulty in maintaining eye contact during social interaction is a hallmark symptom of", "q_te": "ఇతరులతో సంభాషించేటప్పుడు కళ్ళలోకి సూటిగా చూడలేకపోవడం (కంటి చూపు సంబంధం లేకపోవడం) దీని లక్షణం", "opts": [{"en": "Children with Autism", "te": "ఆటిజం (Autism) గల పిల్లలు", "raw": "Children with Autism / ఆటిజం (Autism) గల పిల్లలు"}, {"en": "Gifted children", "te": "ప్రతిభావంతులైన పిల్లలు", "raw": "Gifted children / ప్రతిభావంతులైన పిల్లలు"}, {"en": "Children with Hearing Impairment only", "te": "కేవలం వినికిడి లోపం ఉన్నవారు", "raw": "Children with Hearing Impairment only / కేవలం వినికిడి లోపం ఉన్నవారు"}, {"en": "Art students", "te": "చిత్రకళా విద్యార్థులు", "raw": "Art students / చిత్రకళా విద్యార్థులు"}], "ans": 1, "exp_en": "Poor, fleeting, or absent eye-to-eye contact during social communication is one of the cardinal diagnostic behavioral markers of Autism Spectrum Disorder (ASD).", "exp_te": "ఇతరులతో మాట్లాడేటప్పుడు నేరుగా కళ్ళలోకి చూడకపోవడం (Lack of eye contact) అనేది ఆటిజం (Autism Spectrum Disorder) యొక్క ప్రధాన లక్షణం."}, {"id": 96, "sec": "Special Education", "passage": "", "q_en": "The word 'Autism' is derived from the Greek word 'Autos', which means", "q_te": "'ఆటిజం' (Autism) అనే పదం 'ఆటోస్' (Autos) అనే గ్రీకు పదం నుండి వచ్చింది, దీని అర్థం", "opts": [{"en": "Your self", "te": "మీరు", "raw": "Your self / మీరు"}, {"en": "Our self", "te": "మేము", "raw": "Our self / మేము"}, {"en": "Self (Alone / Self-contained)", "te": "స్వయం / తనలో తాను లీనమగుట (Self)", "raw": "Self (Alone / Self-contained) / స్వయం / తనలో తాను లీనమగుట (Self)"}, {"en": "Them self", "te": "వారు", "raw": "Them self / వారు"}], "ans": 3, "exp_en": "Eugen Bleuler coined the term from the Greek 'Autos' (meaning 'self'), describing an individual who is locked within oneself, isolated from external social realities.", "exp_te": "'ఆటోస్' (Autos) అనగా గ్రీకు భాషలో 'స్వయం' (Self / తనలో తాను) అని అర్థం. బాహ్య ప్రపంచంతో సంబంధం లేకుండా తన లోకంలో తాను ఉండే స్వభావాన్ని ఇది సూచిస్తుంది."}, {"id": 97, "sec": "Special Education", "passage": "", "q_en": "The screening instrument 'C.H.A.T' (Checklist for Autism in Toddlers) is conducted for", "q_te": "'C.H.A.T' (Checklist for Autism in Toddlers) పరీక్షను ఎవరి కోసం నిర్వహిస్తారు", "opts": [{"en": "Children with Intellectual Disability", "te": "మేధో వైకల్యం గల పిల్లలు", "raw": "Children with Intellectual Disability / మేధో వైకల్యం గల పిల్లలు"}, {"en": "Children with Learning Disability", "te": "అభ్యసన వైకల్యం గల పిల్లలు", "raw": "Children with Learning Disability / అభ్యసన వైకల్యం గల పిల్లలు"}, {"en": "Children with Autism", "te": "ఆటిజం (Autism) గల పిల్లలు", "raw": "Children with Autism / ఆటిజం (Autism) గల పిల్లలు"}, {"en": "Children with Dwarfism", "te": "మరుగుజ్జుతనం గల పిల్లలు", "raw": "Children with Dwarfism / మరుగుజ్జుతనం గల పిల్లలు"}], "ans": 3, "exp_en": "CHAT (Checklist for Autism in Toddlers) is a validated early-screening questionnaire administered at 18 months of age to screen toddlers for Autism Spectrum Disorder.", "exp_te": "CHAT (Checklist for Autism in Toddlers) అనేది 18 నెలల పసిపిల్లలలో ఆటిజం (Autism) లక్షణాలను ప్రాథమికంగా గుర్తించడానికి నిర్వహించే స్క్రీనింగ్ పరీక్ష."}, {"id": 98, "sec": "Special Education", "passage": "", "q_en": "Expand ABA", "q_te": "ABA యొక్క పూర్తి రూపం", "opts": [{"en": "Applied Behaviour Analysis", "te": "అప్లైడ్ బిహేవియర్ అనాలిసిస్ (Applied Behaviour Analysis)", "raw": "Applied Behaviour Analysis / అప్లైడ్ బిహేవియర్ అనాలిసిస్ (Applied Behaviour Analysis)"}, {"en": "All Behaviour Analysis", "te": "ఆల్ బిహేవియర్ అనాలిసిస్", "raw": "All Behaviour Analysis / ఆల్ బిహేవియర్ అనాలిసిస్"}, {"en": "Ask Behaviour Analysis", "te": "ఆస్క్ బిహేవియర్ అనాలిసిస్", "raw": "Ask Behaviour Analysis / ఆస్క్ బిహేవియర్ అనాలిసిస్"}, {"en": "Alternate Behaviour Analysis", "te": "ఆల్టర్నేట్ బిహేవియర్ అనాలిసిస్", "raw": "Alternate Behaviour Analysis / ఆల్టర్నేట్ బిహేవియర్ అనాలిసిస్"}], "ans": 1, "exp_en": "Applied Behavior Analysis (ABA) is an evidence-based scientific therapy based on learning principles, widely utilized in treating children with Autism Spectrum Disorder.", "exp_te": "ABA అనగా 'అప్లైడ్ బిహేవియర్ అనాలిసిస్' (Applied Behaviour Analysis). ఇది ఆటిజం గల పిల్లల్లో ప్రవర్తనా మార్పులకు ఉపయోగించే అత్యంత ప్రసిద్ధ శాస్త్రీయ పద్ధతి."}, {"id": 99, "sec": "Special Education", "passage": "", "q_en": "Which of the following is NOT an educational intervention approach for Autism?", "q_te": "క్రింది వానిలో ఆటిజం బోధనా విధానాలకు సంబంధం లేనిది ఏది", "opts": [{"en": "Eclectic approaches", "te": "ఎక్లెక్టిక్ పద్ధతులు (Eclectic approaches)", "raw": "Eclectic approaches / ఎక్లెక్టిక్ పద్ధతులు (Eclectic approaches)"}, {"en": "Structured teaching (TEACCH)", "te": "నిర్మాణాత్మక బోధన (TEACCH / Structured teaching)", "raw": "Structured teaching (TEACCH) / నిర్మాణాత్మక బోధన (TEACCH / Structured teaching)"}, {"en": "Economical approach", "te": "ఆర్థిక విధానం", "raw": "Economical approach / ఆర్థిక విధానం"}, {"en": "Election approach", "te": "ఎలక్షన్ విధానం (Election approach)", "raw": "Election approach / ఎలక్షన్ విధానం (Election approach)"}], "ans": 4, "exp_en": "Recognized approaches for Autism include Structured Teaching (TEACCH), ABA, Sensory Integration, and Eclectic interventions. 'Election approach' has no relevance.", "exp_te": "ఆటిజంలో స్ట్రక్చర్డ్ టీచింగ్ (TEACCH), ఎక్లెక్టిక్ పద్ధతులు వంటివి ప్రామాణికమైనవి. 'ఎలక్షన్ విధానం' అనే విద్యా విధానం ఉండదు."}, {"id": 100, "sec": "Special Education", "passage": "", "q_en": "Expand 'ASHA' in the context of Special Needs and Autism institutions", "q_te": "ఆటిజం మరియు ప్రత్యేక విద్యా సంస్థల సందర్భంలో 'ASHA' యొక్క పూర్తి రూపం", "opts": [{"en": "Academy of Stage Handicaps and Autism", "te": "అకాడమీ ఆఫ్ స్టేజ్ హ్యాండిక్యాప్స్", "raw": "Academy of Stage Handicaps and Autism / అకాడమీ ఆఫ్ స్టేజ్ హ్యాండిక్యాప్స్"}, {"en": "Asian of Search Handicaps and Autism", "te": "ఏషియన్ ఆఫ్ సెర్చ్ హ్యాండిక్యాప్స్", "raw": "Asian of Search Handicaps and Autism / ఏషియన్ ఆఫ్ సెర్చ్ హ్యాండిక్యాప్స్"}, {"en": "Academy for Severe Handicaps and Autism", "te": "అకాడమీ ఫర్ సివియర్ హ్యాండిక్యాప్స్ అండ్ ఆటిజం (Academy for Severe Handicaps and Autism - ASHA)", "raw": "Academy for Severe Handicaps and Autism / అకాడమీ ఫర్ సివియర్ హ్యాండిక్యాప్స్ అండ్ ఆటిజం (Academy for Severe Handicaps and Autism - ASHA)"}, {"en": "All of State Handicaps and Autism", "te": "ఆల్ ఆఫ్ స్టేట్ హ్యాండిక్యాప్స్", "raw": "All of State Handicaps and Autism / ఆల్ ఆఫ్ స్టేట్ హ్యాండిక్యాప్స్"}], "ans": 3, "exp_en": "ASHA stands for 'Academy for Severe Handicaps and Autism', a leading pioneering non-profit charitable trust and school established in Bangalore in 1995 for children with autism.", "exp_te": "ASHA అనగా 'Academy for Severe Handicaps and Autism'. ఇది తీవ్ర వైకల్యాలు మరియు ఆటిజం గల పిల్లల పునరావాసం కోసం ఏర్పాటైన ప్రముఖ ప్రత్యేక విద్యా సంస్థ."}, {"id": 101, "sec": "Special Education", "passage": "", "q_en": "Lovaas Programme (Early Intensive Behavioral Intervention) is proven useful for", "q_te": "లోవాస్ ప్రోగ్రామ్ (Lovaas Programme) దేనికి అత్యంత ఉపయోగకరమైనది", "opts": [{"en": "Learning disabilities", "te": "అభ్యసన వైకల్యాలు", "raw": "Learning disabilities / అభ్యసన వైకల్యాలు"}, {"en": "Hearing loss rehabilitation", "te": "శ్రవణ లోపం", "raw": "Hearing loss rehabilitation / శ్రవణ లోపం"}, {"en": "Speech articulation defect", "te": "వాక్ లోపం", "raw": "Speech articulation defect / వాక్ లోపం"}, {"en": "Autism (Early Intensive Behavior Intervention)", "te": "ఆటిజం (Autism - ప్రవర్తనా చికిత్స)", "raw": "Autism (Early Intensive Behavior Intervention) / ఆటిజం (Autism - ప్రవర్తనా చికిత్స)"}], "ans": 4, "exp_en": "Dr. Ivar Lovaas developed the Lovaas Model of Applied Behavior Analysis (ABA), an Early Intensive Behavioral Intervention (EIBI) specifically for young children with Autism.", "exp_te": "డాక్టర్ ఐవర్ లోవాస్ రూపొందించిన లోవాస్ ప్రోగ్రామ్ (ABA ఆధారిత తీవ్ర ప్రవర్తనా శిక్షణ) ఆటిజం గల పిల్లల భాష మరియు సాంఘిక నైపుణ్యాల అభివృద్ధికి ప్రపంచ ప్రసిద్ధి చెందింది."}, {"id": 102, "sec": "Special Education", "passage": "", "q_en": "One of the most complex and critical challenges in dealing with Autism is", "q_te": "ఆటిజం విషయంలో అత్యంత సంక్లిష్టమైన మరియు సవాలుతో కూడిన ప్రక్రియ", "opts": [{"en": "Rewarding the child", "te": "బహుమతులు ఇవ్వడం", "raw": "Rewarding the child / బహుమతులు ఇవ్వడం"}, {"en": "Accurate Early Diagnosis and Identification", "te": "ఖచ్చితమైన ముందస్తు నిర్ధారణ మరియు వ్యాధి నిర్ధారణ (Diagnosis)", "raw": "Accurate Early Diagnosis and Identification / ఖచ్చితమైన ముందస్తు నిర్ధారణ మరియు వ్యాధి నిర్ధారణ (Diagnosis)"}, {"en": "Punishing inappropriate behavior", "te": "శిక్షించడం", "raw": "Punishing inappropriate behavior / శిక్షించడం"}, {"en": "Scolding", "te": "మందలించడం", "raw": "Scolding / మందలించడం"}], "ans": 2, "exp_en": "Autism is a heterogeneous spectrum condition with no medical blood test or brain scan; differential diagnosis relies on meticulous behavioral observation and standardized clinical assessment.", "exp_te": "ఆటిజానికి ఎటువంటి రక్త లేదా జన్యు పరీక్షలు నేరుగా లేకపోవడం వల్ల, ప్రవర్తనా పరిశీలన ద్వారా ప్రారంభ దశలోనే ఖచ్చితంగా నిర్ధారించడం (Diagnosis) అత్యంత క్లిష్టమైన ప్రక్రియ."}, {"id": 103, "sec": "Special Education", "passage": "", "q_en": "Which of the following is NOT related to the clinical assessment of children with Autism Spectrum Disorder?", "q_te": "ఆటిజం గల పిల్లల క్లినికల్ అసెస్‌మెంట్‌కు సంబంధం లేనిది ఏది", "opts": [{"en": "Clinical psychological assessment", "te": "క్లినికల్ మనోవైజ్ఞానిక అంచనా", "raw": "Clinical psychological assessment / క్లినికల్ మనోవైజ్ఞానిక అంచనా"}, {"en": "Observation in natural setting", "te": "సహజ పరిసరాల్లో పరిశీలన", "raw": "Observation in natural setting / సహజ పరిసరాల్లో పరిశీలన"}, {"en": "Economic income assessment", "te": "కుటుంబ ఆర్థిక ఆదాయ అంచనా (Economic assessment)", "raw": "Economic income assessment / కుటుంబ ఆర్థిక ఆదాయ అంచనా (Economic assessment)"}, {"en": "Behavioral assessment", "te": "ప్రవర్తనా అంచనా", "raw": "Behavioral assessment / ప్రవర్తనా అంచనా"}], "ans": 3, "exp_en": "Diagnostic assessment of ASD involves clinical history, developmental observation, and behavioral rating scales. Family income/economic assessment is not a clinical metric.", "exp_te": "ఆటిజం క్లినికల్ అంచనాలో ప్రవర్తన, సంభాషణ, సంజ్ఞానాత్మక అంశాలను పరీక్షిస్తారు కానీ కుటుంబ ఆర్థిక ఆదాయాన్ని పరిగణించరు."}, {"id": 104, "sec": "Special Education", "passage": "", "q_en": "Which teaching strategy is least suitable for children with Autism Spectrum Disorder?", "q_te": "ఆటిజం గల పిల్లలకు ఏమాత్రం సరిపడని బోధనా పద్ధతి ఏది", "opts": [{"en": "Discrete Trial Training (DTT)", "te": "డిస్క్రీట్ ట్రయల్ ట్రైనింగ్ (DTT)", "raw": "Discrete Trial Training (DTT) / డిస్క్రీట్ ట్రయల్ ట్రైనింగ్ (DTT)"}, {"en": "Structured Environment (TEACCH)", "te": "నిర్మాణాత్మక తరగతి పరిసరం (TEACCH)", "raw": "Structured Environment (TEACCH) / నిర్మాణాత్మక తరగతి పరిసరం (TEACCH)"}, {"en": "Visual Schedules / Communication", "te": "దృశ్య సమాచార సాధనాలు", "raw": "Visual Schedules / Communication / దృశ్య సమాచార సాధనాలు"}, {"en": "Passive Lecture Method", "te": "నిష్క్రియ ఉపన్యాస పద్ధతి (Lecture Method)", "raw": "Passive Lecture Method / నిష్క్రియ ఉపన్యాస పద్ధతి (Lecture Method)"}], "ans": 4, "exp_en": "Children with Autism struggle with verbal auditory processing and passive listening. Long, unstructured verbal lecture methods are completely ineffective for them.", "exp_te": "ఆటిజం పిల్లలకు శ్రవణ గ్రహణంలో ఇబ్బందులు ఉంటాయి. దృశ్య ఉపకరణాలు లేకుండా ఏకధాటిగా సాగే సంప్రదాయ 'ఉపన్యాస పద్ధతి' (Lecture Method) వారికి ఏమాత్రం ఉపయోగపడదు."}, {"id": 105, "sec": "Special Education", "passage": "", "q_en": "Which of the following is NOT a standard behavioral technique in Applied Behavior Analysis (ABA)?", "q_te": "క్రింది వానిలో ABA (అప్లైడ్ బిహేవియర్ అనాలిసిస్) విధానానికి చెందని వ్యూహం ఏది", "opts": [{"en": "Prompting", "te": "ప్రాంప్టింగ్ (Prompting - ప్రేరేపణ)", "raw": "Prompting / ప్రాంప్టింగ్ (Prompting - ప్రేరేపణ)"}, {"en": "Shaping", "te": "షేపింగ్ (Shaping - ప్రవర్తనా రూపుదిద్దడం)", "raw": "Shaping / షేపింగ్ (Shaping - ప్రవర్తనా రూపుదిద్దడం)"}, {"en": "Positioning / Static Position", "te": "పొజిషన్ (Position)", "raw": "Positioning / Static Position / పొజిషన్ (Position)"}, {"en": "Modelling", "te": "మోడలింగ్ (Modelling - నమూనా ప్రదర్శన)", "raw": "Modelling / మోడలింగ్ (Modelling - నమూనా ప్రదర్శన)"}], "ans": 3, "exp_en": "Core behavioral modification techniques in ABA include Prompting, Fading, Shaping, Chaining, and Modeling. 'Position' is a physical posture term, not an ABA learning strategy.", "exp_te": "ABA లో ప్రాంప్టింగ్, షేపింగ్, చైనింగ్, మోడలింగ్ అనేవి ప్రవర్తనా నైపుణ్యాల పద్ధతులు. 'పొజిషన్' అనేది భౌతిక స్థితికి సంబంధించింది కానీ ABA వ్యూహం కాదు."}, {"id": 106, "sec": "Special Education", "passage": "", "q_en": "Early developmental milestones, motor skills, eating, and sleeping patterns of a toddler are identified primarily through", "q_te": "పిల్లల ప్రారంభ మైలురాళ్ళు, చలన నైపుణ్యాలు, ఆహారపు అలవాట్లు, నిద్ర రుగ్మతలను ప్రధానంగా దీని ద్వారా సేకరిస్తారు", "opts": [{"en": "Comprehensive Interview with Parents", "te": "తల్లిదండ్రులతో సమగ్ర ఇంటర్వ్యూ / చరిత్ర సేకరణ (Interview with Parents)", "raw": "Comprehensive Interview with Parents / తల్లిదండ్రులతో సమగ్ర ఇంటర్వ్యూ / చరిత్ర సేకరణ (Interview with Parents)"}, {"en": "Class Attendance Register", "te": "ఉపాధ్యాయుని హాజరు పట్టిక", "raw": "Class Attendance Register / ఉపాధ్యాయుని హాజరు పట్టిక"}, {"en": "Direct interview with non-verbal child", "te": "మాట్లాడలేని శిశువుతో నేరుగా ఇంటర్వ్యూ", "raw": "Direct interview with non-verbal child / మాట్లాడలేని శిశువుతో నేరుగా ఇంటర్వ్యూ"}, {"en": "Formal Certificate", "te": "వైద్య ధ్రువీకరణ పత్రం", "raw": "Formal Certificate / వైద్య ధ్రువీకరణ పత్రం"}], "ans": 1, "exp_en": "Because toddlers cannot self-report, a structured clinical Developmental Case History Interview with Parents/caregivers is the vital source for developmental history.", "exp_te": "చిన్న పిల్లలు తమ సమస్యలను తాము వివరించలేరు కాబట్టి, వారి పుట్టుక, చలన మైలురాళ్ళు, ఆహార-నిద్ర అలవాట్ల సమగ్ర వివరాలను తల్లిదండ్రులను ప్రశ్నించడం (Parent Interview) ద్వారానే తెలుసుకుంటారు."}, {"id": 107, "sec": "Special Education", "passage": "", "q_en": "Which of the following is NOT an appropriate teaching practice for children with Autism?", "q_te": "క్రింది వానిలో ఆటిజం గల పిల్లలకు తగని బోధనా సూచన ఏది", "opts": [{"en": "Using concrete Teaching Learning Material (TLM)", "te": "దృశ్య బోధనాభ్యసన సామాగ్రిని (TLM) ఉపయోగించడం", "raw": "Using concrete Teaching Learning Material (TLM) / దృశ్య బోధనాభ్యసన సామాగ్రిని (TLM) ఉపయోగించడం"}, {"en": "Keeping the child Isolated from peers", "te": "విద్యార్థిని తోటివారి నుండి పూర్తిగా ఒంటరిగా (Isolated) ఉంచడం", "raw": "Keeping the child Isolated from peers / విద్యార్థిని తోటివారి నుండి పూర్తిగా ఒంటరిగా (Isolated) ఉంచడం"}, {"en": "Using Computers / Assistive tech instead of handwriting", "te": "చేతిరాతకు బదులుగా కంప్యూటర్లు/కీబోర్డులను ఉపయోగించడం", "raw": "Using Computers / Assistive tech instead of handwriting / చేతిరాతకు బదులుగా కంప్యూటర్లు/కీబోర్డులను ఉపయోగించడం"}, {"en": "Encouraging special talents and hyper-focus areas", "te": "పిల్లల్లోని ప్రత్యేక ప్రతిభను ప్రోత్సహించడం", "raw": "Encouraging special talents and hyper-focus areas / పిల్లల్లోని ప్రత్యేక ప్రతిభను ప్రోత్సహించడం"}], "ans": 2, "exp_en": "Isolating a child with autism exacerbates their social communication deficits. Modern inclusive education demands structured social integration and peer socialization.", "exp_te": "ఆటిజం పిల్లలను తరగతి గదిలో లేదా సమాజంలో ఒంటరిగా (Isolated) ఉంచడం వారి సాంఘిక వికాసాన్ని మరింత దెబ్బతీస్తుంది. వారిని ఇతరులతో కలిపి నేర్పించాలి."}, {"id": 108, "sec": "Special Education", "passage": "", "q_en": "Expand PDD-NOS", "q_te": "PDD-NOS యొక్క పూర్తి రూపం", "opts": [{"en": "Pervasive Developmental Disorder Not Otherwise Specified", "te": "పర్వేసివ్ డెవలప్‌మెంటల్ డిజార్డర్ నాట్ అదర్‌వైస్ స్పెసిఫైడ్ (PDD-NOS)", "raw": "Pervasive Developmental Disorder Not Otherwise Specified / పర్వేసివ్ డెవలప్‌మెంటల్ డిజార్డర్ నాట్ అదర్‌వైస్ స్పెసిఫైడ్ (PDD-NOS)"}, {"en": "Passive Developmental Disorder Not Otherwise Specified", "te": "పాసివ్ డెవలప్‌మెంటల్ డిజార్డర్", "raw": "Passive Developmental Disorder Not Otherwise Specified / పాసివ్ డెవలప్‌మెంటల్ డిజార్డర్"}, {"en": "Prevention Developmental Disorder Not Otherwise Specified", "te": "ప్రివెన్షన్ డెవలప్‌మెంటల్ డిజార్డర్", "raw": "Prevention Developmental Disorder Not Otherwise Specified / ప్రివెన్షన్ డెవలప్‌మెంటల్ డిజార్డర్"}, {"en": "Pre Developmental Disorder Not Otherwise Specified", "te": "ప్రీ డెవలప్‌మెంటల్ డిజార్డర్", "raw": "Pre Developmental Disorder Not Otherwise Specified / ప్రీ డెవలప్‌మెంటల్ డిజార్డర్"}], "ans": 1, "exp_en": "PDD-NOS stands for Pervasive Developmental Disorder Not Otherwise Specified, previously categorized as atypical autism under DSM-IV.", "exp_te": "PDD-NOS అనగా 'Pervasive Developmental Disorder Not Otherwise Specified'. ఇది ఆటిజం లక్షణాలు పాక్షికంగా కనిపించే నాడీ వికాస రుగ్మత."}, {"id": 109, "sec": "Special Education", "passage": "", "q_en": "The child-led developmental strategy 'Floor Time' is a form of", "q_te": "ఆటిజం పిల్లల కోసం రూపొందించిన 'ఫ్లోర్ టైమ్' (Floor Time) అనేది ఏ రకమైన చికిత్సా విధానం", "opts": [{"en": "Water Therapy", "te": "జల చికిత్స", "raw": "Water Therapy / జల చికిత్స"}, {"en": "Relationship-based Play Therapy (DIR/Floortime)", "te": "ఆటల ఆధారిత చికిత్స (Play Therapy / DIR Floortime)", "raw": "Relationship-based Play Therapy (DIR/Floortime) / ఆటల ఆధారిత చికిత్స (Play Therapy / DIR Floortime)"}, {"en": "Drug Therapy", "te": "మందుల చికిత్స", "raw": "Drug Therapy / మందుల చికిత్స"}, {"en": "Mud Therapy", "te": "మట్టి చికిత్స", "raw": "Mud Therapy / మట్టి చికిత్స"}], "ans": 2, "exp_en": "DIR/Floortime, developed by Dr. Stanley Greenspan, is a relationship-based, child-led Play Therapy where the adult joins the child on the floor at their level of play.", "exp_te": "డాక్టర్ స్టాన్లీ గ్రీన్‌స్పాన్ రూపొందించిన 'ఫ్లోర్ టైమ్' (Floortime) అనేది నేలపై కూర్చొని పిల్లల ఆసక్తులకు అనుగుణంగా భావోద్వేగ బంధాన్ని పెంపొందించే 'ఆటల ఆధారిత చికిత్స' (Play Therapy)."}, {"id": 110, "sec": "Special Education", "passage": "", "q_en": "Which classroom condition is NOT suitable for children with Autism Spectrum Disorder?", "q_te": "ఆటిజం గల పిల్లల అభ్యసనానికి ఏమాత్రం అనుకూలం కాని తరగతి వాతావరణం ఏది", "opts": [{"en": "Minimising excess bright light by using curtains", "te": "కర్టెన్లు ఉపయోగించి తీవ్రమైన వెలుతురును తగ్గించడం", "raw": "Minimising excess bright light by using curtains / కర్టెన్లు ఉపయోగించి తీవ్రమైన వెలుతురును తగ్గించడం"}, {"en": "Organizing structured learning spaces", "te": "క్రమబద్ధమైన తరగతి వాతావరణాన్ని ఏర్పాటు చేయడం", "raw": "Organizing structured learning spaces / క్రమబద్ధమైన తరగతి వాతావరణాన్ని ఏర్పాటు చేయడం"}, {"en": "Enhancing loud sound disturbances and noisy environments", "te": "లౌడ్ సౌండ్లు, విపరీతమైన శబ్ద కాలుష్యాన్ని పెంచడం (Enhance sound disturbances)", "raw": "Enhancing loud sound disturbances and noisy environments / లౌడ్ సౌండ్లు, విపరీతమైన శబ్ద కాలుష్యాన్ని పెంచడం (Enhance sound disturbances)"}, {"en": "Giving clear, visual instructions", "te": "స్పష్టమైన సూచనలను అందించడం", "raw": "Giving clear, visual instructions / స్పష్టమైన సూచనలను అందించడం"}], "ans": 3, "exp_en": "Autistic individuals frequently suffer from sensory auditory hypersensitivity. Loud noises and auditory clutter trigger sensory overload and acute distress.", "exp_te": "ఆటిజం పిల్లలకు శబ్దాల పట్ల తీవ్రమైన సున్నితత్వం (Auditory Hypersensitivity) ఉంటుంది. తరగతిలో విపరీతమైన శబ్దాలు పెంచడం వారిని తీవ్ర ఆందోళనకు గురిచేస్తుంది."}, {"id": 111, "sec": "Special Education", "passage": "", "q_en": "Biofeedback provides immediate objective physiological information about", "q_te": "బయోఫీడ్‌బ్యాక్ (Biofeedback) సాంకేతికత దేని గురించిన ప్రత్యక్ష సమాచారాన్ని అందిస్తుంది", "opts": [{"en": "Biodiversity", "te": "జీవ వైవిధ్యం", "raw": "Biodiversity / జీవ వైవిధ్యం"}, {"en": "Biographical charts", "te": "జీవిత చరిత్రలు", "raw": "Biographical charts / జీవిత చరిత్రలు"}, {"en": "Involuntary functions and physiological responses of the Body", "te": "శరీరంలోని అంతర్గత నాడీ-శారీరక విధులు (గుండె వేగం, కండరాల ఒత్తిడి మొదలైనవి)", "raw": "Involuntary functions and physiological responses of the Body / శరీరంలోని అంతర్గత నాడీ-శారీరక విధులు (గుండె వేగం, కండరాల ఒత్తిడి మొదలైనవి)"}, {"en": "Others' secret thoughts", "te": "ఇతరుల భావాలు", "raw": "Others' secret thoughts / ఇతరుల భావాలు"}], "ans": 3, "exp_en": "Biofeedback utilizes electronic sensors to monitor and display involuntary body functions (heart rate, breathing, muscle tension, brain waves) to train self-regulation.", "exp_te": "బయోఫీడ్‌బ్యాక్ అనేది శరీరంలోని గుండె కొట్టుకునే వేగం, రక్తపోటు, కండరాల ఉద్రిక్తత వంటి శరీర విధులను మానిటర్‌పై చూపిస్తూ నియంత్రించుకోవడానికి శిక్షణనిచ్చే పద్ధతి."}, {"id": 112, "sec": "Special Education", "passage": "", "q_en": "Which instructional technique is least effective for teaching children with Autism Spectrum Disorder?", "q_te": "ఆటిజం గల పిల్లలకు బోధించడానికి ఏమాత్రం ప్రభావవంతం కాని పద్ధతి ఏది", "opts": [{"en": "Discrete Trial Training (DTT)", "te": "డిస్క్రీట్ ట్రయల్ ట్రైనింగ్ (DTT)", "raw": "Discrete Trial Training (DTT) / డిస్క్రీట్ ట్రయల్ ట్రైనింగ్ (DTT)"}, {"en": "Sensory Integration Therapy (SIT)", "te": "సెన్సరీ ఇంటిగ్రేషన్ థెరపీ (SIT)", "raw": "Sensory Integration Therapy (SIT) / సెన్సరీ ఇంటిగ్రేషన్ థెరపీ (SIT)"}, {"en": "Structured Environment / Study Carrel", "te": "నిర్మాణాత్మక పరిసరం / స్టడీ కారెల్", "raw": "Structured Environment / Study Carrel / నిర్మాణాత్మక పరిసరం / స్టడీ కారెల్"}, {"en": "Open Verbal Discussion method", "te": "ఓపెన్ గ్రూప్ చర్చా పద్ధతి (Discussion Method)", "raw": "Open Verbal Discussion method / ఓపెన్ గ్రూప్ చర్చా పద్ధతి (Discussion Method)"}], "ans": 4, "exp_en": "Abstract, rapid, unstructured verbal group discussions are baffling and overwhelming for autistic learners who require visual cues, routine, and structured prompts.", "exp_te": "ఆటిజం పిల్లలకు సంభాషణా నైపుణ్యాల లోపం ఉన్నందున, అమూర్తమైన 'చర్చా పద్ధతి' (Discussion method) వారికి ఏమాత్రం ప్రయోజనం కలిగించదు."}, {"id": 113, "sec": "Special Education", "passage": "", "q_en": "Extreme insistence on sameness, rigid routines, and lack of flexibility are most observable in", "q_te": "రొటీన్‌లో ఏమాత్రం మార్పును అంగీకరించకపోవడం, విపరీతమైన దృఢత్వం (Lack of flexibility) ఎవరిలో కనిపిస్తుంది", "opts": [{"en": "Visually Impaired", "te": "దృష్టి లోపం ఉన్నవారు", "raw": "Visually Impaired / దృష్టి లోపం ఉన్నవారు"}, {"en": "Hearing Impaired", "te": "వినికిడి లోపం ఉన్నవారు", "raw": "Hearing Impaired / వినికిడి లోపం ఉన్నవారు"}, {"en": "Autism Spectrum Disorder", "te": "ఆటిజం (Autism) గల పిల్లలు", "raw": "Autism Spectrum Disorder / ఆటిజం (Autism) గల పిల్లలు"}, {"en": "Locomotor Disabled", "te": "చలన వైకల్యం గలవారు", "raw": "Locomotor Disabled / చలన వైకల్యం గలవారు"}], "ans": 3, "exp_en": "Restricted, repetitive patterns of behavior and intense distress over minor changes in routine (insistence on sameness) are diagnostic criteria for Autism.", "exp_te": "తాము అలవాటు పడిన దినచర్యలో చిన్న మార్పు వచ్చినా తట్టుకోలేకపోవడం, దృఢమైన పద్ధతులను పట్టుకు వేలాడటం ఆటిజం (Autism) యొక్క ముఖ్య లక్షణం."}, {"id": 114, "sec": "Special Education", "passage": "", "q_en": "National Autism Awareness Month is celebrated in the month of", "q_te": "జాతీయ ఆటిజం అవగాహన మాసమును (National Autism Awareness Month) ఈ నెలలో జరుపుకుంటారు", "opts": [{"en": "March", "te": "మార్చి", "raw": "March / మార్చి"}, {"en": "January", "te": "జనవరి", "raw": "January / జనవరి"}, {"en": "April", "te": "ఏప్రిల్", "raw": "April / ఏప్రిల్"}, {"en": "December", "te": "డిసెంబర్", "raw": "December / డిసెంబర్"}], "ans": 2, "exp_en": "As per the official SCERT answer key, Option (2) [January] is indicated. Factually and worldwide, April is designated and observed internationally as World Autism Month / Autism Awareness Month (with World Autism Awareness Day on April 2nd).", "exp_te": "SCERT అధికారిక 'కీ' ప్రకారం ఐచ్ఛికం (2) [జనవరి] గా ఇవ్వబడింది. అంతర్జాతీయంగా మరియు సాధారణ పరిజ్ఞానం ప్రకారం 'ఏప్రిల్' నెలను ప్రపంచ ఆటిజం అవగాహన మాసంగా (World Autism Awareness Month) పరిగణిస్తారు (ఏప్రిల్ 2న ప్రపంచ ఆటిజం అవగాహన దినోత్సవం)."}, {"id": 115, "sec": "Special Education", "passage": "", "q_en": "Which condition does NOT belong under the umbrella of Pervasive Developmental Disorders (PDD/ASD)?", "q_te": "క్రింది వానిలో పర్వేసివ్ డెవలప్‌మెంటల్ డిజార్డర్స్ (PDD/ASD) పరిధిలోకి రానిది ఏది", "opts": [{"en": "Autistic disorder", "te": "ఆటిస్టిక్ డిజార్డర్", "raw": "Autistic disorder / ఆటిస్టిక్ డిజార్డర్"}, {"en": "Asperger's disorder", "te": "ఆస్పెర్గర్స్ డిజార్డర్", "raw": "Asperger's disorder / ఆస్పెర్గర్స్ డిజార్డర్"}, {"en": "Rett's disorder", "te": "రెట్స్ డిజార్డర్", "raw": "Rett's disorder / రెట్స్ డిజార్డర్"}, {"en": "Physical / Orthopedic disorder", "te": "శారీరక / ఆర్థోపెడిక్ వైకల్యం (Physical disorder)", "raw": "Physical / Orthopedic disorder / శారీరక / ఆర్థోపెడిక్ వైకల్యం (Physical disorder)"}], "ans": 4, "exp_en": "PDD umbrella encompasses Autistic Disorder, Asperger's, Rett's Syndrome, Childhood Disintegrative Disorder (CDD), and PDD-NOS. Physical locomotor disability is entirely separate.", "exp_te": "PDD గొడుగు కింద ఆటిజం, ఆస్పెర్గర్స్, రెట్స్ సిండ్రోమ్ మొదలైన నాడీ వికాస సమస్యలు ఉంటాయి. శారీరక చలన వైకల్యం (Physical disorder) దీని పరిధిలోకి రాదు."}, {"id": 116, "sec": "Special Education", "passage": "", "q_en": "Choose the INCORRECT statement regarding Autism and medical treatment", "q_te": "ఆటిజం మరియు ఔషధ చికిత్సకు సంబంధించి సరికాని ప్రకటన ఏది", "opts": [{"en": "Drugs do not cure Autism", "te": "మందులు ఆటిజంను నయం చేయలేవు", "raw": "Drugs do not cure Autism / మందులు ఆటిజంను నయం చేయలేవు"}, {"en": "Drugs can help manage associated symptoms (seizures, hyperactivity)", "te": "మందులు కేవలం సంబంధిత సమస్యల (మూర్ఛ, అతి చురుకుదనం) నియంత్రణకు తోడ్పడతాయి", "raw": "Drugs can help manage associated symptoms (seizures, hyperactivity) / మందులు కేవలం సంబంధిత సమస్యల (మూర్ఛ, అతి చురుకుదనం) నియంత్రణకు తోడ్పడతాయి"}, {"en": "Pharmacotherapy is a complete curative treatment for Autism", "te": "మందుల ద్వారా ఆటిజంను సంపూర్ణంగా నయం చేయవచ్చు (Curative treatment)", "raw": "Pharmacotherapy is a complete curative treatment for Autism / మందుల ద్వారా ఆటిజంను సంపూర్ణంగా నయం చేయవచ్చు (Curative treatment)"}, {"en": "Psychotropic drugs play only a supportive role in managing severe behaviors", "te": "తీవ్రమైన ప్రవర్తనా సమస్యలను అదుపు చేయడానికి మాత్రమే మందులు ఉపయోగపడతాయి", "raw": "Psychotropic drugs play only a supportive role in managing severe behaviors / తీవ్రమైన ప్రవర్తనా సమస్యలను అదుపు చేయడానికి మాత్రమే మందులు ఉపయోగపడతాయి"}], "ans": 3, "exp_en": "There is NO cure or curative pharmacotherapy for Autism Spectrum Disorder. Medications are prescribed solely to manage co-occurring conditions like anxiety, aggression, or seizures.", "exp_te": "ఆటిజంను మందుల ద్వారా పూర్తిగా నయం చేయవచ్చనడం అవాస్తవం. ఆటిజం ఒక న్యూరో డెవలప్‌మెంటల్ పరిస్థితి; దీనికి శాశ్వత నివారణ మందులు లేవు, కేవలం ప్రవర్తనా శిక్షణే ప్రధానం."}, {"id": 117, "sec": "Special Education", "passage": "", "q_en": "An animal-assisted therapy known to enhance attention, social bonding, and calmness in autistic children is", "q_te": "ఆటిజం పిల్లలలో ఏకాగ్రత, సాంఘిక స్పందనలను మెరుగుపరచడానికి తోడ్పడే వినూత్న చికిత్స", "opts": [{"en": "Holding Therapy", "te": "హోల్డింగ్ థెరపీ", "raw": "Holding Therapy / హోల్డింగ్ థెరపీ"}, {"en": "Water Therapy", "te": "జల చికిత్స", "raw": "Water Therapy / జల చికిత్స"}, {"en": "'G' Therapy", "te": "'జి' థెరపీ", "raw": "'G' Therapy / 'జి' థెరపీ"}, {"en": "Dolphin / Animal-Assisted Therapy", "te": "డాల్ఫిన్ థెరపీ (Dolphin / Animal-assisted Therapy)", "raw": "Dolphin / Animal-Assisted Therapy / డాల్ఫిన్ థెరపీ (Dolphin / Animal-assisted Therapy)"}], "ans": 4, "exp_en": "Dolphin-Assisted Therapy (DAT) is an animal-assisted sensory therapy that encourages non-verbal communication, tactile interaction, and emotional engagement in autistic individuals.", "exp_te": "డాల్ఫిన్లతో నీటిలో సంభాషిస్తూ ఆడుకునే 'డాల్ఫిన్ థెరపీ' (Dolphin Therapy) ఆటిజం గల పిల్లలలో ఇంద్రియ సమన్వయాన్ని మరియు ఏకాగ్రతను పెంచడానికి ఉపయోగపడుతుంది."}, {"id": 118, "sec": "Special Education", "passage": "", "q_en": "PECS (Picture Exchange Communication System) is primarily designed to", "q_te": "PECS (పిక్చర్ ఎక్స్ఛేంజ్ కమ్యూనికేషన్ సిస్టమ్) దేని కొరకు రూపొందించబడింది", "opts": [{"en": "Initiate functional communication and speech development using picture cards", "te": "చిత్ర కార్డులను ఇచ్చిపుచ్చుకోవడం ద్వారా ప్రాథమిక భావవ్యక్తీకరణను ప్రారంభించడం", "raw": "Initiate functional communication and speech development using picture cards / చిత్ర కార్డులను ఇచ్చిపుచ్చుకోవడం ద్వారా ప్రాథమిక భావవ్యక్తీకరణను ప్రారంభించడం"}, {"en": "Improve moral values", "te": "నైతిక విలువలను పెంచడం", "raw": "Improve moral values / నైతిక విలువలను పెంచడం"}, {"en": "Improve personal self-motivation", "te": "స్వీయ ప్రేరణను అభివృద్ధి చేయడం", "raw": "Improve personal self-motivation / స్వీయ ప్రేరణను అభివృద్ధి చేయడం"}, {"en": "Improve physical fitness", "te": "శారీరక దృఢత్వాన్ని మెరుగుపరచడం", "raw": "Improve physical fitness / శారీరక దృఢత్వాన్ని మెరుగుపరచడం"}], "ans": 1, "exp_en": "PECS (developed by Bondy & Frost) teaches non-verbal individuals with autism to initiate communication by exchanging a picture of a desired item with a communicative partner.", "exp_te": "చిత్రాల కార్డులను ఉపాధ్యాయునికి లేదా తల్లిదండ్రులకు అందించడం ద్వారా మాటలు రాని ఆటిజం పిల్లలు తమ అవసరాలను వ్యక్తపరచడానికి PECS విధానం తోడ్పడుతుంది."}, {"id": 119, "sec": "Special Education", "passage": "", "q_en": "Desires, interests, attitudes, imaginations, and emotions of an individual belong to this educational domain", "q_te": "వ్యక్తి యొక్క కోరికలు, ఆసక్తులు, వైఖరులు మరియు భావోద్వేగాలు ఏ వికాస రంగానికి చెందుతాయి", "opts": [{"en": "Cognitive domain", "te": "జ్ఞానాత్మక రంగం (Cognitive)", "raw": "Cognitive domain / జ్ఞానాత్మక రంగం (Cognitive)"}, {"en": "Affective domain", "te": "భావావేశ రంగం (Affective Domain)", "raw": "Affective domain / భావావేశ రంగం (Affective Domain)"}, {"en": "Conative domain", "te": "కోనేటివ్ రంగం", "raw": "Conative domain / కోనేటివ్ రంగం"}, {"en": "Psychomotor domain", "te": "మానసిక చలనాత్మక రంగం", "raw": "Psychomotor domain / మానసిక చలనాత్మక రంగం"}], "ans": 2, "exp_en": "According to Bloom's taxonomy and psychology, feelings, values, appreciation, motivations, and emotional attitudes reside within the Affective Domain.", "exp_te": "వ్యక్తి భావోద్వేగాలు, అనుభూతులు, ఆసక్తులు మరియు వైఖరులకు సంబంధించిన మానసిక రంగాన్ని 'భావావేశ రంగం' (Affective Domain) అంటారు."}, {"id": 120, "sec": "Special Education", "passage": "", "q_en": "We generally observe this type of solitary play pattern characteristically in children with Autism", "q_te": "ఆటిజం గల పిల్లలలో సాధారణంగా ఎక్కువగా కనిపించే క్రీడా విధానం", "opts": [{"en": "Parallel Play", "te": "సమాంతర క్రీడ", "raw": "Parallel Play / సమాంతర క్రీడ"}, {"en": "Associative Play", "te": "సంసర్గ క్రీడ", "raw": "Associative Play / సంసర్గ క్రీడ"}, {"en": "Solo Play (Playing alone)", "te": "ఏకాంత / సోలో క్రీడ (Solo Play / ఒంటరిగా ఆడుకోవడం)", "raw": "Solo Play (Playing alone) / ఏకాంత / సోలో క్రీడ (Solo Play / ఒంటరిగా ఆడుకోవడం)"}, {"en": "Cooperative Play", "te": "సహకార క్రీడ", "raw": "Cooperative Play / సహకార క్రీడ"}], "ans": 3, "exp_en": "Due to social interaction and reciprocity impairments, children with ASD predominantly engage in Solo Play, playing alone with objects rather than sharing or playing cooperatively with peers.", "exp_te": "సాంఘిక సంభాషణా లోపం వల్ల ఆటిజం పిల్లలు తోటి పిల్లలతో కలిసి ఆడుకోలేక, తమలో తాము ఒంటరిగా ఆడుకునే 'సోలో ప్లే' (Solo Play) ను ప్రదర్శిస్తారు."}, {"id": 121, "sec": "Special Education", "passage": "", "q_en": "Speech reading (Lip Reading) is an indispensable communicative skill for children with", "q_te": "పెదవుల కదలికలను గమనించి గ్రహించే 'లిప్ రీడింగ్' (Speech Reading) ఏ లోపం గల పిల్లలకు అత్యవసరం", "opts": [{"en": "Visual Impairment", "te": "దృష్టి లోపం", "raw": "Visual Impairment / దృష్టి లోపం"}, {"en": "Hearing Impairment", "te": "శ్రవణ (వినికిడి) లోపం (Hearing Impairment)", "raw": "Hearing Impairment / శ్రవణ (వినికిడి) లోపం (Hearing Impairment)"}, {"en": "Intellectual Disability", "te": "మేధో వైకల్యం", "raw": "Intellectual Disability / మేధో వైకల్యం"}, {"en": "Locomotor Disability", "te": "చలన వైకల్యం", "raw": "Locomotor Disability / చలన వైకల్యం"}], "ans": 2, "exp_en": "Lip-reading (Speech-reading) allows individuals with severe hearing loss to decode spoken language visually by observing the lip, tongue, and facial movements of the speaker.", "exp_te": "వినబడని శబ్దాలను మాట్లాడేవారి పెదవుల కదలికల ద్వారా గ్రహించే 'లిప్ రీడింగ్' నైపుణ్యం వినికిడి లోపం (Hearing Impairment) ఉన్నవారికి అత్యంత కీలకం."}, {"id": 122, "sec": "Special Education", "passage": "", "q_en": "Which of the following activities is NOT related to Art and Craft in early special education?", "q_te": "క్రింది వానిలో లలిత కళలు మరియు క్రాఫ్ట్ కృత్యాలకు సంబంధం లేనిది ఏది", "opts": [{"en": "Expressing emotions creatively", "te": "భావోద్వేగాలను సృజనాత్మకంగా వ్యక్తం చేయడం", "raw": "Expressing emotions creatively / భావోద్వేగాలను సృజనాత్మకంగా వ్యక్తం చేయడం"}, {"en": "Developing fine motor skills", "te": "సూక్ష్మ చలన నైపుణ్యాలను అభివృద్ధి చేయడం", "raw": "Developing fine motor skills / సూక్ష్మ చలన నైపుణ్యాలను అభివృద్ధి చేయడం"}, {"en": "Sensory-motor physical development", "te": "ఇంద్రియ-చలన సమన్వయం", "raw": "Sensory-motor physical development / ఇంద్రియ-చలన సమన్వయం"}, {"en": "Eating food", "te": "ఆహారం తినడం (Eating)", "raw": "Eating food / ఆహారం తినడం (Eating)"}], "ans": 4, "exp_en": "Art and craft encompasses drawing, modeling, cutting, and emotional expression. Eating is an Adaptive Daily Living (ADL) self-care skill, not an art and craft task.", "exp_te": "చిత్రలేఖనం, మట్టి పనులు, రంగులు వేయడం కళా కృత్యాలు. భోజనం చేయడం (Eating) అనేది రోజువారీ స్వయం సహాయక నైపుణ్యం (ADL)."}, {"id": 123, "sec": "Special Education", "passage": "", "q_en": "Identifying hearing loss at this early developmental stage yields the best communicative outcomes", "q_te": "వినికిడి లోపాన్ని ఈ ప్రారంభ దశలోనే గుర్తించి నివారణ చర్యలు చేపడితే అత్యుత్తమ ఫలితాలు వస్తాయి", "opts": [{"en": "Puberty", "te": "యవ్వనారంభ దశ", "raw": "Puberty / యవ్వనారంభ దశ"}, {"en": "Early Childhood", "te": "పూర్వ బాల్యదశ", "raw": "Early Childhood / పూర్వ బాల్యదశ"}, {"en": "Later Childhood", "te": "ఉత్తర బాల్యదశ", "raw": "Later Childhood / ఉత్తర బాల్యదశ"}, {"en": "Infancy (Newborn stage)", "te": "శైశవ దశ (నవజాత శిశు దశ / Infancy)", "raw": "Infancy (Newborn stage) / శైశవ దశ (నవజాత శిశు దశ / Infancy)"}], "ans": 4, "exp_en": "Universal newborn hearing screening (UNHS) in infancy ensures early intervention before 6 months of age, enabling normal speech and language acquisition during the critical brain plasticity window.", "exp_te": "శిశువు పుట్టిన వెంటనే లేదా శైశవ దశలోనే వినికిడి లోపాన్ని గుర్తిస్తే, మెదడు భాషా కేంద్రాలు వికసించే వయస్సులోనే శ్రవణ పరికరాలు లేదా కాక్లియర్ ఇంప్లాంట్ ద్వారా మాటలు నేర్పవచ్చు."}, {"id": 124, "sec": "Special Education", "passage": "", "q_en": "A person experiencing persistent hearing loss needs to consult which medical specialist?", "q_te": "వినికిడి లోపం ఉన్న వ్యక్తులు సంప్రదించాల్సిన వైద్య నిపుణుడు", "opts": [{"en": "Cardiologist", "te": "కార్డియాలజిస్ట్ (గుండె నిపుణుడు)", "raw": "Cardiologist / కార్డియాలజిస్ట్ (గుండె నిపుణుడు)"}, {"en": "Dentist", "te": "దంత వైద్యుడు", "raw": "Dentist / దంత వైద్యుడు"}, {"en": "Psychologist", "te": "సైకాలజిస్ట్", "raw": "Psychologist / సైకాలజిస్ట్"}, {"en": "E.N.T. Specialist (Otolaryngologist)", "te": "ఇ.ఎన్.టి. వైద్యుడు (చెవి, ముక్కు, గొంతు నిపుణుడు - E.N.T)", "raw": "E.N.T. Specialist (Otolaryngologist) / ఇ.ఎన్.టి. వైద్యుడు (చెవి, ముక్కు, గొంతు నిపుణుడు - E.N.T)"}], "ans": 4, "exp_en": "Otolaryngologists (ENT doctors) diagnose and treat diseases and structural disorders of the Ear, Nose, and Throat, including all types of hearing impairment.", "exp_te": "చెవి, ముక్కు, గొంతు సమస్యలు మరియు వినికిడి లోపాలను పరీక్షించి చికిత్స చేసే వైద్య నిపుణుడిని ENT డాక్టర్ (Otolaryngologist) అంటారు."}, {"id": 125, "sec": "Special Education", "passage": "", "q_en": "Speech production and articulation fundamentally depend upon the prior", "q_te": "స్పష్టమైన వాక్కు (Speech) అనేది ప్రాథమికంగా దేని వికాసంపై ఆధారపడి ఉంటుంది", "opts": [{"en": "Development of Body height", "te": "శరీర ఎత్తు పెరగడం", "raw": "Development of Body height / శరీర ఎత్తు పెరగడం"}, {"en": "Development of arbitrary behavior", "te": "సాధారణ ప్రవర్తన", "raw": "Development of arbitrary behavior / సాధారణ ప్రవర్తన"}, {"en": "Development of receptive Language and auditory processing", "te": "భాషా వికాసం మరియు శ్రవణ గ్రహణ శక్తి (Development of Language)", "raw": "Development of receptive Language and auditory processing / భాషా వికాసం మరియు శ్రవణ గ్రహణ శక్తి (Development of Language)"}, {"en": "Development of social attitude", "te": "సాంఘిక వైఖరి", "raw": "Development of social attitude / సాంఘిక వైఖరి"}], "ans": 3, "exp_en": "Speech is the verbal expression of language. A child cannot produce expressive speech without first acquiring internal language comprehension and acoustic phonemic concepts.", "exp_te": "వాక్కు అనేది భాష యొక్క మౌఖిక రూపం. సరైన భాషా గ్రహణ వికాసం (Development of Language) మరియు వినికిడి ఉన్నప్పుడే స్పష్టమైన ఉచ్ఛారణ సాధ్యమవుతుంది."}, {"id": 126, "sec": "Special Education", "passage": "", "q_en": "The B.E.R.A. (Brainstem Evoked Response Audiometry) test is conducted to diagnose disorders in", "q_te": "BERA (Brainstem Evoked Response Audiometry) పరీక్ష ఏ అవయవ లోపాన్ని నిర్ధారించడానికి చేస్తారు", "opts": [{"en": "Heart", "te": "గుండె", "raw": "Heart / గుండె"}, {"en": "Nose", "te": "ముక్కు", "raw": "Nose / ముక్కు"}, {"en": "Ear (Auditory brainstem pathway)", "te": "చెవి (శ్రవణ నాడీ మార్గం / Ear)", "raw": "Ear (Auditory brainstem pathway) / చెవి (శ్రవణ నాడీ మార్గం / Ear)"}, {"en": "Mouth", "te": "నోరు", "raw": "Mouth / నోరు"}], "ans": 3, "exp_en": "BERA (or ABR) measures electrical brainwave activity in response to auditory clicks, assessing hearing thresholds and the integrity of the acoustic nerve from the inner ear to the brainstem.", "exp_te": "BERA పరీక్ష అనేది చెవి నుండి మెదడు కాండం వరకు శ్రవణ నాడి ద్వారా విద్యుత్ సంకేతాలు ప్రసారమయ్యే తీరును కొలిచే ఆధునిక వినికిడి పరీక్ష."}, {"id": 127, "sec": "Special Education", "passage": "", "q_en": "Natural rhythm, prosody, and intonation of speech are severely impaired in persons with", "q_te": "మాటలలో సహజసిద్ధమైన లయ (Rhythm), శృతి లోపించి వినపడే వైకల్యం", "opts": [{"en": "Learning Disability", "te": "అభ్యసన వైకల్యం", "raw": "Learning Disability / అభ్యసన వైకల్యం"}, {"en": "Visual Impairment", "te": "దృష్టి లోపం", "raw": "Visual Impairment / దృష్టి లోపం"}, {"en": "Hearing Impairment", "te": "శ్రవణ (వినికిడి) లోపం (Hearing Impairment)", "raw": "Hearing Impairment / శ్రవణ (వినికిడి) లోపం (Hearing Impairment)"}, {"en": "Blood Disorder", "te": "రక్త సంబంధిత రుగ్మత", "raw": "Blood Disorder / రక్త సంబంధిత రుగ్మత"}], "ans": 3, "exp_en": "Because children with congenital hearing impairment lack the auditory feedback loop to self-monitor pitch and volume, their speech often lacks natural rhythm, pitch modulation, and melody.", "exp_te": "వినికిడి లోపం ఉన్న పిల్లలు తాము మాట్లాడే మాటలను తాము తిరిగి వినలేరు (Auditory feedback లోపం), అందువల్ల వారి మాటలలో సహజమైన లయ, శృతి (Rhythm) లోపిస్తుంది."}, {"id": 128, "sec": "Special Education", "passage": "", "q_en": "Cochlear Implants are surgically placed biomedical devices designed to provide direct electrical stimulation to the", "q_te": "కాక్లియర్ ఇంప్లాంట్స్ (Cochlear Implants) శస్త్రచికిత్స ద్వారా నేరుగా ఏ నాడిని విద్యుత్ సంకేతాలతో ఉత్తేజపరుస్తాయి?", "opts": [{"en": "Optic nerve", "te": "దృష్టి నాడి (ఆప్టిక్ నెర్వ్)", "raw": "Optic nerve / దృష్టి నాడి (ఆప్టిక్ నెర్వ్)"}, {"en": "Spinal cord", "te": "వెన్నుపాము", "raw": "Spinal cord / వెన్నుపాము"}, {"en": "Olfactory nerve", "te": "ఘ్రాణ నాడి", "raw": "Olfactory nerve / ఘ్రాణ నాడి"}, {"en": "Auditory nerve (Cochlear nerve)", "te": "శ్రవణ నాడి (Auditory nerve)", "raw": "Auditory nerve (Cochlear nerve) / శ్రవణ నాడి (Auditory nerve)"}], "ans": 4, "exp_en": "A Cochlear Implant bypasses damaged hair cells in the cochlea and directly stimulates the auditory nerve fibers with electrical pulses to send sound signals to the brain.", "exp_te": "కాక్లియర్ ఇంప్లాంట్ అనేది లోపలి చెవిలోని దెబ్బతిన్న రోమ కణాలను దాటవేసి, నేరుగా 'శ్రవణ నాడి'ని (Auditory Nerve) ప్రేరేపించడం ద్వారా మెదడుకు శబ్ద సంకేతాలను చేరవేస్తుంది."}, {"id": 129, "sec": "Special Education", "passage": "", "q_en": "The smallest bone in the human body, located in the middle ear, is the", "q_te": "మానవ శరీరంలోనే అతి చిన్న ఎముక, మధ్య చెవిలో ఉండేది ఏది", "opts": [{"en": "Stapes (Stirrup)", "te": "స్టేప్స్ (Stapes / కర్ణాంతరాస్థి)", "raw": "Stapes (Stirrup) / స్టేప్స్ (Stapes / కర్ణాంతరాస్థి)"}, {"en": "Incus (Anvil)", "te": "ఇంకస్", "raw": "Incus (Anvil) / ఇంకస్"}, {"en": "Malleus (Hammer)", "te": "మాలియస్", "raw": "Malleus (Hammer) / మాలియస్"}, {"en": "Rib", "te": "పక్కటెముక", "raw": "Rib / పక్కటెముక"}], "ans": 1, "exp_en": "The Stapes (stirrup bone) in the middle ear ossicular chain is approximately 3 mm long and is the smallest and lightest bone in the human body.", "exp_te": "మధ్య చెవిలోని మూడు ఎముకలలో ఒకటైన 'స్టేప్స్' (Stapes) మానవ శరీరంలోనే అత్యంత చిన్న ఎముక."}, {"id": 130, "sec": "Special Education", "passage": "", "q_en": "A child uttering 'Thathi' instead of 'Kaki' (substituting sounds) displays this speech defect", "q_te": "వినికిడి లోపం గల పిల్లవాడు 'కాకి' అనడానికి బదులుగా 'తాతి' అని పలకడం ఏ రకమైన వాక్ లోపం", "opts": [{"en": "Rhythm Disorders", "te": "లయ లోపాలు", "raw": "Rhythm Disorders / లయ లోపాలు"}, {"en": "Voice Disorders", "te": "స్వర లోపాలు", "raw": "Voice Disorders / స్వర లోపాలు"}, {"en": "Articulatory Disorders (Substitution)", "te": "ఉచ్ఛారణా లోపాలు (Articulatory Disorders - అక్షర మార్పిడి)", "raw": "Articulatory Disorders (Substitution) / ఉచ్ఛారణా లోపాలు (Articulatory Disorders - అక్షర మార్పిడి)"}, {"en": "Stuttering", "te": "నత్తి", "raw": "Stuttering / నత్తి"}], "ans": 3, "exp_en": "Articulation disorders (SODA: Substitution, Omission, Distortion, Addition) occur when speech sounds are substituted. Replacing 'k' with 'th' is a classic substitution error.", "exp_te": "ఒక అక్షరానికి బదులుగా మరొక అక్షరాన్ని పలికే దోషాన్ని ఉచ్ఛారణా లోపాలలో 'మార్పిడి' (Substitution Articulatory Disorder) అంటారు."}, {"id": 131, "sec": "Special Education", "passage": "", "q_en": "Which of the following precautions is INCORRECT and should NOT be done when maintaining a Hearing Aid?", "q_te": "శ్రవణ పరికరాన్ని (Hearing Aid) సంరక్షించేటప్పుడు చేయకూడని పని ఏది", "opts": [{"en": "Keep away from pet animals", "te": "పెంపుడు జంతువులకు దూరంగా ఉంచడం", "raw": "Keep away from pet animals / పెంపుడు జంతువులకు దూరంగా ఉంచడం"}, {"en": "Remove the battery when hearing aid is not in use", "te": "ఉపయోగించనప్పుడు బ్యాటరీని తీసి ఉంచడం", "raw": "Remove the battery when hearing aid is not in use / ఉపయోగించనప్పుడు బ్యాటరీని తీసి ఉంచడం"}, {"en": "Clean the electronic hearing aid with water", "te": "ఎలక్ట్రానిక్ శ్రవణ పరికరాన్ని నీటితో కడగడం (Clean with water)", "raw": "Clean the electronic hearing aid with water / ఎలక్ట్రానిక్ శ్రవణ పరికరాన్ని నీటితో కడగడం (Clean with water)"}, {"en": "Keep the device away from moisture and direct heat", "te": "తేమ మరియు అధిక వేడికి దూరంగా ఉంచడం", "raw": "Keep the device away from moisture and direct heat / తేమ మరియు అధిక వేడికి దూరంగా ఉంచడం"}], "ans": 3, "exp_en": "Hearing aids are sensitive micro-electronic devices. Water or moisture will immediately corrode circuitry, short-circuit the microphone, and permanently ruin the instrument.", "exp_te": "శ్రవణ యంత్రాలు సున్నితమైన ఎలక్ట్రానిక్ పరికరాలు. వాటిని నీటితో కడిగితే మైక్రోఫోన్ మరియు సర్క్యూట్లు దెబ్బతింటాయి; కాబట్టి ఎట్టి పరిస్థితుల్లోనూ నీటితో కడగకూడదు."}, {"id": 132, "sec": "Special Education", "passage": "", "q_en": "A Perinatal (occurring during birth/delivery) cause of child impairment is", "q_te": "ప్రసవ సమయంలో (Peri-Natal) వైకల్యానికి దారితీసే కారణం ఏది", "opts": [{"en": "Rh factor incompatibility during pregnancy", "te": "గర్భధారణ సమయంలో Rh రక్త వైరుధ్యం (Prenatal)", "raw": "Rh factor incompatibility during pregnancy / గర్భధారణ సమయంలో Rh రక్త వైరుధ్యం (Prenatal)"}, {"en": "Complicated prolonged instrumental delivery causing brain anoxia", "te": "ప్రసవ సమయంలో ఫోర్సెప్స్ వంటి సాధనాల వల్ల తలకు గాయం లేదా ఆక్సిజన్ అందకపోవడం (Perinatal)", "raw": "Complicated prolonged instrumental delivery causing brain anoxia / ప్రసవ సమయంలో ఫోర్సెప్స్ వంటి సాధనాల వల్ల తలకు గాయం లేదా ఆక్సిజన్ అందకపోవడం (Perinatal)"}, {"en": "Taking teratogenic drugs during first trimester", "te": "గర్భిణీ స్త్రీలు నిషేధిత మందులు వాడటం (Prenatal)", "raw": "Taking teratogenic drugs during first trimester / గర్భిణీ స్త్రీలు నిషేధిత మందులు వాడటం (Prenatal)"}, {"en": "Pre-conceptional genetic chromosomal mutations", "te": "జన్యుపరమైన లోపాలు (Prenatal)", "raw": "Pre-conceptional genetic chromosomal mutations / జన్యుపరమైన లోపాలు (Prenatal)"}], "ans": 2, "exp_en": "Perinatal causes occur precisely during the labor and delivery process, such as birth asphyxia, prolonged labor, and mechanical forceps birth trauma.", "exp_te": "ప్రసవం జరుగుతున్న సమయంలో (Perinatal) బిడ్డకు ఆక్సిజన్ అందకపోవడం లేదా ఫోర్సెప్స్ ప్రసవ గాయాల వల్ల మెదడు దెబ్బతిని వైకల్యం కలగవచ్చు."}, {"id": 133, "sec": "Special Education", "passage": "", "q_en": "Hearing loss that occurs before a child naturally acquires spoken language is termed", "q_te": "పిల్లవాడు సంభాషణా భాషను నేర్చుకోవడానికి ముందే సంభవించే వినికిడి లోపాన్ని ఏమంటారు", "opts": [{"en": "Post-lingual deafness", "te": "భాషార్జనానంతర బధిరత్వం (Post-lingual)", "raw": "Post-lingual deafness / భాషార్జనానంతర బధిరత్వం (Post-lingual)"}, {"en": "Pre-lingual deafness", "te": "భాషార్జనకు పూర్వ బధిరత్వం (Pre-lingual Deafness)", "raw": "Pre-lingual deafness / భాషార్జనకు పూర్వ బధిరత్వం (Pre-lingual Deafness)"}, {"en": "Accidental deafness", "te": "ప్రమాదవశాత్తు బధిరత్వం", "raw": "Accidental deafness / ప్రమాదవశాత్తు బధిరత్వం"}, {"en": "Temporary hearing loss", "te": "తాత్కాలిక లోపం", "raw": "Temporary hearing loss / తాత్కాలిక లోపం"}], "ans": 2, "exp_en": "Pre-lingual deafness refers to hearing impairment present at birth or acquired before the critical development of speech and language (typically under 2-3 years).", "exp_te": "సహజంగా మాట్లాడటం నేర్చుకోవడానికి ముందే (సాధారణంగా 2-3 సంవత్సరాల లోపే) కలిగే వినికిడి లోపాన్ని 'భాషార్జనకు పూర్వ బధిరత్వం' (Pre-lingual deafness) అంటారు."}, {"id": 134, "sec": "Special Education", "passage": "", "q_en": "In audiology, the 'Speech Banana' graphical region on an audiogram represents", "q_te": "ఆడియోగ్రామ్‌పై 'స్పీచ్ బనానా' (Speech Banana) ఆకారం దేనిని సూచిస్తుంది", "opts": [{"en": "Hearing sensitivity to loud thunder", "te": "తీవ్రమైన శబ్దాలను వినడం", "raw": "Hearing sensitivity to loud thunder / తీవ్రమైన శబ్దాలను వినడం"}, {"en": "The frequency and intensity boundaries of human speech sounds", "te": "మానవ సంభాషణా ధ్వనుల పౌనఃపున్యం మరియు తీవ్రత ప్రాంతం (Speech Sounds)", "raw": "The frequency and intensity boundaries of human speech sounds / మానవ సంభాషణా ధ్వనుల పౌనఃపున్యం మరియు తీవ్రత ప్రాంతం (Speech Sounds)"}, {"en": "Vision clarity", "te": "దృష్టి తీక్షణత", "raw": "Vision clarity / దృష్టి తీక్షణత"}, {"en": "Mobility tracking", "te": "శరీర కదలికలు", "raw": "Mobility tracking / శరీర కదలికలు"}], "ans": 2, "exp_en": "The 'Speech Banana' is a banana-shaped area plotted on an audiogram (frequencies 250-8000 Hz, intensities 20-60 dB) where all vowels and consonants of human conversational speech occur.", "exp_te": "ఆడియోగ్రామ్ గ్రాఫ్‌పై అరటిపండు ఆకారంలో ఉండే ప్రాంతంలో మానవ సంభాషణకు సంబంధించిన అన్ని అచ్చులు, హల్లుల ధ్వనుల ఫ్రీక్వెన్సీ మరియు తీవ్రత ఉంటాయి."}, {"id": 135, "sec": "Special Education", "passage": "", "q_en": "Which of the following is NOT an intrinsic clinical parameter of Speech?", "q_te": "క్రింది వానిలో వాక్కు (Speech) యొక్క సహజ గుణాంశం కానిది ఏది", "opts": [{"en": "Voice quality and pitch", "te": "వాయిస్ (Voice / స్వర నాణ్యత)", "raw": "Voice quality and pitch / వాయిస్ (Voice / స్వర నాణ్యత)"}, {"en": "Fluency and rate", "te": "ఫ్లూయెన్సీ (Fluency / ధారాళత)", "raw": "Fluency and rate / ఫ్లూయెన్సీ (Fluency / ధారాళత)"}, {"en": "Rhythm and melody", "te": "రిథమ్ (Rhythm / లయ)", "raw": "Rhythm and melody / రిథమ్ (Rhythm / లయ)"}, {"en": "Accuracy (General knowledge)", "te": "ఖచ్చితత్వం (Accuracy - సాధారణ పరిజ్ఞానం)", "raw": "Accuracy (General knowledge) / ఖచ్చితత్వం (Accuracy - సాధారణ పరిజ్ఞానం)"}], "ans": 4, "exp_en": "The physiological parameters of speech are Voice (pitch, loudness, quality), Fluency (rate, flow), and Articulation/Rhythm. 'Accuracy' is an intellectual metric, not a speech organ parameter.", "exp_te": "వాక్కు యొక్క శాస్త్రీయ గుణాంశాలు స్వరము (Voice), ధారాళత (Fluency), మరియు లయ (Rhythm). ఖచ్చితత్వం అనేది వాక్కు యొక్క భౌతిక పారామీటర్ కాదు."}, {"id": 136, "sec": "Special Education", "passage": "", "q_en": "In children with speech impairment, poor and uncoordinated articulation of phonemes leads to", "q_te": "వాక్ లోపం గల పిల్లలలో ధ్వనుల సరైన ఉచ్ఛారణ మరియు సమన్వయం లేకపోవడం వల్ల ఏమి జరుగుతుంది", "opts": [{"en": "Superior oration", "te": "గొప్ప ఉపన్యాస నైపుణ్యం", "raw": "Superior oration / గొప్ప ఉపన్యాస నైపుణ్యం"}, {"en": "Difficulty in intelligibility of speech", "te": "మాటలు ఎదుటివారికి స్పష్టంగా అర్థం కాకపోవడం (Loss of Intelligibility)", "raw": "Difficulty in intelligibility of speech / మాటలు ఎదుటివారికి స్పష్టంగా అర్థం కాకపోవడం (Loss of Intelligibility)"}, {"en": "Enhanced vocabulary", "te": "అధిక పద సంపద", "raw": "Enhanced vocabulary / అధిక పద సంపద"}, {"en": "Rapid reading", "te": "వేగవంతమైన పఠనం", "raw": "Rapid reading / వేగవంతమైన పఠనం"}], "ans": 2, "exp_en": "When speech sounds are distorted, omitted, or substituted due to motor coordination issues, the overall clarity and intelligibility of spoken language drops significantly.", "exp_te": "ఉచ్ఛారణా లోపాల వల్ల వారు మాట్లాడే మాటలు ఇతరులకు అర్థం కాకుండా స్పష్టత లోపిస్తుంది (Lack of Speech Intelligibility)."}, {"id": 137, "sec": "Special Education", "passage": "", "q_en": "Daniel Ling '6' Sound Test is used to", "q_te": "డేనియల్ లింగ్ '6' సౌండ్ టెస్ట్ దీని కోసం ఉపయోగించబడుతుంది", "opts": [{"en": "Identify and detect Speech Sounds (/m, u, a, i, sh, s/)", "te": "ధ్వనులను గుర్తించడం/గ్రహించడం (Identify Sounds)", "raw": "Identify and detect Speech Sounds (/m, u, a, i, sh, s/) / ధ్వనులను గుర్తించడం/గ్రహించడం (Identify Sounds)"}, {"en": "Identify Intelligence", "te": "ప్రజ్ఞను గుర్తించడం", "raw": "Identify Intelligence / ప్రజ్ఞను గుర్తించడం"}, {"en": "Identify Speech defects only", "te": "మాటల లోపాలను గుర్తించడం", "raw": "Identify Speech defects only / మాటల లోపాలను గుర్తించడం"}, {"en": "Measure IQ Accuracy", "te": "ఖచ్చితత్వాన్ని కొలవడం", "raw": "Measure IQ Accuracy / ఖచ్చితత్వాన్ని కొలవడం"}], "ans": 1, "exp_en": "The Ling 6 Sound Test (developed by Daniel Ling) uses six sounds (/m/, /u/, /a/, /i/, /sh/, /s/) spanning low, mid, and high frequencies (250 Hz to 4000 Hz) to quickly check whether a child with hearing impairment can detect and identify speech sounds across the speech frequency spectrum.", "exp_te": "డేనియల్ లింగ్ 6 సౌండ్ టెస్ట్ లో ఆరు ప్రాథమిక ధ్వనులు (/m/, /u/, /a/, /i/, /sh/, /s/) ఉంటాయి. శ్రవణ సహాయ పరికరాలు ధరించిన శ్రవణ లోపం గల పిల్లలు సంభాషణ ధ్వనులను సరిగ్గా వినగలుగుతున్నారా మరియు గుర్తించగలుగుతున్నారా (Identify the Sounds) అని తనిఖీ చేయడానికి ఈ పరీక్ష ఉపయోగపడుతుంది."}, {"id": 138, "sec": "Special Education", "passage": "", "q_en": "A demerit / limitation of Otoacoustic Emission (OAE) Test is", "q_te": "ఓటోఅకౌస్టిక్ ఎమిషన్ (OAE) పరీక్ష యొక్క లోపం/పరిమితి", "opts": [{"en": "It is a quick Test", "te": "ఇది చాలా శీఘ్రంగా పూర్తయ్యే పరీక్ష", "raw": "It is a quick Test / ఇది చాలా శీఘ్రంగా పూర్తయ్యే పరీక్ష"}, {"en": "It can be performed on new born babies", "te": "నవజాత శిశువులపై కూడా నిర్వహించవచ్చు", "raw": "It can be performed on new born babies / నవజాత శిశువులపై కూడా నిర్వహించవచ్చు"}, {"en": "Test results are reliable", "te": "ఫలితాలు విశ్వసనీయమైనవి", "raw": "Test results are reliable / ఫలితాలు విశ్వసనీయమైనవి"}, {"en": "Initial cost is high / test equipment cost is high", "te": "ప్రారంభ పరికరాల వ్యయం ఎక్కువ (Initial cost is high)", "raw": "Initial cost is high / test equipment cost is high / ప్రారంభ పరికరాల వ్యయం ఎక్కువ (Initial cost is high)"}], "ans": 4, "exp_en": "While OAE is a fast, non-invasive objective screening test ideal for newborns, its equipment initial cost is high, and it cannot evaluate hearing beyond the cochlea (retrocochlear / auditory neuropathy disorders).", "exp_te": "OAE (Otoacoustic Emission) పరీక్ష శీఘ్రమైనది మరియు పసిపిల్లలకు అనువైనదే అయినప్పటికీ, దీని ప్రత్యేక యంత్ర పరికరాల ప్రారంభ వ్యయం చాలా ఎక్కువ (Initial cost is high). అలాగే ఇది కర్ణాంతరానికి ఆవల ఉండే శ్రవణ నాడీ లోపాలను గుర్తించలేదు."}, {"id": 139, "sec": "Special Education", "passage": "", "q_en": "This training should be given prior to improve residual hearing ability in Children with Hearing Impairment", "q_te": "శ్రవణ లోపం గల పిల్లలలో మిగిలి ఉన్న శ్రవణ శక్తిని (Residual hearing) మెరుగుపరచడానికి ముందుగా ఇవ్వవలసిన శిక్షణ", "opts": [{"en": "Mobility training", "te": "మొబిలిటీ శిక్షణ (చలనశీలత)", "raw": "Mobility training / మొబిలిటీ శిక్షణ (చలనశీలత)"}, {"en": "Speech training", "te": "స్పీచ్ ట్రైనింగ్ (వాక్ శిక్షణ)", "raw": "Speech training / స్పీచ్ ట్రైనింగ్ (వాక్ శిక్షణ)"}, {"en": "Auditory training", "te": "ఆడిటరీ ట్రైనింగ్ (శ్రవణ శిక్షణ)", "raw": "Auditory training / ఆడిటరీ ట్రైనింగ్ (శ్రవణ శిక్షణ)"}, {"en": "Speech reading (Lip reading)", "te": "స్పీచ్ రీడింగ్ (పెదవుల కదలికల గ్రహణ)", "raw": "Speech reading (Lip reading) / స్పీచ్ రీడింగ్ (పెదవుల కదలికల గ్రహణ)"}], "ans": 3, "exp_en": "Auditory Training is the systematic training given to a child with hearing impairment to maximize the use of their residual hearing (using hearing aids or cochlear implants) to become aware of, discriminate, identify, and comprehend environmental and speech sounds.", "exp_te": "శ్రవణ లోపం గల పిల్లల్లో మిగిలి ఉన్న వినికిడి శక్తిని (Residual hearing) గరిష్టంగా ఉపయోగించుకోవడానికి మొదటగా 'ఆడిటరీ ట్రైనింగ్' (శ్రవణ శిక్షణ) ఇవ్వాలి. శబ్దాల ఉనికిని గుర్తించడం మరియు విచక్షణ చేయడంలో ఇది మొదటి మెట్టు."}, {"id": 140, "sec": "Special Education", "passage": "", "q_en": "Eardrum (Tympanic Membrane)", "q_te": "కర్ణభేరి (Eardrum / Tympanic Membrane) చేయు పని", "opts": [{"en": "Separates external ear from middle ear", "te": "బాహ్య చెవిని మధ్య చెవి నుండి వేరు చేస్తుంది", "raw": "Separates external ear from middle ear / బాహ్య చెవిని మధ్య చెవి నుండి వేరు చేస్తుంది"}, {"en": "Separates inner ear from middle ear", "te": "లోపలి చెవిని మధ్య చెవి నుండి వేరు చేస్తుంది", "raw": "Separates inner ear from middle ear / లోపలి చెవిని మధ్య చెవి నుండి వేరు చేస్తుంది"}, {"en": "Situated in inner ear", "te": "లోపలి చెవిలో ఉంటుంది", "raw": "Situated in inner ear / లోపలి చెవిలో ఉంటుంది"}, {"en": "Regulates Brain", "te": "మెదడును నియంత్రిస్తుంది", "raw": "Regulates Brain / మెదడును నియంత్రిస్తుంది"}], "ans": 1, "exp_en": "The eardrum (tympanic membrane) is a thin, cone-shaped semi-transparent membrane that separates the external auditory canal from the middle ear cavity and vibrates in response to sound waves.", "exp_te": "కర్ణభేరి (Tympanic membrane) బాహ్య శ్రవణ కుహరాన్ని (బాహ్య చెవిని) మధ్య చెవి నుండి వేరు చేస్తుంది. శబ్ద తరంగాలు దీనిని తాకినప్పుడు ఇది కంపించి ఆ ప్రకంపనలను మధ్య చెవిలోని కర్ణాంతర ఎముకలకు అందజేస్తుంది."}, {"id": 141, "sec": "Special Education", "passage": "", "q_en": "Which of the following is NOT a cause of Deafness / Hearing Impairment?", "q_te": "కింది వాటిలో చెవుడు/శ్రవణ లోపానికి కారణం కానిది", "opts": [{"en": "Chromosomal aberrations", "te": "క్రోమోజోముల లోపాలు", "raw": "Chromosomal aberrations / క్రోమోజోముల లోపాలు"}, {"en": "Mother blood (Rh incompatibility / Rh factor)", "te": "తల్లి రక్తంలోని Rh కారకం (Rh factor)", "raw": "Mother blood (Rh incompatibility / Rh factor) / తల్లి రక్తంలోని Rh కారకం (Rh factor)"}, {"en": "Pre-natal maternal infections", "te": "జనన పూర్వ ఇన్ఫెక్షన్లు", "raw": "Pre-natal maternal infections / జనన పూర్వ ఇన్ఫెక్షన్లు"}, {"en": "Social development", "te": "సాంఘిక వికాసం (Social development)", "raw": "Social development / సాంఘిక వికాసం (Social development)"}], "ans": 4, "exp_en": "Social development is a positive psycho-social developmental process and is definitely NOT a biomedical cause of hearing impairment or deafness, whereas genetics, Rh incompatibility, and prenatal infections are well-established biological causes.", "exp_te": "సాంఘిక వికాసం (Social development) అనేది ఒక వ్యక్తి యొక్క ఆరోగ్యకరమైన సామాజిక ప్రక్రియ. ఇది ఎంతమాత్రం వినికిడి లోపానికి కారణం కాదు. క్రోమోజోమ్ లోపాలు, Rh కారకం వ్యత్యాసాలు, గర్భస్థ శిశువుకు సోకే అంటువ్యాధులు శ్రవణ లోపానికి దారితీసే ముఖ్య కారణాలు."}, {"id": 142, "sec": "Special Education", "passage": "", "q_en": "It helps to improve speech skills and academic skills of children with Hearing Impairment", "q_te": "శ్రవణ లోపం గల పిల్లల వాక్ నైపుణ్యాలు మరియు విద్యా నైపుణ్యాలను మెరుగుపరచడానికి ఇది తోడ్పడుతుంది", "opts": [{"en": "Art Education", "te": "కళా విద్య", "raw": "Art Education / కళా విద్య"}, {"en": "Remedial Teaching", "te": "ఉపశమన బోధన / నివారణా బోధన (Remedial Teaching)", "raw": "Remedial Teaching / ఉపశమన బోధన / నివారణా బోధన (Remedial Teaching)"}, {"en": "Playing Games", "te": "ఆటలు ఆడటం", "raw": "Playing Games / ఆటలు ఆడటం"}, {"en": "Craft Activities", "te": "చేతిపనులు", "raw": "Craft Activities / చేతిపనులు"}], "ans": 2, "exp_en": "Remedial Teaching (నివారణా బోధన / ఉపశమన బోధన) provides individualized instructional support and customized intervention to overcome specific speech, language, and academic deficits in hearing-impaired learners.", "exp_te": "ఉపశమన బోధన (Remedial Teaching) ద్వారా శ్రవణ లోపం గల పిల్లలకు ప్రత్యేక శ్రద్ధతో వారి వ్యక్తిగత అవసరాలకు తగినట్లు బోధించడం వల్ల వారి వాక్ నైపుణ్యాలు మరియు అభ్యాస/విద్యా నైపుణ్యాలు గణనీయంగా మెరుగుపడతాయి."}, {"id": 143, "sec": "Special Education", "passage": "", "q_en": "Expand RCI", "q_te": "RCI ని విస్తరించగా", "opts": [{"en": "Re Collect Institute", "te": "రీ కలెక్ట్ ఇన్స్టిట్యూట్", "raw": "Re Collect Institute / రీ కలెక్ట్ ఇన్స్టిట్యూట్"}, {"en": "Rising Council of Institute", "te": "రైజింగ్ కౌన్సిల్ ఆఫ్ ఇన్స్టిట్యూట్", "raw": "Rising Council of Institute / రైజింగ్ కౌన్సిల్ ఆఫ్ ఇన్స్టిట్యూట్"}, {"en": "Rehabilitation Council of India", "te": "రిహాబిలిటేషన్ కౌన్సిల్ ఆఫ్ ఇండియా (Rehabilitation Council of India)", "raw": "Rehabilitation Council of India / రిహాబిలిటేషన్ కౌన్సిల్ ఆఫ్ ఇండియా (Rehabilitation Council of India)"}, {"en": "Rare Council of India", "te": "రేర్ కౌన్సిల్ ఆఫ్ ఇండియా", "raw": "Rare Council of India / రేర్ కౌన్సిల్ ఆఫ్ ఇండియా"}], "ans": 3, "exp_en": "RCI stands for the Rehabilitation Council of India, a statutory body constituted under the RCI Act 1992 that regulates training policies and programmes for disability rehabilitation professionals and personnel in India.", "exp_te": "RCI పూర్తి రూపం 'రిహాబిలిటేషన్ కౌన్సిల్ ఆఫ్ ఇండియా' (Rehabilitation Council of India - భారత పునరావాస మండలి). ఇది భారతదేశంలో ప్రత్యేక విద్య మరియు పునరావాస నిపుణుల శిక్షణా ప్రమాణాలను క్రమబద్ధీకరించే చట్టబద్ధమైన సంస్థ."}, {"id": 144, "sec": "Special Education", "passage": "", "q_en": "The character / attitude that should NOT be developed in children with Hearing Impairment is", "q_te": "శ్రవణ లోపం గల పిల్లలలో పెంపొందించకూడని/కలిగించకూడని లక్షణం", "opts": [{"en": "Developing communication skills", "te": "భావప్రసార నైపుణ్యాలను అభివృద్ధి చేయడం", "raw": "Developing communication skills / భావప్రసార నైపుణ్యాలను అభివృద్ధి చేయడం"}, {"en": "Developing speech reading (lip reading)", "te": "స్పీచ్ రీడింగ్ (లిప్ రీడింగ్) ను పెంపొందించడం", "raw": "Developing speech reading (lip reading) / స్పీచ్ రీడింగ్ (లిప్ రీడింగ్) ను పెంపొందించడం"}, {"en": "Developing inferiority complex", "te": "ఆత్మన్యూనతా భావాన్ని (Inferiority complex) కలిగించడం", "raw": "Developing inferiority complex / ఆత్మన్యూనతా భావాన్ని (Inferiority complex) కలిగించడం"}, {"en": "Developing auditory training", "te": "ఆడిటరీ శిక్షణను పెంపొందించడం", "raw": "Developing auditory training / ఆడిటరీ శిక్షణను పెంపొందించడం"}], "ans": 3, "exp_en": "Teachers and parents should build confidence, self-esteem, and social skills in children with hearing impairment, and must NEVER allow or cause an inferiority complex to develop in them.", "exp_te": "శ్రవణ లోపం గల పిల్లలలో ఆత్మన్యూనతా భావాన్ని (Inferiority complex) ఎట్టి పరిస్థితుల్లోనూ కలిగించకూడదు లేదా ప్రోత్సహించకూడదు. వారికి సమాజంలో సమానమైన ఆత్మవిశ్వాసం, కమ్యూనికేషన్ మరియు స్వతంత్ర జీవన నైపుణ్యాలను పెంపొందించాలి."}, {"id": 145, "sec": "Special Education", "passage": "", "q_en": "'Cribogram' is an automated neonatal screening device used to identify", "q_te": "'క్రిబోగ్రామ్' (Cribogram) అనేది దేనిని గుర్తించడానికి ఉపయోగించే పరికరం", "opts": [{"en": "Intellectual Disability", "te": "మేధో వైకల్యం", "raw": "Intellectual Disability / మేధో వైకల్యం"}, {"en": "Visual Impairment", "te": "దృష్టి లోపం", "raw": "Visual Impairment / దృష్టి లోపం"}, {"en": "Learning Disability", "te": "అభ్యసన వైకల్యం", "raw": "Learning Disability / అభ్యసన వైకల్యం"}, {"en": "Hearing Impairment in infants", "te": "శిశువులలో వినికిడి లోపం (Hearing Impairment)", "raw": "Hearing Impairment in infants / శిశువులలో వినికిడి లోపం (Hearing Impairment)"}], "ans": 4, "exp_en": "A Cribogram records neonates' startle, respiratory, and motor reflex movements in response to calibrated sound bursts to detect early hearing loss.", "exp_te": "క్రిబోగ్రామ్ పరికరం శిశువు పడుకునే తొట్టిలో ఉంచి, ధ్వనులను వినిపించినప్పుడు వారి శరీర కదలికలను కొలవడం ద్వారా పుట్టుకతో వచ్చే వినికిడి లోపాన్ని గుర్తిస్తుంది."}, {"id": 146, "sec": "Special Education", "passage": "", "q_en": "Which of the following is NOT a recognized dimensional form of Integrated Education?", "q_te": "క్రింది వానిలో సమీకృత విద్య (Integrated Education) రూపాలకు సంబంధం లేనిది ఏది", "opts": [{"en": "Partial Integration", "te": "పాక్షిక సమైక్యత (Partial Integration)", "raw": "Partial Integration / పాక్షిక సమైక్యత (Partial Integration)"}, {"en": "Peripheral Integration", "te": "పరిధీయ సమైక్యత (Peripheral Integration)", "raw": "Peripheral Integration / పరిధీయ సమైక్యత (Peripheral Integration)"}, {"en": "Total Integration", "te": "సంపూర్ణ సమైక్యత (Total Integration)", "raw": "Total Integration / సంపూర్ణ సమైక్యత (Total Integration)"}, {"en": "Gender Integration", "te": "జెండర్ ఇంటిగ్రేషన్ (Gender Integration)", "raw": "Gender Integration / జెండర్ ఇంటిగ్రేషన్ (Gender Integration)"}], "ans": 4, "exp_en": "S.J. Pijl and Meijer classify educational integration into Locational/Peripheral, Social/Partial, and Functional/Total integration. 'Gender integration' is a demographic concept.", "exp_te": "సమీకృత విద్యలో పాక్షిక సమైక్యత, పరిధీయ సమైక్యత, సంపూర్ణ సమైక్యత అనేవి వైకల్య విద్యా నమూనాలు. 'జెండర్ ఇంటిగ్రేషన్' అనేది లింగ సమానత్వానికి సంబంధించింది."}, {"id": 147, "sec": "Special Education", "passage": "", "q_en": "A psychological condition where an individual exhibits hearing loss despite having anatomically and physiologically intact ears is", "q_te": "చెవి నిర్మాణం, నాడీ వ్యవస్థ సాధారణంగా ఉన్నప్పటికీ మానసిక కారణాల వల్ల వినికిడి కోల్పోయినట్లు ప్రవర్తించడం", "opts": [{"en": "Conductive Hearing Loss", "te": "వహన వినికిడి లోపం", "raw": "Conductive Hearing Loss / వహన వినికిడి లోపం"}, {"en": "Sensory-Neural Hearing Loss", "te": "సెన్సరీ న్యూరల్ లోపం", "raw": "Sensory-Neural Hearing Loss / సెన్సరీ న్యూరల్ లోపం"}, {"en": "Central Auditory Disorder", "te": "సెంట్రల్ ఆడిటరీ డిజార్డర్", "raw": "Central Auditory Disorder / సెంట్రల్ ఆడిటరీ డిజార్డర్"}, {"en": "Functional / Psychogenic Deafness", "te": "ఫంక్షనల్ / సైకోజెనిక్ బధిరత్వం (Functional Deafness)", "raw": "Functional / Psychogenic Deafness / ఫంక్షనల్ / సైకోజెనిక్ బధిరత్వం (Functional Deafness)"}], "ans": 4, "exp_en": "Functional (or psychogenic/non-organic) deafness is an apparent hearing impairment where organic audiological tests reveal normal hearing, triggered by psychological trauma or stress.", "exp_te": "చెవులు, నాడీ వ్యవస్థ ఆరోగ్యంగా ఉన్నప్పటికీ తీవ్ర మానసిక ఒత్తిడి లేదా భావోద్వేగాల వల్ల వినపడటం లేదని భావించడాన్ని 'ఫంక్షనల్ / సైకోజెనిక్ బధిరత్వం' అంటారు."}, {"id": 148, "sec": "Special Education", "passage": "", "q_en": "The function of the Microphone in an electronic Hearing Aid is to", "q_te": "శ్రవణ యంత్రంలోని (Hearing Aid) మైక్రోఫోన్ నిర్వహించే ముఖ్యమైన పని", "opts": [{"en": "Convert acoustic sound waves into electrical signals", "te": "ధ్వని తరంగాలను విద్యుత్ సంకేతాలుగా మార్చడం (Converts sound into electrical signals)", "raw": "Convert acoustic sound waves into electrical signals / ధ్వని తరంగాలను విద్యుత్ సంకేతాలుగా మార్చడం (Converts sound into electrical signals)"}, {"en": "Convert electrical signals into amplified sound signals", "te": "విద్యుత్ సంకేతాలను తిరిగి ధ్వనిగా మార్చడం", "raw": "Convert electrical signals into amplified sound signals / విద్యుత్ సంకేతాలను తిరిగి ధ్వనిగా మార్చడం"}, {"en": "Indicate sound decibels on a screen", "te": "ధ్వని తీవ్రతను ప్రదర్శించడం", "raw": "Indicate sound decibels on a screen / ధ్వని తీవ్రతను ప్రదర్శించడం"}, {"en": "Measure audio frequency", "te": "పౌనఃపున్యాన్ని కొలవడం", "raw": "Measure audio frequency / పౌనఃపున్యాన్ని కొలవడం"}], "ans": 1, "exp_en": "In a hearing aid, the Microphone acts as an input transducer converting acoustic air pressure waves into fluctuating electrical audio signals for the amplifier.", "exp_te": "మైక్రోఫోన్ గాలిలోని ధ్వని కంపనాలను స్వీకరించి వాటిని విద్యుత్ సంకేతాలుగా (Electrical signals) మారుస్తుంది. ఆ తర్వాత యాంప్లిఫైయర్ వాటిని వృద్ధి చేస్తుంది."}, {"id": 149, "sec": "Special Education", "passage": "", "q_en": "The standard physical unit used to measure Sound Intensity (Loudness) is", "q_te": "ధ్వని తీవ్రతను (Sound Intensity / Loudness) కొలవడానికి ఉపయోగించే ప్రమాణాలు", "opts": [{"en": "Hertz (Hz)", "te": "హెర్ట్జ్ (Hz - పౌనఃపున్యం)", "raw": "Hertz (Hz) / హెర్ట్జ్ (Hz - పౌనఃపున్యం)"}, {"en": "Degrees", "te": "డిగ్రీలు", "raw": "Degrees / డిగ్రీలు"}, {"en": "Decibels (dB)", "te": "డెసిబుల్స్ (dB - Decibels)", "raw": "Decibels (dB) / డెసిబుల్స్ (dB - Decibels)"}, {"en": "Pound", "te": "పౌండ్లు", "raw": "Pound / పౌండ్లు"}], "ans": 3, "exp_en": "Sound intensity and volume are measured logarithmically in Decibels (dB), named in honor of Alexander Graham Bell. Hertz (Hz) measures frequency/pitch.", "exp_te": "ధ్వని తీవ్రతను లేదా శబ్ద పరిమాణాన్ని 'డెసిబుల్స్' (dB) లలో కొలుస్తారు. ధ్వని పౌనఃపున్యాన్ని (Frequency) హెర్ట్జ్ (Hz) లలో కొలుస్తారు."}, {"id": 150, "sec": "Special Education", "passage": "", "q_en": "The educational scheme providing home-based educational support to children with severe multiple disabilities is", "q_te": "తీవ్ర వైకల్యాలు ఉండి పాఠశాలకు రాలేని పిల్లలకు గృహ ఆధారిత విద్యను (Home-based Education) అందించే పథకం", "opts": [{"en": "PRASHAST", "te": "ప్రశస్త్", "raw": "PRASHAST / ప్రశస్త్"}, {"en": "SAMARTH Scheme (Samagra Shiksha)", "te": "సమర్థ్ పథకం (SAMARTH - సమగ్ర శిక్షా)", "raw": "SAMARTH Scheme (Samagra Shiksha) / సమర్థ్ పథకం (SAMARTH - సమగ్ర శిక్షా)"}, {"en": "Adult Literacy", "te": "వయోజన విద్య", "raw": "Adult Literacy / వయోజన విద్య"}, {"en": "DHRISHTI", "te": "దృష్టి", "raw": "DHRISHTI / దృష్టి"}], "ans": 2, "exp_en": "Project SAMARTH (under Samagra Shiksha) provides home-based education, physical therapy, and customized assistive support through itinerant resource teachers to severely disabled children.", "exp_te": "సమగ్ర శిక్షా ఆధ్వర్యంలోని 'సమర్థ్' (SAMARTH) పథకం ద్వారా తీవ్ర దివ్యాంగత్వం గల పిల్లల ఇళ్ల వద్దకే ప్రత్యేక ఉపాధ్యాయులు వెళ్లి గృహ ఆధారిత విద్యను అందిస్తారు."}, {"id": 151, "sec": "Special Education", "passage": "", "q_en": "Specific Learning Disability (SLD) fundamentally arises from", "q_te": "నిర్దిష్ట అభ్యసన వైకల్యం (Learning Disability) ప్రాథమికంగా దేని వలన కలుగుతుంది", "opts": [{"en": "Neuro-developmental processing deficiency in the brain", "te": "మెదడులోని నాడీ వికాస సమాచార గ్రహణ లోపం (Neuro-developmental processing deficiency)", "raw": "Neuro-developmental processing deficiency in the brain / మెదడులోని నాడీ వికాస సమాచార గ్రహణ లోపం (Neuro-developmental processing deficiency)"}, {"en": "Laziness and unwillingness to study", "te": "విద్యార్థి బద్ధకం", "raw": "Laziness and unwillingness to study / విద్యార్థి బద్ధకం"}, {"en": "Lack of economic resources alone", "te": "కేవలం ఆర్థిక లేమి", "raw": "Lack of economic resources alone / కేవలం ఆర్థిక లేమి"}, {"en": "Emotional temper alone", "te": "కోపం మరియు మొండితనం", "raw": "Emotional temper alone / కోపం మరియు మొండితనం"}], "ans": 1, "exp_en": "Learning disabilities are neurological in origin, affecting how the brain receives, processes, stores, and analyzes linguistic and mathematical information.", "exp_te": "అభ్యసన వైకల్యం అనేది సోమరితనం వల్ల వచ్చేది కాదు; మెదడులోని నాడీ వ్యవస్థ భాషా మరియు సమాచార విశ్లేషణను గ్రహించడంలో లోపం (Neuro-developmental) వల్ల వస్తుంది."}, {"id": 152, "sec": "Special Education", "passage": "", "q_en": "Which of the following is NOT an informal assessment tool used directly by a classroom teacher to assess learning difficulties?", "q_te": "తరగతి ఉపాధ్యాయుడు విద్యార్థి అభ్యసన సమస్యలను స్వయంగా గుర్తించడానికి ఉపయోగించని సాధనం ఏది", "opts": [{"en": "Teacher Checklists", "te": "ఉపాధ్యాయుని చెక్‌లిస్టులు", "raw": "Teacher Checklists / ఉపాధ్యాయుని చెక్‌లిస్టులు"}, {"en": "High-Risk Medical Neonatal Registers", "te": "హై-రిస్క్ మెడికల్ రిజిస్టర్లు (ఆసుపత్రి రికార్డులు)", "raw": "High-Risk Medical Neonatal Registers / హై-రిస్క్ మెడికల్ రిజిస్టర్లు (ఆసుపత్రి రికార్డులు)"}, {"en": "Teacher-made Achievement Tests", "te": "బోధనా నిష్పత్తి పరీక్షలు", "raw": "Teacher-made Achievement Tests / బోధనా నిష్పత్తి పరీక్షలు"}, {"en": "Parental Observations", "te": "తల్లిదండ్రుల పరిశీలనలు", "raw": "Parental Observations / తల్లిదండ్రుల పరిశీలనలు"}], "ans": 2, "exp_en": "High-Risk Infant Registers are clinical medical registers maintained by pediatric hospitals, not informal classroom assessment tools developed by teachers.", "exp_te": "ఆసుపత్రులలో పురిటి సమయంలో నిర్వహించే 'హై-రిస్క్ రిజిస్టర్లు' వైద్యపరమైనవి. ఉపాధ్యాయుడు తరగతి గదిలో చెక్‌లిస్టులు, పరీక్షలను ఉపయోగిస్తాడు."}, {"id": 153, "sec": "Special Education", "passage": "", "q_en": "Total inability to read and comprehend printed words due to acquired neurological injury is termed", "q_te": "మెదడుకు గాయం కావడం వల్ల ముద్రిత పదాలను చదివి అర్థం చేసుకునే సామర్థ్యాన్ని కోల్పోవడాన్ని ఏమంటారు", "opts": [{"en": "Dysgraphia", "te": "డిస్‌గ్రాఫియా", "raw": "Dysgraphia / డిస్‌గ్రాఫియా"}, {"en": "Agraphia", "te": "ఆగ్రాఫియా", "raw": "Agraphia / ఆగ్రాఫియా"}, {"en": "Alexia (Word Blindness)", "te": "అలెక్సియా (Alexia / వర్డ్ బ్లైండ్‌నెస్)", "raw": "Alexia (Word Blindness) / అలెక్సియా (Alexia / వర్డ్ బ్లైండ్‌నెస్)"}, {"en": "Spelling Difficulty", "te": "స్పెల్లింగ్ లోపం", "raw": "Spelling Difficulty / స్పెల్లింగ్ లోపం"}], "ans": 3, "exp_en": "Alexia (also termed visual aphasia or word blindness) is an acquired neurological condition causing complete inability to read text despite intact vision.", "exp_te": "దృష్టి సాధారణంగా ఉన్నప్పటికీ మెదడులోని నాడీ కేంద్రాలు దెబ్బతినడం వల్ల పుస్తకంలోని పదాలను అస్సలు చదవలేకపోవడాన్ని 'అలెక్సియా' (Alexia) అంటారు."}, {"id": 154, "sec": "Special Education", "passage": "", "q_en": "'Dyscalculia' refers to severe difficulty in", "q_te": "'డిస్‌కాలిక్యులియా' (Dyscalculia) అనేది దేనిలోని తీవ్రమైన లోపం", "opts": [{"en": "Oral language and pronunciation", "te": "మౌఖిక భాష మరియు ఉచ్ఛారణ", "raw": "Oral language and pronunciation / మౌఖిక భాష మరియు ఉచ్ఛారణ"}, {"en": "Reading printed texts", "te": "పుస్తకాలు చదవడం", "raw": "Reading printed texts / పుస్తకాలు చదవడం"}, {"en": "Fine motor writing and drawing", "te": "చేతిరాత రాయడం", "raw": "Fine motor writing and drawing / చేతిరాత రాయడం"}, {"en": "Mathematical and arithmetic calculations", "te": "గణిత భావనలు మరియు సంఖ్యా లెక్కింపులు (Arithmetic calculations)", "raw": "Mathematical and arithmetic calculations / గణిత భావనలు మరియు సంఖ్యా లెక్కింపులు (Arithmetic calculations)"}], "ans": 4, "exp_en": "Dyscalculia is a specific learning disorder involving severe persistent difficulty understanding numbers, learning arithmetic facts, and computing mathematical operations.", "exp_te": "సంఖ్యలను గుర్తించడం, కూడికలు, తీసివేతలు వంటి ప్రాథమిక గణిత భావనలను అర్థం చేసుకోవడంలో ఉండే తీవ్ర వైకల్యాన్ని 'డిస్‌కాలిక్యులియా' అంటారు."}, {"id": 155, "sec": "Special Education", "passage": "", "q_en": "Hypoglycemia (chronically low blood sugar level) during critical brain development can impair phonological processing causing", "q_te": "శిశువు రక్తంలో గ్లూకోజ్ స్థాయిలు తీవ్రంగా పడిపోవడం (హైపోగ్లైసీమియా) దేనికి దారితీయవచ్చు", "opts": [{"en": "Dyslexia (Reading impairment)", "te": "డిస్లెక్సియా (Dyslexia / పఠన లోపం)", "raw": "Dyslexia (Reading impairment) / డిస్లెక్సియా (Dyslexia / పఠన లోపం)"}, {"en": "Dysphasia", "te": "డిస్ఫాసియా", "raw": "Dysphasia / డిస్ఫాసియా"}, {"en": "Aphasia", "te": "ఎఫాసియా", "raw": "Aphasia / ఎఫాసియా"}, {"en": "Alexia", "te": "అలెక్సియా", "raw": "Alexia / అలెక్సియా"}], "ans": 1, "exp_en": "Severe perinatal or infantile hypoglycemia can damage brain cortical areas responsible for phonemic decoding and visual memory, contributing to developmental dyslexia.", "exp_te": "చిన్నతనంలో మెదడుకు గ్లూకోజ్ కొరత ఏర్పడటం వల్ల మెదడులోని పఠన మరియు భాషా కేంద్రాలు దెబ్బతిని 'డిస్లెక్సియా' (పఠన లోపం) కలిగే ప్రమాదం ఉంది."}, {"id": 156, "sec": "Special Education", "passage": "", "q_en": "When a student persistently writes 'd' instead of 'b', '81' instead of '18', and '302' instead of '32', the student demonstrates", "q_te": "ఒక విద్యార్థి 'b' కి బదులుగా 'd', '18' కి బదులుగా '81', '32' కి బదులుగా '302' అని తలక్రిందులుగా రాస్తుంటే అది ఏ లోపం", "opts": [{"en": "Hearing Impairment", "te": "వినికిడి లోపం", "raw": "Hearing Impairment / వినికిడి లోపం"}, {"en": "Learning Disability (Dyslexia / Spatial Reversal)", "te": "నిర్దిష్ట అభ్యసన వైకల్యం (Learning Disability - అక్షరాల తారుమారు)", "raw": "Learning Disability (Dyslexia / Spatial Reversal) / నిర్దిష్ట అభ్యసన వైకల్యం (Learning Disability - అక్షరాల తారుమారు)"}, {"en": "Speech and Language Disability", "te": "వాక్ లోపం", "raw": "Speech and Language Disability / వాక్ లోపం"}, {"en": "Complete Blindness", "te": "అంధత్వం", "raw": "Complete Blindness / అంధత్వం"}], "ans": 2, "exp_en": "Letter, number, and directional spatial reversals (mirror writing, transpositions like b/d, p/q, 18/81) are classic symptoms of visual-spatial processing deficits in Learning Disabilities.", "exp_te": "అక్షరాలను, సంఖ్యలను తారుమారు చేసి అద్దంలో కనిపించినట్లు రాయడం (Mirror writing / Reversals) అభ్యసన వైకల్యం (Learning Disability) లోని ముఖ్య లక్షణం."}, {"id": 157, "sec": "Special Education", "passage": "", "q_en": "Providing segregated schooling to children with disabilities in a dedicated separate school is called", "q_te": "దివ్యాంగ పిల్లలకు సాధారణ పాఠశాలలతో సంబంధం లేకుండా ప్రత్యేక పాఠశాలలో మాత్రమే విద్యను అందించడం", "opts": [{"en": "General Education", "te": "సాధారణ విద్య", "raw": "General Education / సాధారణ విద్య"}, {"en": "Special Education", "te": "ప్రత్యేక విద్య (Special Education - ప్రత్యేక పాఠశాలలు)", "raw": "Special Education / ప్రత్యేక విద్య (Special Education - ప్రత్యేక పాఠశాలలు)"}, {"en": "Partial Special Education", "te": "పాక్షిక ప్రత్యేక విద్య", "raw": "Partial Special Education / పాక్షిక ప్రత్యేక విద్య"}, {"en": "Integrated Education", "te": "సమీకృత విద్య", "raw": "Integrated Education / సమీకృత విద్య"}], "ans": 2, "exp_en": "Special Education historically refers to segregated educational provisions in dedicated special schools equipped with specialized teachers and adapted resources exclusively for children with disabilities.", "exp_te": "దివ్యాంగ పిల్లలను సాధారణ విద్యార్థుల నుండి వేరుచేసి, ప్రత్యేక వనరులు, ఉపాధ్యాయులు గల ప్రత్యేక పాఠశాలలో చదివించడాన్ని 'ప్రత్యేక విద్య' (Special Education) అంటారు."}, {"id": 158, "sec": "Special Education", "passage": "", "q_en": "Newly acquired academic and adaptive skills taught to children with Learning Disabilities should be", "q_te": "అభ్యసన వైకల్యం గల పిల్లలు నేర్చుకున్న కొత్త నైపుణ్యాలను ఎలా అభ్యసింపజేయాలి", "opts": [{"en": "Practiced repeatedly (Overlearning / Distributed Practice)", "te": "పదే పదే పునరావృతం చేస్తూ సాధన చేయించాలి (Repeated Practice / Overlearning)", "raw": "Practiced repeatedly (Overlearning / Distributed Practice) / పదే పదే పునరావృతం చేస్తూ సాధన చేయించాలి (Repeated Practice / Overlearning)"}, {"en": "Left immediately without practice", "te": "వదిలివేయాలి", "raw": "Left immediately without practice / వదిలివేయాలి"}, {"en": "Practiced only once", "te": "కేవలం ఒక్కసారి మాత్రమే చేయించాలి", "raw": "Practiced only once / కేవలం ఒక్కసారి మాత్రమే చేయించాలి"}, {"en": "Practiced once before annual exams", "te": "పరీక్షల ముందు ఒక్కసారి చూడాలి", "raw": "Practiced once before annual exams / పరీక్షల ముందు ఒక్కసారి చూడాలి"}], "ans": 1, "exp_en": "Students with SLD have working memory and retrieval difficulties. Distributed overlearning through frequent, structured, repeated practice ensures long-term retention.", "exp_te": "అభ్యసన వైకల్యం ఉన్న పిల్లలకు స్వల్పకాలిక జ్ఞాపకశక్తి లోపం ఉంటుంది. కాబట్టి వారు నేర్చుకున్న అంశాలను మర్చిపోకుండా పదే పదే పునశ్చరణ (Repeated Practice) చేయించాలి."}, {"id": 159, "sec": "Special Education", "passage": "", "q_en": "Choose the correct statements regarding educational paradigms:\ni. Partial integration means providing special education services in a resource room within a regular school.\nii. Inclusive education means educating children with disabilities in regular classrooms alongside their non-disabled peers with necessary supports.", "q_te": "విద్యా విధానాలకు సంబంధించి సరైన వాక్యాలను ఎంపిక చేయండి:\ni. పాక్షిక సమైక్యత అనగా సాధారణ పాఠశాలలో రిసోర్స్ గది ద్వారా ప్రత్యేక విద్యను అందించడం.\nii. సమ్మిళిత విద్య అనగా సాధారణ తరగతి గదిలోనే తోటి సాధారణ పిల్లలతో కలిసి చదువుకునేలా చేయడం.", "opts": [{"en": "Only statement i is correct", "te": "కేవలం వాక్యం i మాత్రమే సరైనది", "raw": "Only statement i is correct / కేవలం వాక్యం i మాత్రమే సరైనది"}, {"en": "Only statement ii is correct", "te": "కేవలం వాక్యం ii మాత్రమే సరైనది", "raw": "Only statement ii is correct / కేవలం వాక్యం ii మాత్రమే సరైనది"}, {"en": "Both statement i and statement ii are correct", "te": "వాక్యాలు i మరియు ii రెండూ సరైనవి (Both are correct)", "raw": "Both statement i and statement ii are correct / వాక్యాలు i మరియు ii రెండూ సరైనవి (Both are correct)"}, {"en": "Neither statement is correct", "te": "రెండూ సరైనవి కావు", "raw": "Neither statement is correct / రెండూ సరైనవి కావు"}], "ans": 3, "exp_en": "Both statements accurately reflect international definitions: Integration provides specialized support within a regular school setting, while Inclusion comprehensively transforms the general classroom to accommodate all learners.", "exp_te": "పాక్షిక సమీకృత విద్యలో రిసోర్స్ రూమ్ సేవలు ఉంటాయి; సమ్మిళిత విద్యలో పిల్లలందరూ ఒకే తరగతి గదిలో కలిసి చదువుకుంటారు. కాబట్టి రెండు వాక్యాలూ సరైనవే."}, {"id": 160, "sec": "Special Education", "passage": "", "q_en": "Which of the following is commonly referred to as an 'Invisible Disability'?", "q_te": "క్రింది వానిలో సాధారణంగా బయటకు కనిపించని 'అదృశ్య వైకల్యం' (Invisible Disability) ఏది", "opts": [{"en": "Total Blindness", "te": "సంపూర్ణ అంధత్వం", "raw": "Total Blindness / సంపూర్ణ అంధత్వం"}, {"en": "Cerebral Palsy", "te": "సెరిబ్రల్ పాల్సీ", "raw": "Cerebral Palsy / సెరిబ్రల్ పాల్సీ"}, {"en": "Locomotor Disability", "te": "చలన వైకల్యం", "raw": "Locomotor Disability / చలన వైకల్యం"}, {"en": "Specific Learning Disability (Dyslexia)", "te": "నిర్దిష్ట అభ్యసన వైకల్యం (Specific Learning Disability)", "raw": "Specific Learning Disability (Dyslexia) / నిర్దిష్ట అభ్యసన వైకల్యం (Specific Learning Disability)"}], "ans": 4, "exp_en": "Specific Learning Disability (SLD) is called an 'invisible handicap' because the child appears completely normal physically and has average intelligence, yet struggles severely with decoding symbols.", "exp_te": "అభ్యసన వైకల్యం (SLD) గల పిల్లలు శారీరకంగా సాధారణంగా కనిపిస్తారు, వీల్‌చైర్ లేదా కళ్లద్దాలు వంటివి ఉండవు కాబట్టి దీనిని 'అదృశ్య వైకల్యం' (Invisible Disability) అంటారు."}, {"id": 161, "sec": "Special Education", "passage": "", "q_en": "Realistic and lasting functional skills can be developed in children with Learning Disabilities primarily through", "q_te": "అభ్యసన వైకల్యం గల పిల్లలలో వాస్తవిక, క్రియాత్మక ప్రవర్తనలను దేని ద్వారా అభివృద్ధి చేయవచ్చు", "opts": [{"en": "Remedial Teaching / Education", "te": "సవరణాత్మక బోధన (Remedial Education / Teaching)", "raw": "Remedial Teaching / Education / సవరణాత్మక బోధన (Remedial Education / Teaching)"}, {"en": "Art Education alone", "te": "కేవలం చిత్రలేఖనం", "raw": "Art Education alone / కేవలం చిత్రలేఖనం"}, {"en": "University Education", "te": "విశ్వవిద్యాలయ విద్య", "raw": "University Education / విశ్వవిద్యాలయ విద్య"}, {"en": "Craft Education alone", "te": "కేవలం చేతిపనులు", "raw": "Craft Education alone / కేవలం చేతిపనులు"}], "ans": 1, "exp_en": "Remedial teaching identifies specific diagnostic learning deficits and provides targeted, individualized multi-sensory instruction to bridge learning gaps.", "exp_te": "పిల్లలు ఎక్కడ వెనుకబడ్డారో గుర్తించి, ప్రత్యేక వ్యూహాలతో వారి లోపాలను సరిదిద్దే 'సవరణాత్మక బోధన' (Remedial Teaching) ద్వారా వారి సామర్థ్యాలను పెంచవచ్చు."}, {"id": 162, "sec": "Special Education", "passage": "", "q_en": "A child learning the concept of 'the shape of a boat' by seeing and touching a physical toy boat is learning at which conceptual level?", "q_te": "ఒక పిల్లవాడు నిజమైన పడవ బొమ్మను చూస్తూ, తాకుతూ 'పడవ ఆకారం' అనే భావనను నేర్చుకోవడం ఏ స్థాయి భావనా వికాసం", "opts": [{"en": "Operational level", "te": "ప్రచాలక స్థాయి", "raw": "Operational level / ప్రచాలక స్థాయి"}, {"en": "Concrete level", "te": "మూర్త స్థాయి (Concrete Level / ప్రత్యక్ష అనుభవ స్థాయి)", "raw": "Concrete level / మూర్త స్థాయి (Concrete Level / ప్రత్యక్ష అనుభవ స్థాయి)"}, {"en": "Abstract level", "te": "అమూర్త స్థాయి", "raw": "Abstract level / అమూర్త స్థాయి"}, {"en": "Empowerment level", "te": "సాధికారత స్థాయి", "raw": "Empowerment level / సాధికారత స్థాయి"}], "ans": 2, "exp_en": "The Concrete Level of conceptual development involves learning through tangible, visible physical objects that can be directly observed and manipulated.", "exp_te": "ప్రత్యక్షంగా కంటికి కనిపించే, చేతితో తాకగలిగే వస్తువులను చూసి నేర్చుకునే స్థాయిని 'మూర్త స్థాయి' (Concrete level) అంటారు."}, {"id": 163, "sec": "Special Education", "passage": "", "q_en": "The teaching-learning instructional methodology that systematically matches the individual learning pathways of children with Learning Disabilities is", "q_te": "అభ్యసన వైకల్యం గల పిల్లల వ్యక్తిగత అవసరాలకు అనుగుణంగా రూపొందించిన బోధనా పద్ధతి", "opts": [{"en": "Programmed Instruction", "te": "ప్రోగ్రామ్డ్ బోధన", "raw": "Programmed Instruction / ప్రోగ్రామ్డ్ బోధన"}, {"en": "Behavioral Approach", "te": "ప్రవర్తనా విధానం", "raw": "Behavioral Approach / ప్రవర్తనా విధానం"}, {"en": "Multi-Sensory Approach (VAKT)", "te": "బహుళ-ఇంద్రియ విధానం (Multi-Sensory Approach - VAKT)", "raw": "Multi-Sensory Approach (VAKT) / బహుళ-ఇంద్రియ విధానం (Multi-Sensory Approach - VAKT)"}, {"en": "Test-related Approach", "te": "పరీక్షా సంబంధిత విధానం", "raw": "Test-related Approach / పరీక్షా సంబంధిత విధానం"}], "ans": 1, "exp_en": "Programmed Instruction breaks learning down into small, logical, self-paced sequential frames with immediate feedback, ideally suited for individualized special education.", "exp_te": "విద్యార్థి తన స్వంత వేగంతో నేర్చుకుంటూ, వెంటనే ఫీడ్‌బ్యాక్ పొందేలా విషయాలను చిన్న చిన్న భాగాలుగా విభజించే 'ప్రోగ్రామ్డ్ బోధన' (Programmed Instruction) వైయుక్తిక బోధనకు అనువైనది."}, {"id": 164, "sec": "Special Education", "passage": "", "q_en": "This method facilitates language development alongside correcting reading difficulties by using the child's own spoken words as reading material", "q_te": "పిల్లల స్వంత అనుభవాలు, మాటల ఆధారంగా భాషను మరియు పఠన నైపుణ్యాలను అభివృద్ధి చేసే పద్ధతి", "opts": [{"en": "Language Experience Approach (LEA)", "te": "భాషా అనుభవ పద్ధతి (Language Experience Approach - LEA)", "raw": "Language Experience Approach (LEA) / భాషా అనుభవ పద్ధతి (Language Experience Approach - LEA)"}, {"en": "Phonic Approach", "te": "ఫోనిక్ విధానం", "raw": "Phonic Approach / ఫోనిక్ విధానం"}, {"en": "Basal Reading Approach", "te": "బాసల్ రీడింగ్ పద్ధతి", "raw": "Basal Reading Approach / బాసల్ రీడింగ్ పద్ధతి"}, {"en": "Specialized Techniques Approach", "te": "ప్రత్యేక సాంకేతిక పద్ధతి", "raw": "Specialized Techniques Approach / ప్రత్యేక సాంకేతిక పద్ధతి"}], "ans": 1, "exp_en": "The Language Experience Approach (LEA) transcribes the child's own dictated thoughts and oral experiences into written text, guaranteeing that the reading text is personally meaningful and familiar.", "exp_te": "పిల్లలు స్వయంగా చెప్పే అనుభవాలను ఉపాధ్యాయుడు బోర్డుపై రాసి, దానినే పఠన పాఠ్యాంశంగా మార్చి బోధించే విధానాన్ని 'లాంగ్వేజ్ ఎక్స్‌పీరియన్స్ అప్రోచ్' (LEA) అంటారు."}, {"id": 165, "sec": "Special Education", "passage": "", "q_en": "An effective daily classroom practice to enhance reading fluency and accuracy in children with Specific Learning Disabilities is", "q_te": "అభ్యసన వైకల్యం గల పిల్లలలో పఠన నైపుణ్యాన్ని పెంచడానికి ప్రతిరోజూ చేయించాల్సిన ఆచరణ", "opts": [{"en": "Coloring pictures", "te": "చిత్రాలకు రంగులు వేయడం", "raw": "Coloring pictures / చిత్రాలకు రంగులు వేయడం"}, {"en": "Classifying objects", "te": "వస్తువులను వర్గీకరించడం", "raw": "Classifying objects / వస్తువులను వర్గీకరించడం"}, {"en": "Playing outdoor games", "te": "ఆటలు ఆడటం", "raw": "Playing outdoor games / ఆటలు ఆడటం"}, {"en": "Daily structured loud reading practice with guidance", "te": "ప్రతిరోజూ మార్గదర్శకత్వంతో కూడిన గట్టిగా చదివే సాధన (Daily loud reading practice)", "raw": "Daily structured loud reading practice with guidance / ప్రతిరోజూ మార్గదర్శకత్వంతో కూడిన గట్టిగా చదివే సాధన (Daily loud reading practice)"}], "ans": 4, "exp_en": "Guided oral repeated loud reading provides auditory feedback, improves phonemic awareness, enhances word decoding speed, and builds reading fluency.", "exp_te": "ప్రతిరోజూ ఉపాధ్యాయుని పర్యవేక్షణలో గట్టిగా, స్పష్టంగా చదివించడం (Loud reading) వల్ల పిల్లలు తమ ఉచ్ఛారణా తప్పులను సరిదిద్దుకొని ధారాళంగా చదవగలుగుతారు."}, {"id": 166, "sec": "Special Education", "passage": "", "q_en": "Writing the names of objects and animals with the help of pictures, models, and flashcards primarily facilitates developing", "q_te": "బొమ్మలు, ఫ్లాష్ కార్డులు చూపిస్తూ వస్తువులు, జంతువుల పేర్లు రాయింపజేయడం దేనిని అభివృద్ధి చేస్తుంది", "opts": [{"en": "Mathematical skill", "te": "గణిత నైపుణ్యం", "raw": "Mathematical skill / గణిత నైపుణ్యం"}, {"en": "Writing and orthographic spelling skill", "te": "లేఖన మరియు అక్షరక్రమ నైపుణ్యం (Writing & Spelling Skill)", "raw": "Writing and orthographic spelling skill / లేఖన మరియు అక్షరక్రమ నైపుణ్యం (Writing & Spelling Skill)"}, {"en": "Social etiquette", "te": "జీవన నైపుణ్యం", "raw": "Social etiquette / జీవన నైపుణ్యం"}, {"en": "Logical thinking", "te": "తార్కిక ఆలోచన", "raw": "Logical thinking / తార్కిక ఆలోచన"}], "ans": 2, "exp_en": "Pairing visual stimuli (pictures, flashcards) with letter formation reinforces the orthographic-motor mapping in memory, directly improving spelling and writing skills.", "exp_te": "చిత్రాలు, కార్డుల సహాయంతో పేర్లను రాయించడం వల్ల పిల్లల్లో చేతిరాత మరియు అక్షరక్రమ నైపుణ్యాలు (Writing skills) దృఢపడతాయి."}, {"id": 167, "sec": "Special Education", "passage": "", "q_en": "A proven hands-on activity that develops early numeracy and counting concepts in children is", "q_te": "పిల్లలలో ప్రాథమిక గణిత మరియు సంఖ్యా భావనలను నేర్పడానికి తోడ్పడే ప్రత్యక్ష కృత్యం", "opts": [{"en": "Reading comprehension passage", "te": "వ్యాస పఠనం", "raw": "Reading comprehension passage / వ్యాస పఠనం"}, {"en": "Explaining money verbally", "te": "డబ్బు గురించి ఉపన్యసించడం", "raw": "Explaining money verbally / డబ్బు గురించి ఉపన్యసించడం"}, {"en": "Teaching numbers using concrete manipulatives like buttons, beads, and counters", "te": "పూసలు, గుండీలు (Buttons, Beads) వంటి మూర్త వస్తువులతో లెక్కించడం నేర్పడం", "raw": "Teaching numbers using concrete manipulatives like buttons, beads, and counters / పూసలు, గుండీలు (Buttons, Beads) వంటి మూర్త వస్తువులతో లెక్కించడం నేర్పడం"}, {"en": "Writing small words", "te": "చిన్న పదాలు రాయడం", "raw": "Writing small words / చిన్న పదాలు రాయడం"}], "ans": 3, "exp_en": "Using concrete manipulatives (buttons, beads, pebbles, Abacus beads) translates abstract numerical quantities into tangible tactile objects, developing fundamental mathematical understanding.", "exp_te": "అమూర్తమైన అంకెలను అర్థం చేసుకోవడానికి పూసలు, గుండీలు, పుల్లలు వంటి మూర్త వస్తువులను లెక్కపెట్టించడం అత్యంత ప్రభావవంతమైన గణిత అభ్యసన పద్ధతి."}, {"id": 168, "sec": "Special Education", "passage": "", "q_en": "Which learning activity is most helpful in training and refining Eye-Hand Coordination?", "q_te": "కంటికి మరియు చేతికి మధ్య సమన్వయాన్ని (Eye-Hand Coordination) పెంపొందించడానికి అత్యంత తోడ్పడేది", "opts": [{"en": "Drawing and sketching pictures", "te": "చిత్రలేఖనం / బొమ్మలు గీయడం (Drawing pictures)", "raw": "Drawing and sketching pictures / చిత్రలేఖనం / బొమ్మలు గీయడం (Drawing pictures)"}, {"en": "Silent thinking", "te": "నిశ్శబ్దంగా ఆలోచించడం", "raw": "Silent thinking / నిశ్శబ్దంగా ఆలోచించడం"}, {"en": "Describing upcoming situations", "te": "భవిష్యత్ పరిస్థితులను వర్ణించడం", "raw": "Describing upcoming situations / భవిష్యత్ పరిస్థితులను వర్ణించడం"}, {"en": "Poem recitation", "te": "పద్య పఠనం", "raw": "Poem recitation / పద్య పఠనం"}], "ans": 1, "exp_en": "Drawing, sketching, tracing, and coloring require visual tracking precisely synchronized with fine-motor hand and finger movements, directly enhancing Eye-Hand Coordination.", "exp_te": "చిత్రాలు గీయడం, రంగులు వేయడం వంటి కృత్యాలలో కళ్ళు చూసే దిశకు అనుగుణంగా చేతి వేళ్ళు కదలాల్సి ఉంటుంది, ఇది కంటి-చేతి సమన్వయాన్ని బలోపేతం చేస్తుంది."}, {"id": 169, "sec": "Special Education", "passage": "", "q_en": "A modern continuous learning environment that provides multi-modal and adaptive pacing for children with Specific Learning Disabilities is", "q_te": "అభ్యసన వైకల్యం గల పిల్లలు తమ స్వంత వేగంతో నేర్చుకోవడానికి తోడ్పడే నిరంతర అభ్యసన విధానం", "opts": [{"en": "Internet / Computer-based assistive learning", "te": "ఇంటర్నెట్ మరియు కంప్యూటర్ ఆధారిత అభ్యసనం (Internet-based Learning)", "raw": "Internet / Computer-based assistive learning / ఇంటర్నెట్ మరియు కంప్యూటర్ ఆధారిత అభ్యసనం (Internet-based Learning)"}, {"en": "Strict teacher-centred lectures", "te": "ఉపాధ్యాయ కేంద్రీకృత ఉపన్యాసం", "raw": "Strict teacher-centred lectures / ఉపాధ్యాయ కేంద్రీకృత ఉపన్యాసం"}, {"en": "Traditional rote teaching", "te": "సాంప్రదాయ బట్టీ విధానం", "raw": "Traditional rote teaching / సాంప్రదాయ బట్టీ విధానం"}, {"en": "Rigid blackboard copying", "te": "నల్లబల్ల రాతలు", "raw": "Rigid blackboard copying / నల్లబల్ల రాతలు"}], "ans": 1, "exp_en": "Internet and computer-assisted technologies offer interactive visuals, speech-to-text, audio narration, and self-paced repetition tailored for learning disabled children.", "exp_te": "కంప్యూటర్ మరియు ఇంటర్నెట్ ఆధారిత అభ్యసనంలో దృశ్య-శ్రవణ మాధ్యమాలు, ఆడియో బుక్స్ అందుబాటులో ఉంటాయి కాబట్టి పిల్లలు తమ వేగానికి అనుగుణంగా సులభంగా నేర్చుకుంటారు."}, {"id": 170, "sec": "Special Education", "passage": "", "q_en": "The primary educational objective of internet-based and assistive software for children with Specific Learning Disabilities is to", "q_te": "అభ్యసన వైకల్యం గల పిల్లలకు కంప్యూటర్ / ఇంటర్నెట్ ఆధారిత విద్యను అందించడంలో ముఖ్య ఉద్దేశం", "opts": [{"en": "Provide random video games", "te": "వీడియో గేమ్‌లు ఆడుకోవడం", "raw": "Provide random video games / వీడియో గేమ్‌లు ఆడుకోవడం"}, {"en": "Cater to the individual learning style and multisensory needs of the student", "te": "విద్యార్థి వ్యక్తిగత అభ్యసనా శైలి మరియు అవసరాలకు అనుగుణంగా బోధించడం (Individual Learning Style)", "raw": "Cater to the individual learning style and multisensory needs of the student / విద్యార్థి వ్యక్తిగత అభ్యసనా శైలి మరియు అవసరాలకు అనుగుణంగా బోధించడం (Individual Learning Style)"}, {"en": "Force students to memorize exam answers", "te": "పరీక్షల్లో జవాబులు కంఠస్థం చేయించడం", "raw": "Force students to memorize exam answers / పరీక్షల్లో జవాబులు కంఠస్థం చేయించడం"}, {"en": "Pass time", "te": "సమయం గడపడం", "raw": "Pass time / సమయం గడపడం"}], "ans": 2, "exp_en": "Educational technology personalizes content delivery, transforming abstract text into auditory or graphical formats matching the child's distinctive cognitive profile.", "exp_te": "ప్రతి విద్యార్థి యొక్క వ్యక్తిగత అభ్యసనా శైలికి (Learning Style), వారికున్న ప్రత్యేక అవసరాలకు తగినట్లుగా డిజిటల్ మాధ్యమాల ద్వారా బోధించడమే దీని ముఖ్య లక్ష్యం."}, {"id": 171, "sec": "Special Education", "passage": "", "q_en": "Which of the following creates genuine interest and high motivation for learning in children with Specific Learning Disabilities?", "q_te": "అభ్యసన వైకల్యం గల పిల్లలలో నేర్చుకోవాలనే ఆసక్తిని, ఉత్సాహాన్ని కలిగించేది ఏది", "opts": [{"en": "Silent conventional libraries", "te": "నిశ్శబ్ద గ్రంథాలయాలు", "raw": "Silent conventional libraries / నిశ్శబ్ద గ్రంథాలయాలు"}, {"en": "Monotonous radio speeches", "te": "సాధారణ రేడియో ఉపన్యాసాలు", "raw": "Monotonous radio speeches / సాధారణ రేడియో ఉపన్యాసాలు"}, {"en": "Interactive educational games and gamified learning", "te": "పరస్పర ప్రతిస్పందన గల విద్యా క్రీడలు (Interactive Educational Games)", "raw": "Interactive educational games and gamified learning / పరస్పర ప్రతిస్పందన గల విద్యా క్రీడలు (Interactive Educational Games)"}, {"en": "Text-only books", "te": "రాత పుస్తకాలు", "raw": "Text-only books / రాత పుస్తకాలు"}], "ans": 3, "exp_en": "Gamified learning platforms provide immediate multi-sensory feedback, visual rewards, low-stakes practice, and high engagement for children with learning challenges.", "exp_te": "ఇంటరాక్టివ్ ఎడ్యుకేషనల్ గేమ్‌లు (Interactive games) ఆటపాటలతో కూడిన ఫీడ్‌బ్యాక్ అందిస్తాయి, తద్వారా పిల్లలు ఒత్తిడి లేకుండా ఉత్సాహంగా నేర్చుకుంటారు."}, {"id": 172, "sec": "Special Education", "passage": "", "q_en": "This electronic tool provides word prediction, spell-check, and speech-to-text to enhance reading-writing skills in children with SLD", "q_te": "అభ్యసన వైకల్యం గల పిల్లల్లో పఠన-లేఖన నైపుణ్యాలను మెరుగుపరచడానికి తోడ్పడే సాంకేతిక పరికరం", "opts": [{"en": "Compact disc alone", "te": "కేవలం సీడీలు", "raw": "Compact disc alone / కేవలం సీడీలు"}, {"en": "Simple FM Radio", "te": "రేడియో", "raw": "Simple FM Radio / రేడియో"}, {"en": "Audio cassette player", "te": "టేప్ రికార్డర్", "raw": "Audio cassette player / టేప్ రికార్డర్"}, {"en": "Computer with assistive software", "te": "సహాయక సాఫ్ట్‌వేర్ గల కంప్యూటర్ (Computer)", "raw": "Computer with assistive software / సహాయక సాఫ్ట్‌వేర్ గల కంప్యూటర్ (Computer)"}], "ans": 4, "exp_en": "Computers equipped with assistive technologies (screen readers, speech synthesizers, phonetic spellcheckers, voice-typing) dramatically empower children with reading and writing disabilities.", "exp_te": "స్పెల్-చెకర్, టెక్స్ట్-టు-స్పీచ్ వంటి ఫీచర్లు గల కంప్యూటర్ (Computer) అభ్యసన వైకల్యం గల పిల్లలకు చదవడం, రాయడంలో ఒక అద్భుతమైన సహాయక సాధనంగా పనిచేస్తుంది."}, {"id": 173, "sec": "Special Education", "passage": "", "q_en": "Multimedia (integrating text, audio, images, animation, and video) directly supports which learning methodology?", "q_te": "మల్టీమీడియా (పాఠ్యం, ధ్వని, బొమ్మలు, వీడియోల కలయిక) ఏ అభ్యసన విధానానికి అత్యంత తోడ్పడుతుంది", "opts": [{"en": "Rigid formal learning", "te": "కఠినమైన సంప్రదాయ అభ్యసనం", "raw": "Rigid formal learning / కఠినమైన సంప్రదాయ అభ్యసనం"}, {"en": "Informal learning", "te": "అనియత అభ్యసనం", "raw": "Informal learning / అనియత అభ్యసనం"}, {"en": "Multi-Sensory Learning", "te": "బహుళ-ఇంద్రియ అభ్యసనం (Multi-Sensory Learning)", "raw": "Multi-Sensory Learning / బహుళ-ఇంద్రియ అభ్యసనం (Multi-Sensory Learning)"}, {"en": "Passive listening", "te": "నిష్క్రియ శ్రవణం", "raw": "Passive listening / నిష్క్రియ శ్రవణం"}], "ans": 3, "exp_en": "Multimedia stimulates both the auditory and visual sensory channels simultaneously, facilitating multi-sensory cognitive processing and improved comprehension.", "exp_te": "మల్టీమీడియా అనేది ఒకే సమయంలో కంటికి మరియు చెవికి సమాచారాన్ని అందిస్తూ జ్ఞానేంద్రియాలన్నింటినీ ఉత్తేజపరిచే 'బహుళ-ఇంద్రియ అభ్యసనం' (Multi-sensory learning)."}, {"id": 174, "sec": "Special Education", "passage": "", "q_en": "Television combining auditory, visual, and motion stimuli helps improve motivation by enhancing this cognitive process in learning-disabled children", "q_te": "శ్రవణ, దృశ్య మరియు చలన దృశ్యాలతో కూడిన టెలివిజన్ కార్యక్రమాలు పిల్లలలో దేనిని పెంచడానికి తోడ్పడతాయి", "opts": [{"en": "Sustained Attention / Focus", "te": "ఏకాగ్రత / శ్రద్ధ (Attention / Focus)", "raw": "Sustained Attention / Focus / ఏకాగ్రత / శ్రద్ధ (Attention / Focus)"}, {"en": "Forgetting", "te": "విస్మృతి (మర్చిపోవడం)", "raw": "Forgetting / విస్మృతి (మర్చిపోవడం)"}, {"en": "Distraction", "te": "పరధ్యానం", "raw": "Distraction / పరధ్యానం"}, {"en": "Narrowness of mind", "te": "సంకుచితత్వం", "raw": "Narrowness of mind / సంకుచితత్వం"}], "ans": 1, "exp_en": "Dynamic audio-visual media capture and sustain attention, preventing daydreaming and helping children focus on core instructional messages.", "exp_te": "రంగులు, ధ్వనులు, కదిలే చిత్రాలు పిల్లల దృష్టిని ఆకర్షించి, పాఠ్యాంశంపై వారి 'ఏకాగ్రతను' (Attention) నిలపడానికి ఎంతగానో సహాయపడతాయి."}, {"id": 175, "sec": "Special Education", "passage": "", "q_en": "For students with Learning Disabilities, the instructional materials and tasks should NEVER be", "q_te": "అభ్యసన వైకల్యం గల విద్యార్థులకు అందించే పాఠ్యాంశాలు, పనులు ఎప్పుడూ ఇలా ఉండకూడదు", "opts": [{"en": "Simple and clear", "te": "సరళంగా", "raw": "Simple and clear / సరళంగా"}, {"en": "Attractive", "te": "ఆకర్షణీయంగా", "raw": "Attractive / ఆకర్షణీయంగా"}, {"en": "Encouraging", "te": "ప్రోత్సాహకరంగా", "raw": "Encouraging / ప్రోత్సాహకరంగా"}, {"en": "Excessively Frustrating, Unstructured, and Difficult", "te": "అర్థం కాని రీతిలో అత్యంత కఠినంగా మరియు క్లిష్టంగా (Difficult)", "raw": "Excessively Frustrating, Unstructured, and Difficult / అర్థం కాని రీతిలో అత్యంత కఠినంగా మరియు క్లిష్టంగా (Difficult)"}], "ans": 4, "exp_en": "Tasks that far exceed the student's current developmental ability cause learned helplessness and anxiety; tasks must follow a graded scaffolding approach.", "exp_te": "పిల్లల సామర్థ్యానికి మించిన అతి కఠినమైన, సంక్లిష్టమైన పనులను ఇస్తే వారు చదువుపై విరక్తి పెంచుకుంటారు. కాబట్టి కఠినంగా ఉండకూడదు."}, {"id": 176, "sec": "Special Education", "passage": "", "q_en": "The ideal supportive behavior expected from parents of children with Learning Disabilities is", "q_te": "అభ్యసన వైకల్యం ఉన్న పిల్లల తల్లిదండ్రులు ప్రదర్శించాల్సిన సరైన వైఖరి", "opts": [{"en": "Refusing to assist when the child asks for help", "te": "సహాయం అడిగినప్పుడు తిరస్కరించడం", "raw": "Refusing to assist when the child asks for help / సహాయం అడిగినప్పుడు తిరస్కరించడం"}, {"en": "Completing the child's homework themselves", "te": "పిల్లల హోమ్‌వర్క్‌ను తామే రాసిపెట్టడం", "raw": "Completing the child's homework themselves / పిల్లల హోమ్‌వర్క్‌ను తామే రాసిపెట్టడం"}, {"en": "Encouraging independence without over-pampering or fostering dependence", "te": "అధిక గారాబం చేయకుండా, పిల్లలు సొంతంగా చేసేలా ఆత్మవిశ్వాసం నింపడం", "raw": "Encouraging independence without over-pampering or fostering dependence / అధిక గారాబం చేయకుండా, పిల్లలు సొంతంగా చేసేలా ఆత్మవిశ్వాసం నింపడం"}, {"en": "Humiliating the child before relatives", "te": "ఇతరుల ముందు తక్కువ చేసి మాట్లాడటం", "raw": "Humiliating the child before relatives / ఇతరుల ముందు తక్కువ చేసి మాట్లాడటం"}], "ans": 3, "exp_en": "Parental over-protection reinforces helplessness, while rejection destroys self-worth. Parents should provide patient encouragement while nurturing the child's independence.", "exp_te": "పిల్లలను అతిగా గారాబం చేయకుండా, అలాగే నిరుత్సాహపరచకుండా వారి సామర్థ్యంపై నమ్మకం ఉంచి స్వతంత్రంగా నేర్చుకునేలా ప్రోత్సహించాలి."}, {"id": 177, "sec": "Special Education", "passage": "", "q_en": "Educated parents and society should recognize children with learning disabilities as", "q_te": "తల్లిదండ్రులు మరియు సమాజం అభ్యసన వైకల్యం గల పిల్లలను ఎలా చూడాలి", "opts": [{"en": "Unproductive burdens", "te": "నిరుపయోగమైన భారం", "raw": "Unproductive burdens / నిరుపయోగమైన భారం"}, {"en": "Valuable productive resources capable of societal contribution", "te": "సమాజానికి ఉపయోగపడే విలువైన ఉత్పాదక మానవ వనరులు (Productive resources)", "raw": "Valuable productive resources capable of societal contribution / సమాజానికి ఉపయోగపడే విలువైన ఉత్పాదక మానవ వనరులు (Productive resources)"}, {"en": "Hopeless liabilities", "te": "నిష్ప్రయోజకులు", "raw": "Hopeless liabilities / నిష్ప్రయోజకులు"}, {"en": "Defective individuals", "te": "లోపభూయిష్టమైనవారు", "raw": "Defective individuals / లోపభూయిష్టమైనవారు"}], "ans": 2, "exp_en": "Persons with SLD often possess unique talents in art, design, architecture, and lateral problem-solving, making them highly productive assets to society.", "exp_te": "సరైన శిక్షణ అందిస్తే అభ్యసన వైకల్యం ఉన్నవారు సమాజంలో అత్యున్నత రంగాలలో రాణించగల 'విలువైన ఉత్పాదక వనరులు' (Productive Resources)."}, {"id": 178, "sec": "Special Education", "passage": "", "q_en": "Due to chronic academic setbacks and social misunderstanding, the self-esteem of children with untreated Learning Disability is typically at a", "q_te": "చదువులో వెనుకబాటుతనం వల్ల అభ్యసన వైకల్యం గల పిల్లలలో ఆత్మగౌరవం, మనో-సామాజిక ప్రవర్తన ఏ స్థాయిలో ఉంటుంది", "opts": [{"en": "High superior level", "te": "ఉన్నత స్థాయిలో", "raw": "High superior level / ఉన్నత స్థాయిలో"}, {"en": "Stable advanced level", "te": "స్థిరమైన స్థాయిలో", "raw": "Stable advanced level / స్థిరమైన స్థాయిలో"}, {"en": "Low / Vulnerable level", "te": "తక్కువ / న్యూనతా స్థాయిలో (Low level)", "raw": "Low / Vulnerable level / తక్కువ / న్యూనతా స్థాయిలో (Low level)"}, {"en": "Dominant level", "te": "ఆధిపత్య స్థాయిలో", "raw": "Dominant level / ఆధిపత్య స్థాయిలో"}], "ans": 3, "exp_en": "Continuous school failure, reprimands, and peer teasing commonly result in low self-concept, social withdrawal, and depressed psycho-social functioning.", "exp_te": "తోటి విద్యార్థులు, ఉపాధ్యాయుల నుండి ఎదురయ్యే విమర్శల వల్ల వారిలో ఆత్మన్యూనతా భావం పెరిగి, మనో-సామాజిక ప్రవర్తన తక్కువ స్థాయిలో (Low level) ఉంటుంది."}, {"id": 179, "sec": "Special Education", "passage": "", "q_en": "To cultivate psychological stability and confidence in a child with Learning Disability, the teacher should", "q_te": "అభ్యసన వైకల్యం గల విద్యార్థిలో మానసిక స్థైర్యాన్ని, ఆత్మవిశ్వాసాన్ని నింపడానికి ఉపాధ్యాయుడు చేయాల్సింది", "opts": [{"en": "Provide empathetic guidance, structured encouragement, and counseling", "te": "తగిన మార్గదర్శకత్వం, సానుభూతితో కూడిన కౌన్సిలింగ్ అందించడం (Guidance & Counselling)", "raw": "Provide empathetic guidance, structured encouragement, and counseling / తగిన మార్గదర్శకత్వం, సానుభూతితో కూడిన కౌన్సిలింగ్ అందించడం (Guidance & Counselling)"}, {"en": "Forbid the child from sharing feelings with anyone", "te": "పిల్లవాడు ఎవరితోనూ మాట్లాడకుండా నియంత్రించడం", "raw": "Forbid the child from sharing feelings with anyone / పిల్లవాడు ఎవరితోనూ మాట్లాడకుండా నియంత్రించడం"}, {"en": "Remain indifferent when the child shows progress", "te": "మంచి పని చేసినప్పుడు పట్టించుకోకపోవడం", "raw": "Remain indifferent when the child shows progress / మంచి పని చేసినప్పుడు పట్టించుకోకపోవడం"}, {"en": "Isolate the child in hopeless situations", "te": "ఒంటరిగా వదిలివేయడం", "raw": "Isolate the child in hopeless situations / ఒంటరిగా వదిలివేయడం"}], "ans": 1, "exp_en": "Teachers act as mentors. Offering warm empathetic listening, individualized guidance, and positive reinforcement builds emotional resilience in struggling learners.", "exp_te": "ఉపాధ్యాయుడు విద్యార్థి ఇబ్బందులను అర్థం చేసుకొని, ఓర్పుతో మార్గదర్శకత్వం మరియు కౌన్సిలింగ్ (Guidance and Counselling) అందించడం ద్వారా వారిలో ధైర్యాన్ని నింపాలి."}, {"id": 180, "sec": "Special Education", "passage": "", "q_en": "An essential element in facilitating social integration and peer acceptance for children with disabilities is", "q_te": "ప్రత్యేక అవసరాలు గల పిల్లల సాంఘిక వికాస ప్రక్రియలో ఉపాధ్యాయులు చేయాల్సిన ముఖ్యమైన పని", "opts": [{"en": "Encouraging anti-social behaviors", "te": "సాంఘిక వ్యతిరేక ప్రవర్తనలను ప్రోత్సహించడం", "raw": "Encouraging anti-social behaviors / సాంఘిక వ్యతిరేక ప్రవర్తనలను ప్రోత్సహించడం"}, {"en": "Not assigning any classroom responsibilities", "te": "తరగతిలో ఎటువంటి బాధ్యతలు అప్పగించకపోవడం", "raw": "Not assigning any classroom responsibilities / తరగతిలో ఎటువంటి బాధ్యతలు అప్పగించకపోవడం"}, {"en": "Encouraging inappropriate isolation", "te": "పిల్లలను ఏకాంతంగా ఉండనివ్వడం", "raw": "Encouraging inappropriate isolation / పిల్లలను ఏకాంతంగా ఉండనివ్వడం"}, {"en": "Observing, analyzing, and actively training their social and cooperative skills", "te": "వారి సాంఘిక నైపుణ్యాలను నిశితంగా పరిశీలిస్తూ, స్నేహపూర్వక ప్రవర్తనను పెంపొందించడం", "raw": "Observing, analyzing, and actively training their social and cooperative skills / వారి సాంఘిక నైపుణ్యాలను నిశితంగా పరిశీలిస్తూ, స్నేహపూర్వక ప్రవర్తనను పెంపొందించడం"}], "ans": 4, "exp_en": "Social skills do not always develop incidentally in children with special needs; teachers must systematically observe, teach, model, and reinforce prosocial cooperative behaviors.", "exp_te": "విద్యార్థుల సాంఘిక నైపుణ్యాలను పరిశీలించి, తరగతిలోని ఇతర పిల్లలతో కలిసి పనిచేసేలా బాధ్యతలు అప్పగిస్తూ సాంఘిక వికాసానికి (Social skills) తోడ్పడాలి."}, {"id": 181, "sec": "Special Education", "passage": "", "q_en": "'Lack of Intelligence to live independently in a Society is called Mental Retardation' was defined by", "q_te": "'సమాజంలో స్వతంత్రంగా జీవించడానికి తగిన ప్రజ్ఞ లేకపోవడాన్నే మానసిక వైకల్యం అంటారు' అని నిర్వచించిన వారు", "opts": [{"en": "Benda", "te": "బెండా (Benda)", "raw": "Benda / బెండా (Benda)"}, {"en": "Sarason, Dorris", "te": "సారాసన్, డోరిస్ (Sarason, Dorris)", "raw": "Sarason, Dorris / సారాసన్, డోరిస్ (Sarason, Dorris)"}, {"en": "AAMR", "te": "AAMR", "raw": "AAMR"}, {"en": "Smith, Neisworth", "te": "స్మిత్, నీస్వర్త్ (Smith, Neisworth)", "raw": "Smith, Neisworth / స్మిత్, నీస్వర్త్ (Smith, Neisworth)"}], "ans": 4, "exp_en": "Smith and Neisworth defined mental retardation (intellectual disability) in terms of social and behavioral competence as the lack of sufficient intelligence required by an individual to live independently and effectively within their community and society.", "exp_te": "స్మిత్ మరియు నీస్వర్త్ (Smith & Neisworth) మానసిక వైకల్యాన్ని నిర్వచిస్తూ, సమాజంలో ఒక వ్యక్తి స్వతంత్రంగా జీవించడానికి అవసరమైన కనీస ప్రజ్ఞా సామర్థ్యం లోపించడాన్నే 'మానసిక వైకల్యం' (Mental Retardation) గా పేర్కొన్నారు."}, {"id": 182, "sec": "Special Education", "passage": "", "q_en": "A head circumference significantly below 17 inches in an adult is seen in persons with", "q_te": "తల చుట్టుకొలత 17 అంగుళాల కంటే తక్కువగా ఉండే పరిస్థితి వీరిలో కనిపిస్తుంది", "opts": [{"en": "Macrocephaly", "te": "మాక్రోసెఫాలీ (పెద్ద తల)", "raw": "Macrocephaly / మాక్రోసెఫాలీ (పెద్ద తల)"}, {"en": "Microcephaly", "te": "మైక్రోసెఫాలీ (చిన్న తల)", "raw": "Microcephaly / మైక్రోసెఫాలీ (చిన్న తల)"}, {"en": "Hydrocephalus", "te": "హైడ్రోసెఫలస్ (నీరు చేరిన తల)", "raw": "Hydrocephalus / హైడ్రోసెఫలస్ (నీరు చేరిన తల)"}, {"en": "Cretinism", "te": "క్రెటినిజం", "raw": "Cretinism / క్రెటినిజం"}], "ans": 2, "exp_en": "Microcephaly ('small head') is a neurological condition where the head circumference is more than two to three standard deviations below the mean for age and sex (less than 17 inches in adults), resulting in restricted brain development and intellectual disability.", "exp_te": "తల యొక్క చుట్టుకొలత సాధారణం కంటే చాలా చిన్నదిగా, 17 అంగుళాల కంటే తక్కువగా ఉండటాన్ని 'మైక్రోసెఫాలీ' (Microcephaly) అంటారు. దీనివల్ల మెదడు ఎదుగుదల ఆగిపోయి మానసిక వైకల్యం కలుగుతుంది."}, {"id": 183, "sec": "Special Education", "passage": "", "q_en": "Intellectual disability caused due to the deficiency/absence of the enzyme that metabolizes the amino acid 'Phenylalanine' among children is", "q_te": "పిల్లల్లో 'ఫినైల్ అలనైన్' అను అమైనో ఆమ్లాన్ని విచ్ఛిన్నం చేసే ఎంజైమ్ లోపం వల్ల కలిగే మానసిక వైకల్యం", "opts": [{"en": "Down's Syndrome", "te": "డౌన్స్ సిండ్రోమ్", "raw": "Down's Syndrome / డౌన్స్ సిండ్రోమ్"}, {"en": "Cretinism", "te": "క్రెటినిజం", "raw": "Cretinism / క్రెటినిజం"}, {"en": "Phenylketonuria (PKU)", "te": "ఫినైల్ కిటోనూరియా (Phenylketonuria - PKU)", "raw": "Phenylketonuria (PKU) / ఫినైల్ కిటోనూరియా (Phenylketonuria - PKU)"}, {"en": "Dwarfism", "te": "మరుగుజ్జుతనం (డ్వార్ఫిజం)", "raw": "Dwarfism / మరుగుజ్జుతనం (డ్వార్ఫిజం)"}], "ans": 3, "exp_en": "Phenylketonuria (PKU) is an inborn error of metabolism caused by a deficiency of the liver enzyme phenylalanine hydroxylase (PAH), leading to accumulation of phenylalanine in the body which severely damages brain development causing intellectual disability.", "exp_te": "ఫినైల్ కిటోనూరియా (PKU) అనేది ఒక జన్యు సంబంధిత జీవక్రియా లోపం. ఫినైల్ అలనైన్ హైడ్రాక్సిలేస్ అను ఎంజైమ్ లోపం వల్ల శరీరంలో ఫినైల్ అలనైన్ విషపూరితంగా పేరుకుపోయి నాడీ వ్యవస్థ మరియు మెదడు దెబ్బతిని మానసిక వైకల్యం ఏర్పడుతుంది."}, {"id": 184, "sec": "Special Education", "passage": "", "q_en": "The suitable rehabilitation / educational classification category for students with Mild Intellectual Disability is", "q_te": "స్వల్ప మానసిక వైకల్యం (Mild Intellectual Disability - IQ 50-70) గల విద్యార్థులకు అనువైన పునరావాస/విద్యా విధానం", "opts": [{"en": "Trainable (TMR)", "te": "శిక్షణ పొందదగిన వారు (Trainable)", "raw": "Trainable (TMR) / శిక్షణ పొందదగిన వారు (Trainable)"}, {"en": "Custodial (CMR)", "te": "సంరక్షణ మాత్రమే పొందదగిన వారు (Custodial)", "raw": "Custodial (CMR) / సంరక్షణ మాత్రమే పొందదగిన వారు (Custodial)"}, {"en": "Home-based care", "te": "గృహ ఆధారిత సంరక్షణ (Home-based)", "raw": "Home-based care / గృహ ఆధారిత సంరక్షణ (Home-based)"}, {"en": "Educable (EMR)", "te": "విద్యను నేర్చుకోదగిన వారు (Educable - EMR)", "raw": "Educable (EMR) / విద్యను నేర్చుకోదగిన వారు (Educable - EMR)"}], "ans": 4, "exp_en": "Under traditional educational classification of intellectual disability: Mild ID (IQ 50-70) is categorized as 'Educable Mentally Retarded' (EMR), Moderate ID (IQ 35-49) as 'Trainable' (TMR), and Severe/Profound (IQ below 35) as 'Custodial'.", "exp_te": "విద్యా వర్గీకరణ ప్రకారం స్వల్ప మానసిక వైకల్యం (Mild ID, IQ 50-69) గల విద్యార్థులను 'విద్యాబోధన పొందదగిన వారు' (Educable Mentally Retarded - EMR) అంటారు. వీరు ప్రాథమిక విద్యా నైపుణ్యాలు మరియు రోజువారీ జీవన నైపుణ్యాలను నేర్చుకోగలరు."}, {"id": 185, "sec": "Special Education", "passage": "", "q_en": "Which of the following is NOT an assessment checklist used for students with Intellectual Disability?", "q_te": "మానసిక వైకల్యం గల విద్యార్థులను అంచనా వేయడానికి ఉపయోగించని చెక్‌లిస్ట్", "opts": [{"en": "FACP", "te": "FACP (ఫంక్షనల్ అసెస్‌మెంట్ చెక్‌లిస్ట్ ఫర్ ప్రోగ్రామింగ్)", "raw": "FACP / FACP (ఫంక్షనల్ అసెస్‌మెంట్ చెక్‌లిస్ట్ ఫర్ ప్రోగ్రామింగ్)"}, {"en": "MDPS", "te": "MDPS (మద్రాస్ డెవలప్‌మెంటల్ ప్రోగ్రామింగ్ సిస్టమ్)", "raw": "MDPS / MDPS (మద్రాస్ డెవలప్‌మెంటల్ ప్రోగ్రామింగ్ సిస్టమ్)"}, {"en": "Cribogram", "te": "క్రిబోగ్రామ్ (Cribogram)", "raw": "Cribogram / క్రిబోగ్రామ్ (Cribogram)"}, {"en": "BASIC-MR", "te": "BASIC-MR (బిహేవియరల్ అసెస్‌మెంట్ స్కేల్ ఫర్ ఇండియన్ చిల్డ్రన్ విత్ MR)", "raw": "BASIC-MR / BASIC-MR (బిహేవియరల్ అసెస్‌మెంట్ స్కేల్ ఫర్ ఇండియన్ చిల్డ్రన్ విత్ MR)"}], "ans": 3, "exp_en": "FACP, MDPS, and BASIC-MR are widely used Indian assessment tools for intellectual disability, whereas 'Cribogram' is an automated infant hearing screening instrument.", "exp_te": "క్రిబోగ్రామ్ (Cribogram) అనేది పసిపిల్లల శ్రవణ (వినికిడి) లోపాన్ని పరీక్షించడానికి ఉపయోగించే సాధనం. FACP, MDPS, BASIC-MR అనేవి మానసిక వైకల్యం గల పిల్లల వికాస మరియు ప్రవర్తనా నైపుణ్యాలను అంచనా వేసే ప్రామాణిక సాధనాలు."}, {"id": 186, "sec": "Special Education", "passage": "", "q_en": "Expand MDPS", "q_te": "MDPS ను విస్తరించగా", "opts": [{"en": "Madras Development Programming System", "te": "మద్రాస్ డెవలప్‌మెంట్ ప్రోగ్రామింగ్ సిస్టమ్ (Madras Development Programming System)", "raw": "Madras Development Programming System / మద్రాస్ డెవలప్‌మెంట్ ప్రోగ్రామింగ్ సిస్టమ్ (Madras Development Programming System)"}, {"en": "Minimum Development Programming System", "te": "మినిమమ్ డెవలప్‌మెంట్ ప్రోగ్రామింగ్ సిస్టమ్", "raw": "Minimum Development Programming System / మినిమమ్ డెవలప్‌మెంట్ ప్రోగ్రామింగ్ సిస్టమ్"}, {"en": "Maximum Development Programming System", "te": "మాక్సిమమ్ డెవలప్‌మెంట్ ప్రోగ్రామింగ్ సిస్టమ్", "raw": "Maximum Development Programming System / మాక్సిమమ్ డెవలప్‌మెంట్ ప్రోగ్రామింగ్ సిస్టమ్"}, {"en": "Madras Development Prompting System", "te": "మద్రాస్ డెవలప్‌మెంట్ ప్రాంప్టింగ్ సిస్టమ్", "raw": "Madras Development Prompting System / మద్రాస్ డెవలప్‌మెంట్ ప్రాంప్టింగ్ సిస్టమ్"}], "ans": 1, "exp_en": "MDPS stands for 'Madras Developmental Programming System', developed by Dr. Jayachandran and Dr. Vimala in Chennai to assess adaptive behaviors in individuals with intellectual disabilities across 18 functional domains.", "exp_te": "MDPS పూర్తి రూపం 'Madras Development Programming System' (మద్రాస్ డెవలప్‌మెంటల్ ప్రోగ్రామింగ్ సిస్టమ్). మానసిక వైకల్యం గల పిల్లల అనుకూల ప్రవర్తనలు మరియు వికాస నైపుణ్యాలను 18 డొమైన్లలో అంచనా వేయడానికి దీనిని రూపొందించారు."}, {"id": 187, "sec": "Special Education", "passage": "", "q_en": "While preparing a curriculum related to students with Intellectual Disability, these components must be considered in this specific order", "q_te": "మానసిక వైకల్యం గల విద్యార్థులకు పాఠ్యప్రణాళిక (Curriculum) తయారు చేయునపుడు పరిగణించవలసిన సరైన క్రమము", "opts": [{"en": "Aim, Basis, Contents, Methods, Materials", "te": "లక్ష్యం, పునాది, విషయాలు, పద్ధతులు, సామాగ్రి", "raw": "Aim, Basis, Contents, Methods, Materials / లక్ష్యం, పునాది, విషయాలు, పద్ధతులు, సామాగ్రి"}, {"en": "Basis, Aim, Contents, Methods, Materials", "te": "పునాది (Basis), లక్ష్యం (Aim), విషయాలు (Contents), పద్ధతులు (Methods), సామాగ్రి (Materials)", "raw": "Basis, Aim, Contents, Methods, Materials / పునాది (Basis), లక్ష్యం (Aim), విషయాలు (Contents), పద్ధతులు (Methods), సామాగ్రి (Materials)"}, {"en": "Aim, Contents, Basis, Materials, Methods", "te": "లక్ష్యం, విషయాలు, పునాది, సామాగ్రి, పద్ధతులు", "raw": "Aim, Contents, Basis, Materials, Methods / లక్ష్యం, విషయాలు, పునాది, సామాగ్రి, పద్ధతులు"}, {"en": "Contents, Basis, Aim, Materials, Methods", "te": "విషయాలు, పునాది, లక్ష్యం, సామాగ్రి, పద్ధతులు", "raw": "Contents, Basis, Aim, Materials, Methods / విషయాలు, పునాది, లక్ష్యం, సామాగ్రి, పద్ధతులు"}], "ans": 2, "exp_en": "The scientific order of curriculum development begins with establishing the philosophical/psychological Basis (పునాది), formulating the Aims (లక్ష్యాలు), selecting the Content/Syllabus (విషయాలు), choosing appropriate Teaching Methods (బోధనా పద్ధతులు), and preparing TLM/Materials (బోధనా సామాగ్రి).", "exp_te": "పాఠ్యప్రణాళిక తయారీలో శాస్త్రీయ సోపానాల సరైన క్రమం: 1) పునాది/ఆధారం (Basis), 2) లక్ష్యాలు (Aim), 3) విషయ సూచిక/పాఠ్యాంశాలు (Contents), 4) బోధనా పద్ధతులు (Methods), 5) బోధనాభ్యసన సామాగ్రి (Materials)."}, {"id": 188, "sec": "Special Education", "passage": "", "q_en": "In the 'VAKT' multisensory approach, 'K' stands for", "q_te": "'VAKT' బహుళేంద్రియ విధానంలో 'K' అనునది దీనిని సూచిస్తుంది", "opts": [{"en": "Knowledge", "te": "నాలెడ్జ్ (జ్ఞానం)", "raw": "Knowledge / నాలెడ్జ్ (జ్ఞానం)"}, {"en": "Kinaesthetic (Movement / muscle sensation)", "te": "కైనస్తెటిక్ (శరీర కదలికలు/స్పర్శానుభవం)", "raw": "Kinaesthetic (Movement / muscle sensation) / కైనస్తెటిక్ (శరీర కదలికలు/స్పర్శానుభవం)"}, {"en": "Kind", "te": "కైండ్", "raw": "Kind / కైండ్"}, {"en": "Kindergarten", "te": "కిండర్ గార్టెన్", "raw": "Kindergarten / కిండర్ గార్టెన్"}], "ans": 2, "exp_en": "VAKT is Fernald's multisensory instructional approach integrating: V = Visual (చూడటం), A = Auditory (వినడం), K = Kinaesthetic (కదలికలు/కండరాల స్పర్శ - tracing/movement), T = Tactile (స్పర్శ - feeling texture).", "exp_te": "VAKT విధానం ఒక ప్రసిద్ధ బహుళేంద్రియ పద్ధతి: V = Visual (దృష్టి), A = Auditory (శ్రవణం), K = Kinaesthetic (కైనస్తెటిక్ - కదలికలు/కండరాల అనుభూతి), T = Tactile (స్పర్శ). కావున 'K' అంటే Kinaesthetic."}, {"id": 189, "sec": "Special Education", "passage": "", "q_en": "To teach the syllabus for students with Intellectual Disability at the primary stage, which instructional principle should be followed?", "q_te": "ప్రాథమిక స్థాయిలో మానసిక వైకల్యం గల విద్యార్థులకు పాఠ్యాంశాలను బోధించడానికి అనుసరించాల్సిన బోధనా సూత్రం", "opts": [{"en": "Abstract to Concrete", "te": "అమూర్తం నుండి మూర్తమునకు", "raw": "Abstract to Concrete / అమూర్తం నుండి మూర్తమునకు"}, {"en": "Unknown to Known", "te": "తెలియని దాని నుండి తెలిసిన దానికి", "raw": "Unknown to Known / తెలియని దాని నుండి తెలిసిన దానికి"}, {"en": "Whole to Part", "te": "మొత్తం నుండి భాగమునకు (Whole to Part)", "raw": "Whole to Part / మొత్తం నుండి భాగమునకు (Whole to Part)"}, {"en": "Complex to Simple", "te": "క్లిష్టమైన దాని నుండి సరళమైన దానికి", "raw": "Complex to Simple / క్లిష్టమైన దాని నుండి సరళమైన దానికి"}], "ans": 3, "exp_en": "Gestalt developmental pedagogy emphasizes teaching from 'Whole to Part' (మొత్తం నుండి భాగమునకు) - first presenting the complete, meaningful object or situation as a whole entity before breaking it down into component parts, which facilitates conceptual perception in learners with intellectual disabilities.", "exp_te": "మానసిక వైకల్యం గల పిల్లలకు ప్రాథమిక స్థాయిలో బోధించేటప్పుడు 'మొత్తం నుండి భాగమునకు' (Whole to Part) అను సూత్రం పాటించాలి. మొదట వస్తువు లేదా భావనను సమగ్రంగా చూపించి, ఆ తర్వాత దానిలోని విడి భాగాలను బోధించడం ద్వారా వారు తేలికగా గ్రహిస్తారు."}, {"id": 190, "sec": "Special Education", "passage": "", "q_en": "To know the ongoing performance, mastery, and diagnostic gaps of a student with Intellectual Disability, a teacher relies on", "q_te": "మేధో వైకల్యం గల విద్యార్థి యొక్క అభ్యసన స్థాయిని మరియు పురోగతిని తెలుసుకోవడానికి ఉపాధ్యాయునికి తోడ్పడేది", "opts": [{"en": "Continuous Comprehensive Evaluation (Formative Assessment)", "te": "నిరంతర సమగ్ర మూల్యాంకనం (Evaluation / Formative Assessment)", "raw": "Continuous Comprehensive Evaluation (Formative Assessment) / నిరంతర సమగ్ర మూల్యాంకనం (Evaluation / Formative Assessment)"}, {"en": "Unit Plan alone", "te": "యూనిట్ ప్రణాళిక", "raw": "Unit Plan alone / యూనిట్ ప్రణాళిక"}, {"en": "Annual Plan alone", "te": "వార్షిక ప్రణాళిక", "raw": "Annual Plan alone / వార్షిక ప్రణాళిక"}, {"en": "Syllabus outline alone", "te": "సిలబస్", "raw": "Syllabus outline alone / సిలబస్"}], "ans": 1, "exp_en": "Continuous formative evaluation and criterion-referenced assessment provide constant data on whether the student has mastered targeted behavioral milestones in their IEP.", "exp_te": "విద్యార్థి సాధించిన పురోగతిని ఎప్పటికప్పుడు తెలుసుకోవడానికి ఉపాధ్యాయుడు 'నిరంతర మూల్యాంకనం' (Evaluation) పై ఆధారపడతాడు."}, {"id": 191, "sec": "Special Education", "passage": "", "q_en": "The instructional technique of breaking a complex skill down into small, sequential, teachable component steps is called", "q_te": "ఒక సంక్లిష్టమైన పనిని చిన్న చిన్న సరళమైన అంశాలుగా విభజించి క్రమపద్ధతిలో బోధించే పద్ధతి", "opts": [{"en": "Imitation", "te": "అనుకpushకరణ", "raw": "Imitation / అనుకpushకరణ"}, {"en": "Cuing", "te": "క్యూయింగ్", "raw": "Cuing / క్యూయింగ్"}, {"en": "Fading", "te": "ఫేడింగ్", "raw": "Fading / ఫేడింగ్"}, {"en": "Task Analysis", "te": "టాస్క్ అనాలిసిస్ (Task Analysis / కృత్య విశ్లేషణ)", "raw": "Task Analysis / టాస్క్ అనాలిసిస్ (Task Analysis / కృత్య విశ్లేషణ)"}], "ans": 4, "exp_en": "Task Analysis is the cornerstone of special education methodology, breaking down any task (like brushing teeth, tying shoelaces) into its sub-component steps.", "exp_te": "ఒక పెద్ద పనిని (ఉదాహరణకు బ్రష్ చేసుకోవడం) చిన్న చిన్న దశలుగా విభజించి నేర్పించే పద్ధతిని 'టాస్క్ అనాలిసిస్' (Task Analysis / కృత్య విశ్లేషణ) అంటారు."}, {"id": 192, "sec": "Special Education", "passage": "", "q_en": "Rehabilitation provided to students with Intellectual Disability by training in horticulture, crafts, and carpentry is termed", "q_te": "మేధో వైకల్యం గల విద్యార్థులకు తోటపని, పెయింటింగ్ వంటి పనుల ద్వారా అందించే పునరావాసం", "opts": [{"en": "Educational Rehabilitation", "te": "విద్యా పునరావాసం", "raw": "Educational Rehabilitation / విద్యా పునరావాసం"}, {"en": "Audiological Rehabilitation", "te": "శ్రవణ పునరావాసం", "raw": "Audiological Rehabilitation / శ్రవణ పునరావాసం"}, {"en": "Vocational Rehabilitation", "te": "వృత్తిపరమైన పునరావాసం (Vocational Rehabilitation)", "raw": "Vocational Rehabilitation / వృత్తిపరమైన పునరావాసం (Vocational Rehabilitation)"}, {"en": "Social Rehabilitation", "te": "సామాజిక పునరావాసం", "raw": "Social Rehabilitation / సామాజిక పునరావాసం"}], "ans": 3, "exp_en": "Vocational rehabilitation prepares individuals with cognitive disabilities to perform economic jobs and manual skills to achieve self-sustained adult living.", "exp_te": "ఆర్థిక స్వయం సమృద్ధిని సాధించడానికి వివిధ వృత్తులలో నైపుణ్యాలను అందించడాన్ని 'వృత్తి పునరావాసం' (Vocational Rehabilitation) అంటారు."}, {"id": 193, "sec": "Special Education", "passage": "", "q_en": "Which of the following topics is NOT part of an Individualized Educational Programme (IEP)?", "q_te": "క్రింది వానిలో వ్యక్తిగత విద్యా ప్రణాళిక (IEP) కు సంబంధం లేని అంశం ఏది", "opts": [{"en": "Annual Goals", "te": "వార్షిక లక్ష్యాలు", "raw": "Annual Goals / వార్షిక లక్ష్యాలు"}, {"en": "Evaluation methods", "te": "మూల్యాంకనం", "raw": "Evaluation methods / మూల్యాంకనం"}, {"en": "Short-term Objectives", "te": "స్వల్పకాలిక లక్ష్యాలు", "raw": "Short-term Objectives / స్వల్పకాలిక లక్ష్యాలు"}, {"en": "School Administrative Management", "te": "పాఠశాల పరిపాలనా నిర్వహణ (School Management)", "raw": "School Administrative Management / పాఠశాల పరిపాలనా నిర్వహణ (School Management)"}], "ans": 4, "exp_en": "An IEP is an educational blueprint for a specific child's instruction; overall school building management and governance have no place in a student's IEP.", "exp_te": "IEP అనేది విద్యార్థి విద్యా ప్రణాళిక. పాఠశాల నిర్వహణ (School Management) అనేది పరిపాలనా పరమైన అంశం కానీ IEP లో భాగం కాదు."}, {"id": 194, "sec": "Special Education", "passage": "", "q_en": "According to the cognitive development theory of Piaget, a student with intellectual disability must understand primary number concepts before learning fundamentals in Mathematics", "q_te": "గణితంలో ప్రాథమిక ప్రక్రియలను నేర్చుకోవడానికి ముందే పిల్లలు ప్రాథమిక సంఖ్యా భావనలను గ్రహించాలని తెలిపిన సంజ్ఞానాత్మక వికాస సిద్ధాంతకర్త", "opts": [{"en": "Skinner", "te": "బి.ఎఫ్. స్కిన్నర్", "raw": "Skinner / బి.ఎఫ్. స్కిన్నర్"}, {"en": "Pavlov", "te": "ఇవాన్ పావ్‌లోవ్", "raw": "Pavlov / ఇవాన్ పావ్‌లోవ్"}, {"en": "Jean Piaget", "te": "జీన్ పియాజే (Jean Piaget)", "raw": "Jean Piaget / జీన్ పియాజే (Jean Piaget)"}, {"en": "Kohler", "te": "వోల్ఫ్‌గ్యాంగ్ కోహ్లర్", "raw": "Kohler / వోల్ఫ్‌గ్యాంగ్ కోహ్లర్"}], "ans": 3, "exp_en": "Jean Piaget established that children must acquire conservation of number and concrete operational logic before they can master formal arithmetic and mathematical operations.", "exp_te": "పిల్లలు గణిత చతుర్విధ ప్రక్రియలను నేర్చుకోవడానికి ముందే మూర్త ప్రచాలక దశకు సంబంధించిన ప్రాథమిక సంఖ్యా భావనలను (Number concepts) గ్రహించాలని జీన్ పియాజే సిద్ధాంతం చెబుతుంది."}, {"id": 195, "sec": "Special Education", "passage": "", "q_en": "Which of the following is NOT a scientifically recognized behavioral modification method to manage problem behaviors in children with Intellectual Disability?", "q_te": "మేధో వైకల్యం గల పిల్లలలో ప్రవర్తనా సమస్యలను తగ్గించి మంచి ప్రవర్తనను పెంపొందించడానికి పనికిరాని పద్ధతి ఏది", "opts": [{"en": "Shaping", "te": "షేపింగ్ (Shaping)", "raw": "Shaping / షేపింగ్ (Shaping)"}, {"en": "Chaining", "te": "చైనింగ్ (Chaining)", "raw": "Chaining / చైనింగ్ (Chaining)"}, {"en": "Prompting", "te": "ప్రాంప్టింగ్ (Prompting)", "raw": "Prompting / ప్రాంప్టింగ్ (Prompting)"}, {"en": "Over-Pampering and indulgence", "te": "అతి గారాబం చేయడం (Pampering / మితిమీరిన గారాబం)", "raw": "Over-Pampering and indulgence / అతి గారాబం చేయడం (Pampering / మితిమీరిన గారాబం)"}], "ans": 4, "exp_en": "Scientific behavioral techniques include Shaping, Chaining, Prompting, and Extinction. Indulgent pampering rewards tantrums and reinforces maladaptive behavior.", "exp_te": "షేపింగ్, చైనింగ్, ప్రాంప్టింగ్ అనేవి శాస్త్రీయ ప్రవర్తనా మార్పిడి పద్ధతులు. అతిగా గారాబం చేయడం (Pampering) వల్ల పిల్లలలో మొండితనం మరియు సమస్య ప్రవర్తనలు పెరుగుతాయి."}, {"id": 196, "sec": "Special Education", "passage": "", "q_en": "When selecting Teaching Learning Material (TLM) for students with Intellectual Disability, the primary factor a teacher must consider is", "q_te": "మేధో వైకల్యం గల విద్యార్థులకు బోధనా సామాగ్రిని (TLM) ఎంపిక చేసేటప్పుడు ఉపాధ్యాయుడు ప్రధానంగా పరిగణించాల్సింది", "opts": [{"en": "Their Mental Age and current Cognitive developmental level", "te": "వారి మానసిక వయస్సు మరియు ప్రజ్ఞా స్థాయి (Intelligence Level / Mental Age)", "raw": "Their Mental Age and current Cognitive developmental level / వారి మానసిక వయస్సు మరియు ప్రజ్ఞా స్థాయి (Intelligence Level / Mental Age)"}, {"en": "Selecting materials that are abstract and difficult", "te": "అత్యంత కఠినమైన సామాగ్రి", "raw": "Selecting materials that are abstract and difficult / అత్యంత కఠినమైన సామాగ్రి"}, {"en": "Materials irrespective of age and safety", "te": "వయస్సుతో సంబంధం లేని వస్తువులు", "raw": "Materials irrespective of age and safety / వయస్సుతో సంబంధం లేని వస్తువులు"}, {"en": "The cost and expensiveness of the material", "te": "అత్యంత ఖరీదైన సామాగ్రి", "raw": "The cost and expensiveness of the material / అత్యంత ఖరీదైన సామాగ్రి"}], "ans": 1, "exp_en": "TLM for intellectually disabled children must match their mental age (cognitive capability) and functional developmental stage rather than their chronological age.", "exp_te": "మేధో వైకల్యం గల పిల్లలకు బోధనా సామాగ్రిని వారి మానసిక వయస్సు (Mental Age) మరియు ప్రస్తుత ప్రజ్ఞా స్థాయికి అనుగుణంగా ఎంపిక చేయాలి."}, {"id": 197, "sec": "Special Education", "passage": "", "q_en": "'Food' and water are examples of which type of Reinforcement?", "q_te": "'ఆహారం' అనేది ఏ రకమైన పునర్బలనానికి (Reinforcement) చెందినది", "opts": [{"en": "Secondary Reinforcement", "te": "ద్వితీయ పునర్బలనం", "raw": "Secondary Reinforcement / ద్వితీయ పునర్బలనం"}, {"en": "Primary Reinforcement (Unconditioned Reinforcer)", "te": "ప్రాథమిక పునర్బలనం (Primary Reinforcement / సహజ అవసరం)", "raw": "Primary Reinforcement (Unconditioned Reinforcer) / ప్రాథమిక పునర్బలనం (Primary Reinforcement / సహజ అవసరం)"}, {"en": "Social Reinforcement", "te": "సాంఘిక పునర్బలనం", "raw": "Social Reinforcement / సాంఘిక పునర్బలనం"}, {"en": "Economic Reinforcement", "te": "ఆర్థిక పునర్బలనం", "raw": "Economic Reinforcement / ఆర్థిక పునర్బలనం"}], "ans": 2, "exp_en": "Primary reinforcers are biological necessities essential for survival (food, water, warmth, sleep) that naturally reinforce behavior without prior learning.", "exp_te": "ఆహారం, నీరు వంటి సహజ శారీరక మనుగడ అవసరాలు ఎటువంటి ముందస్తు శిక్షణ లేకుండానే ప్రవర్తనను ఉత్తేజపరుస్తాయి కాబట్టి వీటిని 'ప్రాథమిక పునర్బలనం' (Primary Reinforcement) అంటారు."}, {"id": 198, "sec": "Special Education", "passage": "", "q_en": "When a student with Intellectual Disability says 'Bulu' instead of 'Blue', this articulatory speech error is classified as", "q_te": "ఒక విద్యార్థి 'Blue' అనడానికి బదులుగా 'Bulu' (బులు) అని అదనపు ధ్వనిని చేర్చి పలికితే అది ఏ ఉచ్ఛారణా దోషం", "opts": [{"en": "Omission", "te": "లోపించడం (Omission)", "raw": "Omission / లోపించడం (Omission)"}, {"en": "Addition", "te": "అదనంగా చేర్చడం (Addition)", "raw": "Addition / అదనంగా చేర్చడం (Addition)"}, {"en": "Substitution", "te": "మార్పిడి (Substitution)", "raw": "Substitution / మార్పిడి (Substitution)"}, {"en": "Distortion", "te": "వక్రీకరణ (Distortion)", "raw": "Distortion / వక్రీకరణ (Distortion)"}], "ans": 2, "exp_en": "In articulation disorders (SODA): Adding an extra vowel or syllable into a word (inserting 'u' to pronounce 'Bulu' for 'Blue') is an Addition error.", "exp_te": "ఒక పదం పలికేటప్పుడు అందులో లేని అదనపు అక్షరాన్ని లేదా స్వరాన్ని చేర్చి పలకడాన్ని ఉచ్ఛారణా లోపాలలో 'చేరిక' (Addition) అంటారు."}, {"id": 199, "sec": "Special Education", "passage": "", "q_en": "An effective projection device used to project printed images and opaque textbook materials onto a classroom screen is an", "q_te": "పుస్తకాల్లోని చిత్రాలను, అపారదర్శక వస్తువులను తెరపై పెద్దవిగా చూపించడానికి తరగతి గదిలో ఉపయోగించే ప్రొజెక్షన్ సాధనం", "opts": [{"en": "Blackboard", "te": "నల్లబల్ల", "raw": "Blackboard / నల్లబల్ల"}, {"en": "Clay models", "te": "మట్టి నమూనాలు", "raw": "Clay models / మట్టి నమూనాలు"}, {"en": "Epidiascope (Opaque Projector)", "te": "ఎపిడయాస్కోప్ (Epidiascope / ఒపేక్ ప్రొజెక్టర్)", "raw": "Epidiascope (Opaque Projector) / ఎపిడయాస్కోప్ (Epidiascope / ఒపేక్ ప్రొజెక్టర్)"}, {"en": "Garden", "te": "తోట", "raw": "Garden / తోట"}], "ans": 3, "exp_en": "An Epidiascope is an optical projector capable of projecting images of both transparent slides and opaque flat materials (book pages, drawings) onto a screen for enlarged group viewing.", "exp_te": "ఎపిడయాస్కోప్ (Epidiascope) అనేది పుస్తకంలోని ముద్రిత చిత్రాలను, అపారదర్శక వస్తువులను పెద్ద స్క్రీన్‌పై స్పష్టంగా ప్రదర్శించే ప్రొజెక్షన్ దృశ్య సాధనం."}, {"id": 200, "sec": "Special Education", "passage": "", "q_en": "A classical manipulative mathematical aid used to teach multiplication tables and products to students with Mild Intellectual Disability is", "q_te": "స్వల్ప మేధో వైకల్యం గల విద్యార్థులకు గుణకారాలను సులభంగా నేర్పించడానికి తోడ్పడే గణిత సామాగ్రి", "opts": [{"en": "Simple Abacus", "te": "సాధారణ అబాకస్", "raw": "Simple Abacus / సాధారణ అబాకస్"}, {"en": "Napier's Rods (Napier's Bones)", "te": "నేపియర్ పట్టీలు (Napier's Rods / నేపియర్ బోన్స్)", "raw": "Napier's Rods (Napier's Bones) / నేపియర్ పట్టీలు (Napier's Rods / నేపియర్ బోన్స్)"}, {"en": "Cubic Rods", "te": "క్యూబిక్ రాడ్స్", "raw": "Cubic Rods / క్యూబిక్ రాడ్స్"}, {"en": "Cuisenaire Strips", "te": "కుసినైర్ స్ట్రిప్స్", "raw": "Cuisenaire Strips / కుసినైర్ స్ట్రిప్స్"}], "ans": 2, "exp_en": "John Napier invented Napier's Bones (Rods), a manually-operated calculating device specifically designed for lattice-based multiplication and division.", "exp_te": "జాన్ నేపియర్ రూపొందించిన 'నేపియర్ పట్టీలు' (Napier's Rods) గుణకారాలను గడుల పద్ధతిలో సులభంగా లెక్కించడానికి తోడ్పడే అద్భుతమైన గణిత సాధనం."}, {"id": 201, "sec": "Special Education", "passage": "", "q_en": "Which electronic hardware device allows a teacher to present educational multimedia lessons to an entire classroom on a large display?", "q_te": "కంప్యూటర్‌లోని మల్టీమీడియా పాఠ్యాంశాలను తరగతి గదిలోని విద్యార్థులందరికీ పెద్ద తెరపై ప్రదర్శించడానికి తోడ్పడే సాధనం", "opts": [{"en": "Printed books", "te": "పుస్తకాలు", "raw": "Printed books / పుస్తకాలు"}, {"en": "Multimedia LCD/LED Projector", "te": "మల్టీమీడియా ప్రొజెక్టర్ (Multimedia Projector)", "raw": "Multimedia LCD/LED Projector / మల్టీమీడియా ప్రొజెక్టర్ (Multimedia Projector)"}, {"en": "Simple Radio", "te": "రేడియో", "raw": "Simple Radio / రేడియో"}, {"en": "Newspaper", "te": "వార్తాపత్రిక", "raw": "Newspaper / వార్తాపత్రిక"}], "ans": 2, "exp_en": "A Multimedia Projector connects to a computer or video player to project bright, magnified visual and video lessons onto a whiteboard or projection screen.", "exp_te": "మల్టీమీడియా ప్రొజెక్టర్ (Projector) ద్వారా కంప్యూటర్‌లోని యానిమేషన్లు, వీడియోలు, రంగుల చిత్రాలను పెద్ద తెరపై విద్యార్థులందరికీ స్పష్టంగా బోధించవచ్చు."}, {"id": 202, "sec": "Special Education", "passage": "", "q_en": "The flagship national initiative launched by the Government of India to empower citizens with digital literacy and rural high-speed internet connectivity is", "q_te": "భారతదేశంలో డిజిటల్ అక్షరాస్యతను సాధించడానికి, గ్రామీణ ప్రాంతాలకు ఇంటర్నెట్ సౌకర్యాలు కల్పించడానికి ప్రారంభించిన ప్రధాన కార్యక్రమం", "opts": [{"en": "Bharat Scouts and Guides", "te": "భారత్ స్కౌట్స్ అండ్ గైడ్స్", "raw": "Bharat Scouts and Guides / భారత్ స్కౌట్స్ అండ్ గైడ్స్"}, {"en": "MANAK", "te": "మనక్ (MANAK)", "raw": "MANAK / మనక్ (MANAK)"}, {"en": "Digital India Programme", "te": "డిజిటల్ ఇండియా కార్యక్రమం (Digital India Programme)", "raw": "Digital India Programme / డిజిటల్ ఇండియా కార్యక్రమం (Digital India Programme)"}, {"en": "Quit India Programme", "te": "క్విట్ ఇండియా", "raw": "Quit India Programme / క్విట్ ఇండియా"}], "ans": 3, "exp_en": "Digital India, launched in 2015, aims to transform India into a digitally empowered society and knowledge economy by providing broadband infrastructure and digital literacy.", "exp_te": "దేశంలోని పౌరులందరికీ డిజిటల్ సేవలు, ఇంటర్నెట్ సౌకర్యాలు మరియు డిజిటల్ పరిజ్ఞానాన్ని అందించడానికి 2015లో ప్రారంభించిన పథకం 'డిజిటల్ ఇండియా' (Digital India)."}, {"id": 203, "sec": "Special Education", "passage": "", "q_en": "Expand PECS", "q_te": "PECS యొక్క పూర్తి రూపం", "opts": [{"en": "Print Exchange Communication System", "te": "ప్రింట్ ఎక్స్ఛేంజ్ కమ్యూనికేషన్ సిస్టమ్", "raw": "Print Exchange Communication System / ప్రింట్ ఎక్స్ఛేంజ్ కమ్యూనికేషన్ సిస్టమ్"}, {"en": "Picture Exchange Communication System", "te": "పిక్చర్ ఎక్స్ఛేంజ్ కమ్యూనికేషన్ సిస్టమ్ (Picture Exchange Communication System - PECS)", "raw": "Picture Exchange Communication System / పిక్చర్ ఎక్స్ఛేంజ్ కమ్యూనికేషన్ సిస్టమ్ (Picture Exchange Communication System - PECS)"}, {"en": "Picture Entertaining Cinema System", "te": "పిక్చర్ సినిమా సిస్టమ్", "raw": "Picture Entertaining Cinema System / పిక్చర్ సినిమా సిస్టమ్"}, {"en": "Print Embossed Contract System", "te": "ప్రింట్ కాంట్రాక్ట్ సిస్టమ్", "raw": "Print Embossed Contract System / ప్రింట్ కాంట్రాక్ట్ సిస్టమ్"}], "ans": 2, "exp_en": "PECS stands for Picture Exchange Communication System, an augmentative and alternative communication (AAC) intervention for non-verbal individuals.", "exp_te": "PECS అనగా 'Picture Exchange Communication System'. ఇది ఆటిజం మరియు మాటలు రాని పిల్లలకు చిత్రాల ద్వారా భావవ్యక్తీకరణ నేర్పించే ప్రముఖ సాధనం."}, {"id": 204, "sec": "Special Education", "passage": "", "q_en": "Expand CAI in educational technology", "q_te": "విద్యా సాంకేతిక శాస్త్రంలో CAI యొక్క పూర్తి రూపం", "opts": [{"en": "Computer Assisted Instruction", "te": "కంప్యూటర్ అసిస్టెడ్ ఇన్‌స్ట్రక్షన్ (Computer Assisted Instruction - CAI)", "raw": "Computer Assisted Instruction / కంప్యూటర్ అసిస్టెడ్ ఇన్‌స్ట్రక్షన్ (Computer Assisted Instruction - CAI)"}, {"en": "Class Associated Instruction", "te": "క్లాస్ అసోసియేటెడ్ ఇన్‌స్ట్రక్షన్", "raw": "Class Associated Instruction / క్లాస్ అసోసియేటెడ్ ఇన్‌స్ట్రక్షన్"}, {"en": "Computer Associated Instruction", "te": "కంప్యూటర్ అసోసియేటెడ్ ఇన్‌స్ట్రక్షన్", "raw": "Computer Associated Instruction / కంప్యూటర్ అసోసియేటెడ్ ఇన్‌స్ట్రక్షన్"}, {"en": "Class Assisted Implementation", "te": "క్లాస్ అసిస్టెడ్ ఇంప్లిమెంటేషన్", "raw": "Class Assisted Implementation / క్లాస్ అసిస్టెడ్ ఇంప్లిమెంటేషన్"}], "ans": 1, "exp_en": "CAI stands for Computer-Assisted Instruction, an interactive instructional technique whereby a computer is used to present instructional material and track learning progress.", "exp_te": "CAI అనగా 'Computer Assisted Instruction' (కంప్యూటర్ ఆధారిత బోధన). కంప్యూటర్ సహాయంతో విద్యార్థులకు వ్యక్తిగత వేగంతో పాఠాలు నేర్పించే విధానం."}, {"id": 205, "sec": "Special Education", "passage": "", "q_en": "Stealing, persistent lying, gossiping destructively, and violating established rules are categorized under", "q_te": "దొంగతనం చేయడం, అబద్ధాలు చెప్పడం, ఇతరులపై విమర్శలు చేయడం, నియమాలను ఉల్లంఘించడం ఏ ప్రవర్తనకు చెందినవి", "opts": [{"en": "Hyperactivity", "te": "అతి చురుకుదనం", "raw": "Hyperactivity / అతి చురుకుదనం"}, {"en": "Anti-Social / Conduct Behavior", "te": "సాంఘిక వ్యతిరేక ప్రవర్తన (Anti-Social Behaviour / ప్రవర్తనా రుగ్మత)", "raw": "Anti-Social / Conduct Behavior / సాంఘిక వ్యతిరేక ప్రవర్తన (Anti-Social Behaviour / ప్రవర్తనా రుగ్మత)"}, {"en": "Phobic Fears", "te": "భయాలు", "raw": "Phobic Fears / భయాలు"}, {"en": "Temper Tantrums", "te": "టెంపర్ టాన్‌ట్రమ్స్", "raw": "Temper Tantrums / టెంపర్ టాన్‌ట్రమ్స్"}], "ans": 2, "exp_en": "Anti-social conduct behaviors involve chronic, repetitive violation of societal norms, rules, and the personal rights of others (theft, deceitfulness, defiance).", "exp_te": "సామాజిక నిబంధనలను ఉల్లంఘిస్తూ ఇతరులకు హాని కలిగించే దొంగతనాలు, అబద్ధాలు చెప్పడం వంటి చర్యలను 'సాంఘిక వ్యతిరేక ప్రవర్తన' (Anti-social behavior) అంటారు."}, {"id": 206, "sec": "Special Education", "passage": "", "q_en": "In Community-Based Rehabilitation (CBR), CPP stands for", "q_te": "కమ్యూనిటీ ఆధారిత పునరావాసంలో (CBR) CPP అనగా", "opts": [{"en": "Community Pupils Poverty", "te": "కమ్యూనిటీ ప్యూపిల్స్ పావర్టీ", "raw": "Community Pupils Poverty / కమ్యూనిటీ ప్యూపిల్స్ పావర్టీ"}, {"en": "Community Programme for People", "te": "కమ్యూనిటీ ప్రోగ్రామ్ ఫర్ పీపుల్", "raw": "Community Programme for People / కమ్యూనిటీ ప్రోగ్రామ్ ఫర్ పీపుల్"}, {"en": "Community People Participation", "te": "కమ్యూనిటీ పీపుల్ పార్టిసిపేషన్ (Community People Participation / సమాజ ప్రజల భాగస్వామ్యం)", "raw": "Community People Participation / కమ్యూనిటీ పీపుల్ పార్టిసిపేషన్ (Community People Participation / సమాజ ప్రజల భాగస్వామ్యం)"}, {"en": "Community Persons with Problems", "te": "కమ్యూనిటీ పర్సన్స్ విత్ ప్రాబ్లమ్స్", "raw": "Community Persons with Problems / కమ్యూనిటీ పర్సన్స్ విత్ ప్రాబ్లమ్స్"}], "ans": 3, "exp_en": "CPP stands for Community People Participation, ensuring that local community members actively participate in rehabilitating and including persons with disabilities.", "exp_te": "CPP అనగా 'Community People Participation' (సమాజ ప్రజల భాగస్వామ్యం). దివ్యాంగుల పునరావాసంలో స్థానిక ప్రజల భాగస్వామ్యాన్ని ఇది సూచిస్తుంది."}, {"id": 207, "sec": "Special Education", "passage": "", "q_en": "A major underlying cause of chronic emotional conflict and distress in a child with Intellectual Disability is", "q_te": "మేధో వైకల్యం గల పిల్లలలో తీవ్రమైన మానసిక సంఘర్షణకు మరియు బాధకు ప్రధాన కారణం", "opts": [{"en": "Receiving genuine appreciation from teachers", "te": "ఉపాధ్యాయుల నుండి ప్రశంసలు అందుకోవడం", "raw": "Receiving genuine appreciation from teachers / ఉపాధ్యాయుల నుండి ప్రశంసలు అందుకోవడం"}, {"en": "Receiving parental affection and acceptance", "te": "తల్లిదండ్రుల నుండి ప్రేమ లభించడం", "raw": "Receiving parental affection and acceptance / తల్లిదండ్రుల నుండి ప్రేమ లభించడం"}, {"en": "Not getting hostel accommodation", "te": "హాస్టల్ వసతి దొరకకపోవడం", "raw": "Not getting hostel accommodation / హాస్టల్ వసతి దొరకకపోవడం"}, {"en": "Experiencing chronic rejection, hostility, and unprovoked anger from parents or family", "te": "తల్లిదండ్రులు లేదా కుటుంబ సభ్యులు వారిని కారణం లేకుండా తిరస్కరించడం, ద్వేషించడం (Feeling of rejection)", "raw": "Experiencing chronic rejection, hostility, and unprovoked anger from parents or family / తల్లిదండ్రులు లేదా కుటుంబ సభ్యులు వారిని కారణం లేకుండా తిరస్కరించడం, ద్వేషించడం (Feeling of rejection)"}], "ans": 4, "exp_en": "Parental rejection, emotional neglect, and stigma inflict severe psychic trauma on cognitively challenged children, causing profound emotional conflict.", "exp_te": "తల్లిదండ్రులు తమ స్వంత బిడ్డను అంగీకరించకుండా చిన్నచూపు చూడటం, తిరస్కరించడం (Rejection) పిల్లలలో తీవ్రమైన మానసిక సంఘర్షణకు దారితీస్తుంది."}, {"id": 208, "sec": "Special Education", "passage": "", "q_en": "Which of the following serves as a powerful Social Reinforcement for a student with Intellectual Disability?", "q_te": "మేధో వైకల్యం గల విద్యార్థికి అత్యంత ప్రభావవంతమైన సాంఘిక పునర్బలనం (Social Reinforcement) ఏది", "opts": [{"en": "Food item", "te": "ఆహారం ఇవ్వడం (ప్రాథమిక పునర్బలనం)", "raw": "Food item / ఆహారం ఇవ్వడం (ప్రాథమిక పునర్బలనం)"}, {"en": "Giving extra sleep", "te": "నిద్రపోనివ్వడం", "raw": "Giving extra sleep / నిద్రపోనివ్వడం"}, {"en": "Verbal Appreciation, praise, and a smile", "te": "మనస్ఫూర్తిగా మెచ్చుకోవడం, ప్రశంసించడం (Verbal Appreciation / సానుకూల ప్రశంస)", "raw": "Verbal Appreciation, praise, and a smile / మనస్ఫూర్తిగా మెచ్చుకోవడం, ప్రశంసించడం (Verbal Appreciation / సానుకూల ప్రశంస)"}, {"en": "Giving Chocolates", "te": "చాక్లెట్లు ఇవ్వడం", "raw": "Giving Chocolates / చాక్లెట్లు ఇవ్వడం"}], "ans": 3, "exp_en": "Social reinforcers are non-tangible social gestures such as smiles, public praise, clapping, high-fives, and verbal appreciation that validate self-esteem.", "exp_te": "చాక్లెట్లు లేదా వస్తువులు కాకుండా ఉపాధ్యాయుడు చిరునవ్వుతో ప్రశంసించడం, శభాష్ అని మెచ్చుకోవడం (Appreciation) గొప్ప 'సాంఘిక పునర్బలనం'గా పనిచేస్తుంది."}, {"id": 209, "sec": "Special Education", "passage": "", "q_en": "Siblings of a person with Intellectual Disability can provide the most constructive support by", "q_te": "మేధో వైకల్యం గల వ్యక్తి యొక్క తోబుట్టువులు (Siblings) అందించాల్సిన అత్యంత సరైన సహకారం", "opts": [{"en": "Keeping away and isolating themselves from the disabled sibling", "te": "వారి నుండి దూరంగా ఉంటూ ఒంటరిగా చేయడం", "raw": "Keeping away and isolating themselves from the disabled sibling / వారి నుండి దూరంగా ఉంటూ ఒంటరిగా చేయడం"}, {"en": "Never letting the disabled sibling participate in household activities", "te": "ఇంటి పనులలో వారిని ఎప్పుడూ భాగస్వామ్యం చేయకపోవడం", "raw": "Never letting the disabled sibling participate in household activities / ఇంటి పనులలో వారిని ఎప్పుడూ భాగస్వామ్యం చేయకపోవడం"}, {"en": "Promoting positive attitudes, social awareness, and inclusion among peers and neighbors", "te": "ఇరుగుపొరుగు మరియు సమాజంలో వారి పట్ల సానుకూల వైఖరిని, అవగాహనను కల్పించడం", "raw": "Promoting positive attitudes, social awareness, and inclusion among peers and neighbors / ఇరుగుపొరుగు మరియు సమాజంలో వారి పట్ల సానుకూల వైఖరిని, అవగాహనను కల్పించడం"}, {"en": "Ignoring their emotional needs completely", "te": "వారి అవసరాలను పట్టించుకోకపోవడం", "raw": "Ignoring their emotional needs completely / వారి అవసరాలను పట్టించుకోకపోవడం"}], "ans": 3, "exp_en": "Siblings act as natural social bridges, advocating for their brother/sister, dispelling community stigma, and modeling respectful inclusion to neighbors and peers.", "exp_te": "తోబుట్టువులు తమ దివ్యాంగ సోదరుడు/సోదరి పట్ల ఇరుగుపొరుగు వారికి సరైన అవగాహన కల్పిస్తూ, సమాజంలో వారిని గౌరవప్రదంగా కలుపుకుపోయేలా చేయాలి."}, {"id": 210, "sec": "Special Education", "passage": "", "q_en": "A proven behavioral technique used to teach a complex chain of functional self-care skills to children with Intellectual Disability is", "q_te": "మేధో వైకల్యం గల పిల్లలకు సంక్లిష్టమైన స్వయం సహాయక నైపుణ్యాలను దశలవారీగా నేర్పడానికి ఉపయోగించే పద్ధతి", "opts": [{"en": "Open playground free run", "te": "ఆటస్థలం", "raw": "Open playground free run / ఆటస్థలం"}, {"en": "Flashing lights", "te": "లైట్ల వెలుగు", "raw": "Flashing lights / లైట్ల వెలుగు"}, {"en": "Chaining (Forward and Backward Chaining)", "te": "చైనింగ్ పద్ధతి (Chaining - Forward / Backward Chaining)", "raw": "Chaining (Forward and Backward Chaining) / చైనింగ్ పద్ధతి (Chaining - Forward / Backward Chaining)"}, {"en": "Closing doors", "te": "తలుపులు వేయడం", "raw": "Closing doors / తలుపులు వేయడం"}], "ans": 3, "exp_en": "Chaining connects discrete behavioral links identified in a task analysis into a single smooth sequence (e.g., Forward chaining or Backward chaining to put on a shirt).", "exp_te": "టాస్క్ అనాలిసిస్‌లో విభజించిన ప్రతి చిన్న దశను ఒక గొలుసుకట్టు క్రమంలో ఒకదాని తర్వాత ఒకటి నేర్పించే పద్ధతిని 'చైనింగ్' (Chaining) అంటారు."}, {"id": 211, "sec": "Special Education", "passage": "", "q_en": "Having two or more co-occurring disabilities (such as blindness and hearing impairment) is defined as", "q_te": "ఒక వ్యక్తిలో రెండు లేదా అంతకంటే ఎక్కువ వైకల్యాలు కలిసి ఉండటాన్ని ఏమంటారు", "opts": [{"en": "Multiple Disabilities", "te": "బహుళ వైకల్యాలు (Multiple Disabilities)", "raw": "Multiple Disabilities / బహుళ వైకల్యాలు (Multiple Disabilities)"}, {"en": "Single sensory disability", "te": "ఏక ఇంద్రియ వైకల్యం", "raw": "Single sensory disability / ఏక ఇంద్రియ వైకల్యం"}, {"en": "Dual sensory disability alone", "te": "ద్వంద్వ ఇంద్రియ లోపం", "raw": "Dual sensory disability alone / ద్వంద్వ ఇంద్రియ లోపం"}, {"en": "Deafness alone", "te": "సాధారణ బధిరత్వం", "raw": "Deafness alone / సాధారణ బధిరత్వం"}], "ans": 1, "exp_en": "Multiple Disabilities refers to concomitant impairments (such as intellectual disability-blindness, locomotor disability-cerebral palsy) whose combination causes severe educational needs.", "exp_te": "ఒకే వ్యక్తిలో రెండు లేదా అంతకంటే ఎక్కువ రకాల వైకల్యాలు (ఉదాహరణకు అంధత్వంతో పాటు వినికిడి లోపం, లేదా బుద్ధిమాంద్యంతో పాటు చలన లోపం) ఉండటాన్ని 'బహుళ వైకల్యాలు' (Multiple Disabilities) అంటారు."}, {"id": 212, "sec": "Special Education", "passage": "", "q_en": "Functional assessment for children with Multiple Disabilities begins fundamentally with", "q_te": "బహుళ వైకల్యాలు గల పిల్లల సామర్థ్యాలను అంచనా వేయడానికి ప్రారంభంలో నిర్వహించే పరీక్ష", "opts": [{"en": "End-line Assessment", "te": "ఎండ్ లైన్ అసెస్‌మెంట్", "raw": "End-line Assessment / ఎండ్ లైన్ అసెస్‌మెంట్"}, {"en": "Baseline Assessment (Foundational functional assessment)", "te": "బేస్‌లైన్ అసెస్‌మెంట్ (Baseline Assessment / మూలాధార అంచనా)", "raw": "Baseline Assessment (Foundational functional assessment) / బేస్‌లైన్ అసెస్‌మెంట్ (Baseline Assessment / మూలాధార అంచనా)"}, {"en": "Audiological Assessment alone", "te": "కేవలం వినికిడి పరీక్ష", "raw": "Audiological Assessment alone / కేవలం వినికిడి పరీక్ష"}, {"en": "Gray Oral Reading List", "te": "గ్రే ఓరల్ రీడింగ్ లిస్ట్", "raw": "Gray Oral Reading List / గ్రే ఓరల్ రీడింగ్ లిస్ట్"}], "ans": 2, "exp_en": "A comprehensive Baseline Assessment evaluates the child's current entry-level functional abilities, sensory thresholds, and physical capabilities before setting IEP goals.", "exp_te": "విద్యార్థికి ఏ నైపుణ్యాలు వచ్చు, ఏవి రావు అని ప్రారంభంలో వారి ప్రస్తుత సామర్థ్యాలను సమగ్రంగా తెలుసుకోవడానికి 'బేస్‌లైన్ అసెస్‌మెంట్' (Baseline Assessment) నిర్వహిస్తారు."}, {"id": 213, "sec": "Special Education", "passage": "", "q_en": "An example of a congenital Cranial anomaly (abnormal skull/brain enlargement due to fluid accumulation) is", "q_te": "పుర్రె / మెదడు నిర్మాణంలో ద్రవం చేరి తల పరిమాణం అసాధారణంగా పెరిగే క్రేనియల్ రుగ్మత", "opts": [{"en": "Dwarfism", "te": "మరుగుజ్జుతనం (Dwarfism)", "raw": "Dwarfism / మరుగుజ్జుతనం (Dwarfism)"}, {"en": "Down's Syndrome", "te": "డౌన్స్ సిండ్రోమ్", "raw": "Down's Syndrome / డౌన్స్ సిండ్రోమ్"}, {"en": "Cretinism", "te": "క్రెటినిజం", "raw": "Cretinism / క్రెటినిజం"}, {"en": "Hydrocephalus", "te": "హైడ్రోసెఫలస్ (Hydrocephalus / నీటి తల)", "raw": "Hydrocephalus / హైడ్రోసెఫలస్ (Hydrocephalus / నీటి తల)"}], "ans": 4, "exp_en": "Hydrocephalus is a cranial anomaly where cerebrospinal fluid (CSF) builds up within the brain cavities (ventricles), expanding the head and putting harmful pressure on brain tissue.", "exp_te": "హైడ్రోసెఫలస్ (Hydrocephalus) అనేది పుర్రెలో సెరిబ్రోస్పైనల్ ద్రవం (CSF) అధికంగా చేరడం వల్ల తల పరిమాణం విపరీతంగా ఉబ్బిపోయే క్రేనియల్ వైకల్యం."}, {"id": 214, "sec": "Special Education", "passage": "", "q_en": "Identifying and intervening with a Child with Multiple Disabilities (CwMD) at this developmental stage prevents secondary complications and yields the best outcomes", "q_te": "బహుళ వైకల్యాలు గల పిల్లలను ఈ ప్రారంభ దశలోనే గుర్తించి చికిత్స/శిక్షణ ప్రారంభిస్తే అత్యుత్తమ ఫలితాలు సాధించవచ్చు", "opts": [{"en": "Early stage / Infancy (Early Intervention)", "te": "ప్రారంభ శైశవ దశ (Early Stage / Early Intervention)", "raw": "Early stage / Infancy (Early Intervention) / ప్రారంభ శైశవ దశ (Early Stage / Early Intervention)"}, {"en": "Puberty", "te": "యవ్వనారంభ దశ", "raw": "Puberty / యవ్వనారంభ దశ"}, {"en": "Late Puberty", "te": "ఉత్తర కౌమార దశ", "raw": "Late Puberty / ఉత్తర కౌమార దశ"}, {"en": "Adolescence", "te": "కౌమార దశ", "raw": "Adolescence / కౌమార దశ"}], "ans": 1, "exp_en": "Early Identification and Early Intervention (0-3 and 3-6 years) capitalize on neural plasticity, preventing secondary contractures and maximizing sensory-motor development.", "exp_te": "శిశువు పుట్టిన ప్రారంభ దశలోనే (Early stage) గుర్తించి తగిన ఫిజియోథెరపీ, ఇంద్రియ శిక్షణ అందిస్తే మెదడు అభివృద్ధి వేగంగా జరిగి వైకల్య తీవ్రతను గణనీయంగా తగ్గించవచ్చు."}, {"id": 215, "sec": "Special Education", "passage": "", "q_en": "A primary hallmark clinical characteristic of Muscular Dystrophy is", "q_te": "మస్కులర్ డిస్ట్రోఫీ (Muscular Dystrophy) యొక్క ప్రధాన లక్షణం", "opts": [{"en": "Normal stable posture", "te": "సాధారణ భంగిమ", "raw": "Normal stable posture / సాధారణ భంగిమ"}, {"en": "Unusually large head", "te": "పెద్ద తల", "raw": "Unusually large head / పెద్ద తల"}, {"en": "Progressive skeletal muscle weakness and degeneration", "te": "శరీరంలోని కండరాలు క్రమక్రమంగా క్షీణించి బలహీనపడటం (Progressive muscle weakness)", "raw": "Progressive skeletal muscle weakness and degeneration / శరీరంలోని కండరాలు క్రమక్రమంగా క్షీణించి బలహీనపడటం (Progressive muscle weakness)"}, {"en": "Difficulty in abstract thinking alone", "te": "కేవలం ఆలోచనా లోపం", "raw": "Difficulty in abstract thinking alone / కేవలం ఆలోచనా లోపం"}], "ans": 3, "exp_en": "Muscular Dystrophy comprises a group of genetic diseases characterized by progressive weakness, loss of muscle mass, and chronic degeneration of skeletal muscles.", "exp_te": "మస్కులర్ డిస్ట్రోఫీ అనేది జన్యుపరమైన కండరాల క్షీణత వ్యాధి. దీనిలో నడవడానికి, కదలడానికి తోడ్పడే అస్థిపంజర కండరాలు క్రమంగా బలహీనపడి కదలికలు నిలిచిపోతాయి."}, {"id": 216, "sec": "Special Education", "passage": "", "q_en": "The diagnostic assessment that examines functional skills needed by a child with special needs to succeed in real everyday environments is called", "q_te": "నిజ జీవిత పరిసరాలలో స్వతంత్రంగా జీవించడానికి అవసరమైన ఆచరణాత్మక నైపుణ్యాలను అంచనా వేసే పద్ధతి", "opts": [{"en": "Formative Assessment", "te": "నిర్మాణాత్మక మూల్యాంకనం", "raw": "Formative Assessment / నిర్మాణాత్మక మూల్యాంకనం"}, {"en": "Functional Assessment", "te": "ఫంక్షనల్ అసెస్‌మెంట్ (క్రియాత్మక / ఆచరణాత్మక అంచనా - Functional Assessment)", "raw": "Functional Assessment / ఫంక్షనల్ అసెస్‌మెంట్ (క్రియాత్మక / ఆచరణాత్మక అంచనా - Functional Assessment)"}, {"en": "Structured Written Examinations", "te": "రాత పరీక్షలు", "raw": "Structured Written Examinations / రాత పరీక్షలు"}, {"en": "Complicated Memory Test", "te": "సంక్లిష్ట జ్ఞాపకశక్తి పరీక్ష", "raw": "Complicated Memory Test / సంక్లిష్ట జ్ఞాపకశక్తి పరీక్ష"}], "ans": 2, "exp_en": "Functional Assessment evaluates practical daily living, mobility, communication, and vocational skills needed to function independently across home, school, and community environments.", "exp_te": "పాఠ్యపుస్తక మార్కుల కంటే రోజువారీ జీవితంలో బ్రష్ చేసుకోవడం, దుస్తులు ధరించడం, సమాజంలో మెలగడం వంటి ఆచరణాత్మక నైపుణ్యాలను అంచనా వేసే పద్ధతిని 'ఫంక్షనల్ అసెస్‌మెంట్' అంటారు."}, {"id": 217, "sec": "Special Education", "passage": "", "q_en": "The total number of recognized categories of disabilities under the Rights of Persons with Disabilities (RPwD) Act, 2016 is", "q_te": "దివ్యాంగుల హక్కుల చట్టం (RPwD Act) 2016 ప్రకారం గుర్తించబడిన మొత్తం వైకల్యాల సంఖ్య", "opts": [{"en": "25", "te": "25", "raw": "25"}, {"en": "15", "te": "15", "raw": "15"}, {"en": "30", "te": "30", "raw": "30"}, {"en": "21", "te": "21 (ఇరవై ఒకటి)", "raw": "21 / 21 (ఇరవై ఒకటి)"}], "ans": 4, "exp_en": "The RPwD Act 2016 expanded the number of benchmark disability categories from 7 (under the 1995 PwD Act) to 21 distinct conditions, including Autism, Acid Attack, and Blood disorders.", "exp_te": "RPwD చట్టం 2016 ద్వారా భారతదేశంలో అధికారికంగా గుర్తించబడిన వైకల్యాల సంఖ్యను 7 నుండి 21 కి పెంచడం జరిగింది."}, {"id": 218, "sec": "Special Education", "passage": "", "q_en": "Children with Multiple Disabilities (CwMD) benefit most socially, emotionally, and cognitively from", "q_te": "బహుళ వైకల్యాలు గల పిల్లలకు అత్యంత ప్రయోజనకరమైన విద్యా విధానం", "opts": [{"en": "Informal Education alone", "te": "అనియత విద్య", "raw": "Informal Education alone / అనియత విద్య"}, {"en": "Distance Education", "te": "దూరవిద్య", "raw": "Distance Education / దూరవిద్య"}, {"en": "Online Education alone", "te": "ఆన్‌లైన్ విద్య", "raw": "Online Education alone / ఆన్‌లైన్ విద్య"}, {"en": "Inclusive Education in mainstream schools with support", "te": "సమ్మిళిత విద్య (Inclusive Education - తోటి పిల్లలతో కలిసి చదవడం)", "raw": "Inclusive Education in mainstream schools with support / సమ్మిళిత విద్య (Inclusive Education - తోటి పిల్లలతో కలిసి చదవడం)"}], "ans": 4, "exp_en": "Inclusive Education provides rich peer interactions, reduces social isolation, models age-appropriate communication, and ensures equal human dignity for children with severe disabilities.", "exp_te": "సమ్మిళిత విద్య (Inclusive Education) లో సాధారణ పిల్లలతో కలిసి చదువుకోవడం వల్ల బహుళ వైకల్యాలు గల పిల్లల్లో ఆత్మవిశ్వాసం, సాంఘిక అనుకరణ మరియు సమానత్వ భావన పెంపొందుతాయి."}, {"id": 219, "sec": "Special Education", "passage": "", "q_en": "According to the RPwD Act 2016, Dwarfism is medically defined as a medical or genetic condition resulting in an adult height of less than or equal to", "q_te": "RPwD చట్టం 2016 ప్రకారం మరుగుజ్జుతనం (Dwarfism) గల వ్యక్తి యొక్క గరిష్ట వయోజన ఎత్తు పరిమితి", "opts": [{"en": "147 cm (4 feet 10 inches)", "te": "147 సెం.మీ. లేదా అంతకంటే తక్కువ (147 Cms / 4 అడుగుల 10 అంగుళాలు)", "raw": "147 cm (4 feet 10 inches) / 147 సెం.మీ. లేదా అంతకంటే తక్కువ (147 Cms / 4 అడుగుల 10 అంగుళాలు)"}, {"en": "196 cm", "te": "196 సెం.మీ.", "raw": "196 cm / 196 సెం.మీ."}, {"en": "188 cm", "te": "188 సెం.మీ.", "raw": "188 cm / 188 సెం.మీ."}, {"en": "202 cm", "te": "202 సెం.మీ.", "raw": "202 cm / 202 సెం.మీ."}], "ans": 1, "exp_en": "Under the RPwD Act 2016, 'Dwarfism' means a medical or genetic condition resulting in an adult height of 4 feet 10 inches (147 centimeters) or less.", "exp_te": "దివ్యాంగుల హక్కుల చట్టం 2016 ప్రకారం వయోజన వయస్సు వచ్చినప్పటికీ 4 అడుగుల 10 అంగుళాలు (147 సెం.మీ.) లేదా అంతకంటే తక్కువ ఎత్తు ఉన్నవారిని 'డ్వార్ఫిజం' (మరుగుజ్జుతనం) క్రింద గుర్తిస్తారు."}, {"id": 220, "sec": "Special Education", "passage": "", "q_en": "Brushing, bathing, toileting, and eating independently belong to which category of adaptive skills?", "q_te": "బ్రష్ చేసుకోవడం, స్నానం చేయడం, భోజనం చేయడం వంటి స్వయం సహాయక పనులు ఏ రంగానికి చెందినవి", "opts": [{"en": "Personal Care Activities (Activities of Daily Living - ADL)", "te": "వ్యక్తిగత సంరక్షణ / దైనందిన స్వయం సహాయక కృత్యాలు (Personal Care / ADL)", "raw": "Personal Care Activities (Activities of Daily Living - ADL) / వ్యక్తిగత సంరక్షణ / దైనందిన స్వయం సహాయక కృత్యాలు (Personal Care / ADL)"}, {"en": "Vocational care activities", "te": "వృత్తిపరమైన కృత్యాలు", "raw": "Vocational care activities / వృత్తిపరమైన కృత్యాలు"}, {"en": "Recreational care activities", "te": "వినోద కృత్యాలు", "raw": "Recreational care activities / వినోద కృత్యాలు"}, {"en": "Employment activities", "te": "ఉపాధి కృత్యాలు", "raw": "Employment activities / ఉపాధి కృత్యాలు"}], "ans": 1, "exp_en": "Activities of Daily Living (ADLs) are fundamental self-care tasks (eating, bathing, dressing, toileting, personal hygiene) necessary for independent living.", "exp_te": "రోజూ ఉదయం లేచినప్పటి నుండి రాత్రి పడుకునే వరకు స్నానం, ఆహారం, మలమూత్ర విసర్జన వంటి స్వయం నిర్వహణ పనులను 'వ్యక్తిగత సంరక్షణా కృత్యాలు' (ADL) అంటారు."}, {"id": 221, "sec": "Special Education", "passage": "", "q_en": "Sorting different types of fruits, vegetables, and objects by shape and color represents which domain of activity for children with multiple disabilities?", "q_te": "కూరగాయలు, పండ్లను వాటి ఆకారాలు, రంగుల ఆధారంగా వేరుచేసి అమర్చడం అనేది ఏ రకమైన కృత్యం", "opts": [{"en": "Personal self-care activity", "te": "వ్యక్తిగత కృత్యం", "raw": "Personal self-care activity / వ్యక్తిగత కృత్యం"}, {"en": "Cognitive / Perceptual Activity", "te": "సంజ్ఞానాత్మక / ప్రత్యక్ష జ్ఞాన కృత్యం (Cognitive Activity)", "raw": "Cognitive / Perceptual Activity / సంజ్ఞానాత్మక / ప్రత్యక్ష జ్ఞాన కృత్యం (Cognitive Activity)"}, {"en": "Orientation and Mobility", "te": "ఓరియంటేషన్ మరియు మొబిలిటీ", "raw": "Orientation and Mobility / ఓరియంటేషన్ మరియు మొబిలిటీ"}, {"en": "Leisure and recreation alone", "te": "విశ్రాంతి కృత్యం", "raw": "Leisure and recreation alone / విశ్రాంతి కృత్యం"}], "ans": 2, "exp_en": "Sorting and classifying items based on attributes like size, color, texture, and shape trains sensory perception, categorization, and foundational cognitive thinking.", "exp_te": "వివిధ పండ్లు, కూరగాయలను రంగు, పరిమాణం ఆధారంగా పోల్చి వేరుచేయడం (Classification) అనేది మెదడు యొక్క ఆలోచనా శక్తిని పెంచే 'సంజ్ఞానాత్మక కృత్యం' (Cognitive activity)."}, {"id": 222, "sec": "Special Education", "passage": "", "q_en": "Training provided to a student with multiple disabilities to navigate safely along corridor walls and walk to the playground is termed", "q_te": "బహుళ వైకల్యం గల విద్యార్థి పాఠశాల కారిడార్లు, ఆటస్థలానికి సురక్షితంగా వెళ్ళేందుకు అందించే శిక్షణ", "opts": [{"en": "Vocational training", "te": "వృత్తి శిక్షణ", "raw": "Vocational training / వృత్తి శిక్షణ"}, {"en": "Auditory training", "te": "శ్రవణ శిక్షణ", "raw": "Auditory training / శ్రవణ శిక్షణ"}, {"en": "Communication training", "te": "సంభాషణా శిక్షణ", "raw": "Communication training / సంభాషణా శిక్షణ"}, {"en": "Orientation and Mobility (O&M) Training", "te": "ఓరియంటేషన్ మరియు మొబిలిటీ శిక్షణ (దిశాజ్ఞానం మరియు చలన శిక్షణ - O&M)", "raw": "Orientation and Mobility (O&M) Training / ఓరియంటేషన్ మరియు మొబిలిటీ శిక్షణ (దిశాజ్ఞానం మరియు చలన శిక్షణ - O&M)"}], "ans": 4, "exp_en": "Orientation (knowing where you are and where you want to go) and Mobility (moving safely, gracefully, and independently from one place to another) is called O&M training.", "exp_te": "తాము ఎక్కడున్నారో తెలుసుకోవడం (Orientation) మరియు ఎవరి సహాయం లేకుండా సురక్షితంగా నడవడం (Mobility) నేర్పించే విధానాన్ని 'ఓరియంటేషన్ అండ్ మొబిలిటీ శిక్షణ' అంటారు."}, {"id": 223, "sec": "Special Education", "passage": "", "q_en": "Modifying instruction, pacing, and materials to meet an individual child's unique educational goals without lowering standards is called", "q_te": "ప్రత్యేక అవసరాలు గల పిల్లల వ్యక్తిగత లక్ష్యాలకు అనుగుణంగా పాఠ్యప్రణాళికను సర్దుబాటు చేయడం", "opts": [{"en": "Size change only", "te": "పరిమాణాన్ని మార్చడం", "raw": "Size change only / పరిమాణాన్ని మార్చడం"}, {"en": "Curriculum Adaptation / Differentiated Curriculum", "te": "పాఠ్యప్రణాళికా సర్దుబాటు / సవరణ (Curriculum Adaptation / Differentiated Instruction)", "raw": "Curriculum Adaptation / Differentiated Curriculum / పాఠ్యప్రణాళికా సర్దుబాటు / సవరణ (Curriculum Adaptation / Differentiated Instruction)"}, {"en": "Difficulty escalation", "te": "కఠినతను పెంచడం", "raw": "Difficulty escalation / కఠినతను పెంచడం"}, {"en": "Time restriction", "te": "సమయాన్ని తగ్గించడం", "raw": "Time restriction / సమయాన్ని తగ్గించడం"}], "ans": 2, "exp_en": "Curriculum adaptation involves modifications and accommodations in content presentation, instructional materials, and student response modes to make the curriculum accessible.", "exp_te": "దివ్యాంగ పిల్లల అభ్యసన స్థాయికి తగినట్లుగా పాఠ్యాంశాల పరిమాణం, బోధనా సామాగ్రి మరియు పరీక్షా విధానంలో మార్పులు చేయడాన్ని 'పాఠ్యప్రణాళికా సర్దుబాటు' (Curriculum Adaptation) అంటారు."}, {"id": 224, "sec": "Special Education", "passage": "", "q_en": "The unwritten, unofficial, and unintended lessons, values, and social behaviors transmitted to students in a school are referred to as the", "q_te": "పాఠ్యపుస్తకాలలో లిఖితపూర్వకంగా లేనప్పటికీ పాఠశాల వాతావరణం ద్వారా విద్యార్థులు పరోక్షంగా నేర్చుకునే విలువల ప్రణాళిక", "opts": [{"en": "Written Curriculum", "te": "లిఖిత పాఠ్యప్రణాళిక", "raw": "Written Curriculum / లిఖిత పాఠ్యప్రణాళిక"}, {"en": "Taught Curriculum", "te": "బోధించబడిన ప్రణాళిక", "raw": "Taught Curriculum / బోధించబడిన ప్రణాళిక"}, {"en": "Hidden Curriculum (Implicit Curriculum)", "te": "నిగూఢ / అంతర్లీన పాఠ్యప్రణాళిక (Hidden Curriculum)", "raw": "Hidden Curriculum (Implicit Curriculum) / నిగూఢ / అంతర్లీన పాఠ్యప్రణాళిక (Hidden Curriculum)"}, {"en": "Planned Curriculum", "te": "ప్రణాళికాబద్ధమైన సిలబస్", "raw": "Planned Curriculum / ప్రణాళికాబద్ధమైన సిలబస్"}], "ans": 3, "exp_en": "The Hidden Curriculum consists of unstated cultural norms, societal values, implicit expectations, and peer behaviors absorbed informally in the school environment.", "exp_te": "పాఠ్యపుస్తకాల్లో లేకపోయినా పాఠశాల నియమాలు, ఉపాధ్యాయుల ప్రవర్తన, తోటి విద్యార్థుల పరస్పర గౌరవం ద్వారా అలవడే సంస్కృతిని 'నిగూఢ పాఠ్యప్రణాళిక' (Hidden Curriculum) అంటారు."}, {"id": 225, "sec": "Special Education", "passage": "", "q_en": "A multi-level, differentiated classroom environment provides which of the following outcomes?", "q_te": "వివిధ అభ్యసనా స్థాయిలు గల విద్యార్థులున్న తరగతి గది (Multi-level classroom) దేనిని అందిస్తుంది", "opts": [{"en": "Quality individualized learning for diverse learners", "te": "అభ్యాసకులందరికీ నాణ్యమైన, అర్థవంతమైన అభ్యసనం (Quality Learning)", "raw": "Quality individualized learning for diverse learners / అభ్యాసకులందరికీ నాణ్యమైన, అర్థవంతమైన అభ్యసనం (Quality Learning)"}, {"en": "Encourages bad behavior", "te": "చెడు ప్రవర్తన", "raw": "Encourages bad behavior / చెడు ప్రవర్తన"}, {"en": "Low grasping power", "te": "తక్కువ గ్రహణ శక్తి", "raw": "Low grasping power / తక్కువ గ్రహణ శక్తి"}, {"en": "Inferiority complex", "te": "న్యూనతా భావం", "raw": "Inferiority complex / న్యూనతా భావం"}], "ans": 1, "exp_en": "Multi-level classrooms employ differentiated instruction, cooperative learning, and peer scaffolding, ensuring that every learner progresses at their optimal developmental rate.", "exp_te": "విభిన్న సామర్థ్యాలు గల తరగతి గదిలో విద్యార్థులందరి స్థాయిలకు అనుగుణంగా బోధనా వ్యూహాలు అమలు చేయడం వల్ల ప్రతి ఒక్కరికీ 'నాణ్యమైన అభ్యసనం' (Quality Learning) లభిస్తుంది."}, {"id": 226, "sec": "Special Education", "passage": "", "q_en": "Picture communication is which type of communication?", "q_te": "చిత్రాల ద్వారా భావప్రసారం (Picture communication) అనేది ఏ రకమైన కమ్యూనికేషన్?", "opts": [{"en": "Verbal", "te": "శాబ్దిక (Verbal)", "raw": "Verbal / శాబ్దిక (Verbal)"}, {"en": "Verbal language", "te": "శాబ్దిక భాష (Verbal language)", "raw": "Verbal language / శాబ్దిక భాష (Verbal language)"}, {"en": "Non-verbal", "te": "అశాబ్దిక (Non-verbal)", "raw": "Non-verbal / అశాబ్దిక (Non-verbal)"}, {"en": "Speech", "te": "వాక్కు (Speech)", "raw": "Speech / వాక్కు (Speech)"}], "ans": 3, "exp_en": "Picture communication (such as PECS - Picture Exchange Communication System) utilizes visual symbols, graphics, and images rather than spoken words, making it a prominent form of Non-verbal augmentative communication.", "exp_te": "చిత్రాలు, సంకేతాలు, గ్రాఫిక్స్ ద్వారా భావాలను తెలియజేయడం 'అశాబ్దిక భావప్రసారము' (Non-verbal communication) కిందకు వస్తుంది. మాటలు మాట్లాడలేని పిల్లలకు PECS (పిక్చర్ ఎక్స్ఛేంజ్ కమ్యూనికేషన్ సిస్టమ్) ఎంతగానో సహాయపడుతుంది."}, {"id": 227, "sec": "Special Education", "passage": "", "q_en": "The ability to process information received from the eyes to guide the hands in the performance of a task is called", "q_te": "కంటి ద్వారా గ్రహించిన సమాచారాన్ని ఉపయోగించి పనులను సమర్థవంతంగా చేయడానికి చేతులను సమన్వయపరిచే సామర్థ్యాన్ని ఏమంటారు?", "opts": [{"en": "Eye-hand co-ordination", "te": "కన్ను-చేయి సమన్వయం (Eye-hand co-ordination)", "raw": "Eye-hand co-ordination / కన్ను-చేయి సమన్వయం (Eye-hand co-ordination)"}, {"en": "Hand and finger strength", "te": "చేయి మరియు వేళ్ళ బలం", "raw": "Hand and finger strength / చేయి మరియు వేళ్ళ బలం"}, {"en": "Grasp", "te": "పట్టు (Grasp)", "raw": "Grasp / పట్టు (Grasp)"}, {"en": "Hand dominance", "te": "చేతి ప్రాబల్యం (Hand dominance)", "raw": "Hand dominance / చేతి ప్రాబల్యం (Hand dominance)"}], "ans": 1, "exp_en": "Eye-hand coordination (కన్ను-చేయి సమన్వయం) is the coordinated processing of visual input alongside motor output of the hands to execute fine motor tasks such as writing, cutting, catching, or manipulating objects.", "exp_te": "కళ్ల ద్వారా చూసి గ్రహించిన సమాచారాన్ని అనుసరించి చేతులు స్పందించి పనిచేసే సమన్వయ సామర్థ్యాన్ని 'కన్ను-చేయి సమన్వయం' (Eye-hand co-ordination) అంటారు. రాత, బొమ్మలు గీయడం, వస్తువులను పట్టుకోవడంలో ఇది కీలకమైనది."}, {"id": 228, "sec": "Special Education", "passage": "", "q_en": "Expand AAC", "q_te": "AAC ని విస్తరించగా", "opts": [{"en": "All Alternative Communication", "te": "ఆల్ ఆల్టర్నేటివ్ కమ్యూనికేషన్", "raw": "All Alternative Communication / ఆల్ ఆల్టర్నేటివ్ కమ్యూనికేషన్"}, {"en": "Alternate Avoidance Communication", "te": "ఆల్టర్నేట్ అవాయిడెన్స్ కమ్యూనికేషన్", "raw": "Alternate Avoidance Communication / ఆల్టర్నేట్ అవాయిడెన్స్ కమ్యూనికేషన్"}, {"en": "Augmentative and Alternative Communication", "te": "ఆగ్మెంటివ్ అండ్ ఆల్టర్నేటివ్ కమ్యూనికేషన్ (Augmentative and Alternative Communication)", "raw": "Augmentative and Alternative Communication / ఆగ్మెంటివ్ అండ్ ఆల్టర్నేటివ్ కమ్యూనికేషన్ (Augmentative and Alternative Communication)"}, {"en": "Aural Alternative Communication", "te": "ఆరల్ ఆల్టర్నేటివ్ కమ్యూనికేషన్", "raw": "Aural Alternative Communication / ఆరల్ ఆల్టర్నేటివ్ కమ్యూనికేషన్"}], "ans": 3, "exp_en": "AAC stands for Augmentative and Alternative Communication, referring to communication methods, tools, and systems (both unaided like gestures and aided like communication boards/speech generating devices) used to supplement or replace spoken language.", "exp_te": "AAC పూర్తి రూపం 'Augmentative and Alternative Communication' (అనుబంధ మరియు ప్రత్యామ్నాయ భావప్రసారము). సాధారణంగా మాట్లాడలేని వారికి కమ్యూనికేషన్ బోర్డులు, చిత్రాలు లేదా ఎలక్ట్రానిక్ పరికరాల ద్వారా భావాలను వ్యక్తపరచడానికి AAC తోడ్పడుతుంది."}, {"id": 229, "sec": "Special Education", "passage": "", "q_en": "Which of the following is a Low-Tech assistive material useful for Children with Special Needs (CwSN) in a classroom?", "q_te": "తరగతి గదిలో ప్రత్యేక అవసరాలు గల పిల్లలకు (CwSN) ఉపయోగపడే తక్కువ సాంకేతికత గల (Low-Tech) సాధనం", "opts": [{"en": "GPS devices", "te": "GPS పరికరాలు", "raw": "GPS devices / GPS పరికరాలు"}, {"en": "Multimedia Presentation", "te": "మల్టీమీడియా ప్రజెంటేషన్", "raw": "Multimedia Presentation / మల్టీమీడియా ప్రజెంటేషన్"}, {"en": "Geo boards, Peg boards", "te": "జియో బోర్డులు, పెగ్ బోర్డులు (Geo boards, Peg boards)", "raw": "Geo boards, Peg boards / జియో బోర్డులు, పెగ్ బోర్డులు (Geo boards, Peg boards)"}, {"en": "e-Books", "te": "ఈ-బుక్స్ (e-Books)", "raw": "e-Books / ఈ-బుక్స్ (e-Books)"}], "ans": 3, "exp_en": "Low-tech assistive devices are non-electronic, simple physical tools that require no battery or electricity. Geo boards and Peg boards are classic low-tech tactile materials used to teach geometry, spatial concepts, and fine motor skills.", "exp_te": "ఎలక్ట్రానిక్ లేదా విద్యుత్ అవసరం లేని సాధారణ భౌతిక ఉపకరణాలను 'తక్కువ సాంకేతికత సాధనాలు' (Low-Tech materials) అంటారు. జియో బోర్డులు, పెగ్ బోర్డులు స్పర్శ ద్వారా ఆకారాలు, గణిత భావనలను నేర్చుకోవడానికి ఉపయోగపడే ఉత్తమ లో-టెక్ సాధనాలు."}, {"id": 230, "sec": "Special Education", "passage": "", "q_en": "During the classroom teaching process, what percentage of knowledge is perceived through the Visual Sense in normal sensory reception?", "q_te": "బోధనా ప్రక్రియలో సాధారణంగా చూడడం (దృష్టి జ్ఞానేంద్రియం) ద్వారా పొందే జ్ఞానం యొక్క శాతం ఎంత", "opts": [{"en": "23%", "te": "23%", "raw": "23%"}, {"en": "43%", "te": "43%", "raw": "43%"}, {"en": "63%", "te": "63%", "raw": "63%"}, {"en": "83%", "te": "83% (సుమారు 83 శాతం)", "raw": "83% / 83% (సుమారు 83 శాతం)"}], "ans": 4, "exp_en": "Research in sensory learning shows that humans acquire approximately 83% of external information through sight, 11% through hearing, 3.5% through smell, 1.5% through touch, and 1% through taste.", "exp_te": "మనోవిజ్ఞాన శాస్త్ర పరిశోధనల ప్రకారం మానవుడు తన పంచేంద్రియాల ద్వారా పొందే జ్ఞానంలో దాదాపు 83% కేవలం కంటి చూపు (దృష్టి) ద్వారానే గ్రహిస్తాడు."}, {"id": 231, "sec": "Special Education", "passage": "", "q_en": "Standing and walking assistive devices come under which category of assistive aids?", "q_te": "నిలబడటానికి మరియు నడవడానికి సహాయపడే ఉపకరణాలు ఈ వర్గానికి చెందుతాయి", "opts": [{"en": "Teaching and learning aids", "te": "బోధనాభ్యసన సామగ్రి (Teaching & learning aids)", "raw": "Teaching and learning aids / బోధనాభ్యసన సామగ్రి (Teaching & learning aids)"}, {"en": "Mobility and transportation aids", "te": "చలనశీలత మరియు రవాణా ఉపకరణాలు (Mobility and transportation aids)", "raw": "Mobility and transportation aids / చలనశీలత మరియు రవాణా ఉపకరణాలు (Mobility and transportation aids)"}, {"en": "Computer access aids", "te": "కంప్యూటర్ యాక్సెస్ సాధనాలు", "raw": "Computer access aids / కంప్యూటర్ యాక్సెస్ సాధనాలు"}, {"en": "Communication aids", "te": "భావప్రసార ఉపకరణాలు (Communication aids)", "raw": "Communication aids / భావప్రసార ఉపకరణాలు (Communication aids)"}], "ans": 2, "exp_en": "Standing frames, crutches, parallel bars, walkers, and wheelchairs are classified under Mobility and transportation aids (చలనశీలత ఉపకరణాలు) as they assist individuals with physical impairments in moving, standing, and ambulation.", "exp_te": "క్రచెస్ (వాకింగ్ స్టిక్స్), వాకర్స్, వీల్ చైర్స్, స్టాండింగ్ ఫ్రేమ్స్ వంటి నిలబడటానికి మరియు నడవడానికి తోడ్పడే పరికరాలన్నీ 'చలనశీలత మరియు రవాణా ఉపకరణాలు' (Mobility and transportation aids) కిందకు వస్తాయి."}, {"id": 232, "sec": "Special Education", "passage": "", "q_en": "A specialized compact assistive chord keyboard that allows typing all characters and numbers using only 6 keys is the", "q_te": "కేవలం '6' కీల కలయికతో అన్ని అక్షరాలను మరియు సంఖ్యలను టైప్ చేయడానికి వీలు కల్పించే సహాయక కీబోర్డ్", "opts": [{"en": "Microwriter", "te": "మైక్రోరైటర్ (Microwriter / కార్డ్ కీబోర్డ్)", "raw": "Microwriter / మైక్రోరైటర్ (Microwriter / కార్డ్ కీబోర్డ్)"}, {"en": "Macrowriter", "te": "మ్యాక్రోరైటర్", "raw": "Macrowriter / మ్యాక్రోరైటర్"}, {"en": "Alphavision", "te": "ఆల్ఫా విజన్", "raw": "Alphavision / ఆల్ఫా విజన్"}, {"en": "Touch Screen", "te": "టచ్ స్క్రీన్", "raw": "Touch Screen / టచ్ స్క్రీన్"}], "ans": 1, "exp_en": "The Microwriter is a portable 6-key chording communication device allowing fast one-handed text entry for users with visual and motor impairments.", "exp_te": "మైక్రోరైటర్ (Microwriter) అనేది కేవలం 6 మీటలను వివిధ కలయికలలో నొక్కడం ద్వారా అన్ని అక్షరాలను కంప్యూటర్‌లో సులభంగా టైప్ చేసే పోర్టబుల్ సాధనం."}, {"id": 233, "sec": "Special Education", "passage": "", "q_en": "Secondary prevention in special health and education focuses on", "q_te": "వైకల్యాల నివారణలో 'ద్వితీయ నివారణ' (Secondary Prevention) దేనిని సూచిస్తుంది", "opts": [{"en": "Labelling individuals with stigmas", "te": "లేబులింగ్ వేయడం", "raw": "Labelling individuals with stigmas / లేబులింగ్ వేయడం"}, {"en": "Early identification, screening, and prompt intervention", "te": "ముందస్తు గుర్తింపు మరియు తక్షణ జోక్యం / చికిత్స (Early Identification & Intervention)", "raw": "Early identification, screening, and prompt intervention / ముందస్తు గుర్తింపు మరియు తక్షణ జోక్యం / చికిత్స (Early Identification & Intervention)"}, {"en": "Lifelong custodial institutionalization", "te": "సంరక్షణ కేంద్రాలలో ఉంచడం", "raw": "Lifelong custodial institutionalization / సంరక్షణ కేంద్రాలలో ఉంచడం"}, {"en": "Marriage restrictions alone", "te": "వివాహ నియంత్రణ", "raw": "Marriage restrictions alone / వివాహ నియంత్రణ"}], "ans": 2, "exp_en": "Secondary prevention aims to detect health conditions, impairment, or developmental delays early (screening, medication, intervention) to prevent them from becoming lifelong permanent disabilities.", "exp_te": "సమస్య ప్రారంభంలోనే స్క్రీనింగ్ ద్వారా గుర్తించి, వెంటనే వైద్యం మరియు నివారణ చర్యలు చేపట్టడాన్ని (Early Identification and Intervention) 'ద్వితీయ నివారణ' అంటారు."}, {"id": 234, "sec": "Special Education", "passage": "", "q_en": "The tactile communication method where a deaf-blind person places their thumb on the speaker's lips and fingers on the cheek/throat to feel speech vibrations is", "q_te": "బధిర-అంధత్వం (Deaf-blind) ఉన్న వ్యక్తులు మాట్లాడేవారి పెదవులు, గొంతు కంపనాలను చేతితో తాకి మాటలను గ్రహించే స్పర్శ పద్ధతి", "opts": [{"en": "Chaining method", "te": "చైనింగ్ పద్ధతి", "raw": "Chaining method / చైనింగ్ పద్ధతి"}, {"en": "Auditory verbal training alone", "te": "శ్రవణ శిక్షణ", "raw": "Auditory verbal training alone / శ్రవణ శిక్షణ"}, {"en": "Tadoma Method (Tactile Speechreading)", "te": "తడోమా పద్ధతి (Tadoma Method / స్పర్శ వాక్ గ్రహణ పద్ధతి)", "raw": "Tadoma Method (Tactile Speechreading) / తడోమా పద్ధతి (Tadoma Method / స్పర్శ వాక్ గ్రహణ పద్ధతి)"}, {"en": "Braille slate typing alone", "te": "బ్రెయిలీ రాత", "raw": "Braille slate typing alone / బ్రెయిలీ రాత"}], "ans": 3, "exp_en": "The Tadoma Method (tactile lipreading) allows deaf-blind persons to feel vocal cord vibrations, jaw movements, and air stream changes with their fingers to decode speech.", "exp_te": "తడోమా పద్ధతి (Tadoma Method) లో బధిర-అంధులు తమ బొటనవేలును ఎదుటివారి పెదవులపై, మిగిలిన వేళ్ళను దవడ, గొంతుపై ఉంచి ధ్వని కంపనాల ద్వారా మాటలను అర్థం చేసుకుంటారు."}, {"id": 235, "sec": "Special Education", "passage": "", "q_en": "Which of the following is classified as a Chronic Neurological Condition under the RPwD Act 2016?", "q_te": "RPwD చట్టం 2016 ప్రకారం దీర్ఘకాలిక నాడీ సంబంధిత రుగ్మతగా (Chronic Neurological Condition) గుర్తించబడినది ఏది", "opts": [{"en": "Parkinson's Disease", "te": "పార్కిన్సన్స్ వ్యాధి (Parkinson's Disease)", "raw": "Parkinson's Disease / పార్కిన్సన్స్ వ్యాధి (Parkinson's Disease)"}, {"en": "Thalassemia", "te": "తలసేమియా (రక్త రుగ్మత)", "raw": "Thalassemia / తలసేమియా (రక్త రుగ్మత)"}, {"en": "Hemophilia", "te": "హీమోఫీలియా (రక్త రుగ్మత)", "raw": "Hemophilia / హీమోఫీలియా (రక్త రుగ్మత)"}, {"en": "Acid Attack Victimhood", "te": "యాసిడ్ దాడి బాధితులు", "raw": "Acid Attack Victimhood / యాసిడ్ దాడి బాధితులు"}], "ans": 1, "exp_en": "Under RPwD Act 2016, Parkinson's Disease and Multiple Sclerosis are explicitly classified under Chronic Neurological Conditions. Thalassemia is a blood disorder.", "exp_te": "పార్కిన్సన్స్ వ్యాధి (Parkinson's Disease) మెదడులోని డోపమైన్ లోపం వల్ల శరీర వణుకును కలిగించే 'దీర్ఘకాలిక నాడీ సంబంధిత రుగ్మత' (Chronic Neurological Condition)."}, {"id": 236, "sec": "Special Education", "passage": "", "q_en": "Expand UDL in modern inclusive pedagogy", "q_te": "ఆధునిక సమ్మిళిత విద్యా విధానంలో UDL యొక్క పూర్తి రూపం", "opts": [{"en": "Universal Design for Lacking", "te": "యూనివర్సల్ డిజైన్ ఫర్ లాకింగ్", "raw": "Universal Design for Lacking / యూనివర్సల్ డిజైన్ ఫర్ లాకింగ్"}, {"en": "Unique Design for Learning", "te": "యూనిక్ డిజైన్ ఫర్ లెర్నింగ్", "raw": "Unique Design for Learning / యూనిక్ డిజైన్ ఫర్ లెర్నింగ్"}, {"en": "Universal Design for Learning", "te": "యూనివర్సల్ డిజైన్ ఫర్ లెర్నింగ్ (Universal Design for Learning - UDL)", "raw": "Universal Design for Learning / యూనివర్సల్ డిజైన్ ఫర్ లెర్నింగ్ (Universal Design for Learning - UDL)"}, {"en": "Understand Development for Learning", "te": "అండర్‌స్టాండ్ డెవలప్‌మెంట్", "raw": "Understand Development for Learning / అండర్‌స్టాండ్ డెవలప్‌మెంట్"}], "ans": 3, "exp_en": "Universal Design for Learning (UDL) is an instructional framework providing multiple means of engagement, representation, and action/expression to optimize learning for all.", "exp_te": "UDL అనగా 'Universal Design for Learning'. తరగతిలోని అందరు పిల్లల అభ్యసన శైలులకు సరిపోయేలా పాఠ్యాంశాలను రూపొందించే సార్వత్రిక విద్యా నమూనా."}, {"id": 237, "sec": "Special Education", "passage": "", "q_en": "A microcomputer-assisted input device facilitating typing for children with fine-motor and visual disabilities is the", "q_te": "పాక్షిక దృష్టి లోపం మరియు చలన లోపం గల పిల్లలకు కంప్యూటర్‌లో టైపింగ్ చేయడానికి తోడ్పడే పరికరం", "opts": [{"en": "Touch screen terminal", "te": "టచ్ స్క్రీన్ టెర్మినల్", "raw": "Touch screen terminal / టచ్ స్క్రీన్ టెర్మినల్"}, {"en": "Microwriter", "te": "మైక్రోరైటర్ (Microwriter)", "raw": "Microwriter / మైక్రోరైటర్ (Microwriter)"}, {"en": "Typewriter", "te": "టైప్‌రైటర్", "raw": "Typewriter / టైప్‌రైటర్"}, {"en": "Laser cane alone", "te": "లేజర్ కేన్", "raw": "Laser cane alone / లేజర్ కేన్"}], "ans": 2, "exp_en": "The Microwriter allows users with limited motor control or low vision to produce typed text smoothly by chording combinations on five finger-keys and a thumb-key.", "exp_te": "చేతి కండరాల ఇబ్బంది మరియు దృష్టి లోపం ఉన్నవారు ఒకే చేత్తో సులభంగా కంప్యూటర్‌లో అక్షరాలు టైప్ చేయడానికి 'మైక్రోరైటర్' (Microwriter) ఉపయోగపడుతుంది."}, {"id": 238, "sec": "Special Education", "passage": "", "q_en": "Electronic ultrasonic travel aids like the 'Sonic Guide' used by visually impaired persons for mobility must always be used in combination with a", "q_te": "అల్ట్రాసోనిక్ ధ్వనులతో అడ్డంకులను గుర్తించే 'సోనిక్ గైడ్' (Sonic Guide) ను అంధులు దేనితో కలిపి మాత్రమే ఉపయోగించాలి", "opts": [{"en": "Braille book", "te": "బ్రెయిలీ పుస్తకం", "raw": "Braille book / బ్రెయిలీ పుస్తకం"}, {"en": "Hockey stick", "te": "హాకీ స్టిక్", "raw": "Hockey stick / హాకీ స్టిక్"}, {"en": "Long Cane (White Cane) or Guide Dog", "te": "లాంగ్ కేన్ (వైట్ కేన్ / Long Cane) లేదా గైడ్ డాగ్ తో కలిపి", "raw": "Long Cane (White Cane) or Guide Dog / లాంగ్ కేన్ (వైట్ కేన్ / Long Cane) లేదా గైడ్ డాగ్ తో కలిపి"}, {"en": "Stylus", "te": "స్టైలస్", "raw": "Stylus / స్టైలస్"}], "ans": 3, "exp_en": "Electronic Travel Aids (ETAs) like Sonicguide detect head-level obstacles using ultrasound, but do NOT detect ground drop-offs (steps, curbs); hence, they MUST be paired with a traditional Long Cane.", "exp_te": "సోనిక్ గైడ్ పైనున్న అడ్డంకులను శబ్ద సంకేతాలతో హెచ్చరిస్తుంది కానీ నేలపై ఉండే గుంతలను గుర్తించలేదు; అందువల్ల దీనిని తప్పనిసరిగా 'లాంగ్ కేన్' (వైట్ కేన్) తో కలిపే వాడాలి."}, {"id": 239, "sec": "Special Education", "passage": "", "q_en": "If children with multiple disabilities are completely denied opportunities to participate in family and school routines, it leads to severe", "q_te": "బహుళ వైకల్యం గల పిల్లలను కుటుంబ మరియు పాఠశాల కృత్యాలలో పాల్గొననివ్వకుండా వేరుచేస్తే అది దేనికి దారితీస్తుంది", "opts": [{"en": "Physical growth acceleration", "te": "శారీరక పెరుగుదల", "raw": "Physical growth acceleration / శారీరక పెరుగుదల"}, {"en": "Severe Psycho-Social problems, depression, and regression", "te": "తీవ్రమైన మనో-సామాజిక సమస్యలు, నిస్పృహ మరియు ప్రవర్తనా క్షీణత (Psycho-social problems)", "raw": "Severe Psycho-Social problems, depression, and regression / తీవ్రమైన మనో-సామాజిక సమస్యలు, నిస్పృహ మరియు ప్రవర్తనా క్షీణత (Psycho-social problems)"}, {"en": "Hereditary problems", "te": "వంశపారంపర్య సమస్యలు", "raw": "Hereditary problems / వంశపారంపర్య సమస్యలు"}, {"en": "Financial prosperity", "te": "ఆర్థిక లాభం", "raw": "Financial prosperity / ఆర్థిక లాభం"}], "ans": 2, "exp_en": "Social deprivation, confinement, and exclusion trigger profound psycho-social trauma, depression, secondary behavioral disturbances, and functional developmental regression.", "exp_te": "దివ్యాంగ పిల్లలను ఇతరులతో కలవనివ్వకుండా ఒంటరిగా ఉంచడం వారిలో తీవ్ర నిరాశ, ఆందోళన మరియు 'మనో-సామాజిక సమస్యల'కు (Psycho-social problems) కారణమవుతుంది."}, {"id": 240, "sec": "Special Education", "passage": "", "q_en": "A specialized telecommunication device that enables face-to-face as well as telephone interaction between a sighted person and a deaf-blind person is the", "q_te": "సాధారణ దృష్టి ఉన్న వ్యక్తి మరియు బధిర-అంధత్వం గల వ్యక్తి మధ్య ముఖాముఖి సంభాషణకు తోడ్పడే బ్రెయిలీ పరికరం", "opts": [{"en": "Telebraille", "te": "టెలిబ్రెయిలీ (TeleBraille)", "raw": "Telebraille / టెలిబ్రెయిలీ (TeleBraille)"}, {"en": "Visual ring indicator", "te": "విజువల్ రింగ్", "raw": "Visual ring indicator / విజువల్ రింగ్"}, {"en": "Cordless bell", "te": "కార్డ్‌లెస్ బెల్", "raw": "Cordless bell / కార్డ్‌లెస్ బెల్"}, {"en": "Tele-pan ring", "te": "టెలిపాన్ రింగ్", "raw": "Tele-pan ring / టెలిపాన్ రింగ్"}], "ans": 1, "exp_en": "The TeleBraille device couples a standard QWERTY keyboard with an electronic 20-cell refreshable Braille display, allowing face-to-face and TTY phone conversations for deaf-blind users.", "exp_te": "టెలిబ్రెయిలీ (Telebraille) లో ఒక సాధారణ కీబోర్డ్ మరియు ఉబ్బెత్తు బ్రెయిలీ డిస్‌ప్లే ఉంటాయి. సాధారణ వ్యక్తి టైప్ చేసే మాటలను బధిర-అంధుడు స్పర్శ ద్వారా చదవగలడు."}, {"id": 241, "sec": "Special Education", "passage": "", "q_en": "The tough, protective white outer layer of the eyeball is called the", "q_te": "కంటి గుడ్డు ముందు భాగంలో కనిపించే తెల్లటి రక్షక పొరను ఏమంటారు", "opts": [{"en": "Rods", "te": "రాడ్స్", "raw": "Rods / రాడ్స్"}, {"en": "Eyeball fluid", "te": "కంటి ద్రవం", "raw": "Eyeball fluid / కంటి ద్రవం"}, {"en": "Sclera", "te": "స్క్లెరా (దృఢస్తరం / Sclera - తెల్లటి భాగం)", "raw": "Sclera / స్క్లెరా (దృఢస్తరం / Sclera - తెల్లటి భాగం)"}, {"en": "Retina", "te": "రెటీనా (నేత్రపటలం)", "raw": "Retina / రెటీనా (నేత్రపటలం)"}], "ans": 3, "exp_en": "The Sclera (commonly called the 'white of the eye') is the dense fibrous opaque outer protective tunic covering the posterior 5/6th of the eyeball.", "exp_te": "కంటిలోని కనుగుడ్డును కప్పి ఉంచే తెల్లటి దృఢమైన రక్షక పొరను 'స్క్లెరా' (Sclera - దృఢస్తరం) అంటారు."}, {"id": 242, "sec": "Special Education", "passage": "", "q_en": "The adjustable central circular aperture in the center of the Iris through which light enters the eye is the", "q_te": "కంటిలోని ఐరిస్ (కనుపాప) మధ్యలో కాంతి లోపలికి ప్రవేశించడానికి ఉండే రంధ్రం", "opts": [{"en": "Tear duct", "te": "కన్నీటి గ్రంథి", "raw": "Tear duct / కన్నీటి గ్రంథి"}, {"en": "Pupil", "te": "కనుగుడ్డు రంధ్రం / తారక (Pupil / కంటిపాప రంధ్రం)", "raw": "Pupil / కనుగుడ్డు రంధ్రం / తారక (Pupil / కంటిపాప రంధ్రం)"}, {"en": "Choroid", "te": "రక్తపటలం (Choroid)", "raw": "Choroid / రక్తపటలం (Choroid)"}, {"en": "Cornea tumor", "te": "కార్నియా", "raw": "Cornea tumor / కార్నియా"}], "ans": 2, "exp_en": "The Pupil is the black central opening of the Iris that constricts in bright light and dilates in dim light to regulate the illumination reaching the retina.", "exp_te": "ఐరిస్ మధ్యలో నల్లగా కనిపించే చిన్న రంధ్రం గుండా కాంతి కంటి లోపలి లెన్స్‌పైకి ప్రవేశిస్తుంది. దీనిని 'కంటిపాప / తారక' (Pupil) అంటారు."}, {"id": 243, "sec": "Special Education", "passage": "", "q_en": "An area of partial alteration or complete loss in the visual field surrounded by normal vision is called a", "q_te": "కంటి దృష్టి క్షేత్రంలో అస్పష్టంగా లేదా పూర్తిగా కనిపించకుండా పోయే అంధ బిందువు వంటి భాగాన్ని ఏమంటారు", "opts": [{"en": "Stroma", "te": "స్ట్రోమా", "raw": "Stroma / స్ట్రోమా"}, {"en": "Sclera", "te": "స్క్లెరా", "raw": "Sclera / స్క్లెరా"}, {"en": "Tunnel vision", "te": "టన్నెల్ విజన్", "raw": "Tunnel vision / టన్నెల్ విజన్"}, {"en": "Scotoma (Blind Spot in visual field)", "te": "స్కోటోమా (Scotoma / దృష్టి క్షేత్రంలోని అంధ ప్రాంతం)", "raw": "Scotoma (Blind Spot in visual field) / స్కోటోమా (Scotoma / దృష్టి క్షేత్రంలోని అంధ ప్రాంతం)"}], "ans": 4, "exp_en": "A Scotoma is a localized area of depressed or absent vision within the visual field surrounded by an area of normal or less depressed vision.", "exp_te": "దృష్టి క్షేత్రంలో అక్కడక్కడా ఏమీ కనిపించకుండా ఏర్పడే చీకటి మచ్చ లేదా అంధ ప్రాంతాన్ని వైద్య పరిభాషలో 'స్కోటోమా' (Scotoma) అంటారు."}, {"id": 244, "sec": "Special Education", "passage": "", "q_en": "Visual impairment caused by progressive loss of elasticity and hardening of the eye's crystalline lens due to aging is", "q_te": "వయస్సు పెరగడం వల్ల కంటి లెన్స్ సాగే గుణం తగ్గి, దగ్గరి వస్తువులు సరిగ్గా కనిపించకపోవడాన్ని ఏమంటారు", "opts": [{"en": "Presbyopia (Old-age sight)", "te": "చత్వారం (ప్రెస్బియోపియా / Presbyopia)", "raw": "Presbyopia (Old-age sight) / చత్వారం (ప్రెస్బియోపియా / Presbyopia)"}, {"en": "Hyperopia", "te": "దూరదృష్టి (హైపరోపియా)", "raw": "Hyperopia / దూరదృష్టి (హైపరోపియా)"}, {"en": "Myopia", "te": "హ్రస్వదృష్టి (మయోపియా)", "raw": "Myopia / హ్రస్వదృష్టి (మయోపియా)"}, {"en": "Fusion defect", "te": "కంటి కలయిక లోపం", "raw": "Fusion defect / కంటి కలయిక లోపం"}], "ans": 1, "exp_en": "Presbyopia is the age-related gradual loss of the eye's ability to focus actively on nearby objects, resulting from progressive hardening of the crystalline lens and ciliary muscles.", "exp_te": "వృద్ధాప్యంలో (సాధారణంగా 40 ఏళ్ళు పైబడిన తర్వాత) కంటి కటకం బిరుసెక్కి దగ్గరి అక్షరాలు చదవలేకపోవడాన్ని 'చత్వారం' (Presbyopia) అంటారు."}, {"id": 245, "sec": "Special Education", "passage": "", "q_en": "An infectious chronic eye disease caused by the bacterium Chlamydia trachomatis causing blindness is", "q_te": "'క్లామిడియా ట్రాకోమాటిస్' (Chlamydia trachomatis) అనే సూక్ష్మజీవి వల్ల కంటికి సోకే అంటువ్యాధి", "opts": [{"en": "Cataract", "te": "కంటి శుక్లాలు (కాటరాక్ట్)", "raw": "Cataract / కంటి శుక్లాలు (కాటరాక్ట్)"}, {"en": "Trachoma", "te": "ట్రాకోమా (Trachoma / కండ్లకలక వంటి వ్యాధి)", "raw": "Trachoma / ట్రాకోమా (Trachoma / కండ్లకలక వంటి వ్యాధి)"}, {"en": "Corneal Ulcer", "te": "కార్నియల్ అల్సర్", "raw": "Corneal Ulcer / కార్నియల్ అల్సర్"}, {"en": "Glaucoma", "te": "గ్లాకోమా", "raw": "Glaucoma / గ్లాకోమా"}], "ans": 2, "exp_en": "Trachoma is an infectious disease caused by bacterium Chlamydia trachomatis leading to conjunctival scarring, trichiasis (inward turned eyelashes), and irreversible corneal opacity.", "exp_te": "ట్రాకోమా (Trachoma) అనేది బ్యాక్టీరియా వల్ల కనురెప్పల లోపలి భాగానికి సోకే తీవ్రమైన అంటువ్యాధి, చికిత్స చేయకపోతే కనుపాప దెబ్బతిని అంధత్వం వస్తుంది."}, {"id": 246, "sec": "Special Education", "passage": "", "q_en": "Standard normal visual acuity on the Snellen eye chart is measured as", "q_te": "స్నెల్లెన్ చార్ట్ ప్రకారం సాధారణ మానవుని ప్రామాణిక దృష్టి తీక్షణత (Normal Visual Acuity)", "opts": [{"en": "20/20 (or 6/6 meters)", "te": "20/20 (లేదా 6/6 మీటర్లు)", "raw": "20/20 (or 6/6 meters) / 20/20 (లేదా 6/6 మీటర్లు)"}, {"en": "20/100", "te": "20/100", "raw": "20/100"}, {"en": "20/200", "te": "20/200", "raw": "20/200"}, {"en": "20/70", "te": "20/70", "raw": "20/70"}], "ans": 1, "exp_en": "20/20 vision (expressed as 6/6 in metric) represents standard visual acuity where an individual can identify standard letters at 20 feet that a normal eye sees at 20 feet.", "exp_te": "కంటి సాధారణ దృష్టిని స్నెల్లెన్ చార్ట్ ప్రకారం 20/20 (అడుగులలో) లేదా 6/6 (మీటర్లలో) అని పిలుస్తారు."}, {"id": 247, "sec": "Special Education", "passage": "", "q_en": "A genetic condition characterized by severe lack of melanin pigment in the Iris, Retina, hair, and skin is called", "q_te": "కంటిలోని ఐరిస్ మరియు రెటీనాలో మెలనిన్ వర్ణద్రవ్యం లోపించి దృష్టి సమస్యలు కలిగే జన్యుపరమైన పరిస్థితి", "opts": [{"en": "Night Blindness", "te": "రేచీకటి", "raw": "Night Blindness / రేచీకటి"}, {"en": "Glaucoma", "te": "గ్లాకోమా", "raw": "Glaucoma / గ్లాకోమా"}, {"en": "Low Vision alone", "te": "పాక్షిక దృష్టి", "raw": "Low Vision alone / పాక్షిక దృష్టి"}, {"en": "Albinism", "te": "ఆల్బినిజం (Albinism)", "raw": "Albinism / ఆల్బినిజం (Albinism)"}], "ans": 4, "exp_en": "Ocular or Oculocutaneous Albinism causes translucent irises, foveal hypoplasia, extreme photophobia (light sensitivity), and congenital nystagmus.", "exp_te": "ఆల్బినిజం (Albinism) లో మెలనిన్ లేకపోవడం వల్ల కనుగుడ్డులోని ఐరిస్ మరియు రెటీనా లేత గులాబీ రంగులో ఉండి, కాంతిని తట్టుకోలేక దృష్టి లోపం ఏర్పడుతుంది."}, {"id": 248, "sec": "Special Education", "passage": "", "q_en": "A pseudo-isochromatic diagnostic color vision plate test widely used to detect red-green and yellow-blue color blindness in children and adults is the", "q_te": "పిల్లలు లేదా నిరక్షరాస్యులలో ఎరుపు-పసుపు మరియు ఎరుపు-ఆకుపచ్చ వర్ణాంధత్వాన్ని (Color Blindness) గుర్తించడానికి ఉపయోగించే పరీక్ష", "opts": [{"en": "Maddox Rod Test", "te": "మ్యాడాక్స్ రాడ్ పరీక్ష", "raw": "Maddox Rod Test / మ్యాడాక్స్ రాడ్ పరీక్ష"}, {"en": "Ishihara Test of Color Blindness", "te": "ఇషిహారా వర్ణాంధత్వ పరీక్ష", "raw": "Ishihara Test of Color Blindness / ఇషిహారా వర్ణాంధత్వ పరీక్ష"}, {"en": "Hardy-Rand-Rittler (HRR) Test", "te": "హార్డీ-రాండ్-రిట్లర్ పరీక్ష (Hardy-Rand-Rittler / HRR Test)", "raw": "Hardy-Rand-Rittler (HRR) Test / హార్డీ-రాండ్-రిట్లర్ పరీక్ష (Hardy-Rand-Rittler / HRR Test)"}, {"en": "Allied Muscle Balance Test", "te": "కంటి కండరాల సమతుల్య పరీక్ష", "raw": "Allied Muscle Balance Test / కంటి కండరాల సమతుల్య పరీక్ష"}], "ans": 3, "exp_en": "The Hardy-Rand-Rittler (HRR) Pseudoisochromatic Plates test uses simple geometric shapes (circle, triangle, cross) making it ideal for children and illiterates to diagnose both red-green and blue-yellow defects.", "exp_te": "HRR (Hardy-Rand-Rittler) పరీక్షలో చదవలేని పిల్లలకు కూడా సులభంగా అర్థమయ్యే త్రిభుజం, వృత్తం వంటి బొమ్మలతో ఎరుపు-ఆకుపచ్చ, నీలం-పసుపు రంగుల లోపాలను గుర్తిస్తారు."}, {"id": 249, "sec": "Special Education", "passage": "", "q_en": "The universally standardized eye test chart containing rows of letters in decreasing sizes used to measure distance visual acuity is the", "q_te": "దూర దృష్టి సామర్థ్యాన్ని కొలవడానికి పెద్ద అక్షరాల నుండి చిన్న అక్షరాల వరకు క్రమంగా ఉండే ప్రామాణిక కంటి చార్ట్", "opts": [{"en": "Bjerrum's Screen", "te": "బెర్జమ్ స్క్రీన్", "raw": "Bjerrum's Screen / బెర్జమ్ స్క్రీన్"}, {"en": "Snellen Chart", "te": "స్నెల్లెన్ చార్ట్ (Snellen Chart)", "raw": "Snellen Chart / స్నెల్లెన్ చార్ట్ (Snellen Chart)"}, {"en": "Swift Chart", "te": "స్విఫ్ట్ చార్ట్", "raw": "Swift Chart / స్విఫ్ట్ చార్ట్"}, {"en": "Helen Chart", "te": "హెలెన్ చార్ట్", "raw": "Helen Chart / హెలెన్ చార్ట్"}], "ans": 2, "exp_en": "Created by Dr. Herman Snellen in 1862, the Snellen Chart is the universal clinical gold standard for measuring distant visual acuity.", "exp_te": "కంటి డాక్టర్లు దృష్టి లోపాన్ని కొలవడానికి తరచుగా ఉపయోగించే ప్రామాణిక అక్షరాల చార్ట్‌ను 'స్నెల్లెన్ చార్ట్' (Snellen Chart) అంటారు."}, {"id": 250, "sec": "Special Education", "passage": "", "q_en": "Comprehensive educational planning in an inclusive school must incorporate both", "q_te": "సమ్మిళిత పాఠశాలలో సమగ్ర విద్యా ప్రణాళిక అనగా దేనిని కలిగి ఉండటం", "opts": [{"en": "Teaching classroom lessons only", "te": "కేవలం తరగతి పాఠాలు మాత్రమే చెప్పడం", "raw": "Teaching classroom lessons only / కేవలం తరగతి పాఠాలు మాత్రమే చెప్పడం"}, {"en": "Conducting outdoor sports only", "te": "కేవలం ఆటలు మాత్రమే ఆడించడం", "raw": "Conducting outdoor sports only / కేవలం ఆటలు మాత్రమే ఆడించడం"}, {"en": "Cultural performances only", "te": "కేవలం సాంస్కృతిక కార్యక్రమాలు", "raw": "Cultural performances only / కేవలం సాంస్కృతిక కార్యక్రమాలు"}, {"en": "Curricular and Co-curricular activities holistically integrated", "te": "పాఠ్యాంశాలు మరియు సహ-పాఠ్య కృత్యాల సమగ్ర కలయిక (Curricular & Co-curricular)", "raw": "Curricular and Co-curricular activities holistically integrated / పాఠ్యాంశాలు మరియు సహ-పాఠ్య కృత్యాల సమగ్ర కలయిక (Curricular & Co-curricular)"}], "ans": 4, "exp_en": "Holistic special education requires a balanced synergy of core scholastic academic curricula and co-curricular domains (arts, sports, orientation, daily living skills).", "exp_te": "సంపూర్ణ విద్యా ప్రణాళికలో కేవలం పుస్తక పాఠాలే కాకుండా విద్యార్థి సమగ్ర వికాసానికి అవసరమైన ఆటలు, కళలు, మరియు సహ-పాఠ్యాంశ కృత్యాలు (Co-curricular activities) రెండూ ఉండాలి."}, {"id": 251, "sec": "Special Education", "passage": "", "q_en": "At the secondary school stage, the primary orientation and mobility skill empowering visually impaired students to travel independently is", "q_te": "మాధ్యమిక దశలో దృష్టి లోపం గల విద్యార్థులు స్వతంత్రంగా ప్రయాణించడానికి వారిలో పెంపొందించాల్సిన చలన నైపుణ్యం", "opts": [{"en": "Training with crayons", "te": "క్రేయాన్స్‌తో నడవడం", "raw": "Training with crayons / క్రేయాన్స్‌తో నడవడం"}, {"en": "Training to use wheelchair", "te": "వీల్‌చైర్ వాడకం", "raw": "Training to use wheelchair / వీల్‌చైర్ వాడకం"}, {"en": "Training in independent travel using the White Long Cane", "te": "వైట్ కేన్ / లాంగ్ కేన్ ఉపయోగించి స్వతంత్రంగా నడవడం (Using White Cane)", "raw": "Training in independent travel using the White Long Cane / వైట్ కేన్ / లాంగ్ కేన్ ఉపయోగించి స్వతంత్రంగా నడవడం (Using White Cane)"}, {"en": "Walking with stones", "te": "రాళ్లను విసిరి నడవడం", "raw": "Walking with stones / రాళ్లను విసిరి నడవడం"}], "ans": 3, "exp_en": "Mastering the White Long Cane (using touch-and-slide or Hoover techniques) allows blind teenagers to independently detect obstacles, curbs, and drop-offs safely.", "exp_te": "అంధ విద్యార్థులు సమాజంలో స్వేచ్ఛగా, స్వతంత్రంగా ఎక్కడికైనా వెళ్ళడానికి 'వైట్ కేన్' (White Cane / చేతికర్ర) ఉపయోగించి నడిచే పద్ధతులను నేర్పించాలి."}, {"id": 252, "sec": "Special Education", "passage": "", "q_en": "Providing direct individual training in Braille reading-writing and sensory compensation to blind students at the primary stage is categorized as a", "q_te": "ప్రాథమిక దశలో దృష్టి లోపం గల విద్యార్థులకు బ్రెయిలీ మరియు స్పర్శ నైపుణ్యాలను నేరుగా నేర్పించడాన్ని ఏ రకమైన సేవ అంటారు", "opts": [{"en": "Direct Specialized Service (Direct Itinerant Instruction)", "te": "ప్రత్యక్ష ప్రత్యేక సేవ (Direct Service / ఉపాధ్యాయుని ముఖాముఖి బోధన)", "raw": "Direct Specialized Service (Direct Itinerant Instruction) / ప్రత్యక్ష ప్రత్యేక సేవ (Direct Service / ఉపాధ్యాయుని ముఖాముఖి బోధన)"}, {"en": "Indirect Service", "te": "పరోక్ష సేవ", "raw": "Indirect Service / పరోక్ష సేవ"}, {"en": "Social Service", "te": "సాంఘిక సేవ", "raw": "Social Service / సాంఘిక సేవ"}, {"en": "Economic Service", "te": "ఆర్థిక సేవ", "raw": "Economic Service / ఆర్థిక సేవ"}], "ans": 1, "exp_en": "Direct Services involve one-on-one specialized instruction provided directly by a qualified special education teacher to the child (teaching Braille, cane navigation).", "exp_te": "ప్రత్యేక ఉపాధ్యాయుడు స్వయంగా విద్యార్థి వద్ద కూర్చుని బ్రెయిలీ లిపి, అబాకస్ వంటి నైపుణ్యాలను నేరుగా నేర్పించడాన్ని 'ప్రత్యక్ష సేవ' (Direct Service) అంటారు."}, {"id": 253, "sec": "Special Education", "passage": "", "q_en": "Because children with Visual Impairment cannot learn incidentally by observing distant visual events, their learning must primarily be", "q_te": "దృష్టి లోపం గల పిల్లలు దూరం నుండి చూసి నేర్చుకోలేరు కాబట్టి, వారి అభ్యసనం ప్రధానంగా ఎలా ఉండాలి", "opts": [{"en": "Incidental natural sight learning", "te": "సహజసిద్ధమైన అనుకరణ అభ్యసనం", "raw": "Incidental natural sight learning / సహజసిద్ధమైన అనుకరణ అభ్యసనం"}, {"en": "Mediated Learning (Adult-guided sensory mediation)", "te": "మధ్యవర్తిత్వ ఆధారిత అభ్యసనం (Mediated Learning / ఉపాధ్యాయుని ప్రత్యక్ష వివరణ)", "raw": "Mediated Learning (Adult-guided sensory mediation) / మధ్యవర్తిత్వ ఆధారిత అభ్యసనం (Mediated Learning / ఉపాధ్యాయుని ప్రత్యక్ష వివరణ)"}, {"en": "Passive visual perception", "te": "దృశ్య జ్ఞానం", "raw": "Passive visual perception / దృశ్య జ్ఞానం"}, {"en": "Rote copying without understanding", "te": "బట్టీ పట్టడం", "raw": "Rote copying without understanding / బట్టీ పట్టడం"}], "ans": 2, "exp_en": "Mediated learning experience (Feuerstein's model) is crucial for the visually impaired, where an adult mediator deliberately guides the child's touch and auditory senses to explain abstract concepts.", "exp_te": "చూపు లేని పిల్లలు తాము స్వయంగా పరిసరాలను చూసి అర్థం చేసుకోలేరు; కాబట్టి ఉపాధ్యాయుడు మధ్యవర్తిగా ఉండి స్పర్శ ద్వారా వివరించే 'మీడియేటెడ్ లెర్నింగ్' (Mediated Learning) అవసరం."}, {"id": 254, "sec": "Special Education", "passage": "", "q_en": "The tactile educational aid specifically utilized to teach geometric concepts (angles, shapes, polygons) to children with visual impairment is", "q_te": "దృష్టి లోపం గల పిల్లలకు క్షేత్రగణిత భావనలను (రేఖాగణితం, కోణాలు, ఆకారాలు) నేర్పించడానికి ఉపయోగించే సాధనం", "opts": [{"en": "Plain Abacus", "te": "సాధారణ అబాకస్", "raw": "Plain Abacus / సాధారణ అబాకస్"}, {"en": "Napier strips", "te": "నేపియర్ పట్టీలు", "raw": "Napier strips / నేపియర్ పట్టీలు"}, {"en": "Embossed Raised-Line Geometrical Shapes and Geometry Kit", "te": "ఉబ్బెత్తు రేఖాగణిత ఆకారాలు మరియు జియోమెట్రీ కిట్ (Embossed Geometrical Shapes)", "raw": "Embossed Raised-Line Geometrical Shapes and Geometry Kit / ఉబ్బెత్తు రేఖాగణిత ఆకారాలు మరియు జియోమెట్రీ కిట్ (Embossed Geometrical Shapes)"}, {"en": "Ordinary Graph book", "te": "సాధారణ గ్రాఫ్ బుక్", "raw": "Ordinary Graph book / సాధారణ గ్రాఫ్ బుక్"}], "ans": 3, "exp_en": "Tactile geometry boards with raised-line rubber mats, tactile protractors, compasses, and embossed 3D shapes enable blind students to touch, measure, and construct geometric figures.", "exp_te": "ఉబ్బెత్తుగా చేతి స్పర్శకు తెలిసే ఉబ్బెత్తు రేఖాగణిత పరికరాలు (Embossed geometric shapes, Tactile Geometry Kit) దృష్టి లోపం ఉన్నవారికి జ్యామితి నేర్పడానికి తోడ్పడతాయి."}, {"id": 255, "sec": "Special Education", "passage": "", "q_en": "In 1973, the Government of India initiated standardized efforts to develop uniform Braille contractions and abbreviations for which Indian language?", "q_te": "1973 లో భారత ప్రభుత్వం ఏ భాషలో బ్రెయిలీ కాంట్రాక్షన్స్ (సంక్షిప్త లిపి) ను ప్రామాణికంగా అభివృద్ధి చేయడానికి చర్యలు చేపట్టింది?", "opts": [{"en": "Hindi (Bharati Braille Hindi Contractions)", "te": "హిందీ (Hindi - భారత జాతీయ బ్రెయిలీ కాంట్రాక్షన్స్)", "raw": "Hindi (Bharati Braille Hindi Contractions) / హిందీ (Hindi - భారత జాతీయ బ్రెయిలీ కాంట్రాక్షన్స్)"}, {"en": "Telugu", "te": "తెలుగు", "raw": "Telugu / తెలుగు"}, {"en": "Kannada", "te": "కన్నడ", "raw": "Kannada / కన్నడ"}, {"en": "English", "te": "ఆంగ్లము", "raw": "English / ఆంగ్లము"}], "ans": 1, "exp_en": "In 1973, the Ministry of Education & Social Welfare finalized standard Grade-II Braille contractions and abbreviations for Hindi to increase the reading and typing speed of Hindi Braille.", "exp_te": "1973లో భారత ప్రభుత్వం హిందీ భాషలో వేగంగా చదవడానికి వీలుగా అధికారిక 'బ్రెయిలీ కాంట్రాక్షన్స్' (Braille Contractions - సంక్షిప్త లిపి) ను రూపొందించింది."}, {"id": 256, "sec": "Special Education", "passage": "", "q_en": "A child with Low Vision (partial visual impairment) should be seated in which location in the classroom?", "q_te": "పాక్షిక దృష్టి లోపం (Low Vision) గల విద్యార్థిని తరగతి గదిలో ఎక్కడ కూర్చోబెట్టాలి", "opts": [{"en": "Last row", "te": "చివరి వరుసలో", "raw": "Last row / చివరి వరుసలో"}, {"en": "Middle row", "te": "మధ్య వరుసలో", "raw": "Middle row / మధ్య వరుసలో"}, {"en": "First row (Front row close to blackboard with optimal lighting)", "te": "మొదటి వరుసలో (నల్లబల్లకు దగ్గరగా, తగిన వెలుతురు ఉన్న చోట)", "raw": "First row (Front row close to blackboard with optimal lighting) / మొదటి వరుసలో (నల్లబల్లకు దగ్గరగా, తగిన వెలుతురు ఉన్న చోట)"}, {"en": "Near the dark back corner", "te": "చీకటి మూలన", "raw": "Near the dark back corner / చీకటి మూలన"}], "ans": 3, "exp_en": "Students with low vision must be seated in the front row closest to the blackboard, instructional display, and teacher to maximize viewing angles and prevent glare.", "exp_te": "పాక్షిక దృష్టి లోపం ఉన్న పిల్లలు నల్లబల్లపై రాసే అక్షరాలను స్పష్టంగా చూడటానికి వారిని 'మొదటి వరుసలో' (First row) తగిన వెలుతురు ఉండేలా కూర్చోబెట్టాలి."}, {"id": 257, "sec": "Special Education", "passage": "", "q_en": "To teach comparative mathematical size concepts such as 'long vs short' and 'more vs less' to a visually impaired student, the teacher should use", "q_te": "దృష్టి లోపం గల విద్యార్థికి 'పొడవు-పొట్టి', 'ఎక్కువ-తక్కువ' వంటి గణిత భావనలను నేర్పడానికి ఉపయోగించాల్సిన సామాగ్రి", "opts": [{"en": "Flat two-dimensional pictures", "te": "సమతల చిత్రాలు", "raw": "Flat two-dimensional pictures / సమతల చిత్రాలు"}, {"en": "Paper flashcards", "te": "ఫ్లాష్ కార్డులు", "raw": "Paper flashcards / ఫ్లాష్ కార్డులు"}, {"en": "Audio tape recorder alone", "te": "కేవలం టేప్ రికార్డర్", "raw": "Audio tape recorder alone / కేవలం టేప్ రికార్డర్"}, {"en": "Real three-dimensional tactile objects and tangible replicas", "te": "వాస్తవమైన స్పర్శానుకూల 3D వస్తువులు మరియు ప్రతిరూపాలు (Tactile 3D Materials)", "raw": "Real three-dimensional tactile objects and tangible replicas / వాస్తవమైన స్పర్శానుకూల 3D వస్తువులు మరియు ప్రతిరూపాలు (Tactile 3D Materials)"}], "ans": 4, "exp_en": "Tactile three-dimensional real objects of varying lengths (rods, sticks, blocks) allow blind children to measure length with their fingers and gain concrete spatial understanding.", "exp_te": "పొడవు, పరిమాణాలను అర్థం చేసుకోవడానికి ఫ్లాట్ బొమ్మలు పనికిరావు; చేతితో తాకి తేడాను పోల్చగలిగే నిజమైన వస్తువులు, కర్రలు లేదా త్రీ-డైమెన్షనల్ నమూనాలు (Tactile materials) వాడాలి."}, {"id": 258, "sec": "Special Education", "passage": "", "q_en": "The instructional principle most suitable to teach abstract geographic concepts like 'Latitudes and Longitudes' to a visually impaired student using a tactile relief globe is", "q_te": "దృష్టి లోపం ఉన్న విద్యార్థికి స్పర్శ గ్లోబును ఉపయోగించి 'అక్షాంశాలు-రేఖాంశాలు' నేర్పడానికి అనుసరించాల్సిన బోధనా సూత్రం", "opts": [{"en": "Imaginary to Thinking", "te": "ఊహ నుండి ఆలోచన వైపు", "raw": "Imaginary to Thinking / ఊహ నుండి ఆలోచన వైపు"}, {"en": "Concrete to Abstract (Touching tactile globe first, then abstract coordinates)", "te": "మూర్తం నుండి అమూర్తం వైపు (Concrete to Abstract - స్పర్శ గ్లోబ్ తాకించి అమూర్త రేఖలు వివరించడం)", "raw": "Concrete to Abstract (Touching tactile globe first, then abstract coordinates) / మూర్తం నుండి అమూర్తం వైపు (Concrete to Abstract - స్పర్శ గ్లోబ్ తాకించి అమూర్త రేఖలు వివరించడం)"}, {"en": "Unknown to Known", "te": "తెలియని దాని నుండి తెలిసిన దానికి", "raw": "Unknown to Known / తెలియని దాని నుండి తెలిసిన దానికి"}, {"en": "Complex to Simple", "te": "సంక్లిష్టం నుండి సరళం వైపు", "raw": "Complex to Simple / సంక్లిష్టం నుండి సరళం వైపు"}], "ans": 2, "exp_en": "Touching an embossed physical relief globe (Concrete) allows the blind student to tactilely feel the curved surface and raised equator line before grasping the geometric theory of coordinates (Abstract).", "exp_te": "ముందుగా స్పర్శ ఆధారిత ఉబ్బెత్తు గ్లోబ్‌ను చేతితో తాకించి (మూర్తం), ఆ తర్వాత ఊహాత్మక అక్షాంశ రేఖాంశాల భావనను (అమూర్తం) బోధించడం అత్యుత్తమ పద్ధతి."}, {"id": 259, "sec": "Special Education", "passage": "", "q_en": "An indispensable auditory electronic recording device traditionally empowering students with Visual Impairment to record lectures and study audiobooks is the", "q_te": "దృష్టి లోపం గల విద్యార్థులు తరగతి పాఠాలను రికార్డ్ చేసుకోవడానికి మరియు ఆడియో పుస్తకాలు వినడానికి అత్యంత తోడ్పడే సాధనం", "opts": [{"en": "Abacus", "te": "అబాకస్", "raw": "Abacus / అబాకస్"}, {"en": "Audio Tape Recorder / Digital Voice Recorder", "te": "ఆడియో టేప్ రికార్డర్ / డిజిటల్ వాయిస్ రికార్డర్ (Tape Recorder)", "raw": "Audio Tape Recorder / Digital Voice Recorder / ఆడియో టేప్ రికార్డర్ / డిజిటల్ వాయిస్ రికార్డర్ (Tape Recorder)"}, {"en": "Braille book alone", "te": "బ్రెయిలీ పుస్తకం", "raw": "Braille book alone / బ్రెయిలీ పుస్తకం"}, {"en": "Stylus alone", "te": "స్టైలస్", "raw": "Stylus alone / స్టైలస్"}], "ans": 2, "exp_en": "Digital voice recorders and audio tape recorders provide visually impaired students with independent auditory access to review classroom lectures, spoken notes, and Daisy audiobooks.", "exp_te": "తరగతి గదిలో ఉపాధ్యాయులు బోధించే పాఠాలను ఆడియో రూపంలో రికార్డ్ చేసుకొని, ఇంటి వద్ద పునశ్చరణ చేసుకోవడానికి 'టేప్ రికార్డర్ / డిజిటల్ వాయిస్ రికార్డర్' అత్యంత ఉపయోగకరం."}, {"id": 260, "sec": "Special Education", "passage": "", "q_en": "A modern electronic travel mobility aid used by visually impaired persons that transmits ultrasound waves to warn of obstacles via auditory tones is the", "q_te": "అల్ట్రాసోనిక్ తరంగాలను ప్రసరింపజేస్తూ అడ్డంకులను హెచ్చరించే ఆధునిక చలన సహాయక ఎలక్ట్రానిక్ పరికరం", "opts": [{"en": "OPTACON", "te": "ఆప్టాకాన్ (OPTACON)", "raw": "OPTACON / ఆప్టాకాన్ (OPTACON)"}, {"en": "Optical Magnifier", "te": "భూతద్దాలు (Magnifiers)", "raw": "Optical Magnifier / భూతద్దాలు (Magnifiers)"}, {"en": "Spectacles", "te": "సాధారణ కళ్లద్దాలు", "raw": "Spectacles / సాధారణ కళ్లద్దాలు"}, {"en": "Sonic Guide (K-Sonar / UltraCane)", "te": "సోనిక్ గైడ్ (Sonic Guide / అల్ట్రాసోనిక్ చలన పరికరం)", "raw": "Sonic Guide (K-Sonar / UltraCane) / సోనిక్ గైడ్ (Sonic Guide / అల్ట్రాసోనిక్ చలన పరికరం)"}], "ans": 4, "exp_en": "Sonic Guide (and modern UltraCanes) emit ultrasound pulses and convert reflected sound echoes into stereo auditory signals that tell the blind traveler the distance and direction of obstacles.", "exp_te": "సోనిక్ గైడ్ (Sonic Guide) అనేది అల్ట్రాసోనిక్ ధ్వని తరంగాల ద్వారా మార్గంలోని అడ్డంకులను పసిగట్టి, శబ్ద సంకేతాలతో హెచ్చరిస్తూ అంధులు సురక్షితంగా నడవడానికి తోడ్పడే సాధనం."}, {"id": 261, "sec": "Special Education", "passage": "", "q_en": "An advanced assistive hardware computer screen-access terminal that displays all computer screen commands and text output in refreshable tactile Braille is", "q_te": "కంప్యూటర్‌లోని స్క్రీన్ సమాచారాన్ని, కమాండ్లను తక్షణమే ఉబ్బెత్తు బ్రెయిలీ రూపంలో ప్రదర్శించే పరికరం", "opts": [{"en": "CALL", "te": "CALL", "raw": "CALL"}, {"en": "Super Braille (Refreshable Braille Display terminal)", "te": "సూపర్ బ్రెయిలీ (Super Braille / రిఫ్రెషబుల్ బ్రెయిలీ డిస్‌ప్లే)", "raw": "Super Braille (Refreshable Braille Display terminal) / సూపర్ బ్రెయిలీ (Super Braille / రిఫ్రెషబుల్ బ్రెయిలీ డిస్‌ప్లే)"}, {"en": "MOBIC", "te": "MOBIC", "raw": "MOBIC"}, {"en": "Laser Cane", "te": "లేజర్ కేన్", "raw": "Laser Cane / లేజర్ కేన్"}], "ans": 2, "exp_en": "Super Braille / Refreshable Braille displays feature piezoelectric pins that dynamically rise and fall, translating text and computer operational commands line by line into tactile Braille.", "exp_te": "సూపర్ బ్రెయిలీ (Super Braille) పరికరం కంప్యూటర్ మానిటర్‌పై ఉన్న సమాచారాన్ని ఎప్పటికప్పుడు చేతి వేళ్ళతో తాకేలా రిఫ్రెషబుల్ బ్రెయిలీ చుక్కల రూపంలోకి మారుస్తుంది."}, {"id": 262, "sec": "Special Education", "passage": "", "q_en": "As per official examination concession rules in Andhra Pradesh, the minimum qualifying pass marks in SSC (Class 10) examinations for a student with Visual Impairment is", "q_te": "ఆంధ్రప్రదేశ్ రాష్ట్రంలో పదవ తరగతి (10th Class) బోర్డు పరీక్షలలో దృష్టి లోపం గల విద్యార్థులకు నిర్ణయించిన పాస్ మార్కులు", "opts": [{"en": "10 marks", "te": "10 మార్కులు", "raw": "10 marks / 10 మార్కులు"}, {"en": "20 marks (Concession from standard 35)", "te": "20 మార్కులు (సాధారణ 35 మార్కులకు బదులుగా 20 మార్కుల రాయితీ)", "raw": "20 marks (Concession from standard 35) / 20 మార్కులు (సాధారణ 35 మార్కులకు బదులుగా 20 మార్కుల రాయితీ)"}, {"en": "35 marks", "te": "35 మార్కులు", "raw": "35 marks / 35 మార్కులు"}, {"en": "50 marks", "te": "50 మార్కులు", "raw": "50 marks / 50 మార్కులు"}], "ans": 2, "exp_en": "Government examination guidelines in Andhra Pradesh grant special concessions to visually impaired and orthopedically challenged students, lowering the passing threshold from 35% to 20% in each subject.", "exp_te": "ఆంధ్రప్రదేశ్ ప్రభుత్వ విద్యాశాఖ నిబంధనల ప్రకారం దృష్టి లోపం ఉన్న పదవ తరగతి విద్యార్థులకు సాధారణ పాస్ మార్కులైన 35 కు బదులుగా '20 మార్కులు' వస్తే పాస్ అయినట్లుగా పరిగణిస్తారు."}, {"id": 263, "sec": "Special Education", "passage": "", "q_en": "The modern electronic technological device empowering visually impaired students to independently perform and audit arithmetic calculations through voice is a", "q_te": "దృష్టి లోపం గల విద్యార్థులు గణిత లెక్కలు చేయడానికి తోడ్పడే నూతన శ్రవణ ఎలక్ట్రానిక్ పరికరం", "opts": [{"en": "Slate", "te": "స్లేట్", "raw": "Slate / స్లేట్"}, {"en": "Stylus", "te": "స్టైలస్", "raw": "Stylus / స్టైలస్"}, {"en": "Silent mechanical calculator", "te": "సాధారణ సైలెంట్ కాలిక్యులేటర్", "raw": "Silent mechanical calculator / సాధారణ సైలెంట్ కాలిక్యులేటర్"}, {"en": "Talking Calculator (Voice-output Calculator)", "te": "టాకింగ్ కాలిక్యులేటర్ (Talking Calculator / మాట్లాడే కాలిక్యులేటర్)", "raw": "Talking Calculator (Voice-output Calculator) / టాకింగ్ కాలిక్యులేటర్ (Talking Calculator / మాట్లాడే కాలిక్యులేటర్)"}], "ans": 4, "exp_en": "A Talking Calculator articulates pressed keys and numerical answers aloud through synthetic speech, allowing visually impaired students to calculate independently.", "exp_te": "టాకింగ్ కాలిక్యులేటర్ (Talking Calculator) ప్రతి బటన్ నొక్కినప్పుడు మరియు గణిత సమాధానాన్ని స్పష్టమైన స్వరంతో వినిపిస్తుంది, కాబట్టి చూపు లేనివారు సొంతంగా లెక్కలు చేయవచ్చు."}, {"id": 264, "sec": "Special Education", "passage": "", "q_en": "A high-speed industrial computerized Braille embosser/printer that produces large-volume double-sided Braille textbooks and magazines in minutes is the", "q_te": "తక్కువ సమయంలో బ్రెయిలీ పాఠ్యపుస్తకాలను వేగంగా ముద్రించే అత్యాధునిక కంప్యూటరైజ్డ్ బ్రెయిలీ ప్రింటర్ / ఎంబాసర్", "opts": [{"en": "Quinky", "te": "క్వింకీ", "raw": "Quinky / క్వింకీ"}, {"en": "INDEX 4X4 PRO (Braille Box Embosser)", "te": "ఇండెక్స్ 4X4 ప్రో (INDEX 4X4 PRO / బ్రెయిలీ ఎంబాసర్ ప్రింటర్)", "raw": "INDEX 4X4 PRO (Braille Box Embosser) / ఇండెక్స్ 4X4 ప్రో (INDEX 4X4 PRO / బ్రెయిలీ ఎంబాసర్ ప్రింటర్)"}, {"en": "OPTACON", "te": "ఆప్టాకాన్", "raw": "OPTACON / ఆప్టాకాన్"}, {"en": "SAM", "te": "సామ్", "raw": "SAM / సామ్"}], "ans": 2, "exp_en": "The Index 4X4 PRO (by Index Braille) is an industrial high-speed tractor-fed Braille embosser engineered specifically to produce complete bound Braille books and magazines.", "exp_te": "ఇండెక్స్ 4X4 ప్రో (Index 4X4 Pro) అనేది బ్రెయిలీ పాఠ్యపుస్తకాలను అతి తక్కువ సమయంలో రెండు వైపులా వేగంగా ముద్రించే పారిశ్రామిక స్థాయి బ్రెయిలీ ఎంబాసింగ్ ప్రింటర్."}, {"id": 265, "sec": "Special Education", "passage": "", "q_en": "A computer hardware and software system that converts typed text into synthesized human speech for individuals with visual impairments is a", "q_te": "కంప్యూటర్‌లోని సమాచారాన్ని మనుషుల గొంతు రూపంలోకి మార్చి వినిపించే సాంకేతిక పరికరం", "opts": [{"en": "Alphavision", "te": "ఆల్ఫా విజన్", "raw": "Alphavision / ఆల్ఫా విజన్"}, {"en": "Braille Slate", "te": "బ్రెయిలీ స్లేట్", "raw": "Braille Slate / బ్రెయిలీ స్లేట్"}, {"en": "Speech Synthesizer (Text-to-Speech Engine)", "te": "స్పీచ్ సింథసైజర్ (Speech Synthesizer / టెక్స్ట్-టు-స్పీచ్ ఇంజిన్)", "raw": "Speech Synthesizer (Text-to-Speech Engine) / స్పీచ్ సింథసైజర్ (Speech Synthesizer / టెక్స్ట్-టు-స్పీచ్ ఇంజిన్)"}, {"en": "Pre-Cane", "te": "ప్రీ-కేన్", "raw": "Pre-Cane / ప్రీ-కేన్"}], "ans": 3, "exp_en": "A Speech Synthesizer converts written electronic text into artificial spoken audio output, powering screen readers like JAWS and NVDA for visually impaired users.", "exp_te": "స్పీచ్ సింథసైజర్ (Speech Synthesizer) కంప్యూటర్ స్క్రీన్‌పై ఉన్న రాతపూర్వక సమాచారాన్ని సహజసిద్ధమైన మనుషుల స్వరంలోకి మార్చి చదివి వినిపిస్తుంది."}, {"id": 266, "sec": "Special Education", "passage": "", "q_en": "This acts as a special non-slip drafting board for visually impaired children to draw tactile maps, charts, and geometric diagrams using a stylus", "q_te": "దృష్టి లోపం ఉన్న పిల్లలు పాఠశాల ప్రారంభ దశలో స్పర్శ ఆధారిత మ్యాపులు, చిత్రాలు గీయడానికి స్లేట్‌లా ఉపయోగపడే బోర్డు", "opts": [{"en": "Blackboard", "te": "నల్లబల్ల", "raw": "Blackboard / నల్లబల్ల"}, {"en": "Ordinary Paper Notebook", "te": "సాధారణ నోట్ బుక్", "raw": "Ordinary Paper Notebook / సాధారణ నోట్ బుక్"}, {"en": "Fibre / Rubber-based Tactile Drawing Board", "te": "ఫైబర్ / రబ్బర్ ఆధారిత స్పర్శ చిత్రలేఖన బోర్డు (Fibre-based Tactile Board)", "raw": "Fibre / Rubber-based Tactile Drawing Board / ఫైబర్ / రబ్బర్ ఆధారిత స్పర్శ చిత్రలేఖన బోర్డు (Fibre-based Tactile Board)"}, {"en": "Diagram Book", "te": "డయాగ్రమ్ బుక్", "raw": "Diagram Book / డయాగ్రమ్ బుక్"}], "ans": 3, "exp_en": "A rubber-backed or fibre-based tactile drawing board holds polyester film or plastic foil; when drawn on with a ballpoint stylus, raised embossed tactile lines emerge immediately.", "exp_te": "ఫైబర్ లేదా రబ్బరు పొరతో కూడిన ప్రత్యేక బోర్డుపై స్టైలస్‌తో గీసినప్పుడు ఉబ్బెత్తు రేఖలు ఏర్పడతాయి. ఇది చూపు లేని పిల్లలకు మ్యాపులు, బొమ్మలు గీయడానికి స్లేట్‌లా పనిచేస్తుంది."}, {"id": 267, "sec": "Special Education", "passage": "", "q_en": "An electronic brailler and multi-media learning tool used by students with visual impairment to learn, emboss, audio-check, and interact with diagrams in Braille is the", "q_te": "దృష్టి లోపం గల పిల్లలు బ్రెయిలీని నేర్చుకోవడానికి, చార్టులు మరియు చిత్రాలను ముద్రించుకోవడానికి ఉపయోగపడే ఆధునిక ఎలక్ట్రానిక్ బ్రెయిలర్", "opts": [{"en": "Tactile Maps", "te": "టాక్టైల్ మ్యాప్స్", "raw": "Tactile Maps / టాక్టైల్ మ్యాప్స్"}, {"en": "Bliss Passive Detector", "te": "బ్లిస్ పాసివ్ డిటెక్టర్", "raw": "Bliss Passive Detector / బ్లిస్ పాసివ్ డిటెక్టర్"}, {"en": "MOUNTBATTEN Brailler", "te": "మౌంట్‌బాటెన్ బ్రెయిలర్ (MOUNTBATTEN Brailler)", "raw": "MOUNTBATTEN Brailler / మౌంట్‌బాటెన్ బ్రెయిలర్ (MOUNTBATTEN Brailler)"}, {"en": "Flash cards", "te": "ఫ్లాష్ కార్డులు", "raw": "Flash cards / ఫ్లాష్ కార్డులు"}], "ans": 3, "exp_en": "The Mountbatten Brailler is an electronic teaching and writing tool providing electronic Braille embossing, speech feedback, PC keyboard connectivity, and tactile graphics capability.", "exp_te": "మౌంట్‌బాటెన్ బ్రెయిలర్ (Mountbatten Brailler) అనేది తేలికపాటి కీబోర్డ్, మాట్లాడే ఫీడ్‌బ్యాక్ మరియు బ్రెయిలీ ప్రింటింగ్ సౌకర్యం గల ఆధునిక ఎలక్ట్రానిక్ లెర్నింగ్ పరికరం."}, {"id": 268, "sec": "Special Education", "passage": "", "q_en": "The National Institute for the Visually Handicapped (NIVH, now NIEPVD) is established at", "q_te": "దృష్టి లోపం గల వారి జాతీయ సంస్థ 'NIVH' (NIEPVD) ఎక్కడ స్థాపించబడింది?", "opts": [{"en": "Dehradun (Uttarakhand)", "te": "డెహ్రాడూన్ (ఉత్తరాఖండ్ - Dehradun)", "raw": "Dehradun (Uttarakhand) / డెహ్రాడూన్ (ఉత్తరాఖండ్ - Dehradun)"}, {"en": "Mumbai", "te": "ముంబై", "raw": "Mumbai / ముంబై"}, {"en": "Secunderabad", "te": "సికింద్రాబాద్", "raw": "Secunderabad / సికింద్రాబాద్"}, {"en": "New Delhi", "te": "న్యూఢిల్లీ", "raw": "New Delhi / న్యూఢిల్లీ"}], "ans": 1, "exp_en": "The National Institute for the Empowerment of Persons with Visual Disabilities (Divyangjan) - NIEPVD (formerly NIVH) is headquartered at Rajpur Road, Dehradun.", "exp_te": "భారత ప్రభుత్వ దృష్టి దివ్యాంగుల జాతీయ సాధికారత సంస్థ (NIEPVD / NIVH) ఉత్తరాఖండ్ రాష్ట్రంలోని డెహ్రాడూన్ (Dehradun) లో ఉంది."}, {"id": 269, "sec": "Special Education", "passage": "", "q_en": "Bharati Braille code in India was standardized and developed specifically for", "q_te": "భారతదేశంలో 'భారతి బ్రెయిలీ' (Bharati Braille) కోడ్ ఎవరి కోసం అభివృద్ధి చేయబడింది", "opts": [{"en": "Children with Intellectual Disability", "te": "మేధో వైకల్యం గల పిల్లలు", "raw": "Children with Intellectual Disability / మేధో వైకల్యం గల పిల్లలు"}, {"en": "Children with Hearing Impairment", "te": "వినికిడి లోపం గల పిల్లలు", "raw": "Children with Hearing Impairment / వినికిడి లోపం గల పిల్లలు"}, {"en": "Children with Locomotor Disability", "te": "చలన వైకల్యం గల పిల్లలు", "raw": "Children with Locomotor Disability / చలన వైకల్యం గల పిల్లలు"}, {"en": "Children with Visual Impairment across Indian languages", "te": "దృష్టి లోపం గల పిల్లలు (భారతీయ భాషల బ్రెయిలీ లిపి)", "raw": "Children with Visual Impairment across Indian languages / దృష్టి లోపం గల పిల్లలు (భారతీయ భాషల బ్రెయిలీ లిపి)"}], "ans": 4, "exp_en": "Bharati Braille is the unified standard tactile writing system adopted in 1951 across India, mapping uniform 6-dot Braille cells phonetically to all major Indian languages for blind learners.", "exp_te": "భారతదేశంలోని అన్ని ప్రముఖ ప్రాంతీయ భాషలను (తెలుగు, హిందీ, తమిళం మొదలైనవి) అంధులు సులభంగా చదవడానికి రూపొందించిన ఉమ్మడి లిపిని 'భారతి బ్రెయిలీ' (Bharati Braille) అంటారు."}, {"id": 270, "sec": "Special Education", "passage": "", "q_en": "In providing appropriate socialization, emotional security, and societal priority to a child with Visual Impairment, which of the following is NOT an immediate social partner?", "q_te": "దృష్టి లోపం గల పిల్లల సాంఘిక వికాసంలో మరియు సమాజ ప్రాధాన్యత కల్పించడంలో సంబంధం లేనివారు", "opts": [{"en": "Parents", "te": "తల్లిదండ్రులు", "raw": "Parents / తల్లిదండ్రులు"}, {"en": "Night Watchmen / Security Guards", "te": "నైట్ వాచ్‌మెన్ / రాత్రి కాపలాదారులు (సంబంధం లేనివారు)", "raw": "Night Watchmen / Security Guards / నైట్ వాచ్‌మెన్ / రాత్రి కాపలాదారులు (సంబంధం లేనివారు)"}, {"en": "Siblings", "te": "తోబుట్టువులు", "raw": "Siblings / తోబుట్టువులు"}, {"en": "Peer group and classmates", "te": "తోటి స్నేహితులు మరియు సహచరులు", "raw": "Peer group and classmates / తోటి స్నేహితులు మరియు సహచరులు"}], "ans": 2, "exp_en": "The child's primary socialization network consists of family (parents, siblings), school peers, and teachers. Night watchmen have no role in emotional and social development.", "exp_te": "పిల్లల మనో-సామాజిక ఎదుగుదలలో తల్లిదండ్రులు, తోబుట్టువులు, స్నేహితులు ముఖ్య పాత్ర పోషిస్తారు. నైట్ వాచ్‌మెన్ (రాత్రి కాపలాదారులకు) దీనితో సంబంధం ఉండదు."}];